<!-- 
  项目：Elyden.com
  创建时间：2024.01.29
  上次更新时间：2023.05.11
  组件名称：SpaceCollectionChild
  此文件负责的板块：用户空间合集展示详细合集信息界面
    功能：
      1、游客查看合集和合集内容
      2、空间主人编辑合集内容，新建合集
  -->
<template>
  <div>
    <!-- 合集信息 -->
    <div class="commpilation_info">
      <!-- 合集信息 -->
      <div class="compilation_info_l">
        <!-- 合集信息 此合集包含多少个视频，上次更新时间 -->
        <span>{{video_list.total}}个视频</span>
        <span class="info_cut_icon">|</span>
        <span>{{updateTime}}</span>
        <!-- 合集简介 -->
        <div class="compilation_sysnopsis"> 
          {{synopsis}}
        </div>
      </div>
      <!-- 合集操作按钮 -->
      <div class="compilation_info_r">
        <!-- 播放全部按钮 -->
        <span class="played_all" @click="addVideoPAndGoToVideoPlayer">播放全部</span>
        <!-- 内容按加入时间倒叙展示按钮 -->
        <span class="orderby_time_desc active" @click="changeOrderBy">时间倒叙</span>
        <!-- 内容按加入时间正序展示按钮 -->
        <span class="orderby_time_asc" @click="changeOrderBy">时间正序</span>
      </div>
    </div>
    <!-- 主要内容区 -->
    <div class="main">
      <!-- 视频列表 -->
      <div class="video_list">
        <!-- 给合集添加视频 -->
        <div class="video_list_item1 add_video_compilation" v-if="showModel=='me'" @click="addVideoToCompilation">
          <div class="add_icon">+</div>
          添加视频
        </div>
        <!-- 单个视频 -->
        <div class="video_list_item1" v-for="(item,index) in video_list.list" @click="gotovideo(item.vid)">
          <!-- 视频封面 -->
          <div class="video_list_item1_cover">
            <img :src="getImgURL(item.coverAddress)" alt="稿件封面">
            <div class="videoControl" v-if="showModel=='me'" @click.stop="deleteVideo(item.vid)">
              <span>⛔</span>
            </div>
          </div>
          <!-- 视频标题 -->
          <div class="video_list_item1_title">
            <span> {{ item.title }} </span>
          </div>
          <!-- 视频信息 -->
          <div class="video_list_item1_msg">
            <!-- 视频播放量信息 -->
            <div>
              <svg class="play_video_icon" aria-hidden="true">
                <use xlink:href="#icon-shipin"></use>
              </svg>
              {{ item.playedNum / 10000 > 1 ? item.playedNum / 10000+"万": item.playedNum}}
            </div>
            <!-- 视频日期 -->
            <div class="video_data_item recommend_date">
              {{ item.publishTime? item.publishTime.slice(0,10) :''}}
            </div>
          </div>
        </div>          
      </div>
    </div>
    <!-- 分页导航 -->
    <div class="pageNav">
      <el-pagination
        @size-change="handleSizeChange"
        @current-change="handleCurrentChange"

        :hide-on-single-page="true"
        :current-page="1"
        :page-size="video_list.size"
        layout="prev, pager, next, jumper"
        :total="video_list.total">
      </el-pagination>
    </div>

    <!-- 添加视频到合集弹窗 -->
    <el-dialog
      title="添加视频"
      :visible.sync="dialogCompilationVisible"
      top="30vh"
      width="30%"
      :before-close="handleClose">
      <div>
        <form>
          <div style="font-size: 20px;">
            <div>选择要加入视频</div>
          </div>
          <!-- 视频列表 -->
          <ol style="height: 30vh; overflow-x: auto;" @scroll="scrollVideoList" ref="videoList">
            <!-- 单个视频元素 -->
            <li v-for="(item,index) in select_video_list" :key="item.vid">
              <div style="position: relative; width: 90%;">
                <!-- 视频 -->
                <div class="video_list_item1">
                  <!-- 视频封面 -->
                  <div class="video_list_item1_cover">
                    <img :src=getImgURL(item.coverAddress) alt="稿件封面">
                  </div>
                  <!-- 视频标题 -->
                  <div class="video_list_item1_title">
                    <span class="video_title"> {{ item.title }} </span>
                  </div>
                  <!-- 视频信息 -->
                  <div class="video_list_item1_msg">
                    <!-- 视频播放量 -->
                    <div>
                      <svg class="play_video_icon" aria-hidden="true">
                        <use xlink:href="#icon-shipin"></use>
                      </svg>
                      {{ item.playedNum / 10000 > 1 ? item.playedNum / 10000+"万": item.playedNum}}
                    </div>
                    <!-- 视频发布日期 -->
                    <div class="video_data_item recommend_date">
                      {{ item.publishTime? item.publishTime.slice(0,10) :''}}
                    </div>
                  </div>
                </div>
                <!-- 视频选择框 -->
                <el-checkbox-group style="scale: 2; position: absolute; right: 0; top: 30%;" v-model="checkedCities" @change="handleCheckedCitiesChange">
                  <el-checkbox :label="item.vid">{{  }}</el-checkbox>
                </el-checkbox-group>
              </div>
            </li>
          </ol>
        </form>
      </div>
      <span slot="footer" class="dialog-footer">
        <el-button  @click="cancelAddVideo">取 消</el-button>
        <el-button  type="primary" @click="saveNewCompilation">确定</el-button>
      </span>
    </el-dialog>
  </div>
</template>

<script>
import { addVideoToCompilation, deleteCompilationOneVideo, getCompilationInfo, getExistVidByCompilationId } from '@/api/compilation';
import { countUserVideo, getUserCompilationVideos, getUserVideoByPage, getVideo } from '@/api/video';

  export default{
    name:'SpaceCompilationChild',
    data(){
      return{
        // 合集信息
        compilation_info:{},
        // updateTime:'',
        // synopsis:'',
        // 合集视频vid列表
        vidList:[],
        // 合集视频
        video_list:[],
        // 当前展示页码
        page:1,
        // 内容排序
        orderBy:'desc',

        // 是否展示添加界面
        dialogCompilationVisible: false,
        // 添加合集界面的选择视频列表
        select_video_list:[],
        // 排序条件
        condition:'publish_time',
        // 选择视频列表当前页面
        selectPage:1,
        // 选择结果
        checkedCities: [],
        // 计时器
        timer:'',
        // 当前用户视频总数是
        videoTotal:0,
      }
    },
    computed:{
      updateTime(){
        return this.compilation_info.time
      },
      // 空间展示模式
      showModel() {
        return this.$store.state.spaceViewModel
      },
      synopsis(){
        return this.compilation_info.synopsis
      },
      // 用户空间状态信息
      spaceInfo(){
        // console.log(this.$store.state.spaceInfo);
        return this.$store.state.spaceInfo
      },
    },
    destroyed(){
      console.log("销毁");
    },
    methods:{
      // 点击从此合集中删除视频
      deleteVideo(vid){
        // console.log(vid);
        // console.log(this.compilation_info.id);
        // 提示是否确认删除
        this.$confirm('确认删除此视频吗？')
          .then(async _ => {
            let data = await deleteCompilationOneVideo(this.compilation_info.id, vid)
            if (data == 1) {
              this.$message({
                type: 'success',
                message: '删除成功!'
              });
            }else{
              this.$message({
                type: 'success',
                message: '删除失败!'
              });
            }
            done();
          })
          .catch(_ => {});
      },

      // -----------------------------------------合集添加视频--------------------------------------
      // 取消添加视频
      cancelAddVideo(){
        this.dialogCompilationVisible = false
        this.$refs.videoList.scrollTop = 0
        this.selectPage = 1
      },

      // 添加视频到合集
      addVideoToCompilation(){
        // 展示界面
        this.dialogCompilationVisible = true
        // 获取当前用户所有视频
        this.getAllVideoByPage()
        // 获取当前合集已有视频id集合
        this.getExistVidByCompilationId()
      },
      
      // 确认添加
      async saveNewCompilation(){
        console.log("确认添加");
        // 关闭界面
        this.dialogCompilationVisible = false

        // 拼接vid字符串
        let vidList = ""
        this.checkedCities.forEach((item)=>{
          vidList = vidList + item + ','
          // console.log(this.vidlist);
        })

        let temp = {
          "listId":"",
          "addTime":"",
        }
        temp.listId = this.compilation_info.id
        temp.addTime = Date.now()

        // 发送添加视频请求
        let data = await addVideoToCompilation(vidList, temp)
        if (data == 1) {
          this.$message({
            type: 'success',
            message: '删除成功!'
          });
        }else{
          this.$message({
            type: 'success',
            message: '删除失败!'
          });
        }
      },

      // 获取当前合集已有视频id集合
      async getExistVidByCompilationId(){
        let data = await getExistVidByCompilationId(this.compilation_info.id)
        this.checkedCities = data
      },

      // 分页获取用户全部视频
      async getAllVideoByPage(){
        // 根据空间用户uid获取用户视频稿件的数量
        this.getSpaceUserCountNum()
        console.log(this.selectPage);
        let data = await getUserVideoByPage(this.spaceInfo.uid, this.condition, `${this.selectPage}`)
        this.selectPage += 1
        this.select_video_list = data
      },

      // 根据空间用户uid获取用户视频稿件的数量
      async getSpaceUserCountNum(){
        let data = await countUserVideo(this.$store.state.spaceUserId)
        this.videoTotal = data
      },

      // 添加合集视频列表滚动事件
      scrollVideoList(){
        console.log("没满");
        let scrollTop = event.target.scrollTop
        let clientHeight = event.target.clientHeight
        let scrollHeight = event.target.scrollHeight
        this.timer = ''
        if (scrollTop + clientHeight + 30 >= scrollHeight){
          console.log("调用添加视频");
          // 当前获取到的视频总数小于用户所有视频总数，调用后端分页获取视频信息
          if( this.select_video_list.length < this.videoTotal){
            this.addVideoToSelectVideoList()
          }
        }
      },

      // 滚到底部时调用添加视频
      async addVideoToSelectVideoList(){
        // 有计时器时
        if(this.timer){
          // 清除计时器
          clearTimeout(this.timer)
          // 重新计时
          this.timer = setTimeout(async ()=>{
            let data = await getUserVideoByPage(this.spaceInfo.uid, this.condition, `${this.selectPage}`)
            this.selectPage = this.selectPage + 1
            let temp = data
            temp.forEach((item)=>{
              this.select_video_list.push(item)
            })
          },500)
        }
        // 首次执行
        if(!this.timer){
          let data = await getUserVideoByPage(this.spaceInfo.uid, this.condition, `${this.selectPage}`)
          this.selectPage = this.selectPage + 1
          let temp = data
          temp.forEach((item)=>{
            this.select_video_list.push(item)
          })
          console.log(this.select_video_list);
          // // 设置1s空计时器
          // this.timer = this.timer = setTimeout(()=>{
          // },500)
        }
      },

      // 选择框点击值变化时调用
      handleCheckedCitiesChange(value) {
        console.log(this.checkedCities);
      },

      // 弹窗点击关闭时提示
      handleClose(done) {
        this.$confirm('确认关闭？')
          .then(_ => {
            this.cancelAddVideo()
            done();
          })
          .catch(_ => {});
      },
      // -----------------------------------------合集添加视频--------------------------------------

      // -----------------------------------------合集列表内容--------------------------------------
      // 分页每页条数改变时触发
      handleSizeChange(val) {
        console.log(`每页 ${val} 条`);
      },

      // 分页当前页面改变时触发（这里没实现分页获取合集视频）
      handleCurrentChange(val) {
        // console.log(`当前页: ${val}`);
        // this.getVideoListByPage(val)
      },

      //视频跳跃
      gotovideo(videoid){
        this.$router.push({
          path:'/video', 
          query:{
            vid:videoid
          }
        })
      },

      // 前往播放器播放全部视频
      addVideoPAndGoToVideoPlayer(){
        this.$router.push({
          path:'/video', 
          query:{
            havePList:true,
            from:'compilation',
            id:this.$store.state.compilation_id
          }
        })
      },

      // 点击改变排序
      changeOrderBy(e){
        if(this.orderBy == 'desc'){
          this.orderBy = 'asc'
        }
        else{
          this.orderBy = 'desc'
        }
        if(document.getElementsByClassName('active').length>0){
          document.getElementsByClassName('active')[0].classList.remove('active')
        }
        e.target.classList.add('active')  
        // 获取视频
        this.getVideoByVidList()
      },
      // -----------------------------------------合集列表内容--------------------------------------

      // ---------------------------------------------初始化---------------------------------------
      // 根据合集id查询合集信息
      async getCompilationInfo(){
        let data = await getCompilationInfo(this.$store.state.compilation_id)
        console.log(this.$store.state.compilation_id);
        // 设置当前展示合集信息
        this.compilation_info = data
        // 提交合集标题
        this.$store.dispatch('changeCompilationTitle',this.compilation_info.name)
        this.getVideoByVidList()
        // console.log(this.compilation_info);
      },

      // 根据vid获取视频
      async getVideoByVidList(){
        let temp=''  
        console.log(this.compilation_info.vidList);
        this.compilation_info.vidList.forEach((item)=>{
          temp = temp + item.vid + ','
          console.log(typeof temp);
        })
        console.log(temp);
        let data = await getUserCompilationVideos(temp, this.page, this.orderBy)
        this.video_list = data
        console.log(this.video_list);
      },
      // ---------------------------------------------初始化---------------------------------------

      // 获取视频封面url
      getImgURL(address){
        return getVideo(address)
      },

    },
    created(){
      // this.vidList = this.$route.query.compilation.vidList
      // this.updateTime = this.$route.query.compilation.time
      // this.synopsis = this.$route.query.compilation.synopsis
      // console.log(this.vidList);
      
      // 获取显示合集信息
      this.getCompilationInfo()
      // this.getVideoByVidList()
      // console.log(this.$store.state.compilation_id);
    },
    beforeRouteLeave (to, from, next) {
      // 导航离开该组件的对应路由时调用
      // 可以访问组件实例 `this`
      // console.log(1);
      // 若跳转目标页面不是视频页面，清空合集标题
      // if (to.path != '/video'){
      //   this.$store.dispatch('changeCompilationTitle','')
      // }
      // 离开时关闭详细合集显示
      this.$store.dispatch('changeCompilationTitle','')
      next()
    }
  }
</script>

<style scoped>
  /* 活动样式 */
  .active{
    color: #00a1d6;
  }
  /* 合集信息 */
  .commpilation_info{
    display: flex;
    justify-content: space-between;
    font-size: 12px;
    color: gray;
    margin-top: 30px;
  }
  /* 合集信息分割符 */
  .info_cut_icon{
    margin: 0 10px;
  }
  /* 合集简介 */
  .compilation_sysnopsis{
    margin-top: 10px;
  }
  /* 合集导航右边 */
  .compilation_info_r{
    line-height: 30px;
    font-size: 16px;
    color: black;
  }
  .compilation_info_r span:hover{
    cursor: pointer;
  }
  /* 播放全部按钮 */
  .played_all{
    border: 1px solid gray;
    padding: 4px 10px;
    border-radius: 5px;
    color: gray;
  }
  .played_all:hover{
    border: 1px solid #00a1d6;
    color: #00a1d6;
  }
  /* 按时间倒叙排序 */
  .orderby_time_desc{
    margin: 0 20px;
  }
  /* 按时间排序 */
  .orderby_time_desc,.orderby_time_asc{
    padding: 4px 10px;
  }

  /* 主要内容区 */
  .main{
    margin-top: 20px;
    border-top: 1px solid rgb(230, 230, 230);
  }

  /* 视频列表 */
  .video_list{
    display: flex;
    flex-wrap: wrap;
    margin-bottom: 30px;
  }
  /* 单个视频元素 */
  .video_list_item1{
    width: 202px;
    padding-right: 22px;
    margin-top: 20px;
    cursor: pointer;
  }
  /* 单个视频信息 */
  .video_list_item1_msg{
    font-size: 12px;
    color: gray;
    display: flex;
    justify-content: space-between;
    margin-top: 10px;
  }
  /* 视频封面 */
  .video_list_item1_cover{
    position: relative;
    overflow: hidden;
  }
  /* 视频封面 */
  .video_list_item1 img{
    width: 100%;
    height: 150px;
    border-radius: 5px;
    position: relative;
  }
  /* 视频标题 */
  .video_list_item1_title{
    font-size: 14px;
    height: 40px;
    overflow: hidden;
  }
  /* 播放图标 */
  .play_video_icon{
    width: 1em;
    height: 1em;
    vertical-align: -0.1em;
    fill: currentColor;
    overflow: hidden;
  }
  /* 单个视频控制 删除商品按钮 */
  .videoControl{
    text-align: center;
    position: absolute;
    right: 0;
    height: 0px;
    bottom: 0;
    width: 100%;
    background-color: #f3f3f3;
    transition: height .5s;
  }
  .video_list_item1:hover .videoControl{
    height: 30px;
  }
  /* 合集添加视频按钮 */
  .add_video_compilation{
    padding: 0;
    border: 2px dashed rgb(216, 216, 216);
    height: 140px;
    border-radius: 5px;
    text-align: center;
    margin-right: 20px;

  }
  /* 添加图标 */
  .add_icon{
    font-size: 60px;
    perspective: 500px;
  }
  .add_video_compilation:hover{
    cursor: pointer;
    color: #00a1d6;
  }
  /* 添加样式旋转动画 */
  @keyframes hover-anim{
    0%{transform: rotateY(0deg)}
    100%{transform: rotateY(180deg)}
  }
  /* 悬浮添加按钮时应用动画 */
  .add_video_compilation:hover .add_icon{
    animation: hover-anim 1s ease;
  }

  /* 
    分页导航栏
  */
  .pageNav{
    margin: 0 auto;
    text-align: center;
  }
</style>