import request from '@/Request'

export {
  getCommentByCId,
  getAddCommentById,
  getVidoeAllComment,
  accusationComment,
  accusationAddComment,
  saveNewComment,
  saveNewAddComment,
  updateCommentAnswer,
  getMoreComment,
  saveGoodToComment,
  saveGoodToAddComment,
  saveBadToComment,
  saveBadToAddComment,
  getCommentGoodInfo,
  getCommentBadInfo,

}

// 根据id查看父评论内容
function getCommentByCId(cid){
  return request({
    method:'get',
    url:`/comment?cid=${cid}`,
  })
}

// 根据id查看子评论内容
function getAddCommentById(id){
  return request({
    method:'get',
    url:`/addComment?id=${id}`,
  })
}

// 获取视频的评论内容
function getVidoeAllComment(vid, commentOrder){
  return request({
    method: 'get',
    url: "/comment/"+ vid + '/' + commentOrder
  })
}

// 举报父评论
function accusationComment(data){
  return request({
    method:'post',
    url:'/comment/accusation',
    data: data,
  })
}

// 举报子评论
function accusationAddComment(data){
  return request({
    method:'post',
    url:'/addComment/accusation',
    data: data,
  })
}

// 保存新评论
function saveNewComment(data){
  return request({
    method:'post',
    url:'/comment/save',
    data: data,
  })
}

// 保存新子评论
function saveNewAddComment(data){
  return request({
    method:'post',
    url:'/addComment/save',
    data:data,
  })
}

// 更新评论作为父评论的状态
function updateCommentAnswer(cid, data){
  return request({
    method: 'put',
    url: `/comment/update/${cid}/${data}`,
  })
}

// 分页获取子评论
function getMoreComment(cid, page){
  return request({
    method: 'get',
    url: "/addComment/"+ this.cid + '/' + page
  })
}

// 点赞评论
function saveGoodToComment(vid, cid){
  return request({
    method:'put',
    url:'/comment/info/good/' + vid + '/' + cid,
  })
}

// 点赞子评论
function saveGoodToAddComment(vid, cid){
  return request({
    method:'put',
    url:'/addComment/info/good/' + vid +'/' + cid,
  })
}

// 点踩评论
function saveBadToComment(vid, cid){
  return request({
    method:'put',
    url:'/comment/info/bad/' + vid +'/' + cid,
  })
}

// 点踩子评论
function saveBadToAddComment(vid, cid){
  return request({
    method:'put',
    url:'/addComment/info/bad/' + vid +'/' + cid,
  })
}

// 获取用户在视频中的点赞记录
function getCommentGoodInfo(vid){
  return request({
    method:'get',
    url:'/commentGood/' + vid,
  })
}

// 获取用户在视频的点踩记录
function getCommentBadInfo(vid){
  return request({
    method:'get',
    url:'/commentBad/' + vid,
  })
}
