import request from '@/Request'

export {
  getSpaceSetInfoByUid,
  saveSpaceSetting,
  cancelRecommendVideo,
  setRecommendVideo,
  


  
}

// 根据uid获取空间的设置信息
function  getSpaceSetInfoByUid(uid) {
  return request({
    method: 'get',
    url: "/space/"+ uid,
  })
}

// 保存用户设置信息
function saveSpaceSetting(data){
  return request({
    method:'put',
    url:'/space',
    data:data,
  })
}

// 取消指定推荐视频
function cancelRecommendVideo(uid){
  return request({
    method: 'delete',
    url: '/space/recommend/' + uid
  })
}

// 设置置顶推荐视频
function setRecommendVideo(uid, vid){
  return request({
    method: 'post',
    url: '/space/recommend/' + uid + '/' + vid
  })
}