      getTime(file){
        let url = URL.createObjectURL(file);         
        let audioElement = new Audio(url);         
        let duration;
        audioElement.addEventListener("loadedmetadata",()=> {           
          duration =parseInt(audioElement.duration); //时长为秒，取整  
          // this.newVideoData.vTime = duration       
          // console.log(duration);  
          // 将秒为单位的时间转：分割的字符串时间
          let hour=parseInt(duration/3600)>=10?`${parseInt(duration/3600)}:`:`0${parseInt(duration/3600)}:`
          let minute=parseInt(duration%3600/60)>=10?`${parseInt(duration%3600/60)}:`:`0${parseInt(duration%3600/60)}:`
          let second=parseInt(duration%60)>=10?`${parseInt(duration%60)}`:`0${parseInt(duration%60)}` 
          console.log( `${hour}${minute}${second}`);
        })
      },

      // 自定义上传文件函数，并发将封面图片和视频一起上传, 方法执行多次，但通过文件长度限制，一次请求发送
      myUploadFile(param){
        // 将当前拿到的文件放入要上传的文件列表
        this.uploadList.push(param.file)
        // 如果要上传文件列表的数量和upload组件的文件列表长度一致，发送保存请求
        if (this.uploadList.length == this.fileListLength) {
          // fromData模仿form传递数据给后端
          const formData = new FormData();
          this.uploadList.forEach((file)=>{
            formData.append('fileList', file)
          })
          // 延迟执行为了等获取到视频的时长
          setTimeout(async () => {
            // 封装要传递的数据
            formData.append('title', this.newVideoData.title)
            formData.append('vTime', this.newVideoData.vTime)
            formData.append('publishTime', this.newVideoData.publishTime)
            formData.append('lable', this.newVideoData.lable)
            formData.append('synopsis', this.newVideoData.synopsis)
            // formData.append('file', option.file);
            console.log(formData);
            console.log(this.newVideoData.vTime);
            // 请求地址和data 
            let data = await uploadVideo(formData);
            if (data) {
              this.$message.success('上传成功')
              this.unUpLoadVideo()
            }
          }, 1000);
        }
      },
      
      // 上传文件之前的操作， 数据格式转换和数据校验
      beforeUploadVideo(file){
        // 文件大小 限制5000M
        const isLt100M = file.size / 1024 / 1024 < 100
        // 文件后缀检查 限制MP4格式
        if (['video/mp4','image/png'].indexOf(file.type) == -1){
          this.$message.error('只支持MP4格式和png格式')
          return false
        }
        // 超过5000M提示
        if (!isLt100M) {
          this.$message.error('文件超100M了')
          return false
        }
        // 视频名称和标签不能为空提示
        if (this.newVideoData.title.trim() == ''){
          this.$message.error('视频名称不能为空')
          return
        }

        let temp = ''
        // 拼接视频标签
        this.dynamicTags.forEach((item)=>{
          temp += item + ","
        })
        this.newVideoData.lable = temp

        // 获取视频时间
        if (file.type == 'video/mp4') {
          // 封装数据
          let url = URL.createObjectURL(file);         
          let audioElement = new Audio(url);         
          let duration;
          audioElement.addEventListener("loadedmetadata", ()=> {           
            duration =parseInt(audioElement.duration); //时长为秒，取整  
            // this.newVideoData.vTime = duration       
            // console.log(duration);  
            // 将秒为单位的时间转：分割的字符串时间
            let hour=parseInt(duration/3600)>=10?`${parseInt(duration/3600)}:`:`0${parseInt(duration/3600)}:`
            let minute=parseInt(duration%3600/60)>=10?`${parseInt(duration%3600/60)}:`:`0${parseInt(duration%3600/60)}:`
            let second=parseInt(duration%60)>=10?`${parseInt(duration%60)}`:`0${parseInt(duration%60)}` 
            this.newVideoData.vTime = `${hour}${minute}${second}`
            console.log(this.newVideoData.vTime);
          });    
        }
        // 获取发布时间
        let date = new Date()
        let Y = date.getFullYear() + '-';
        let M = (date.getMonth()+1 < 10 ? '0'+(date.getMonth()+1):date.getMonth()+1) + '-';
        let D = (date.getDate()< 10 ? '0'+date.getDate():date.getDate())+ ' ';
        let h = (date.getHours() < 10 ? '0'+date.getHours():date.getHours())+ ':';
        let m = (date.getMinutes() < 10 ? '0'+date.getMinutes():date.getMinutes()) + ':';
        let s = date.getSeconds() < 10 ? '0'+date.getSeconds():date.getSeconds();
        this.newVideoData.publishTime = Y+M+D+h+m+s;
      },

