        if(this.addCollectionTimer){
          // 清除当前计时器
          clearTimeout(this.addCollectionTimer)
          // 重新计时
          this.addCollectionTimer = setTimeout(()=>{
            // 时间到清除计时器，开放调用接口
            this.addCollectionTimer = ''
          },1000)
        }
        // 首次执行
        if(!this.addCollectionTimer){
          this.addCollectionToList()
          // 设置1s空计时器
          this.addCollectionTimer = this.addCollectionTimer = setTimeout(()=>{
