      search(){
        //存储搜索历史数组 , 搜索记录存储到localStorage
        // 1、读取历史记录列表
        let historyList = JSON.parse(localStorage.getItem('historyList')) || []
        
        if(historyList.indexOf(this.searchContent)<0){
          // 2、将本次搜索记录添加入列表
          if (this.searchContent.trim() != '') {
            historyList.push(this.searchContent);
          }
          // 3、将列表重新写入
          localStorage.setItem('historyList',JSON.stringify(historyList));
        
        }

        // 跳转到搜索结果界面
        this.$router.push({
          path: '/search',
          query:{searchContent:this.searchContent}
        })
        location.reload()
