  上次更新时间：2024.11.02
  组件名称：MenuList
  此文件负责的板块：视频的分类，动态，热门，历史，排行榜等
    功能：
      1、（未完成）常用的功能
      2、（未完成）视频的分类展示
  -->
<template>
  <div class="MenuList">
    <!-- 常用界面 -->
    <div class="MenuList_Left">
      <svg-icon v-for="(item,index) in itemsq" :iconname="itemsq[index]"></svg-icon>
      <a href="#" v-for="(item,index) in menu_item_left">
        {{item}} 
      </a>
    </div>
    <!-- 分类列表 -->
    <div class="MenuList_Right">
      <a href="#" v-for="(item,index) in menu_item_right">{{item}}</a>
    </div>
  </div>
</template>

<script>
export default{
  name:'MenuList',
  data(){
    return{
      // 菜单左边元素
      menu_item_left:['动态','热门','历史','收藏'],
      // 菜单右边元素
      menu_item_right:['文学','历史','数学','英语','生物','体育','新闻','舞蹈','音乐','计算机','动画','美食','纪录片','科技','军事','生活','汽车','...'],
      // 图标名字
      itemsq:['icon-dongtai','icon-paixingbang','icon-lishi','icon-shoucang']
    }
  }
}
</script>

<style scoped>
/* icon图标对齐中间 */
svg{
  margin: 0 auto;
  margin-top: 20px;
}
/* 分类列表整体 */
.MenuList{
  margin: 0 auto;
  width: 80%;
  height: 20%;
  display: flex;
  align-items: bottom;
  justify-content: space-between;
}
/* 左边常用分区 */
.MenuList_Left{
  width: 400px;
  display: grid;
  grid-template-rows: 1fr;
  grid-template-columns: repeat(4,1fr);
  margin-right: 50px;
  margin-top: 20px;
  text-align: center;
  gap: 0px 5px;
}
/* 右边所有分类 */
.MenuList_Right{
  width: 1300px;
  display: grid;
  grid-template-rows: 1fr 1fr;
  grid-template-columns: repeat(9,1fr);
  margin-top: 20px;
  text-align: center;
  gap: 15px 15px;
}
/* 单个列表元素 */
.MenuList a{
  text-decoration: none;
  color:black;
  border-radius: 8px;
  padding: 10px;
}
/* 所有列表元素背景颜色 */
.MenuList_Right a,.MenuList_Left a {
  background-color: rgb(237,237,237);
}
/* 所有列表元素悬浮样式 */
.MenuList_Right a:hover,.MenuList_Left a:hover {
  background-color: rgb(230,230,230);
}
</style>