<!-- 
  项目：Elyden.com
  创建时间：2024.03.10
  上次更新时间：2023.05.10
  组件名称：VideoPlayer
  此文件负责的板块：视频播放器
    功能：
      1、播放视频
      2、发送和查看弹幕
      3、发送和查看评论
      4、举报视频和评论
      5、多种模式分P播放视频
      6、推荐视频列表
  -->

<!-- 
  版本: 0.5
  说明：比较完整版，功能实现大部分,尝试小窗口播放
 -->

<template>
  <div v-if="mystatus">
    <!-- 顶部导航组件 -->
    <HeaderNav initNav="white"></HeaderNav>
    <!-- 空内容，占位顶替导航栏空位 -->
    <div class="nulldiv"></div>
    <!-- 视频播放页面整体 -->
    <div class="VideoPlayer">
      <!-- 视频左边 -->
      <div class="video_title_left_list">
        <!-- 顶部视频信息栏 -->
        <div class="video_title_left_list_head">
          <!-- 视频标题 -->
          <div class="video_title" :class="{'chineseIconIndent':checkChinese(video.title.charAt(0))}">{{ video.title }}</div>
          <!-- 视频信息 -->
          <div class="video_msg">
            <!-- 播放量 -->
            <div class="video_msg_1">
              <svg-icon iconname="icon-shipin"></svg-icon>
              <!-- 三元运算符判断显示格式类型 -->
              <span>{{ video.playedNum / 10000 > 1 ? parseInt(video.playedNum / 10000)+"万": video.playedNum}}</span>
            </div>
            <!-- 弹幕数 -->
            <div class="video_msg_2">
              <svg-icon iconname="icon-danmushu"></svg-icon>
              <!-- 三元运算符判断显示格式类型 -->
              <span>{{ video.incomment / 10000 > 1 ? video.incomment / 10000+"万": video.incomment}}</span>
            </div>
            <!-- 发布日期-->
            <div class="video_msg_3">
              <span>{{ video.publishTime }}</span>
            </div>
            <!-- 是否允许转载 -->
            <div class="video_msg_4" style="color: red;">
              <span>🚫未经作者允许，禁止转载</span>
            </div>
          </div>
        </div>
        <!-- 视频 -->
        <!-- <div class="video"></div> -->
        <!-- <video muted="muted" controls  :src=getVideoURL($store.state.videoList[vid].address) class="video"></video> -->
        <div class="video_area_1" id="video_area" @mousemove="showControl" @mouseleave="closeControl">
          <!-- 视频播放器 -->
          <video style="max-height: 35vw; max-width: 75vw;" muted="muted" autoplay="autoplay" :src=getVideoURL(video.address) class="video" @timeupdate="updateVideoTime" @click="playvideo"></video>
          <!-- canvas弹幕 -->
          <canvas id="myCanvas">
            <!-- <marquee 
              v-for="(item,index) in incommentList"
              behavior="slide"
              hspace="800">
              {{item.comment}}
            </marquee>  -->
          </canvas>
          <!-- 视频内置控制器 -->
          <div class="videoControl" >
            <!-- 提示上次播放进度 -->
            <div ref="historyJump" style="background-color: black; border-radius: 5px; padding: 5px; color: skyblue; font-size: 14px; position: absolute; top: -40px; left: 20px; cursor: pointer;" @click.stop="jumpHistoryWatch" v-if="videoTimePercentage">
              <span>已有上次播放记录点，</span>
              <span style="color: #FB7299;">点击跳转</span>
            </div>
            <!-- 进度条gif动画 -->
            <img src="/img/run.gif" alt="run" ref="videorunimg" >
            <!-- 进度条 -->
            <div class="control_top" ref="sliderFather" @click="videoJump">
              <!-- 已播放的进度条 -->
              <div class="SliderBar" ref="timeSlider"></div>
            </div>
            <!-- 控制器按钮 -->
            <div class="control_bottom" ref="videoControl" @mouseenter="noHideController = true" @mouseleave=" noHideController = false">
              <!-- 控制器左边 -->
              <div class="videoControl_l">
                <!-- 播放按钮 -->
                <div class="playButton">
                  <!-- 上一集按钮 -->
                  <svg-icon iconname="icon-shangyiji" class="playButton-nav last" v-if="havePList" @click.native="jumpPVideo(PContentList[nowPIndex-1].vid, nowPIndex-1)"></svg-icon>
                  <!-- 播放按钮 -->
                  <svg-icon iconname="icon-bofang" class="playButton-nav play" v-if="videoPaused" @click.native="playvideo"></svg-icon>
                  <!-- 暂停按钮 -->
                  <svg-icon iconname="icon-weibiaoti519" class="playButton-nav stop" v-if="!videoPaused" @click.native="playvideo"></svg-icon>
                  <!-- 下一集按钮 -->
                  <svg-icon iconname="icon-xiayiji" class="playButton-nav next" v-if="havePList" @click.native="jumpPVideo(PContentList[nowPIndex+1].vid, nowPIndex+1)"></svg-icon>
                </div>
                <!-- 视频时间 -->
                <div class="Vtime" ref="vidtime"></div>
              </div>
              <!-- 控制器中间 (全屏显示)-->
              <div class="video_incomment" v-if="fullWindow">
                <!-- 弹幕开启按钮 -->
                <div class="in_comment_open" v-if="isOpenIncomment" @click="changeIncommentState">
                  <svg-icon iconname="icon-danmukaiqi"></svg-icon>
                </div>
                <!-- 弹幕关闭按钮 -->
                <div class="in_comment_close" v-if="!isOpenIncomment" @click="changeIncommentState">
                  <svg-icon iconname="icon-danmuguanbi"></svg-icon>
                </div>
                <!-- 弹幕设置 -->
                <div class="in_comment_setting">
                  <el-popover
                    placement="top-start"
                    title="弹幕设置"
                    width="200"
                    popper-class="popoverBox"
                    trigger="hover"
                    content="这是一段内容,这是一段内容,这是一段内容,这是一段内容。">
                    <!-- 弹幕设置弹窗内容 -->
                    <div style="margin: 0">
                      <span>弹幕字体大小</span>
                      <!-- 弹幕字体大小拉条 -->
                      <el-slider v-model="incommentFontSize" :max="30" :min="12"></el-slider>
                    </div>
                    <!-- 弹幕设置按钮,决定是否显示弹幕设置弹窗 -->
                    <svg-icon style="position: relative;" iconname="icon-dianji01" slot="reference" @mouseover.native="showPopoverBox"></svg-icon>
                  </el-popover>
                </div>
                <!-- 发送弹幕 -->
                <form class="send_in_comment">
                  <!-- 输入框 -->
                  <input class="send_in_comment_input" type="text" placeholder="发个友善的弹幕互动下" @focus="noHideController = true" @blur="noHideController = false" @keydown.enter="sendInComment2" v-model="incomment.comment" ref="incomment_input">
                  <!-- 颜色选择器 -->
                  <el-color-picker style="position: relative;" @click.native="openSelectColorBox" popper-class="selectColorBox" v-model="incomment.color" class="color_select"></el-color-picker>
                  <!-- 发送按钮 -->
                  <div class="send_in_comment_button" @click="sendInComment2">发送</div>
                </form>
              </div>
              <!-- 控制器右边 -->
              <div class="videoControl_r">
                <div class="videoSpeedButton">倍速</div>
                <!-- 音量条拉条 -->
                <div class="soundButton">
                  <svg-icon iconname="icon-shengyin" class="icon-nav" v-if="true" @click.native="updateVideoVolume" @mouseover.native="showvolumeSlider"></svg-icon>
                  <el-slider 
                    ref="volumeSlider"
                    @input="updateVideoVolume"
                    @mouseleave.native="closevolumeSlider"
                    v-model="volumevalue"
                    vertical
                    height="100px">
                  </el-slider>
                </div>
                <!-- 网页全屏按钮 -->
                <div class="videoWebButton">
                  <svg-icon iconname="icon-wangyequanping" class="icon-nav" v-if="true"></svg-icon>
                  <svg-icon iconname="icon-quxiaowangyequanping" class="icon-nav" v-if="false"></svg-icon>
                </div>
                <!-- 屏幕全屏按钮 -->
                <div class="videoWindowButton">
                  <!-- 全屏按钮 -->
                  <svg-icon iconname="icon-quanping" class="icon-nav" v-if="!fullWindow" @click.native="function121"></svg-icon>
                  <!-- 取消全屏按钮 -->
                  <svg-icon iconname="icon-quxiaoquanping" class="icon-nav" v-if="fullWindow" @click.native="exitFullscreen"></svg-icon>
                </div>
              </div>
            </div>
          </div>
        </div>
        <!-- 小窗口播放时顶替视频dom位置的 -->
        <div class="video_area" @click="reversePlayer"><div style="text-align: center; line-height: 50vh; color: white;">点击恢复</div></div>

        <!-- 视频数据信息栏 -->
        <div class="video_Info">
          <!-- 当前该视频观看人数（万以下人数） -->
          <div class="watch_num" v-if="watchPeopleNum/1000<10"><span>当前共有{{watchPeopleNum/1000>1 ? parseInt(watchPeopleNum/1000)+"000+": watchPeopleNum}}人一起看,</span></div>
          <!-- 当前该视频观看人数（超过万人）-->
          <div class="watch_num" v-if="watchPeopleNum/1000>10"><span>当前共有{{(watchPeopleNum/10000).toFixed(1)+"万+"}}人一起看,</span></div>
          <!-- 当前有多少条弹幕 -->
          <div class="video_in_comment_num"><span>已有{{video.incomment / 10000 > 1 ? video.incomment / 10000+"万": video.incomment}}条弹幕</span></div>
          <!-- 弹幕开启按钮 -->
          <div class="in_comment_open" v-if="isOpenIncomment" @click="changeIncommentState">
            <svg-icon iconname="icon-danmukaiqi"></svg-icon>
          </div>
          <!-- 弹幕关闭按钮 -->
          <div class="in_comment_close" v-if="!isOpenIncomment" @click="changeIncommentState">
            <svg-icon iconname="icon-danmuguanbi"></svg-icon>
          </div>
          <!-- 弹幕设置 -->
          <div class="in_comment_setting" >
            <el-popover
              placement="top-start"
              title="弹幕设置"
              width="200"
              trigger="hover"
              content="这是一段内容,这是一段内容,这是一段内容,这是一段内容。">
              <!-- 弹幕弹窗设置弹窗 -->
              <div style="margin: 0">
                <span>弹幕字体大小</span>
                <!-- 弹幕字体大小拉条 -->
                <el-slider v-model="incommentFontSize" :max="30" :min="12"></el-slider>
              </div>
              <!-- 弹幕设置按钮，判断是否显示设置弹窗 -->
              <svg-icon iconname="icon-dianji01" slot="reference"></svg-icon>
            </el-popover>
          </div>
          <!-- 发送弹幕 -->
          <form action="" class="send_in_comment">
            <!-- 输入框 -->
            <input class="send_in_comment_input" type="text" placeholder="发个友善的弹幕互动下" @keydown.enter="sendInComment2" v-model="incomment.comment" ref="incomment_input">
            <!-- 颜色选择器 -->
            <el-color-picker v-model="incomment.color" class="color_select"></el-color-picker>
            <!-- 发送按钮 -->
            <div class="send_in_comment_button" @click="sendInComment2">发送</div>
          </form>
          <!-- AI总结按钮 -->
          <div class="AI_video_helper_button">AI总结</div>
        </div>

        <!-- 视频点赞收藏分享区 -->
        <div class="video_nav" style="position: relative;">
          <!-- 点赞 -->
          <div class="video_nav_item video_nav_good" :class="{ 'videoInfoActive': videoInfo.good }" @click="updateVideoGood">
            <div>
              <!-- 点赞动画 -->
              <img v-if="showGoodGif" :key="shownum" style="position: absolute; width: 100px; translate: -100px -20px;" src="/img/good.gif" alt="点赞">
              <!-- 点赞按钮 -->
              <svg class="icon" aria-hidden="true">
                <use xlink:href="#icon-good"></use>
              </svg>
              <!-- 点赞数 -->
              <span>{{ video.good / 10000 > 1 ? (video.good / 10000).toFixed(1)+"万": video.good}}</span>
            </div>
          </div>
          <!-- 献花 -->
          <div class="video_nav_item video_nav_flower" :class="{ 'videoInfoActive': videoInfo.flower }" @click="updateVideoFlower">
            <div>
              <!-- 献花动画 -->
              <img v-if="showFlowerGif" :key="shownum" style="position: absolute; width: 100px; translate: -50px -70px;" src="/img/flower.gif" alt="点赞">
              <!-- 献花按钮 -->
              <svg class="icon" aria-hidden="true">
                <use xlink:href="#icon-flower"></use>
              </svg>
              <!-- 献花数 -->
              <span>{{ video.flower / 10000 > 1 ? (video.flower / 10000).toFixed(1)+"万": video.flower}}</span>
            </div>
          </div>
          <!-- 收藏 -->
          <div class="video_nav_item video_nav_shoucang" :class="{ 'videoInfoActive': videoInfo.collection }" @click="updateVideoCollection">
            <div>
              <!-- 收藏按钮 -->
              <svg class="icon" aria-hidden="true">
                <use xlink:href="#icon-shoucang"></use>
              </svg>
              <!-- 收藏数 -->
              <span>{{ video.collection / 10000 > 1 ? (video.collection / 10000).toFixed(1)+"万": video.collection}}</span>
            </div>
          </div>
          <!-- 转发 -->
          <div class="video_nav_item video_nav_zhuanfa" :class="{ 'videoInfoActive': videoInfo.share }" @click="updateVideoShare">
            <div>
              <!-- 转发图标 -->
              <svg class="icon" aria-hidden="true">
                <use xlink:href="#icon-zhuanfa"></use>
              </svg>
              <!-- 转发数 -->
              <span>{{ video.share / 10000 > 1 ? (video.share / 10000).toFixed(1)+"万": video.share}}</span>
            </div>
          </div>
          <!-- 更多选项 -->
          <el-dropdown @command="handleVideoCommand" style="line-height: 15px; position: absolute; right: 10px;">
            <!-- 更多选项图标 -->
            <i class="el-icon-more" style="cursor: pointer; margin-top: 25px;"></i>
            <!-- 更多选项表单 -->
            <el-dropdown-menu slot="dropdown">
              <!-- 举报视频违规按钮 -->
              <el-dropdown-item command="a">🚨</el-dropdown-item>
            </el-dropdown-menu>
          </el-dropdown>
        </div>

        <!-- 视频简介 -->
        <div class="video_synopsis">{{ video.synopsis }}</div>

        <!-- 视频标签列表 -->
        <div class="video_lable">
          <!-- <div class="lable">{{video.label.split("，")}}</div> -->
          <!-- 单个视频 -->
          <div class="lable" v-for="item in videoLabelList(this.video.label)">{{ item }}</div>
        </div>

        <!-- 视频评论区 -->
        <VideoComment :initVid=vid></VideoComment>
      </div>
      <!-- 视频右边 -->
      <div class="video_title_right_list">
        <div class="video_title_right_list_cont">
          <!-- 用户区 -->
          <div class="video_title_right_list_head">
            <!-- 用户头像 -->
            <div class="video_item_l">
              <!-- 用户头像缩小简介界面弹窗 -->
              <SmallUserCard :user="video.user"></SmallUserCard>
            </div>
            <div class="video_item_r">
              <!-- 用户名称 -->
              <span class="user_name user_name_video">{{video.user.uName}}</span>
              <!-- 发短信按钮 -->
              <button @click="gotoChatRoom(video.uid)" style="cursor: pointer; margin-left: 15px; color: rgb(80, 80, 80);"><span style="font-size: 20px; line-height: 12px; vertical-align: -0.1em;">✉</span>发短信</button>
              <br>
              <!-- 用户简介 -->
              <span class="user_intro">{{video.user.synopsis}}</span>
              <!-- 关注、赞助、取消关注按钮 -->
              <div class="user_button">
                <!-- 赞助选项由用户选择是否开启，默认不开 -->
                <div class="support_button" v-if="true"><i class="el-icon-s-ticket" style="margin-right: 5px;"></i>赞助</div>
                <!-- 关注按钮 -->
                <div class="follow_button" v-if="!isFollow" @click="followUser2(video.user.uid)"><span style="margin-right: 5px; font-size: 22px;line-height: 14px; vertical-align: -0.08em;">+</span><span style="margin-right: 5px;">关注</span>{{video.user.fans / 10000 >= 1 ? (video.user.fans / 10000).toFixed(1)+"万": video.user.fans}}</div>
                <el-dropdown v-if="isFollow">
                  <el-button class="followed_button" >
                    <span style="margin-right: 5px;">已关注</span>{{video.user.fans / 10000 >= 1 ? (video.user.fans / 10000).toFixed(1)+"万": video.user.fans}}
                  </el-button>
                  <el-dropdown-menu slot="dropdown">
                    <el-dropdown-item @click.native="cancelFollow2(video.user.uid)">取消关注</el-dropdown-item>
                  </el-dropdown-menu>
                </el-dropdown>
                
                <!-- 已关注按钮 -->
                <!-- <div class="followed_button" v-if="isFollow" @mouseover="show_unfollow_creator" @mouseleave="hide_unfallow_creator"> -->
                  <!-- 显示该用户关注数 -->
                  <!-- <span style="margin-right: 5px;">关注</span>{{video.user.fans / 10000 >= 1 ? (video.user.fans / 10000).toFixed(1)+"万": video.user.fans}} -->
                  <!-- 取消关注 -->
                  <!-- <div class="unfollow_button" ref="unfallow_creator_button" @click="cancelFollow2(video.user.uid)">取消关注</div> -->
                <!-- </div> -->
              </div>
            </div>
          </div>
          <!-- 弹幕列表 -->
          <div class="video_in_comment_list" ref="video_in_comment_list">
            <div class="video_in_comment_list_content">
              <!-- 折叠状态的弹幕列表 -->
              <div class="video_in_comment_list_nav" @click="change_in_comment_list">
                <span class="video_in_comment_nav_left">弹幕列表</span>
                <span class="video_in_comment_nav_right" ref="video_in_comment_list_nav_icon">v</span>
              </div>
              <!-- 弹幕列表顶部导航 -->
              <div class="video_in_comment_nav">
                <div class="video_in_comment_nav_item video_in_comment_nav_item_videotime">时间</div>
                <div class="video_in_comment_nav_item video_in_comment_nav_item_content">弹幕内容</div>
                <div class="video_in_comment_nav_item video_in_comment_nav_item_sendtime">发送时间</div>
              </div>
              <!-- 弹幕列表 -->
              <div class="video_in_comment_list_content_list" data-simplebar data-simplebar-auto-hide="false">
                <simplebar style="max-height: 500px;">
                  <!-- 单个弹幕 -->
                  <div class="video_in_comment_item" v-for="(item,index) in incommentList" :key="incommentList.icid">
                    <!-- 弹幕所处视频时间 -->
                    <div class="video_in_comment_nav_item_videotime">{{item.videoTime}}</div>
                    <!-- 弹幕内容 -->
                    <div class="video_in_comment_nav_item_content">{{item.comment}}</div>
                    <!-- 弹幕发布时间 -->
                    <div class="video_in_comment_nav_item_sendtime">{{item.publishTime}}</div>
                  </div>
                </simplebar>
              </div>
            </div>
          </div>
          <!-- 视频分区列表 （可无）-->
          <div class="video_P_list" v-if="havePList">
            <!-- 顶部 -->
            <div class="video_P_list_nav">
              <div class="video_P_list_nav_l">
                <!-- 分P合集的名称 -->
                <span class="video_P_list_nav_title">{{PContent.name}}</span>
                <!-- 当前播放的视频是合集第几个 -->
                <span class="video_P_list_nav_now">({{nowPIndex + 1}}</span>
                <span>/</span>
                <!-- 当前分P的总数 -->
                <span class="video_P_list_nav_total">{{ PContent.totalNum }})</span>
              </div>
              <div class="video_P_list_nav_r">
                <!-- 是否开启自动播放分P的下一集 -->
                <span class="auto_play_button">自动播放</span>
                <!-- 开启或关闭按钮 -->
                <el-switch
                  v-model="autoNextVideo"
                  active-color="#00a1d6"
                  inactive-color="#ccd0d7">
                </el-switch>  
              </div>
            </div>
            <!-- 中间 -->
            <div class="video_P_list_info">
              <!-- 视频简介 -->
              <div class="video_P_list_info_l">
                <!-- <span class="video_P_play_total">2000万播放</span> -->
                <span class="video_P_synopsis">{{ PContent.synopsis }}</span>
              </div>
              <!-- 不同类型分P的订阅按钮 -->
              <button class="follow_P_button" v-if="PContentfrom == 'video'">订阅Up</button>
              <button class="follow_P_button" v-if="PContentfrom == 'compilation'">订阅合集</button>
              <button class="follow_P_button" v-if="PContentfrom == 'collection'">订阅收藏</button>
            </div>
            <!-- 分P视频列表 -->
            <div class="video_P_list_tontext" @scroll="PListRefresh">
              <!-- 单个分P元素 -->
              <div class="video_P_list_tontext_item" v-for="(item,index) in PContentList" :class="{'video_P_playing' : item.vid == vid}" @click="jumpPVideo(item.vid, index)">
                <!-- 正在播放视频gif图和视频名称 -->
                <div class="video_P_title_l">
                  <img src="/img/playing.gif" alt="播放gif" v-if="item.vid == vid">
                  <!-- 视频名称 -->
                  <div class="video_title">{{ item.title }}</div>
                </div>
                <!-- 视频时长 -->
                <div class="video_total_time">{{ item.vtime }}</div>
              </div>
            </div>
          </div>
          <!-- 视频推荐区 -->
          <div class="video_guess_list">
            <!-- 单个视频元素 -->
            <div class="video_guess_list_content" v-if="item.vid != vid" v-for="(item,index) in likeList" :key="item.vid" @click="gotovideo(item.vid)">
              <!-- 视频封面 -->
              <img :src=getImgURL(item.coverAddress) alt="推荐">
              <!-- 视频信息 -->
              <div class="video_guess_msg">
                <!-- 视频标题 -->
                <div class="guess_list_video_title" :class="{'chineseIconIndent': checkChinese(item.title.charAt(0)) }">{{item.title}}</div>
                <!-- 视频作者 -->
                <div class="guess_list_video_author" @click="gotoSpace(item.uid)"><svg-icon iconname="icon-zuozhe" class="icon-nav"></svg-icon>{{item.user.uName}}</div>
                <!-- 视频播放信息 -->
                <div class="video_guess_total_msg">
                  <!-- 播放数 -->
                  <div class="video_guess_msg_1">
                    <svg-icon class="video_guess_icon" iconname="icon-shipin"></svg-icon>
                    <span>{{ item.playedNum / 10000 > 1 ? (item.playedNum / 10000).toFixed(1) +"万": item.playedNum}}</span>
                  </div>
                  <!-- 弹幕数 -->
                  <div class="video_guess_msg_2">
                    <svg-icon class="video_guess_icon" iconname="icon-danmushu"></svg-icon>
