        console.log("开启分P播放");
        console.log(this.havePList);
        console.log("内容来源"+this.PContentfrom);
        console.log("内容id："+this.PContentId);
        if (this.PContentfrom == 'compilation'){
          console.log("合集P播放模式");
          this.getPVideoListByCompilationId()
        }
        else if (this.PContentfrom == 'video'){
          console.log("全部视频播放模式");
          this.getPVideoListByUId()
        }
        else if (this.PContentfrom == 'collection'){
