    async getVideoByid(){
      let data = await getVideoByVid(this.vid)
      this.video = data
      // 视频为空
      if (!this.video){
        this.$router.push({
          path:'/Error4XX',
          query:{
            code: 400,
            message: "视频不见了"
          }
        })
        // 将错误url去除
        this.$router.history.
        return
      }
      console.log(this.video);
      this.mystatus=true
      // 如果为播放全视频
      if(this.PContentfrom == 'video'){
        // 获取全部视频总数
        this.getTotalVideoNumByUid(this.video.uid)
      }
      // 请求推荐视频列表
      this.getLikeList(this.video.label, this.video.uid, this.likePage) 
      // 判断登录状态的用户和视频作者的关系
      // this.userIsFollow()
      this.userIsFollow2()
      // console.log(this.video);
      // 更新此视频的播放次数
      this.updateVideoPlayedNum()
      // 判断登录用户是否观看过此视频，点击跳转上次播放位置
      this.isWatch()
      // 获取四连信息
      this.getVideoInfoByvid()
    },

