      var reg = new RegExp("[\u3002\uff1b\uff0c\uff1a\u201c\u201d\uff08\uff09\u3001\uff1f\u300a\u300b\uff01\u3010\u3011\uffe5]+","g");
      return reg.test(str);
    },

    // 调整窗口位置到指定地区（消息界面跳转过来携带需要跳转的位置消息）
    jumpToComment(){
      console.log(3333333);
      // 延迟获取
      setTimeout(() => {
        let target = document.getElementById(`${this.jumpTocid}`)
        if (!target) {
          console.log(target);
          return
        }
        target.style.backgroundColor = 'skyblue'
        let i = 1
        let timer = setInterval(() => {
          target.style.backgroundColor = `rgb(135, 206, 235, ${i-=0.05})`
          if (i==0) {
            clearInterval(timer);
          }
        }, 100);
        window.scrollTo({
          top: target.offsetTop - target.clientHeight
        })
      }, 1000);
    },

