    /**
     * ----------------------------------------------------------------------------------------------
     * 当前视频播放人数统计板块（简单webSocket实现）
     * 统计是连接服务器的session数，一个窗口计算一个
     */
    // 初始化webSocket
    initWebSocket(){
      // 创建webSocket
      this.ws = new WebSocket(`ws://localhost:9000/videoPlayer/${this.vid}`)
      // 添加链接成功点击事件
      this.ws.addEventListener("open", ()=>{
        console.log("链接成功");
        // 如果连接状态成功，发送消息给后端
        // if (this.ws.readyState===1) {
        //   this.sendMessage()
        // }
      })
      // 添加关闭事件
      this.ws.addEventListener("close", ()=>{
        console.log("链接关闭");
        if (this.isNeedRestart) {
          // 不明原因关闭后请求重连
          this.restartSocket()
        }
        // this.isNeedRestart = true
      })
      // 接受后端消息事件
      this.ws.addEventListener("message", (e)=>{
        // console.log(e);
        console.log("接受消息：当前人数：" + e.data);
        this.watchPeopleNum = e.data
      })
      // 添加出错事件
      this.ws.addEventListener("error", ()=>{
        console.log("出错了");
      })
    },
    // 发送消息
    sendMessage(){
      this.ws.send(`${this.uid}`)
    },
    // 手动关闭链接
    closeSocketByHand(){
      // 不需要重连
      this.isNeedRestart = false
      this.ws.close()
    },
    // 断开链接后请求重连
    restartSocket(){
      console.log("链接失败");
      this.socketRestartTimer = setInterval(() => {
        console.log("重新连接中");
        this.ws = new WebSocket(`ws://localhost:9000/ws/${this.uid}`)
        if (this.ws.readyState === 0){
          // 重连成功。关闭计时器
          clearInterval(this.socketRestartTimer)
          this.socketRestartTimer = null
          console.log("重连成功");
          // 添加链接成功点击事件
          this.ws.addEventListener("open", ()=>{
            console.log("链接成功");
            // 如果连接状态成功，发送消息给后端
            if (this.ws.readyState===1) {
              this.sendMessage()
            }
          })
          // 添加关闭事件
          this.ws.addEventListener("close", ()=>{
            console.log("链接关闭");
            if (this.isNeedRestart) {
              // 不明原因关闭后请求重连
              this.restartSocket()
            }
            // this.isNeedRestart = true
          })
          // 添加消息事件
          this.ws.addEventListener("message", (e)=>{
            console.log("接受消息" + e.data);
          })
          // 添加出错事件
          this.ws.addEventListener("error", ()=>{
            console.log("出错了");
          })
        }
      }, 3000);
