    // 按左右方向键跳跃视频
    videoKeyUp(){
      document.onkeydown =  (e) => {
        //事件对象兼容
        let e1 = e || event || window.event || arguments.callee.caller.arguments[0]
        let time = 5  //每次5秒跳跃
        let videoElement = document.getElementsByClassName('video')[0]
        if (e && e.keyCode === 37) {
          // 按向左键
          videoElement.currentTime !== 0 ? videoElement.currentTime -= time : 1;
          this.getIncommentByVid()
          //清空当前正在发送的弹幕
          this.barrage.barrageList = []
          return false;
        } 
        else if (e && e.keyCode === 39) {
          // 按向右键
          videoElement.currentTime !== videoElement.duration ? videoElement.currentTime += time : 1;
          this.getIncommentByVid()
          //清空当前正在发送的弹幕
          this.barrage.barrageList = []
          return false;
        }
      }
    },

