    // 视频控制板块的时间显示  和  时间滑块
    videoControlVtime(video){
    
      let nowTime=video.currentTime;
      let allTime=video.duration;

      // 当前准确的时间速
      let nowhour=parseInt(nowTime/3600)>10?`${parseInt(nowTime/3600)}:`:`0${parseInt(nowTime/3600)}:`
      let nowMinute=parseInt(nowTime%3600/60)>10?`${parseInt(nowTime%3600/60)}:`:`0${parseInt(nowTime%3600/60)}:`
      let nowSecond=parseInt(nowTime%60)>10?`${parseInt(nowTime%60)}/`:`0${parseInt(nowTime%60)} / `
      //总时长解析后的时间
      let allhour=parseInt(allTime/3600)>10?`${parseInt(allTime/3600)}:`:`0${parseInt(allTime/3600)}:`
      let allMinute=parseInt(allTime%3600/60)>10?`${parseInt(allTime%3600/60)}:`:`0${parseInt(allTime%3600/60)}:`
      let allSecond=parseInt(allTime%60)>10?`${parseInt(allTime%60)}`:`0${parseInt(allTime%60)}`
      // 时间显示
      this.$refs.vidtime.innerHTML=`${nowhour}${nowMinute}${nowSecond}${allhour}${allMinute}${allSecond}`

      // 时间滑块控制
      this.$refs.timeSlider.style.width= `${nowTime/allTime*100}%`
      this.$refs.videorunimg.style.transform = `translate( -${this.$refs.timeSlider.offsetWidth}px, -30px)`;

      // 开启了自动播放下一集
      if(this.PContent.vidList){
        if (this.autoNextVideo && nowTime == allTime && this.nowPIndex+1 < this.PContent.vidList.length - 1) {
          this.vid = this.PContentList[this.nowPIndex + 1].vid
          this.nowPIndex += 1
          // 根据当前视频id去查找信息
          this.getVideoByid()
          // 获取当前视频的弹幕信息
          this.getIncommentByVid()
          // 获取当前视频的评论信息
          this.getVideoComment() 
        }
      }
    },

