    // 页面关闭时提交保存观看记录
    saveVideoWatchHistory(){
      console.log("刷新");
      if (localStorage.getItem('token')) {
        const video = document.getElementsByClassName('video')[0]
        let nowTime= video.currentTime;
        let allTime= video.duration;
        this.newHistoryWatch.addTime = Date.now()
        this.newHistoryWatch.contentId = this.vid
        this.newHistoryWatch.uid = this.$store.state.loginUser.uid
        this.newHistoryWatch.videoTimePercentage = (nowTime / allTime).toFixed(2)
        saveWatched(this.newHistoryWatch)
      }
