    // 是否开启窗口播放模式（事件总线）
    changeWindowPlay(data){
      // 开启窗口播放
      if (data) {
        // 开启对video窗口的监听
        this.observer.observe(document.getElementById('video_area'))
        this.windowPlay = true
        console.log(this.incommentFontSize);
        this.openSmallWindowPlay()
      }
      // 关闭窗口播放
      else {
        // 注销对video窗口的监听
        this.observer.unobserve(document.getElementById('video_area'))
        this.windowPlay = false
        this.reversePlayer()
      }
      // data ? this.windowPlay = true : this.windowPlay = false
      // data ? this.initAnim() : this.reversePlayer()
    },

    // 开启窗口播放
    openSmallWindowPlay(){
      // 弹幕默认字体修改大
      this.incommentFontSize = 26

      // 助手组件显示小窗播放按钮
      // this.$bus.$emit('showWindowButton', true)

      tweenline = gsap.timeline({paused:true})
      // 记录原位置
      tweenline.to(".video_area_1",{duration: .1})
      document.getElementsByClassName('video_area')[0].style.display = 'block'
      if (this.windowPlay) {
        this.observer2.observe(document.getElementsByClassName('video_area')[0])
      }
      document.getElementById("video_area").style.position = 'fixed'
      // 防止动画移动瞬间闪屏
      document.getElementById("video_area").style.opacity = '0'
      tweenline.play()

      // // 记录原位置
      // tweenline.to(".video_area_1",{duration: .1})
      // 动画
      tweenline.fromTo('.video_area_1',{
        opacity: 0,
        right: -100,
        bottom: 0,
        width: '30vw',
        immediateRender: false
      },{
        opacity: 1,
        right: 10,
        duration: 2,
        ease: "elastic.out",
        immediateRender: false,
        onComplete:()=>{tweenline.kill()}
      })
    },

    // 初始化窗口播放
    initAnim(){
      // 延时获取视频元素，初始时拿不到
      setTimeout(() => {
        // window的scroll事件在nav栏已经有了，这里不所有scroll事件判断视频是否移除可视窗口
        this.observer = new IntersectionObserver(entries =>{
          if (entries[0].intersectionRatio > 0) {
            // 进入区域，没用，动画播放后，内容一直会处于窗口内，使用按钮点击恢复位置
            // console.log("关闭窗口播放");
            // tween.reverse()
          }
          else{
            // if (!this.windowPlay) {
            //   console.log("ds");
            //   return
            // }
            console.log("开启窗口播放");
            this.openSmallWindowPlay()
          }
        })

        // 监视顶位视频dom的,在开启窗口播放时，检测到进入后，恢复默认播放
        this.observer2 = new IntersectionObserver(entries =>{
          if (entries[0].intersectionRatio > 0) {
            // 助手组件关闭小窗播放按钮
            // this.$bus.$emit('showWindowButton', false)
            this.reversePlayer();
          }
          
        }) 


        // console.log(document.getElementById('video_area'));
        document.getElementsByClassName('video_area')[0].style.height = `${document.getElementById("video_area").clientHeight}px`
        // 监视视频区域
        this.observer.observe(document.getElementById('video_area'))
      }, 1000);
    },

    // 恢复原窗口动画
    reversePlayer(){
      // 弹幕默认字体恢复
      this.incommentFontSize = 16
      console.log("恢复原位置播放");
      // 动画时间线归位并暂停
      tweenline.seek(0).pause()
      // 样式恢复
      document.getElementsByClassName('video_area')[0].style.display = 'none'
      document.getElementById("video_area").style.position = 'relative'
      document.getElementById("video_area").style.width = '100%'
      document.getElementById("video_area").style.opacity = 1
      document.getElementById("video_area").style.right = 0
      document.getElementById("video_area").style.bottom = 0
    },

  },
  created(){
    // 是否开启分P播放
    if(typeof this.$route.query.havePList == typeof ''){
      this.havePList = this.$route.query.havePList
    }
    // 是否有分页类型 合集 视频 收藏
    if(typeof this.$route.query.from == typeof ''){
      this.PContentfrom = this.$route.query.from
    }
    // 如果是空间跳转过来的，携带了需要显示的内容id，合集id 用户id 收藏夹id
    if(typeof this.$route.query.id == typeof ''){
      this.PContentId = this.$route.query.id
    }
    // 有传递要播放视频id 当前视频vid
    if(typeof this.$route.query.vid== typeof ''){
      this.vid = this.$route.query.vid
    }
    // 有需要跳转的评论id位置时赋值
    if(typeof this.$route.query.cid== typeof ''){
      this.jumpTocid = this.$route.query.cid
    }
    // 有需要跳转的历史观看时间
    // if(typeof this.$route.query.videoTimePercentage == typeof ''){
    //   this.videoTimePercentage = this.$route.query.videoTimePercentage
    // }
    // 判断当前播放模式
    this.initVideoPlayer()
  },
  mounted(){
    // 创建弹幕，涉及dom获取，延时调用
    setTimeout(() => {
      this.setCanvas()
    }, 300);
    // 全屏变换事件，解决esc键退出状态转换失败问题
    this.initwindow()
    // 初始化webSocket
    this.initWebSocket()
    // 跳转窗口位置到指定cid
    if (this.jumpTocid != -1) {
      this.jumpToComment()
    }
    // setTimeout(() => {
    //   if (this.videoTimePercentage) {
    //     this.videoInitJump(this.videoTimePercentage)
    //   }
    // }, 500);

    // 全事件总线，评论区组件请求显示登录弹窗
    // this.$bus.$on('showLogin', this.changeDialog)
    this.$bus.$on('changeWindow', this.changeWindowPlay)
    

    // 初始化窗口动画
    this.initAnim()

    // 浏览器刷新和关闭时调用方法，存储历史观看记录
    window.addEventListener('unload', this.saveVideoWatchHistory)

  },
  destroyed(){
    // this.$bus.$off('showLogin', this.changeDialog)
    this.$bus.$off('changeWindow', this.changeWindowPlay)


    // 销毁按键事件
    document.onkeydown = null
    // 销毁全屏变换事件
    document.removeEventListener("fullscreenchange",()=>{if (document.fullscreenElement){}else{this.fullWindow = false}})
    // 关闭socket
    this.closeSocketByHand()
    // 关闭监视
    this.observer.disconnect()
    console.log("销毁");
  },
  beforeRouteLeave(to,from,next){
    console.log("离开");
    // 销毁按键事件
    document.onkeydown = null
    // 销毁全屏变换事件
    document.removeEventListener("fullscreenchange",()=>{if (document.fullscreenElement){}else{this.fullWindow = false}})
    // 关闭socket
    this.closeSocketByHand()
    // 提交观看记录  destory无法读取dom
    this.saveVideoWatchHistory()
    next()
  }
}
