import request from '@/Request'

export{
  getUserHelperSetInfo,
  saveUserHelperSetInfo,


}

// 大语言api地址
const ChatApi = '';

// 获取助手设置信息
function getUserHelperSetInfo(){
  return request({
    method: 'get',
    url:'/helper',
  })
}

// 保存助手设置信息
function saveUserHelperSetInfo(data){
  return request({
    method:'put',
    url:'/helper',
    data:data
  })
}

