<!-- 
  项目：Elyden.com
  创建时间：2024.03.11
  上次更新时间：2024.5.09
  组件名称：login
  此文件负责的板块：登录注册功能
    功能：
      1、登录
      2、注册
  -->
<template>
  <div class="login">
    <!-- 背景动画 -->
    <div id="bacganim"></div>
    <!-- 登录内容区 -->
    <div class="loginmain">
      <!-- 登录表单 -->
      <el-form v-show="!signUpForm" :model='user' :rules='userRules' ref="loginForm" label-width="60px">
        <el-form-item label="账号" prop='account'>
          <el-input v-model="user.account" placeholder='请输入账号 / 电话号 / 邮箱'></el-input>
        </el-form-item>
        <el-form-item label="密码" prop='password'>
          <el-input v-model="user.password" show-password placeholder='请输入密码'></el-input>
        </el-form-item>
        <el-form-item prop="LineCode">
          <el-input placeholder="验证码" v-model="user.LineCode" style="width: 100px;"></el-input>
          <!-- <div id="codeAre" @click="getCode">点击获取</div> -->
          <div class="codeBox" @click="refashCode('login')">
            <img class="code" :src="imgUrl" alt="验证码" ref="loginCode">
          </div>
          <span class="refashCode" ref="refashLoginCode" style="font-size: 12px; display: none;" @click="refashCode('login')">换一张</span>
        </el-form-item>
        <div style="text-align: center;">
          <div style="display: inline-block;">
            <el-button type="primary" @click="login(user)">确认</el-button>
            <el-button @click="resetForm('loginForm')">重置</el-button>
            <el-button type="info" @click="gotoMain">退出登录</el-button>
          </div>
        </div>
        <div style="text-align: center;">
          <span class="signUp" @click.prevent="showSignUpForm">没有账号，注册一个吧!</span>
        </div> 
      </el-form>
      <!-- 注册表单 -->
      <el-form v-show="signUpForm" :model='signUpUser' :rules='signUpUserRules' ref='signUpForm' label-width="80px">
        <el-form-item label="电话" prop='account'>
          <el-input v-model="signUpUser.account" placeholder='请输入账号 / 电话号 / 邮箱'></el-input>
        </el-form-item>
        <el-form-item label="密码" prop='password'>
          <el-input v-model="signUpUser.password" show-password placeholder='请输入6-15位数字、字母组成的密码'></el-input>
        </el-form-item>
        <el-form-item label="二次密码" prop='againPassword'>
          <el-input v-model="signUpUser.againPassword" show-password placeholder='请再次输入密码'></el-input>
        </el-form-item>
        <el-form-item label="用户名称" prop='uName'>
          <el-input v-model="signUpUser.uName" placeholder='请输入小于10位的用户名称'></el-input>
        </el-form-item>
        <el-form-item label="性别" prop='gender'>
          <el-radio-group v-model="signUpUser.gender">
            <el-radio :label="1">男</el-radio>
            <el-radio :label="0">女</el-radio>
            <el-radio :label="2">秘密哦♪</el-radio>
          </el-radio-group>
        </el-form-item>
        <el-form-item label="生日" prop='birthday'>
          <el-date-picker
              v-model="signUpUser.birthday"
              type="date"
              placeholder="选择日期">
            </el-date-picker>
        </el-form-item>
        <el-form-item label="个人简介" prop='synopsis'>
          <el-input
            type="textarea"
            :autosize="{ minRows: 2, maxRows: 4}"
            placeholder="向别人介绍自己吧！"
            v-model="signUpUser.synopsis">
          </el-input>
        </el-form-item>
        <el-form-item label="邮箱" prop='email'>
          <el-input v-model="signUpUser.email" show-password placeholder='请输入邮箱账号'></el-input>
        </el-form-item>
        <el-form-item label="地址" prop='address'>
          <el-input v-model="signUpUser.address" show-password placeholder='请输入联系地址'></el-input>
        </el-form-item>
        <el-form-item prop="LineCode">
          <el-input placeholder="验证码" v-model="signUpUser.LineCode" style="width: 100px;"></el-input>
          <!-- <div id="codeAre" @click="getCode">点击获取</div> -->
          <div class="codeBox" @click="refashCode('signUp')">
            <img class="code" :src="imgUrl" alt="验证码" ref="signUpCode">
          </div>
          <span class="refashCode" ref="refashSignUpCode" style="font-size: 12px; display: none;" @click="refashCode('signUp')">换一张</span>
        </el-form-item>
        <div style="text-align: center;">
          <div style="display: inline-block;">
            <el-button type="primary" @click="signUpAndLogin">注册并登录</el-button>
            <el-button @click="resetForm('signUpForm')">重置</el-button>
            <el-button @click="showSignUpForm">返回登录</el-button>
          </div>
        </div>
      </el-form>
    </div>
  </div>
</template>

<script>
import * as PIXI from "pixi.js";
import {login, getUserInfo, getHelperSet, signUpUser, refashCode} from "@/api/user.js"
import {saveLocal} from "@/utils/StorageUtils.js"
global.PIXI = PIXI;
require("pixi-spine");

let Serika = null;
let anim = null;

export default{
  name:'login',
  data(){
    // 验证密码是否一致
    var validatePass2 = (rule, value, callback) => {
      if (value === '') {
        callback(new Error('请再次输入密码'));
      } else if (value !== this.signUpUser.password) {
        callback(new Error('两次输入密码不一致!'));
      } else {
        callback();
      }
    };
    return{
      imgUrl:"img/点击生成.png",
      // 用户登录信息
      user: {
        "account":"",
        "password":"",
        "LineCode": "",
      },

      // 用户登录校验规则
      userRules: {
        account: [{
          required: true,
          message: '账号不能为空',
          trigger: 'blur'
        }],
        password: [{
          required: true,
          message: '密码不能为空',
          trigger: 'blur'
        }],
        LineCode: [{
          required: true,
          message: '验证码不能为空',
          trigger: 'blur'
        }]
      },
      // 注册用户信息
      signUpUser: {
        "account":"",
        "password":"",
        "uName":"",
        "LineCode": "",
        "againPassword":"",
        "gender":1,
        "birthday":"",
        "synopsis":"",
        "email":"",
        "address":"",
      },
      // 注册用户信息验证规则
      signUpUserRules: {
        account: [{
          required: true,
          message: '电话不能为空',
          trigger: 'blur'
        }, {
          pattern: /^1[34578]\d{9}$/,
          message: '电话号错误',
          trigger: 'blur'
        }],
        password: [{
          required: true,
          message: '密码不能为空',
          trigger: 'blur'
        }, {
          min: 6,
          max: 15,
          message: '密码长度应该为6-15位数字、字母或符号组成',
          trigger: 'blur'
        }],
        againPassword: [{
          validator: validatePass2,
          trigger: 'blur'
        }],
        uName: [{
          required: true,
          message: '名称不能为空',
          trigger: 'blur'
        }, {
          min: 1,
          max: 10,
          message: '名称长度为1-10位',
          trigger: 'blur'
        }],
        gender: [{
          required: true,
          message: '性别不能为空',
          trigger: 'blur'
        }],
        LineCode: [{
          required: true,
          message: '验证码不能为空',
          trigger: 'blur'
        }],
        birthday: [],
        synopsis: [],
        email: [],
        address: [],
      },
      // 是否显示注册表
      signUpForm: false,
    }
  },
  methods:{
    // 初始化背景动画
    initAnim(){
      anim = new PIXI.Application({
        antialias:true,            
        transparent: true,
        // resizeTo: window
      });
      document.getElementById('bacganim').appendChild(anim.view);
      let loader = anim.loader.add('Serika','/spine/Serika_home.json')
      loader.load((loader,res)=>{
        Serika = new PIXI.spine.Spine(res.Serika.spineData)
        let skeleton = Serika.skeleton;
        //获取骨骼
        let controlEye = skeleton.findBone('Touch_Eye')
        let controlHead = skeleton.findBone('Head')
        //眼位置
        let relative = {x: 0, y: 0}   
        //眼骨骼初始位置
        relative.x = controlEye.x
        relative.y = controlEye.y
        let elemt1 = document.querySelector("body")
        //移动
        elemt1.addEventListener('mousemove',function(e){
          controlEye.y = -(e.clientX - 700)/3
          controlEye.x = -(e.clientY - 300)/3
        })
        //过渡
        elemt1.addEventListener('mouseleave',function(e){
          let i = 1
          let timer = setInterval( function(){
            controlEye.y = controlEye.y - (controlEye.y - relative.y)*(i/10)
            controlEye.x = controlEye.x - (controlEye.x - relative.x)*(i/10)
            i++
            if(i===10){
                i=1
                clearInterval(timer)
            }
          }, 40);
        })
        Serika.state.setAnimation(0,'Idle_02',true);
        //Serika.alpha = 0.5;
        //const alphaFilter = new PIXI.filters.AlphaFilter(alpha:0.4)
        const alphaFilter = new PIXI.filters.AlphaFilter();
        Serika.filters = [alphaFilter]
        alphaFilter.alpha = 0.3;
        Serika.x = 700;
        if (window.innerWidth < 767){
          Serika.x = window.innerWidth 
        }
        Serika.y = 1400;
        Serika.scale.x = 0.74;
        Serika.scale.y = 0.74;
        anim.stage.addChild(Serika);

        // let viewWidth = document.getElementById('body').clientWidth;
        anim.renderer.view.style.position = "absolute";
        anim.renderer.view.style.display = "block";
        anim.renderer.autoResize = true;
        anim.renderer.resize(window.innerWidth-1, window.innerHeight-2);
        window.addEventListener('resize', this.resizeBg);
      }); 
      
    },
    resizeBg(){
      console.log(11);
      this.$nextTick(() => {
        // console.log(document.getElementsByClassName('loginmain')[0].clientHeight);
        if (window.innerWidth < 767){
          Serika.x = window.innerWidth 
        }
        let h = document.getElementsByClassName('loginmain')[0].clientHeight;
        window.innerHeight > h ? anim.renderer.resize(window.innerWidth-1, window.innerHeight-2) : anim.renderer.resize(window.innerWidth-1, h-2)
      })
    },
    async refashCode(type){
      if (type == "login") {
        this.$refs.refashLoginCode.style.display = 'inline'
        // this.$refs.loginCode.src = "http://localhost:9000/user/createCode?time=" + new Date().getTime();
        // this.$refs.loginCode.src = URL.createObjectURL(await refashCode());
        this.$refs.loginCode.src = window.URL.createObjectURL(new Blob([await refashCode()], { type: 'image/png' }))
        // const data = await refashCode()
        // this.$refs.loginCode.src = URL.createObjectURL(data);
        // this.$refs.loginCode.onload = function () {
        //   URL.revokeObjectURL(URL.createObjectURL(data))
        // }
        // console.log(await refashCode());
        
        
      }
      else{
        this.$refs.refashSignUpCode.style.display = 'inline'
        // this.$refs.signUpCode.src = "http://localhost:9000/user/createCode?time=" + new Date().getTime();
        this.$refs.signUpCode.src = window.URL.createObjectURL(new Blob([await refashCode()], { type: 'image/png' }))
      }
      
    },
    // 发送登录信息给后端
    login(user){
      this.$refs.loginForm.validate(async (isOk)=>{
        if (isOk) {
          // 发送登录请求，成功获取到data的token，失败为null
          let data = await login(user, this.user.LineCode);
          // console.log(data);
          if (data){
            // 将token存储到本地
            // localStorage.setItem("token",response.data.data.token)
            saveLocal("token", data.token);
            // 获取登录用户信息
            this.getUserInfo()
            // 获取助手设置信息
            this.getHelperSet()
          }
        }
      })
      
    },
    // 获取用户助手设置
    async getHelperSet(){
      let data = await getHelperSet()
      
      this.$store.dispatch('setHelper', data)
      this.$store.dispatch('chanceshow', data.isOpenHelper)
    },
    // 注册并登录
    signUpAndLogin(){
      this.$refs.signUpForm.validate(async (isOk)=>{
        if (isOk) {
          let data = await signUpUser(this.signUpUser);
          if (data){
            // 发送登录请求，成功获取到data的token，失败为null
            let data = await login(this.signUpUser, this.signUpUser.LineCode);
            // console.log(data);
            if (data){
              // 将token存储到本地
              // localStorage.setItem("token",response.data.data.token)
              saveLocal("token", data.token);
              // 获取登录用户信息
              this.getUserInfo()
              // 获取助手设置信息
              this.getHelperSet()
            }
          }
        }
      })
    },
    
    // 重置注册单
    resetForm(formName) {
      this.$refs[formName].resetFields();
    },

    // 获取用户信息
    async getUserInfo(){
      let data = await getUserInfo();
      if (data) {
        // 提示登录成功
        this.loginSuccess();
        // 当前用户登录信息
        this.$store.dispatch('loginUser',data.loginUser)
        // 当前用户状态
        this.$store.dispatch('loginState',true)
        // 判断是否是管理员，确认是否前往后台
        if (data.loginUser.role == '0'){
          this.$confirm('需要前往后台吗', '提示', {
            confirmButtonText: '确定',
            cancelButtonText: '取消',
            type: 'warning'
          }).then(() => {
            // 确认，前往后台
            this.gotoAdmin()
          }).catch(() => {
            // 取消，前往首页
            // 前往首页
            this.gotoMain()
          });
        }
        this.gotoMain();
      }
    },
    // 前往后台
    gotoAdmin(){
      this.$router.push({
        path: '/admin/home',
      })
    },
    // 验证成功后返回主页面
    gotoMain(){
      this.$router.push({
        path: '/',
      })
    },
    // 登录信息弹窗  登录成功
    loginSuccess() {
      this.$notify({
        title: '成功',
        message: '登录成功',
        type: 'success'
      });
    },
    // 注册信息弹窗  账号已存在
    accountSameError() {
      this.$notify.error({
        title: '错误',
        message: '账号已存在'
      });
    },
    // 隐藏和展示注册表单
    showSignUpForm(){
      this.signUpForm = !this.signUpForm;
      // 触发背景大小变化
      let myEvent = new Event('resize');
      window.dispatchEvent(myEvent);
    },
    // 注册成功 重清除表单
    resetall(){
      this.resetForm('signUpForm');
    },
  },
  created(){
    // 如果是其它页面跳转过来  携带了只要注册的参数
    if (typeof this.$route.query.signUp == typeof ''){
      this.signUpForm = this.$route.query.signUp
    }
  },
  mounted(){
    // 初始化背景动画
    this.initAnim()
  },
  beforeDestroy(){
    console.log("123");
    
    window.removeEventListener('resize', this.resizeBg);
  }
}
</script>

<style>
  /* 解决margin塌陷问题 */
  .login{
    height: 100%;
    width: 100%;
  }
  /* 背景动画 */
  #bacganim{
    width: 100%;
    height: 100%;
  }
  /* 画布 */
  #bacganim canvas{
    width: 100%;
  }

  /* 表单界面整体 */
  .loginmain{
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    height: auto;
    padding: 4vh 5vw 4vh 0;
    /* padding-right: 5vw; */
    box-sizing: border-box;
    background-color: rgba(255, 255, 255, 0.7);
    margin: 0 auto;
    border-radius: 20px;
    box-shadow: 2px 2px 2px 3px rgba(173, 173, 173, 0.3);
  }
  .codeBox{
    display: inline-block;
    margin: 0 10px 0 20px;
    width: 100px; 
    height: 40px; 
    background-color: #c7c7c7; 
    text-align: center;
    border-radius: 5px;
    cursor: pointer;
  }
  .code{
    vertical-align: middle;
    line-height: 40px;
  }

  /* 前往注册按钮文字 */
  .signUp, .refashCode{
    color: gray;
    font-size: 12px;
  }
  .signUp:hover, .refashCode:hover{
    color: #00a1d6;
    cursor: pointer;
  }

  /* 多端适配 */
  @media  screen and (min-width: 1200px) {
    .loginmain{
      width: 600px;
    }
  }
  @media  screen and (max-width: 1199px) and (min-width: 768px) {
    .loginmain{
      width: 500px;
    }
  }
  @media screen and (max-width: 767px) {
    .loginmain{
      width: 90%;
    }
  }
</style>