<!-- 
  项目：Elyden.com
  创建时间：2024.01.29
  上次更新时间：2023.05.11
  组件名称：SpaceCollectionHome
  此文件负责的板块：用户空间合集展示简略合集信息界面
    功能：
      1、游客查看合集和合集内容
      2、空间主人编辑合集内容，新建合集
  -->
<template>
  <div class="compilation_content">
    <!-- 单个合集视频列表 -->
    <div class="video_compilation" v-for="(compilationItem,index) in compilation_list" :key="compilationItem.id">
      <!-- 合集导航 -->
      <div class="user_video_nav">
        <!-- 合集顶部导航左边 合集信息 -->
        <div class="user_video_nav_l">
          <!-- 合集名称 -->
          <div class="video_nav_item1" @click="gotoCompilationChild(compilationItem.name,compilationItem.id)">{{ compilationItem.name }}</div>
          <!-- 合集内容数 -->
          <span class="compilation_title_num">{{compilationItem.totalNum}}</span>
        </div>
        <!-- 合集顶部导航右边 按钮 -->
        <div class="user_video_nav_r">
          <!-- <div class="video_nav_r deleted_button" v-if="showModel=='me'" @click="deletedCompilation(compilationItem.id)">删除合集</div> -->
          <!-- 播放全部按钮 -->
          <div class="video_nav_r play_all_button" @click="addVideoPAndGoToVideoPlayer(compilationItem.id)">播放全部</div>
          <!-- 查看更多按钮 -->
          <div class="video_nav_r chack_more_button" @click="gotoCompilationChild(compilationItem.name,compilationItem.id)">查看更多</div>
        </div>
      </div>
      <!-- 视频列表 -->
      <div class="video_list"  v-if="compilation_Videolist[index]">
        <!-- 添加视频到合集 -->
        <div class="video_list_item1 add_video_compilation" v-if="showModel=='me'" @click="addVideoToCompilation(compilationItem.id)">
          <div class="add_icon">+</div>
          添加视频
        </div>
        <!-- 单个视频 -->
        <div class="video_list_item1" v-for="(videoItem,index) in compilation_Videolist[index].videoList" :key="videoItem.vid" @click="gotovideo(videoItem.vid)">
          <!-- 视频封面 -->
          <div class="video_list_item1_cover">
            <img :src=getImgURL(videoItem.coverAddress) alt="稿件封面">
          </div>
          <!-- 视频标题 -->
          <div class="video_list_item1_title">
            <span> {{ videoItem.title }} </span>
          </div>
          <!-- 视频信息 -->
          <div class="video_list_item1_msg">
            <!-- 视频播放量 -->
            <div>
              <svg class="play_video_icon" aria-hidden="true">
                <use xlink:href="#icon-shipin"></use>
              </svg>
              {{ videoItem.playedNum / 10000 > 1 ? videoItem.playedNum / 10000+"万": videoItem.playedNum}}
            </div>
            <!-- 视频发布日期 -->
            <div class="video_data_item recommend_date">
              {{ videoItem.publishTime? videoItem.publishTime.slice(0,10) :''}}
            </div>
          </div>
        </div>
      </div>
      <!-- 举牌序列帧动画 -->
      <div v-if="showModel=='me'" class="deleteGif" alt="删除" @click="deletedCompilation(compilationItem.id)"></div>
    </div>

    <!-- 添加视频到合集弹窗 -->
    <el-dialog
      title="添加视频"
      :visible.sync="dialogCompilationVisible"
      top="30vh"
      width="30%"
      :before-close="handleClose">
      <div>
        <form>
          <div style="font-size: 20px;">
            <div>选择要加入视频</div>
          </div>
          <!-- 选择要加入合集的视频列表 -->
          <ol style="height: 30vh; overflow-x: auto;" @scroll="scrollVideoList" ref="videoList">
            <!-- 单个视频元素 -->
            <li v-for="(item,index) in select_video_list" :key="item.vid">
              <div style="position: relative; width: 90%;">
                <!-- 视频 -->
                <div class="video_list_item1">
                  <!-- 视频封面 -->
                  <div class="video_list_item1_cover">
                    <img :src=getImgURL(item.coverAddress) alt="稿件封面">
                  </div>
                  <!-- 视频标题 -->
                  <div class="video_list_item1_title">
                    <span class="video_title"> {{ item.title }} </span>
                  </div>
                  <!-- 视频信息 -->
                  <div class="video_list_item1_msg">
                    <!-- 播放量 -->
                    <div>
                      <svg class="play_video_icon" aria-hidden="true">
                        <use xlink:href="#icon-shipin"></use>
                      </svg>
                      {{ item.playedNum / 10000 > 1 ? item.playedNum / 10000+"万": item.playedNum}}
                    </div>
                    <!-- 发布日期 -->
                    <div class="video_data_item recommend_date">
                      {{ item.publishTime? item.publishTime.slice(0,10) :''}}
                    </div>
                  </div>
                </div>
                <!-- 选择框 -->
                <el-checkbox-group style="scale: 2; position: absolute; right: 0; top: 30%;" v-model="checkedCities" @change="handleCheckedCitiesChange">
                  <el-checkbox :label="item.vid">{{  }}</el-checkbox>
                </el-checkbox-group>
              </div>
            </li>
          </ol>
        </form>
      </div>
      <span slot="footer" class="dialog-footer">
        <el-button  @click="cancelAddVideo">取 消</el-button>
        <el-button  type="primary" @click="saveNewCompilation">确定</el-button>
      </span>
    </el-dialog>
    
    <!-- 合集没有数据提示 -->
    <div style="text-align: center;" v-if="compilation_list.length==0">
      <img src="/img/nollData.gif" alt="暂无数据" style="width: 100px;"><br>
      <span style="font-size: 16px;">暂无数据</span>
    </div>
  </div>
</template>

<script>
import { addVideoToCompilation, deleteCompilation, getAllCompilationVidList, getCompilationVidList, getExistVidByCompilationId } from '@/api/compilation';
import { countUserVideo, getUserVideoByPage, getVideo, getVideoByVid } from '@/api/video';

  export default{
    name:'SpaceCompilationHome',
    data(){
      return{
        // 是否展示添加界面
        dialogCompilationVisible: false,
        // 要添加的合集id
        compilationId:0,
        // 添加合集界面的选择视频列表
        select_video_list:[],
        // 排序条件
        condition:'publish_time',
        // 选择视频列表当前页面
        page:1,
        // 选择结果
        checkedCities: [],
        // 计时器
        timer:'',
        // 当前用户视频总数是
        videoTotal:0,
        
        // 合集种类列表
        compilation_list:[],
        // 合集视频列表
        compilation_Videolist:[],
      }
    },
    computed:{
      // 展示模式
      showModel() {
        return this.$store.state.spaceViewModel
      },
      // 用户空间状态信息
      spaceInfo(){
        // console.log(this.$store.state.spaceInfo);
        return this.$store.state.spaceInfo
      },
    },
    watch:{
      showModel(){
        // 展示模式改变时,重新渲染
        this.getVideoByVid()
      }
    },
    methods:{
      //------------------------------------------添加视频到合集-----------------------------------
      // 取消添加视频到合集
      cancelAddVideo(){
        this.dialogCompilationVisible = false
        this.$refs.videoList.scrollTop = 0
        this.page = 1
      },
      // 添加视频到指定合集
      addVideoToCompilation(id){
        // 展示界面
        this.dialogCompilationVisible = true
        // 记录要添加的目标合集id
        this.compilationId = id
        // 获取当前用户所有视频
        this.getAllVideoByPage()
        // 获取当前合集已有视频id集合
        this.getExistVidByCompilationId()
      },

      // 获取当前合集已有视频id集合
      async getExistVidByCompilationId(){
        let data = await getExistVidByCompilationId(this.compilationId)
        this.checkedCities = data
      },

      // 获取用户视频
      async getAllVideoByPage(){
        this.getSpaceUserCountNum()
        console.log(this.page);
        let data = await getUserVideoByPage(this.spaceInfo.uid, this.condition, `${this.page}`)
        this.page += 1
        this.select_video_list = data
      },
      
      // 根据空间用户uid获取用户视频稿件的数量
      async getSpaceUserCountNum(){
        let data = await countUserVideo(this.$store.state.spaceUserId)
        this.videoTotal = data
      },

      // 确认添加
      async saveNewCompilation(){
        console.log("确认添加");
        // 关闭界面
        this.dialogCompilationVisible = false

        // 拼接vid字符串
        let vidList = ""
        this.checkedCities.forEach((item)=>{
          vidList = vidList + item + ','
          // console.log(this.vidlist);
        })

        let temp = {
          "listId":"",
          "addTime":"",
        }
        temp.listId = this.compilationId
        temp.addTime = Date.now()

        // 发送添加视频请求
        let data = await addVideoToCompilation(vidList, temp);
        if (data == 1) {
          this.$message({
            type: 'success',
            message: '添加成功!'
          })
        }else{
          this.$message({
            type: 'error',
            message: '添加失败!'
          })
        }
      },

      // 滚动事件
      scrollVideoList(){
        console.log("没满");
        let scrollTop = event.target.scrollTop
        let clientHeight = event.target.clientHeight
        let scrollHeight = event.target.scrollHeight
        this.timer = ''
        if (scrollTop + clientHeight + 30 >= scrollHeight){
          console.log("调用添加视频");
          // 当前获取到的视频总数小于用户所有视频总数，调用后端分页获取视频信息
          if( this.select_video_list.length < this.videoTotal){
            this.addVideoToSelectVideoList()
          }
        }
      },

      // 滚到底部时调用添加视频
      async addVideoToSelectVideoList(){
        // 有计时器时
        if(this.timer){
          // 清除计时器
          clearTimeout(this.timer)
          // 重新计时
          this.timer = setTimeout(async ()=>{
            let data = await getUserVideoByPage(this.spaceInfo.uid, this.condition, `${this.page}`)
            this.page = this.page + 1
            let temp = data
            temp.forEach((item)=>{
              this.select_video_list.push(item)
            })
          },500)
        }
        // 首次执行
        if(!this.timer){
          let data = await getUserVideoByPage(this.spaceInfo.uid, this.condition, `${this.page}`)
          this.page = this.page + 1
          let temp = data
          temp.forEach((item)=>{
            this.select_video_list.push(item)
          })
          console.log(this.select_video_list);
          // // 设置1s空计时器
          // this.timer = this.timer = setTimeout(()=>{
          // },500)
        }
      },

      // 弹窗点击关闭时提示
      handleClose(done) {
        this.$confirm('确认关闭？')
          .then(_ => {
            this.cancelAddVideo()
            done();
          })
        .catch(_ => {});
      },

      // 选择框点击值变化时调用
      handleCheckedCitiesChange(value) {
        console.log(this.checkedCities);
      },
      //------------------------------------------添加视频到合集----------------------------------- 


      // 删除合集提示
      deletedCompilation(id) {
        this.$confirm('确定删除这个合集吗？', '提示', {
          confirmButtonText: '确定',
          cancelButtonText: '取消',
          type: 'warning'
        }).then(() => {
          this.acceptDeletedCompilation(id)
        })
      },

      // 确认删除合集
      async acceptDeletedCompilation(id){
        console.log("删除");
        let data = await deleteCompilation(id);
        if (data == 1) {
          this.$message({
            type: 'success',
            message: '删除成功!'
          });
        }else{
          this.$message({
            type: 'error',
            message: '删除失败!'
          });
        }
      },
      
      // 前往合集详情界面
      gotoCompilationChild(name,id){
        // console.log(compilation);
        // console.log(e.target.innerText);
        this.$store.dispatch('changeCompilationTitle', `合集 · ${name}`)
        this.$store.dispatch('changeCompilationId', id)
        // console.log(this.$store.state.compilation);
        this.$router.push({
          path:'/space/compilation/child',
        })
      },

      //视频跳跃
      gotovideo(videoid){
        this.$router.push({
          path:'/video', 
          query:{
            vid:videoid
          }
        })
      },

      // 播放指定合集全部视频
      addVideoPAndGoToVideoPlayer(compilation_id){
        console.log(compilation_id);
        this.$router.push({
          path:'/video', 
          query:{
            havePList:true,
            from:'compilation',
            id:compilation_id
          }
        })
      },

      // -------------------------------------------初始化---------------------------------------
      // for循环获取单个合集视频
      async getVideoByVid(){
        this.compilation_Videolist = []
        for (let i = 0; i < this.compilation_list.length; i++) {
          // console.log(this.compilation_list[i].vidList.length);
          // 创建对象
          let obj = { compilation_id : i, videoList : [] }
          if(this.compilation_list[i].vidList.length>0){
            // 当前是自己访问 截取前5个
            if(this.$store.state.spaceViewModel =='me'){
              // slice 不改变原数组，返回新的截取后拿到的数组
              var temp = this.compilation_list[i].vidList.slice(0,5)
              //遍历数组的视频id取获取视频信息
              for (let j = 0; j < temp.length; j++){
                let data = await getVideoByVid(temp[j].vid)
                obj.videoList.push(data)
              }
              // temp.forEach(item => {
              //   axios.get("/video/" + item.vid)
              //     .then((res)=>{
              //       obj.videoList.push(res.data.data)
              //     })
              // });
            }
            // 当前是其他人访问 截取前6个
            else if(this.$store.state.spaceViewModel =='other'){
              var temp = this.compilation_list[i].vidList.slice(0,6)
              //遍历数组的视频id取获取视频信息
              for (let j = 0; j < temp.length; j++){
                let data = await getVideoByVid(temp[j].vid)
                obj.videoList.push(data)
              }
              // temp.forEach(item => {
              //   axios.get("/video/" + item.vid)
              //     .then((res)=>{
              //       obj.videoList.push(res.data.data)
              //     })
              // });
            }
          }
          this.compilation_Videolist.push(obj)
        } 
        // console.log(this.compilation_Videolist); 
      },

      // 请求所有合集数据  一页18个，判断当前访问模式将截取结果前5个或者6个
      // 根据uid获取合集列表vid
      async getCompilationVidList(){
        let data = await getAllCompilationVidList(this.$store.state.spaceUserId)
        this.compilation_list = data
        // console.log(this.compilation_list);
        this.getVideoByVid()
      },
      // -------------------------------------------初始化---------------------------------------
      
      // 获取视频封面url
      getImgURL(address){
        return getVideo(address);
      },
    },
    created(){
      this.getCompilationVidList()
    },
    mounted(){
      console.log(this.showModel);
    }
  }
</script>

<style scoped>
  /* 视频播放图标 */
  .play_video_icon{
    width: 1em;
    height: 1em;
    vertical-align: -0.1em;
    fill: currentColor;
    overflow: hidden;
  }

  /* 合集内容区 */
  .compilation_content{
    background-color: white;
    border-radius: 5px;
    position: relative;
    margin-top: 20px;
  }

  /* 用户合集视频 */
  .video_compilation_item{
    margin: 20px 10px 10px 0px;
    padding-top: 10px;
  }

  /* 单个视频合集列表 */
  .video_compilation{
    position: relative;
    margin-bottom: 20px;
    border-bottom: 1px solid rgb(230, 230, 230);
  }

  /* 合集导航 */
  .user_video_nav{
    display: flex;
    width: 100%;
    position: relative;
    justify-content: space-between;
  }

  
  .user_video_nav_r{
    display: flex;
  }
  .user_video_nav_l{
    display: flex;
    align-items: center;
  }
  .video_nav_item1{
    display: inline-block;
    cursor: pointer;
  }
  /* 合集内容数 */
  .compilation_title_num{
    margin-left: 10px; 
    font-size: 12px;
    color: gray;
    background-color: rgb(240, 240, 240);
    border-radius: 10px; padding: 2px 6px;
  }
  /* 删除按钮 */
  .deleted_button{
    border: 1px solid rgb(255, 0, 0);
    color: rgb(255, 0, 0);
    border-radius: 5px;
    margin-right: 10px;
    line-height: 30px;
    padding: 0 10px;
  }
  /* 查看更多按钮 */
  .chack_more_button{
    border: 1px solid gray;
    color: gray;
    border-radius: 5px;
    margin-left: 10px;
    line-height: 30px;
    padding: 0 10px;
  }
  /* 播放全部按钮 */
  .play_all_button{
    border: 1px solid gray;
    color: gray;
    border-radius: 5px;
    line-height: 30px;
    padding: 0 10px;
  }
  .deleted_button,.play_all_button,.chack_more_button{
    font-size: 12px;
  }
  .deleted_button:hover,.play_all_button:hover,.chack_more_button:hover{
    cursor: pointer;
    color: #00a1d6;
    border: 1px #00a1d6 solid;
  }

  /* 合集名称 */
  .video_nav_title{
    display: inline-block;
    font-size: 20px;
    line-height: 20px;
    margin-right: 20px;
    cursor: pointer;
  }

  /* 合集总数 */
  .compilation_item_totalNum{
    font-size: 12px;
    color: gray;
    background-color: rgb(240, 240, 240);
    border-radius: 10px; 
    padding: 2px 6px;
  }

  /* 视频左边导航 */
  .video_nav_l{
    margin-right: 10px;
    cursor: pointer;
  }

  /* 视频列表 */
  .video_list{
    display: flex;
    flex-wrap: wrap;
    margin-bottom: 30px;
  }

  /* 单个视频 */
  .video_list_item1{
    width: 203px;
    margin-right: 20px;
    margin-top: 20px;
    cursor: pointer;
  }

  /* 视频信息 */
  .video_list_item1_msg{
    font-size: 12px;
    color: gray;
    display: flex;
    justify-content: space-between;
    margin-top: 10px;
  }

  /* 视频封面 */
  .video_list_item1 img{
    width: 100%;
    height: 140px;
    border-radius: 5px;
  }

  /* 视频标题 */
  .video_list_item1_title{
    font-size: 14px;
    height: 40px;
    overflow: hidden;
  }

  /* 添加合集 */
  .add_video_compilation{
    border: 2px dashed rgb(216, 216, 216);
    height: 140px;
    border-radius: 5px;
    text-align: center;
    margin-right: 20px;
  }

  /* 添加合集的图标 */
  .add_icon{
    font-size: 60px;
    perspective: 500px;
  }
  /* 添加合集悬浮样式 */
  .add_video_compilation:hover{
    cursor: pointer;
    color: #00a1d6;
  }

  /* 样式旋转动画 */
  @keyframes hover-anim{
    0%{transform: rotateY(0deg)}
    100%{transform: rotateY(180deg)}
  }

  /* 悬浮合集时 添加合集图标的动画 */
  .add_video_compilation:hover .add_icon{
    animation: hover-anim 1s ease;
  }

  /* 删除合集gif展示动画 */
  @keyframes delete-anim {
    0%{background-position: 0 0;}
    100%{background-position: -1218px 0;}
  }

  /* gif动画 */
  .deleteGif{
    cursor: pointer; 
    position: absolute; 
    width: 174px;
    height: 200px;
    right: 0; 
    top: 30%; 
    scale: 0.6;
    translate: 55px 0;
    background-image: url(../assets/images/删除序列帧.png);
    display: none;
  }
  /* 单个合集悬浮时展示gif动画 */
  .video_compilation:hover .deleteGif{
    display: block;
    animation: delete-anim 0.8s steps(7, start) forwards;
  }
</style>