<!-- 
  项目：Elyden.com
  创建时间：2023.03.20
  上次更新时间：2024.03.20
  组件名称：searchResultPage
  此文件负责的板块：搜索结果
    功能：
      1、分页展示搜索结果
      2、筛选搜索结果
  -->
<template>
  <div class="searchResultPage">
    <!-- 顶部导航组件 -->
    <HeaderNav initNav="white"></HeaderNav>
    <!-- 空内容，占位顶替导航栏空位 -->
    <div class="nulldiv"></div>
    <div class="pageComment">
      <!-- 搜索内容分类 -->
      <div class="classNav">
        <!-- 分类列表 -->
        <ol class="nav_list">
          <!-- 视频 -->
          <li>
            <span class="classNav_item">视频</span>
            <span class="calss_num">99+</span>
          </li>
          <!-- 直播 -->
          <li>
            <span class="classNav_item">直播</span>
            <span class="calss_num">12</span>
          </li>
          <!-- 文章 -->
          <li>
            <span class="classNav_item">文章</span>
            <span class="calss_num">1</span>
          </li>
          <!-- 用户 -->
          <li>
            <span class="classNav_item">用户</span>
            <span class="calss_num">2</span>
          </li>
          <!-- 滑动条 -->
          <li><div class="slider_bar"></div></li>
        </ol>
      </div>
      <!-- 筛选列表 -->
      <div class="orderByNav" @change="setVideoClass()">
        <!-- 以什么属性排序 -->
        <ol class="order_by_nav_list">
          <li>
            <!-- <span id="active">综合排序</span> -->
            <input type="radio" id="all" name="orderBy" value="vid" v-model="classify.orderBy" style="display: none;" > 
            <label class="checkBox" id="active" for="all" ref="fistNav" @click="changeClass">综合排序</label>
          </li>
          <li>
            <!-- <span>最多播放</span> -->
            <input id="play" type="radio" name="orderBy" value="played_num" v-model="classify.orderBy" style="display: none;">
            <label for="play" class="checkBox" @click="changeClass">最多播放</label>
          </li>
          <li>
            <!-- <span>最多付费</span> -->
            <input id="pay" type="radio" name="orderBy" value="vid" v-model="classify.orderBy" style="display: none;">
            <label for="pay" class="checkBox" @click="changeClass">最多付费</label>
          </li>
          <li>
            <!-- <span>最新发布</span> -->
            <input id="publish" type="radio" name="orderBy" value="publish_time" v-model="classify.orderBy" style="display: none;">
            <label for="publish" class="checkBox" @click="changeClass">最新发布</label>
          </li>
          <li>
            <!-- <span>最多评论</span> -->
            <input id="comment" type="radio" name="orderBy" value="comments" v-model="classify.orderBy" style="display: none;">
            <label for="comment" class="checkBox" @click="changeClass">最多评论</label>
          </li>
          <li>
            <!-- <span>最多弹幕</span> -->
            <input id="incomment" type="radio" name="orderBy" value="incomment" v-model="classify.orderBy" style="display: none;">
            <label for="incomment" class="checkBox" @click="changeClass">最多弹幕</label>
          </li>
          <li>
            <!-- <span>最多收藏</span> -->
            <input id="collection" type="radio" name="orderBy" value="collection" v-model="classify.orderBy" style="display: none;">
            <label for="collection" class="checkBox" @click="changeClass">最多收藏</label>
          </li>
          <li>
            <!-- <span>最多分享</span> -->
            <input id="share" type="radio" name="orderBy" value="share" v-model="classify.orderBy" style="display: none;">
            <label for="share" class="checkBox" @click="changeClass">最多分享</label>
          </li>
        </ol>
        <!-- 视频时长列表 -->
        <ol class="video_time_nav_list">
          <li>
            <!-- <span id="active">全部时长</span> -->
            <input id="time_1" type="radio" name="videoTime" value="00:00:00,00:00:00" v-model="classify.timeLong" style="display: none;">
            <label for="time_1" class="checkBox" id="active">全部时长</label>
          </li>
          <li>
            <!-- <span>10分钟以下</span> -->
            <input id="time_2" type="radio" name="videoTime" value="00:00:00,00:10:00" v-model="classify.timeLong" style="display: none;">
            <label for="time_2" class="checkBox">10分钟以下</label>
          </li>
          <li>
            <!-- <span>10分钟-30分钟</span> -->
            <input id="time_3" type="radio" name="videoTime" value="00:10:00,00:30:00" v-model="classify.timeLong" style="display: none;">
            <label for="time_3" class="checkBox">10分钟-30分钟</label>
          </li>
          <li>
            <!-- <span>10分钟-30分钟</span> -->
            <input id="time_4" type="radio" name="videoTime" value="00:30:00,00:60:00" v-model="classify.timeLong" style="display: none;">
            <label for="time_4" class="checkBox">30分钟-60分钟</label>
          </li>
          <li>
            <!-- <span>60分钟以上</span> -->
            <input id="time_4" type="radio" name="videoTime" value="00:60:00,max" v-model="classify.timeLong" style="display: none;">
            <label for="time_4" class="checkBox">60分钟以上</label>
          </li>
        </ol>
        <!-- 视频所属分类列表 -->
        <ol class="video_class_nav_list">
          <li>
            <!-- <span id="active">全部分区</span> -->
            <input id="class_1" type="radio" name="videoClass" value="vid" v-model="classify.videoClass" style="display: none;">
            <label for="class_1" class="checkBox" id="active">全部分区</label>
          </li>
          <li>
            <!-- <span>计算机</span> -->
            <input id="class_2" type="radio" name="videoClass" value="计算机" v-model="classify.videoClass" style="display: none;">
            <label for="class_2" class="checkBox">计算机</label>
          </li>
          <li>
            <!-- <span>历史</span> -->
            <input id="class_3" type="radio" name="videoClass" value="历史" v-model="classify.videoClass" style="display: none;">
            <label for="class_3" class="checkBox">历史</label>
          </li>
          <li>
            <!-- <span>生物</span> -->
            <input id="class_4" type="radio" name="videoClass" value="生物" v-model="classify.videoClass" style="display: none;">
            <label for="class_4" class="checkBox">生物</label>
          </li>
          <li>
            <!-- <span>美食</span> -->
            <input id="class_5" type="radio" name="videoClass" value="美食" v-model="classify.videoClass" style="display: none;">
            <label for="class_5" class="checkBox">美食</label>
          </li>
          <li>
            <!-- <span>纪录片</span> -->
            <input id="class_6" type="radio" name="videoClass" value="纪录片" v-model="classify.videoClass" style="display: none;">
            <label for="class_6" class="checkBox">纪录片</label>
          </li>
          <li>
            <!-- <span>科技</span> -->
            <input id="class_7" type="radio" name="videoClass" value="科技" v-model="classify.videoClass" style="display: none;">
            <label for="class_7" class="checkBox">科技</label>
          </li>
          <li>
            <!-- <span>军事</span> -->
            <input id="class_8" type="radio" name="videoClass" value="军事" v-model="classify.videoClass" style="display: none;">
            <label for="class_8" class="checkBox">军事</label>
          </li>
          <li>
            <!-- <span>生活</span> -->
            <input id="class_9" type="radio" name="videoClass" value="生活" v-model="classify.videoClass" style="display: none;">
            <label for="class_9" class="checkBox">生活</label>
          </li>
        </ol>
      </div>
      <!-- 筛选过的视频展示列表 -->
      <div class="videoList">
        <!-- 单个视频 -->
        <div class="video-item" v-for="(item, index) in videoList" @click="gotovideo(item.vid)">
          <!-- 视频封面 -->
          <img :src=getImgURL(item.coverAddress) alt="搜索内容">
          <!-- 视频标题 -->
          <div class="video-title">{{ item.title }}</div>
          <!-- 视频信息 -->
          <div class="video-foot">
            <!-- 作者图标 -->
            <svg-icon iconname="icon-zuozhe" class="icon-nav"></svg-icon>
            <!-- 作者名称 -->
            <span class="video-creater">{{ item.user.uName }}</span>  
            <!-- 发布日期 -->
            <span class="video-date">{{ item.publishTime.slice(0,10) }}</span>
          </div>
        </div>
      </div>
      <!-- 分页导航 -->
      <div class="pageNav" v-if="state">
        <el-pagination
          @size-change="handleSizeChange"
          @current-change="handleCurrentChange"
          :hide-on-single-page="true"
          :current-page="currentPage"
          :page-size="pageSize"
          layout="prev, pager, next, jumper"
          :total="total">
        </el-pagination>
      </div>
    </div>
    <!-- 底部组件 -->
    <MyFooter></MyFooter>
  </div>
</template>

<script>
import { getVideo, searchOrder } from '@/api/video';
import HeaderNav from './HeaderNav.vue';
import MyFooter from './MyFooter.vue'

  export default{
    name:'searchResultPage',
    components:{
      HeaderNav,
      MyFooter,
    },
    watch: {
    // 页面返回上一个页面，刷新，自动播放
      $route(to, from) {
        // console.log(from);
        // console.log(to);
        if(from.fullPath == '/update'){
          // location.reload()
          this.classify.searchContent = this.$route.query.searchContent
          console.log(this.classify.searchContent);
          this.setVideoClass()
        }
      },
    }, 
    data(){
      return{
        // 渲染信号，获取数据后开启
        state:false,

        // 一页42个 7行6列
        videoList:[],
        // 总数据个数
        total:0,
        // 搜索内容
        searchContent:'',
        // 当前页
        currentPage:'',
        // 一页最大数
        pageSize:'',
        // 选择分类
        classify:{
          // 视频推荐算法(composite)：时长（min）30%+四连70%
          "orderBy":"composite", // 以什么属性排序 desc默认
          "timeLong":"00:00:00,00:00:00", //,截取判断
          "videoClass":"",  // 模糊查询label
          "searchContent":"",
          "page":"1"
        },

        // 当前活动选项
        fist_active_nav:'',
      }
    },
    methods:{
      // 点击设置筛选条件获取视频列表
      async setVideoClass(page = 1){
        console.log(page);
        console.log(this.classify.orderBy);
        console.log(this.classify.timeLong);
        console.log(this.classify.videoClass);
        
        // this.classify.searchContent = this.$store.state.searchContent
        // console.log(this.classify.searchContent);
        if (page){
          console.log( JSON.stringify(page));
          this.classify.page = JSON.stringify(page)
        }
        console.log(this.classify);
        let data = await searchOrder(this.classify);
        if (data) {
          this.videoList = data.videoList
          this.total = data.totalSize
          this.currentPage = data.nowPage
          this.pageSize = data.pageSize
          this.state = true
        }
      },

      // 点击分类活动样式修改
      changeClass(){
        console.log(1);
        if (this.fist_active_nav == '') {
          this.fist_active_nav = this.$refs.fistNav
        }
        this.fist_active_nav.style.color = 'gray'
        this.fist_active_nav.style.backgroundColor = 'white'
        console.log(event.target);
        event.target.style.color = '#00a1d6'
        event.target.style.backgroundColor = '#dff6fd'
        this.fist_active_nav = event.target
      },

      //视频跳跃
      gotovideo(videoid){
        this.$router.push({
          path:'/video', 
          query:{
            vid:videoid
          }
        })
      },

      // 分页每页条数改变时触发
      handleSizeChange(val) {
        console.log(`每页 ${val} 条`);
      },
      // 分页当前页面改变时触发
      handleCurrentChange(val) {
        // console.log(`当前页: ${val}`);
        // this.getVideoListByPage(val)
        // 获取视频
        this.setVideoClass(val)
      },

      // （废弃）分页获取视频列表 模糊查询 param传参
      // getVideoListByPage(page){
      //   if(!page){
      //     page = 1
      //   }
      //   axios.get("/video" + `?search=${this.searchContent}` + `&page=${page}`)
      //     .then((res)=>{
      //       console.log(res);
      //       this.videoList = res.data.data.videoList
      //       this.total = res.data.data.totalSize
      //       this.currentPage = res.data.data.nowPage
      //       this.pageSize = res.data.data.pageSize
      //       this.state =true
      //       console.log(this.videoList);
      //     })
      // },

      // 获取视频封面url
      getImgURL(address){
        return getVideo(address)
      },
    },
    created(){
      // 获取想要搜索的内容
      // this.searchContent = this.$route.query.searchContent
      this.classify.searchContent = this.$route.query.searchContent
      // 提交当前搜索内容，在搜索栏提示搜索显示
      this.$store.dispatch('searchContent',this.searchContent)
      // 获取内容
      // this.getVideoListByPage()
      this.setVideoClass()
    },
  }
</script>

<style scoped>
  /* 页面整体的样式 */
  .searchResultPage{	
    background-color: white;
  }
  /* 占位div */
  .nulldiv{
    height: 100px;
  }
  /* 内容区宽度 */
  .pageComment{
    width: 80%;
    margin: 0 auto;
  }
  /* 分类导航 */
  .classNav{
    position: relative;
    margin-bottom: 10px;
    height: 50px;
    line-height: 50px;
    border-bottom: 1px solid rgb(234, 234, 234);
  }
  /* 导航列表 */
  .nav_list{
    display: flex;
    font-size: 20px;
    color: gray;
  }
  /* 搜索类型单个元素 */
  .nav_list li{
    margin-right: 30px;
    cursor: pointer;
  }
  /* 分类导航单个 */
  .classNav_item{
    font-size: 20px;
    padding: 10px 0px;
    color: gray;
  }
  /* 悬浮样式 */
  .classNav_item:hover{
    color: #00a1d6;
    cursor: pointer;
  }
  /* 分类所属数字 */
  .calss_num{
    background-color: #eeeeee;
    font-size: 12px;
    padding: 0px 5px;
    border-radius: 10px;
  }
  /* 活动条 */
  .slider_bar{
    height: 2px;
    width: 40px;
    position: absolute;
    background-color: #00a1d6;
    left: 0;
    bottom: 0;
    border-radius: 2px;
  }

  /* 
    详细分类区域
  */
  /* 分类筛选列表 */
  .orderByNav{
    background-color: rgb(255, 255, 255);
    margin-top: 50px;
  }
  /* 3个分类的列表 */
  .order_by_nav_list,.video_time_nav_list,.video_class_nav_list{
    display: flex;
    margin: 30px 00;
  }
  /* 列表元素 */
  .order_by_nav_list span,.video_time_nav_list span,.video_class_nav_list span{
    font-size: 14px;
    margin-right: 30px;
    color: gray;
    padding: 10px 15px;
    border-radius: 10px;
  }
  /* 点击选择的label */
  .checkBox{
    font-size: 14px;
    margin-right: 30px;
    color: gray;
    padding: 10px 15px;
    border-radius: 10px;
  }
  .checkBox:hover{
    cursor: pointer;
    color: #00a1d6;
  }

  .order_by_nav_list li,.video_time_nav_list li,.video_class_nav_list li{
    cursor: pointer;
  }

  .order_by_nav_list span:hover,.video_time_nav_list span:hover,.video_class_nav_list span:hover{
    color: #00a1d6;
  }

  #active{
    color: #00a1d6;
    background-color: #dff6fd;
  }

  /* 
    视频列表区域
  */
  img{
    width:100%;
    height: 180px;
    border-radius: 10px;
  }
  /* 视频列表 */
  .videoList{
    display: flex;
    flex-wrap: wrap;
  }

  /* 单个视频 */
  .video-item{
    width: 250px;
    margin-right: 12px;
    margin-bottom: 30px;
    cursor: pointer;
  }
  /* 推荐的视频的标题 */
  .video-title{
    max-height: 41px;
    overflow: hidden;
  }
  /* 视频底部信息区 */
  .video-foot{
    font-size: 12px;
    color: gray;
  }

  /* 视频的创作者 */
  .video-creater{
    margin-right: 10px;
  }
  /* 推荐视频的日期 */
  .video-date{
    
  }

  .video-foot:hover{
    color: #00a1d6;
  }

  /* 
    分页导航栏
  */
  .pageNav{
    margin: 0 auto;
    text-align: center;
  }
</style>