    // 文本换行函数
    // 将字符串中的中文视为2个字符位，英文1个字符位，间隔一定位置换行
    getNewline(val, onlineMax) {
      let str = new String(val);
      let bytesCount = 0;
      let s = "";
      for (let i = 0, n = str.length; i < n; i++) {
          let c = str.charCodeAt(i);
          // 统计字符串的字符长度
          if ((c >= 0x0001 && c <= 0x007e) || (0xff60 <= c && c <= 0xff9f)) {
              bytesCount += 1;
          } else {
              bytesCount += 2;
          }
          // 换行
          s += str.charAt(i);
          if (bytesCount >= onlineMax * 2) {
              s = s + '\n';
              // 重置
              bytesCount = 0;
          }
      }
      return s;
    },

