        // this.Elysia.state.setAnimation(0, 'idle', true)
        // // 刷新
        
      }, 3000);
    },
    // 文字渐显动画
    ll(){
      // 文本拆分span标签
      this.$refs.result.innerHTML = text.replace(/\S/g,"<span>$&</span>")

      // 文字动画
      gsap.fromTo('.result span',{
          opacity: 0
        },
        {
          opacity: 1,
          stagger: .1
        })      
    },

    // 提交请求给本机的ChatGML服务器进程
    create_chat_completion(model, messages, functions, use_stream){
      let data = {
        functions: functions,  // 函数定义        空
        model: model,  // 模型名称              固定为'chatgml3-6b'  
        messages: messages,  // 会话历史        
        stream: use_stream,  // 是否流式响应     
        max_tokens: 100,  // 最多生成字数
        temperature: 0.8,  // 温度
        top_p: 0.8,  // 采样概率
        
      }

      if (use_stream) {
        // this.h1(data)
        this.h2(data, use_stream)
      }
      else{
        this.h2(data, use_stream)
      }
      console.log(data);
    },

    // 初始化提问的数据结构  demo的简单提问方式
    submittedCot(){
      // 提问的内容
      console.log(this.searchContent);

      // 创建数据
      // 函数为空，不知道怎么写，应该类似于提问关键词
      let functions = null
      // 聊天信息封装
      let chat_messages = [
        {
            "role": "system",
            "content": "You are ChatGLM3, a large language model trained by Zhipu.AI. Follow the user's instructions carefully. Respond using markdown.",
        },
        {
            "role": "user",
            "content": `${this.searchContent}`
        }
      ]
      // 发起请求方法                 模型名称        聊天信息   方法，这里为空 是否流式输出
      this.create_chat_completion("chatglm3-6b", chat_messages, functions, true)
    },
  }
}
</script>
  
