  创建时间：2024.05.15
  上次更新时间：2024.05.15
  组件名称：Error4XX
  此文件负责的板块：前端错误界面
    功能：
      1、前端错误跳转到此界面
  -->

<template>
  <div>
    <div id="Game"></div>
    <div class="errorNotice" style="font-size: 20px; position: absolute; left: 20%;">
      <!-- <img class="nollDataImg" src="../images/nollData.gif" alt="出错了"> -->
      <span>Error出错了</span>
      <div style="text-align: left; color: gray;">
        <span style="font-size: 14px;">错误码：{{$route.query.code}}</span><br>
        <span style="font-size: 14px;">错误信息：{{ $route.query.message }}</span><br>
        <span style="color: black;">还有 {{ goToMainPageTime }} s，自动跳转首页...</span>
        <button @click="clearGoToMainTime" style="padding: 2px 4px; background-color: transparent; color: skyblue; cursor: pointer;">点击不跳转</button>
      </div>
    </div>
  </div>
</template>

<script>
// 导入pixi和spine
import * as PIXI from "pixi.js";
global.PIXI = PIXI;
require("pixi-spine");

export default{
  name:'Error4XX',
  data(){
    return{
      // 游戏区域大小
      GameWidth: 1000,
      GameHeight: 500,

      // 游戏角色
      aili: '',

      // 控制爬升的按键
      flyCode: "Space",

      // 是否开启游戏状态
      played: false,

      // 是否结束游戏状态
      IsGameOver: false,

      // 文字对象
      GameText: '',

      // 等待开始时间
      time: 3,

      // 游戏开始倒计时计时器
      timer: '',

      // 可通过缺口范围 
      max: 500,
      min: 200,

      // 当前缺口大小
      door: 300,

      // 缺口起始位置
      start: 100,

      // 上障碍物
      graphicsUp: '',

      // 下障碍物
      graphicsDown: '',

      // 分数
      score: 0,

      // Pixi对象
      app: '',

      // 跳转首页倒计时
      goToMainPageTime:5,
      mainPageTimer: '',
    }
  },
  methods:{
    // 初始化游戏
    init(){
      this.app = new PIXI.Application({
        // backgroundColor: 0xf1f2f3,   //背景色
        transparent: true,    //背景透明
        width: this.GameWidth,
        height: this.GameHeight,
      })

      // 添加舞台
      document.getElementById('Game').appendChild(this.app.view)

      // 创建开始游戏文字
      // 文字添加到舞台
      this.GameText = new PIXI.Text('开始游戏')
      // 锚点偏移
      this.GameText.anchor.set(0.5)
      // 居中
      this.GameText.x = this.app.screen.width / 2
      this.GameText.y = this.app.screen.height / 2 - 100
      // // 开启事件
      // GameText.interactive = true
      // // 绑定事件
      // GameText.on("click",()=>{
      //   console.log("开始");
      //   played = true
      // })
      this.GameText.visible = false
      this.app.stage.addChild(this.GameText)


      // 画上半障碍物
      this.graphicsUp = new PIXI.Graphics()
      // 填充色
      this.graphicsUp.beginFill(0xc1c2c3)
      // x,y位置,元素宽，高
      this.graphicsUp.drawRect(0, 0, 100, 100)
      // 锚点居中
      this.graphicsUp.transform.pivot.set(50, 50)
      // 因为锚点居中了，这里要偏移半宽，加上游戏区域，使其在右上方
      this.graphicsUp.x = this.app.screen.width + 50
      this.graphicsUp.y = 50
      this.app.stage.addChild(this.graphicsUp)


      // 画下半障碍物
      this.graphicsDown = new PIXI.Graphics()
      this.graphicsDown.beginFill(0xc1c2c3)
      this.graphicsDown.drawRect(0, 0, 100, 100)
      this.graphicsDown.transform.pivot.set(50, 50)
      // 移动到右边底部
      this.graphicsDown.x = this.app.screen.width + 50
      this.graphicsDown.y = this.app.screen.height - 50
      this.app.stage.addChild(this.graphicsDown)

  
      // 加载角色图片
      let baseTexture = PIXI.BaseTexture.from('/img/flyAnim.png')

      // 创建角色纹理，区域裁剪
      const roleTexture = new PIXI.Texture(
        baseTexture,
        new PIXI.Rectangle(0, 0, 149, 226)
      )

      // 创建角色精灵
      // aili = new PIXI.Sprite(roleTexture)
      // app.stage.addChild(aili);

      // 创建帧动画
      let flyAnimTextureArray = []

      // 图片加入
      for(let i = 0;  i < 12; i++){
        flyAnimTextureArray.push(
          new PIXI.Texture(
            baseTexture,
            new PIXI.Rectangle(149*i, 0, 149, 226)
          )
        )
      }
      // console.log(flyAnimTextureArray);

      // 创建动画精灵
      this.aili = new PIXI.AnimatedSprite(flyAnimTextureArray)
      this.aili.animationSpeed = 0.1
      this.aili.play()
      // console.log(aili);
      this.aili.scale.set(-0.4, 0.4)
      this.aili.x = this.app.screen.width / 2 ;
      this.aili.y = this.app.screen.height - 45 ;
      // aili.x = 0 ;
      // aili.y = 0 ;
      this.aili.transform.pivot.set(70, 120)

      this.app.stage.addChild(this.aili)

      this.aili.interactive = true
      this.aili.on("click",()=>{
        console.log("开始");
        this.played = true
      })

      // 当前角色状态
      let keys = {
        // 跳跃上升
        up: false,
        // 向下
        down: true
      };

      // 窗体添加键盘事件
      // 按下空格起飞
      window.addEventListener("keydown",(e) => {
        if (e.code === this.flyCode){
          // console.log("爬升");
          keys.up = true
          keys.down = false
        }
      })
      // 松手空格下降
      window.addEventListener("keyup",(e) => {
        if (e.code === this.flyCode){
          // console.log("下降");
          keys.up = false
          keys.down = true
        }
      })

      // update函数
      this.app.ticker.add(() =>{
        // 游戏结束退出
        if (this.IsGameOver) return

        // 开始游戏倒计时
        if (this.played && this.timer == '') {
          this.GameText.visible = true
          this.GameText.text = this.time
          this.timer = setInterval(() => {
            this.GameText.text = this.time -1
            this.time -= 1
            if (this.time == 0){
              this.GameText.text = "GO!" 
              return
            }
          }, 1000);
        }
        
        // 开始游戏
        if (this.time <= -1) {
          clearInterval(this.timer)
          // this.timer = ''
          // app.stage.removeChild(text2)
          this.GameText.y = 20
          this.GameText.x = this.app.screen.width / 2
          this.GameText.text = this.score
          // 障碍移动速度加快
          this.graphicsUp.x -= this.score / 2 > 1 ? this.score / 2 + 2 : 2
          // 障碍物移动
          this.graphicsDown.x -= this.score / 2 > 1 ? this.score / 2 + 2 : 2

          if (this.graphicsUp.x < - 50) {
            // 障碍物移除显示区域，分数加1
            this.score += 1
            // 生成新缺口
            this.create()
          }

          // 判断是否碰撞  两个物体的中心原点的x距离小于两个物体半宽和  （json动画）
          // if ((Math.abs(aili.x - graphicsUp.x) < 12.5 + 50 && Math.abs(aili.y - graphicsUp.y) < start / 2 + 70)||(Math.abs(aili.x - graphicsDown.x) < 12.5 + 50 && Math.abs(aili.y - graphicsDown.y ) < (500 - start - door) / 2 + 20 )){
          //     console.log("asdsad");
          //     // 碰撞
          //     // gameOver()
          //     IsGameOver = true
          // }
          // 判断是否碰撞  两个物体的中心原点的x距离小于两个物体半宽和   （序列帧动画）
          if ((Math.abs(this.aili.x - this.graphicsUp.x) < 25 + 50 && Math.abs(this.aili.y - this.graphicsUp.y) < this.start / 2 + 45)||(Math.abs(this.aili.x - this.graphicsDown.x) < 25 + 50 && Math.abs(this.aili.y - this.graphicsDown.y ) < (500 - this.start - this.door) / 2 + 45 )){
            console.log("碰撞");
            // 碰撞
            this.gameOver()
            // IsGameOver = true
          }

          // 按下空格
          if (keys.down){
            this.aili.y += this.score / 2 > 1 ? this.score / 2 + 2 : 2
          }

          // 松开空格
          if (keys.up){
            this.aili.y -= this.score / 2 > 1 ? this.score / 2 + 2 : 2
          }

          // 封底
          if (this.aili.y > this.app.screen.height -45){
            this.aili.y = this.app.screen.height -45
          }

          // 封顶
          if (this.aili.y < 45){
            this.aili.y = 45
          }
          // // 封底
          // if (aili.y > app.screen.height -10){
          //     aili.y = app.screen.height -10
          // }

          // // 封顶
          // if (aili.y < 70){
          //     aili.y = 70
          // }
        }
      });
    },

    // 游戏结束
    gameOver(){
      this.IsGameOver = true
      // 隐藏舞台角色
      this.aili.visible = false
      this.graphicsUp.visible = false
      this.graphicsDown.visible = false

      this.GameText.text = "游戏结束，得分" + this.score + ", 点击刷新"
      this.GameText.y = this.app.screen.height / 2
      this.GameText.interactive = true
      this.GameText.on("click",()=>{
        // 刷新界面，重新开始游戏
        location.reload()
      })
    },

    // 随机生成缺口
    create(){
      // 随机缺口大小
      this.door = Math.floor(Math.random() * (this.max - this.min + 1) + this.min);

      // 生成缺口起始点范围
      let startMax = this.max
      startMax -= this.door
      let startMin = this.min
      startMin = 0

      // 随机起始
      this.start = Math.floor(Math.random()  *(startMax - startMin + 1) + startMin);

      // 清除前面的图形，防止内存泄漏
      this.graphicsUp.clear()
      this.graphicsDown.clear()

      // 画上半障碍物
      this.graphicsUp = new PIXI.Graphics()
      this.graphicsUp.beginFill(0xc1c2c3)
      // x,y,宽，高
      this.graphicsUp.drawRect(0, 0, 100, this.start)
      this.graphicsUp.x = this.app.screen.width - 50
      this.graphicsUp.y = this.start / 2
      this.graphicsUp.transform.pivot.set(50, this.start / 2)
      this.app.stage.addChild(this.graphicsUp)

      // 画下半障碍物
      this.graphicsDown = new PIXI.Graphics()
      this.graphicsDown.beginFill(0xc1c2c3)
      // x,y,宽，高
      this.graphicsDown.drawRect(0, 0, 100, 500 - this.start - this.door)
      this.graphicsDown.x = this.app.screen.width - 50
      this.graphicsDown.y = this.app.screen.height - (500 - this.start - this.door) / 2
      this.graphicsDown.transform.pivot.set(50, (500 - this.start - this.door) / 2)
      this.app.stage.addChild(this.graphicsDown)

      console.log("开始" + this.start);
      console.log("大小" + this.door);
      console.log("底部"+ (500 - this.start - this.door));
    },
    
    // 清除计时器
    clearGoToMainTime(){
      clearInterval(this.mainPageTimer)
    },
  },
  mounted(){
    this.init()
    // 开启前往首页计时器
    this.mainPageTimer = setInterval(() => {
      this.goToMainPageTime -= 1
      if (this.goToMainPageTime == 0) {
        this.$router.push({
          path:'/'
        })
      }
    }, 1000);
  },
  destroyed(){
    clearInterval(this.mainPageTimer)
  }
}
</script>

<style>
  /* 出错gif图 */
  .nollDataImg{
    width: 100px;
    display: block;
    margin: 0 auto;
  }
  /* 游戏界面 */
  #Game{
    text-align: center;
  }
</style>