import request from '@/Request'

const baseUrl = "http://localhost:9000"

export {
  getVipIcon,
  getVipInfoById,
  



  
}

// 获取用户vip图标
function getVipIcon(address) {
  return baseUrl + address;
}

// 根据uid获取空间的设置信息
function  getVipInfoById(uid) {
  return request({
    method: 'get',
    url: "/vipType/" + uid,
  })
}