import request from '@/Request'

export {
  getHistoryByPage,
  isWatched,
  saveWatched,
  

}

// 分页获取历史观看记录
function  getHistoryByPage(page) {
  return request({
    method:'get',
    url:`/historyWatch/${page}`,
  })
}

// 判断是否观看过视频
function isWatched(vid, uid){
  return request({
    method: 'get',
    url: `/historyWatch/${vid}/${uid}`
  })
}

// 保存观看记录
function saveWatched(history){
  return request({
    method:'post',
    url:'/historyWatch/save',
    data:history
  })
}