import request from '@/Request'

export {
  getNoExamineNum,
  getExamineByPage,
  getSignUpNum,
  getHotVideoNum,
  getAllUserByPage,
  admitVideoContent,
  sendMessage,
  sendNoAdmitReasonToFromId,
  deleteVideo,
  deleteContent,
  deleteAddContent,
  deleteExamineById,
  deleteUser,
}

// 获取需要审核内容的数量
function getNoExamineNum() {
  return request({
    method:'get',
    url:'/admin/count',
  })
}

// 分页获取审核内容
function getExamineByPage(type, page){
  return request({
    method:'get',
    url:`/admin/examine/${type}/${page}`,
  })
}

// 分页获取用户信息
function getAllUserByPage(page){
  return request({
    method:'get',
    url:`/admin/allUser?page=${page}`,
  })
}

// 确认上架新视频，审核通过
function admitVideoContent(id, targetId){
  return request({
    method:'put',
    url:`/admin/video?id=${id}&targetId=${targetId}`,
  })
}

// 发送信息
function sendMessage(message){
  return request({
    method:'post',
    url:'/admin/message',
    data:message,
  })
}

// 发送审核不通过原因给制作者
function sendNoAdmitReasonToFromId(id, title, reason){
  return request({
    method:'put',
    url:`/admin/noAddmitVideo?id=${id}&title=${title}`,
    data: reason,
  })
}

// 下架视频
function deleteVideo(id, targetId){
  return request({
    method:'delete',
    url:`/admin/video?id=${id}&targetId=${targetId}`,
  })
}

// 下架父评论
function deleteContent(id, targetId){
  return request({
    method:'delete',
    url:`/admin/comment?id=${id}&targetId=${targetId}`,
  })
}

// 下架子评论
function deleteAddContent(id, targetId){
  return request({
    method:'delete',
    url:`/admin/addComment?id=${id}&targetId=${targetId}`,
  })
}

// 删除审核内容
function deleteExamineById(id){
  return request({
    method:'delete',
    url:`/admin/examine?id=${id}`,
  })
}

// 删除用户
function deleteUser(uid){
  return request({
    method:'delete',
    url:`/admin/user?targetUid=${uid}`,
  })
}

// 获取注册人数
function getSignUpNum(){
  return request({
    method:'get',
    url:'/admin/signUpNum',
  })
}

// 获取热门视频信息 
function getHotVideoNum(){
  return request({
    method:'get',
    url:'/admin/hotVideoNum',
  })
}