<!-- 
  项目：Elyden.com
  创建时间：2024.01.29
  上次更新时间：2023.05.11
  组件名称：SpaceSetting
  此文件负责的板块：用户空间设置板块
    功能：
      1、设置空间显示和隐藏内容（部分未完成）
      2、设置助手功能（部分未完成）
  -->
<template>
  <div class="space_setting_content">

    <!-- 空间设置 -->
    <div class="private">
      <div class="private_title">隐私设置</div>
      <div class="private_setting_list">
        <!-- 列表1 -->
        <ol class="private_setting_list_item list_1">
          <!-- 展示个人简介 -->
          <li>
            公开个性签名
            <el-switch
              v-model="space_set.isOpenSynopsis"
              active-color="#00a1d6"
              inactive-color="#ccd0d7">
            </el-switch>  
          </li>
          <!-- 展示会员 -->
          <li>
            公开会员图标
            <el-switch
              v-model="space_set.isOpenVip"
              active-color="#00a1d6"
              inactive-color="#ccd0d7">
            </el-switch>  
          </li>
          <!-- <li>
            公开粉丝勋章 
            <el-switch
              v-model="space_set.is_open_fan"
              active-color="#00a1d6"
              inactive-color="#ccd0d7">
            </el-switch>  
          </li> -->
          <!-- 展示生日 -->
          <li>
            公开生日
            <el-switch
              v-model="space_set.isOpenBirthday"
              active-color="#00a1d6"
              inactive-color="#ccd0d7">
            </el-switch>  
          </li>
        </ol>
        <!-- 列表2 -->
        <ol class="private_setting_list_item list_2">
          <!-- 展示收藏 -->
          <li>
            公开收藏
            <el-switch
              v-model="space_set.isOpenCollection"
              active-color="#00a1d6"
              inactive-color="#ccd0d7">
            </el-switch>  
          </li>
          <!-- 展示关注 -->
          <li>
            公开关注列表
            <el-switch
              v-model="space_set.isOpenFollow"
              active-color="#00a1d6"
              inactive-color="#ccd0d7">
            </el-switch>  
          </li>
          <!-- 展示粉丝 -->
          <li>
            公开粉丝列表
            <el-switch
              v-model="space_set.isOpenFan"
              active-color="#00a1d6"
              inactive-color="#ccd0d7">
            </el-switch>  
          </li>
          <!-- 展示点赞 -->
          <li>
            公开最近点赞列表
            <el-switch
              v-model="space_set.isOpenGoodVideo"
              active-color="#00a1d6"
              inactive-color="#ccd0d7">
            </el-switch>  
          </li>
          <!-- 展示献花 -->
          <li>
            公开最近献花列表
            <el-switch
              v-model="space_set.isOpenFlower"
              active-color="#00a1d6"
              inactive-color="#ccd0d7">
            </el-switch>  
          </li>
        </ol>
        <!-- 列表3 -->
        <ol class="private_setting_list_item list_3">
          <!-- <li>
            公开直播回放列表
            <el-switch
              v-model="value"
              active-color="#00a1d6"
              inactive-color="#ccd0d7">
            </el-switch>  
          </li> -->
          <!-- <li>
            公开收费专属视频
            <el-switch
              v-model="value"
              active-color="#00a1d6"
              inactive-color="#ccd0d7">
            </el-switch>  
          </li> -->
        </ol>
      </div>
    </div>
    <!-- 助手设置 -->
    <div class="helper_setting">
      <div class="helper_setting_title">助手设置</div>
      <div class="helper_setting_list">
        <!-- 列表1 -->
        <ol class="helper_setting_list_item list_1">
          <!-- 开启助手 -->
          <li>
            默认开启助手
            <el-switch
              v-model="helper_set.isOpenHelper"
              active-color="#00a1d6"
              inactive-color="#ccd0d7">
            </el-switch>  
          </li>
          <!-- 切换助手 -->
          <li>
            助手
            <select name="helper_dropdown">
              <option value="Elysia" selected>Elysia</option>
              <option value="topa">托帕</option>
            </select>
          </li>
          <!-- 助手装扮 -->
          <li>
            助手装扮
            <select name="helper_clothes_dropdown" v-model="helper_set.helperSkin">
              <option value="工作服" selected>工作服</option>
              <option value="学生服">学生服</option>
              <option value="摩托服">摩托服</option>
              <option value="礼服">礼服</option>
            </select>
          </li>
          <!-- 助手语音 -->
          <li>
            助手语音
            <el-switch
              v-model="value"
              active-color="#00a1d6"
              inactive-color="#ccd0d7">
            </el-switch>  
          </li>
          <!-- AI聊天模型 -->
          <li>
            助手大语言模型
            <select name="helper_dropdown">
              <option value="ai" selected>ChatGML3</option>
              <option value="ai">LLaMA2</option>
              <option value="ai">Qwen</option>
            </select>
          </li>
        </ol>
        <!-- 列表2 -->
        <ol class="helper_setting_list_item list_2">
          <!-- 助手动画速度 -->
          <li style="display: block;">
            动画播放速度
            <div>
              <el-slider v-model="helper_set.animSpeed" :max="1" :step="0.01"></el-slider>
            </div>
          </li>
          <!-- 助手语音大小 -->
          <li style="display: block;">
            语音大小
            <div>
              <el-slider v-model="voice_value" :max="1" :step="0.01"></el-slider>
            </div>
          </li>
        </ol>
        <!-- 列表3 -->
        <ol class="helper_setting_list_item list_3">
          <!-- 特殊动画频率 -->
          <li>
            特殊动画触发频率
            <select name="helper_dropdown">
              <option value="1" selected>1min/1次</option>
              <option value="2">2min/1次</option>
            </select>
          </li>
          <!-- 快捷功能 -->
          <li>
            快捷功能
            <select name="helper_dropdown">
              <option value="1" selected>上传文件</option>
            </select>
          </li>
        </ol>
      </div>
    </div>
  </div>
</template>

<script>
import { getUserHelperSetInfo, saveUserHelperSetInfo } from '@/api/helper';
import { getSpaceSetInfoByUid, saveSpaceSetting } from '@/api/space';

  export default{
    name: 'SpaceSetting',
    data(){
      return{
        value: true,
        voice_value: 0.5,
        space_set:{
          "uid":"",
          // 是否设置置顶推荐视频
          "isSetRecomment": "",
          // 置顶推荐vid
          "recommendVid": "",

          // 是否对外显示个人简介
          "isOpenSynopsis": false,
          // 是否对外显示vip图标
          "isOpenVip": false,
          // 是否对外显示生日
          "isOpenBirthday": false,
          // 是否对外显示收藏 
          "isOpenCollection": false,
          // 是否对外显示粉丝勋章
          // is_open_medal:'',
          // 是否对外显示关注表
          "isOpenFollow": false,
          // 是否对外显示粉丝表
          "isOpenFan": false,
          // 是否对外显示最近点赞内容
          "isOpenGoodVideo": false,
          // 是否对外显示最近献花内容
          "isOpenFlower": false,
          // 是否对外显示历史直播回放
          // "is_open_history_living":"",
        },
        helper_set:{
          "isOpenHelper":false,
          "uid":"",
          "helperSkin":"工作服",
          "animSpeed": 1,
        }
      }
    },
    computed:{
      // 用户空间状态信息
      spaceUserId(){
        // console.log(this.$store.state.spaceInfo);
        return this.$store.state.spaceUserId
      },
      spaceInfo(){
        return this.$store.state.spaceInfo
      }
    },
    watch:{
      helper_set:{
        handler(newVal, oldVal){
          // 提交vuex
          this.$store.dispatch('setHelper', this.helper_set)
        },
        // 监视里面属性
        deep:true
      },
      'helper_set.isOpenHelper':{
        handler(){
          // 提交vuex
          this.$store.dispatch('chanceshow', this.helper_set.isOpenHelper)
        }
      }
    },
    methods:{
      // 获取用户助手设置
      async getHelperSet(){
        let data = await getUserHelperSetInfo();
        this.helper_set = data
      },
      // 获取空间设置信息
      async getSpaceSet(){
        let data = await getSpaceSetInfoByUid(this.spaceUserId);
        this.space_set = data
      },


      // 保存空间设置信息
      saveSpaceSetting(){
        this.space_set.uid = this.spaceUserId
        saveSpaceSetting(this.space_set)
      },
      // 保存助手设置信息
      saveHelperSetting(){
        this.space_set.uid = this.spaceUserId
        saveUserHelperSetInfo(this.helper_set)
      }
    },
    created(){
      // 获取用户助手设置信息
      this.getHelperSet()
      // 获取用户空间设置信息
      this.getSpaceSet()
    },
    mounted(){
      this.space_set = this.spaceInfo
    },
    destroyed(){
      
    },
    beforeRouteLeave(to, form, next){
      // 发送请求保存设置信息
      // 发送请求保存空间设置信息
      this.saveSpaceSetting()
      // 发送请求保存助手设置信息
      this.saveHelperSetting()
      next()
    }
    
  }
</script>

<style scoped>
  /* 空间设置栏 */
  .private{
    padding: 15px;
    margin-top: 10px;
    border-radius: 5px;
    background-color: white;
    box-shadow: 0px 0px 20px rgb(229, 229, 229);
  }
  /* 标题 */
  .private_title,.helper_setting_title{
    font-size: 20px;
    margin-bottom: 20px;
  }
  /* 列表 */
  .private_setting_list,.helper_setting_list{
    display: flex;
  }

  .private_setting_list ol:not(:first-child),.helper_setting_list ol:not(:first-child){
    margin-left: 60px;
  }

  .private_setting_list_item li,.helper_setting_list_item li{
    margin: 10px 0;
    width: 250px;
    display: flex;
    justify-content: space-between;
  }

  /* 助手设置 */
  .helper_setting{
    margin-top: 10px;
    background-color: white;
    border-radius: 5px;
    padding: 15px;
    box-shadow: 0px 0px 20px rgb(229, 229, 229);
  }
</style>