<!-- 
  项目：Elyden.com
  创建时间：2024.01.29
  上次更新时间：2023.05.11
  组件名称：SpaceContribution
  此文件负责的板块：用户空间投稿内容界面
    功能：
      1、游客查看用户投稿内容
      2、（没实现，应该写在创作中心界面）空间主人编辑投稿内容
  -->
<template>
  <div>
    <div class="contribute_content">
      <!-- 左边导航 -->
      <div class="aside">
        <!-- 内容 -->
        <div class="aside_content">
          <!-- 视频 -->
          <div class="aside_item" id="active">
            <div>视频</div>
            <div class="contribute_item_count">{{ videoTotal }}</div>
          </div>
          <!-- 文章 -->
          <div class="aside_item">
            <span>文章</span>
            <span class="contribute_item_count">xx</span>
          </div>
        </div>
      </div>
      <!-- 右边内容 -->
      <div class="content">
        <!-- 顶部导航 -->
        <div class="head">
          <!-- 顶部导航左边 -->
          <div class="nav_l">
            <span class="title" v-if="showModel=='me'">我</span>
            <span class="title" v-if="showModel=='other'">TA</span>
            <span class="title">的视频</span>
            <!-- 按钮 -->
            <div class="video_nav_l_l" @mouseleave="return_scroll_bar" @click="click_scroll_bar" @mouseover="move_scroll_bar">
              <!-- 滑动条 -->
              <div class="scroll_bar" ref="scroll_bar"></div>
              <!-- 最新发布 -->
              <div class="video_nav_l new_update nav_active" id="video_nav_l" @click="changeOrderByVideo">最新发布</div>
              <!-- 最多播放 -->
              <div class="video_nav_l play_more" id="video_nav_l" @click="changeOrderByVideo">最多播放</div>
              <!-- 最多收藏 -->
              <div class="video_nav_l collect_more" id="video_nav_l" @click="changeOrderByVideo">最多收藏</div>
            </div>
          </div>
          <!-- 顶部导航右边 播放全部按钮 -->
          <div class="nav_r" @click="addVideoPAndGoToVideoPlayer2($store.state.spaceUserId)">播放全部</div>
        </div>
        <!-- 主要展示区 -->
        <div class="main">
          <!-- 视频列表 -->
          <div class="video_list">
            <!-- 单个商品元素 -->
            <div class="video_list_item1" v-for="(item,index) in video_list.list" @click="gotovideo(item.vid)">
              <!-- 视频封面 -->
              <div class="video_list_item1_cover">
                <img :src="getImgURL(item.coverAddress)" alt="稿件封面">
              </div>
              <!-- 视频标题 -->
              <div class="video_list_item1_title">
                <span> {{ item.title }} </span>
              </div>
              <!-- 视频信息 -->
              <div class="video_list_item1_msg">
                <!-- 播放量 -->
                <div>
                  <svg class="play_video_icon" aria-hidden="true">
                    <use xlink:href="#icon-shipin"></use>
                  </svg>
                  {{ item.playedNum / 10000 > 1 ? item.playedNum / 10000+"万": item.playedNum}}
                </div>
                <!-- 发布日期 -->
                <div class="video_data_item recommend_date">
                  {{ item.publishTime? item.publishTime.slice(0,10) :''}}
                </div>
              </div>
            </div>          
          </div>
        </div>
        <!-- 分页导航 -->
        <div class="pageNav">
          <el-pagination
            @size-change="handleSizeChange"
            @current-change="handleCurrentChange"

            :hide-on-single-page="true"
            :current-page="1"
            :page-size="video_list.size"
            layout="prev, pager, next, jumper"
            :total="video_list.total">
          </el-pagination>
        </div>
      </div>
    </div>
  </div>
</template>

<script>
import { countSpaceUserContribution, getVideo, getVideoOnContributionByPage } from '@/api/video';
  export default{
    name:'SpaceContribution',
    data(){
      return{
        // 导航条点击位置
        click_scroll_bar_position : '',
        // 视频列表
        video_list:[],
        // 排序条件
        condition:'publish_time',
        // 当前页面
        page:1,
        // 视频列表的视频总数量
        videoTotal:0,
      }
    },
    computed:{
      // 空间展示模式
      showModel() {
        return this.$store.state.spaceViewModel
      },
    },
    methods: {
      //视频跳跃
      gotovideo(videoid){
        this.$router.push({
          path:'/video', 
          query:{
            vid:videoid
          }
        })
      },
      
      // 播放全部视频
      addVideoPAndGoToVideoPlayer2(uid){
        console.log(uid);
        this.$router.push({
          path:'/video', 
          query:{
            havePList:true,
            from:'video',
            id:uid
          }
        })
      },

      // 活动条控制
      move_scroll_bar(event){
        if(event.target.id == 'video_nav_l'){
          this.$refs.scroll_bar.style.translate = event.target.offsetLeft -20 + 'px'
        }
      },

      // 活动条控制
      click_scroll_bar(event){
        this.click_scroll_bar_position = event.target.offsetLeft -20 + 'px'
        this.$refs.scroll_bar.style.translate = event.target.offsetLeft -20 + 'px'
      },
      
      // 活动条控制
      return_scroll_bar(){
        this.$refs.scroll_bar.style.translate = this.click_scroll_bar_position
      },



      // 改变排序顺序
      changeOrderByVideo(e){
        // console.log(e.target.className);
        if(e.target.className == 'video_nav_l new_update'){
          this.condition = 'publish_time'
        }
        else if(e.target.className == 'video_nav_l play_more'){
          this.condition = 'played_num'
        }
        else if(e.target.className == 'video_nav_l collect_more'){
          this.condition = 'collection'
        }
        if(document.getElementsByClassName('nav_active').length>0){
          document.getElementsByClassName('nav_active')[0].classList.remove('nav_active')
        }
        e.target.classList.add('nav_active')  
        this.getVideoOnContribute(this.page)
      },


      // 分页每页条数改变时触发
      handleSizeChange(val) {
        console.log(`每页 ${val} 条`);
      },
      // 分页当前页面改变时触发
      handleCurrentChange(page) {
        // console.log(`当前页: ${val}`);
        this.getVideoOnContribute(page)
      },

      // 分页查询用户界面 一页15个
      async getVideoOnContribute(page){
        let data = await getVideoOnContributionByPage(this.$store.state.spaceUserId, this.condition, page)
        this.video_list = data
      },

      // 根据空间用户uid获取用户视频稿件的数量
      async getSpaceUserCountNum(){
        let data = await countSpaceUserContribution(this.$store.state.spaceUserId)
        this.videoTotal = data
      },

      // 获取视频封面url
      getImgURL(address){
        return getVideo(address);
      },

    },
    created(){
      this.getVideoOnContribute(this.page)
      this.getSpaceUserCountNum()
    }
  }
</script>

<style scoped>
  .scroll_bar{
    height: 3px;
    width: 50px;
    background-color: #00a1d6;
    position: absolute;
    bottom: 3px;
    transition: all .3s;
  }
  #active{
    background-color: #00a1d6;
    color: white;
  }
  .nav_active{
    color: #00a1d6;
  }
  
  .contribute_content{
    margin-top: 10px;
    border-radius: 5px;
    padding: 10px 0;
    display: flex;
    justify-content: space-between;
    background-color: white;
    box-shadow: 0px 0px 20px rgb(229, 229, 229);
  }

  .aside{
    width: 250px;
    padding-right: 30px;
  }

  .aside_content{
    font-size: 14px;
    line-height: 56px;
    height: 100%;
    border-right: 1px solid rgb(216, 216, 216);
  }

  .aside_content .aside_item{
    height: 56px;
    display: flex;
    justify-content: space-around;
  }

  .aside_item:hover{
    cursor: pointer;
    color: #00a1d6;
    background-color: rgb(230, 230, 230);
  }


  .content{
    width: 100%;
  }

  .head{
    display: flex;
    justify-content: space-between;
    align-items: center;
  }

  .title{
    font-size: 20px;
    line-height: 60px;
  }

  .nav_l{
    display: flex;
    font-size: 12px;
    line-height: 60px;
  }

  .nav_l div{
    margin-left: 20px;
  }
  
  .nav_r{
    font-size: 14px;
    line-height: 14px;
    border: 1px solid rgb(230, 230, 230);
    color: gray;
    border-radius: 5px;
    padding: 10px 20px;
    margin-right: 30px;
  }

  .nav_r:hover{
    color: #00a1d6;
    border: 1px solid #00a1d6;
    cursor: pointer;
  }

  .video_nav_l_l{
    display: flex;
    position: relative;
  }
  /* 顶部daoahgggggggggggggggg */
  .video_nav_l{
    margin-right: 10px;
    cursor: pointer;
    font-size: 12px;
  }

  /* 视频播放图标 */
  .play_video_icon{
    width: 1em;
    height: 1em;
    vertical-align: -0.1em;
    fill: currentColor;
    overflow: hidden;
  }

  /* 视频列表 */
  .video_list{
    display: flex;
    flex-wrap: wrap;
    margin-bottom: 30px;
  }
  /* 单个商品 */
  .video_list_item1{
    width: 210px;
    padding-right: 20px;
    margin-top: 20px;
    cursor: pointer;
  }
  /* 视频信息 */
  .video_list_item1_msg{
    font-size: 12px;
    color: gray;
    display: flex;
    justify-content: space-between;
    margin-top: 10px;
  }
  /* 视频封面 */
  .video_list_item1 img{
    width: 100%;
    height: 150px;
    border-radius: 5px;
  }
  /* 视频标题 */
  .video_list_item1_title{
    font-size: 14px;
    height: 40px;
    overflow: hidden;
  }


  /* 
    分页导航栏
  */
  .pageNav{
    margin: 0 auto;
    text-align: center;
  }
</style>