<!-- 
  项目：Elyden.com
  创建时间：2024.04.11
  上次更新时间：2024.5.09
  组件名称：Message
  此文件负责的板块：短信
    功能：
      1、展示多种短信内容
      2、根据短信内容跳转不同界面
      3、和指定用户建立实时通信
  -->
<template>
  <div class="Message">
    <HeaderNav initNav="white"></HeaderNav>
    <!-- 空内容，占位顶替导航栏空位 -->
    <div class="nulldiv"></div>
    <div class="PageContent">
      <!-- 左边导航区 -->
      <div class="left_nav">
        <!-- 导航列表 -->
        <ol class="nav_list">
          <!-- 消息中心 -->
          <li>
            <svg-icon iconname="icon-xiaoxi" class="icon-nav"></svg-icon>
            消息中心
          </li>
          <!-- 回复我的 -->
          <li id="0" :class="{'active': type == 0 || type == 1}" @click="changeContent">
            <!-- 红点提醒 -->
            <el-badge :value="AllNoReadMessageNumber.type01Num" v-show="!AllNoReadMessageNumber.type01Num<1" :max="99" class="red-remind-item msg-item-red-remind"></el-badge>
            <div>回复我的</div>
          </li>
          <!-- @我的 -->
          <li id="2" :class="{'active': type == 2}" @click="changeContent">
            <!-- 红点提醒 -->
            <el-badge :value="AllNoReadMessageNumber.type2Num" v-show="!AllNoReadMessageNumber.type2Num<1" :max="99" class="red-remind-item"></el-badge>
            <div>@我的</div>
          </li>
          <!-- 收到的点赞 -->
          <li id="3" :class="{'active': type == 3}" @click="changeContent">
            <!-- 红点提醒 -->
            <el-badge :value="AllNoReadMessageNumber.type3Num" v-show="!AllNoReadMessageNumber.type3Num<1" :max="99" class="red-remind-item"></el-badge>
            <div>收到的赞</div>
          </li>
          <!-- 我的消息 -->
          <li id="4" :class="{'active': type == 4}" @click="changeContent">
            <!-- 红点提醒 -->
            <el-badge :value="AllNoReadMessageNumber.type4Num" v-show="!AllNoReadMessageNumber.type4Num<1" :max="99" class="red-remind-item"></el-badge>
            <div>我的消息</div>
          </li>
          <!-- 系统消息 -->
          <li id="5" :class="{'active': type == 5}" @click="changeContent">
            <!-- 红点提醒 -->
            <el-badge :value="AllNoReadMessageNumber.type5Num" v-show="!AllNoReadMessageNumber.type5Num<1" :max="99" class="red-remind-item"></el-badge>
            <div>系统消息</div>
          </li>
          <!-- 消息设置 -->
          <li><svg-icon iconname="icon-dianji01" class="icon-nav"></svg-icon>消息设置</li>
        </ol>
      </div>
      <!-- 右边导航区 -->
      <div class="right_content" @scroll="messageListScroll">
        <!-- 普通消息 -->
        <div v-if="type!=5 && $route.path=='/message'" class="content_item" v-for="(item, index) in messageList" :key="item.mid" @click="gotovideo(item.type,item.vid,item.cid)">
          <!-- 消息发布者头像 -->
          <div class="content_item_left">
            <img class="user_img_tospace" :src="getImgURL(item.senderInfo.picture)" alt="头像" ref="user_icon_nav">
          </div>
          <!-- 消息内容 -->
          <div class="content_item_right">
            <!-- 消息信息 -->
            <div class="content_right_top">
              <!-- 消息发布者名称 -->
              <span class="user_name">{{item.senderInfo.uName}}</span>
              <!-- 消息类型1 -->
              <span class="message_type" v-if="item.type=='0'">对我的视频发表了评论</span>
              <!-- 消息类型2 -->
              <span class="message_type" v-if="item.type=='1'">回复了我的评论</span>
              <!-- 消息类型3 -->
              <span class="message_type" v-if="item.type=='3'">点赞了我的视频</span>
              <!-- 未读消息提示 -->
              <el-badge is-dot class="item" style="margin-left: 30px;" v-show="!item.isRead"></el-badge>
            </div>
            <!-- 消息的内容 -->
            <div class="content_right_middle">
              <span class="message_content" v-if="item.comment">
                {{ item.comment.length > 100 ? item.comment.substr(0, 100)+"..." : item.comment }}
              </span>
            </div>
            <!-- 操作区 -->
            <div class="content_right_foot">
              <!-- 消息发布日期 -->
              <div class="message_data">{{item.date}}</div>
              <!-- 回复按钮 -->
              <div class="answer_button">回复</div>
              <!-- 点赞 -->
              <div class="good_button"><svg-icon iconname="icon-good" class="icon-nav"></svg-icon>点赞</div>
            </div>
          </div>
          <img v-if="item.fromVideo" class="msgfromvideo" :src="getImgURL(item.fromVideo.coverAddress)" alt="稿件封面">
        </div>
        <!-- 系统消息 -->
        <div v-if="type==5 && $route.path=='/message'" class="systemMessageItem" v-for="(item, index) in messageList" :key="item.mid">
          <div class="systemMessage head">
            <span class="systemMessage title">系统消息</span>
            <!-- 消息发布日期 -->
            <span class="systemMessage date">{{ item.date }}</span>
            <!-- 未读消息提示 -->
            <el-badge is-dot class="item" style="margin-left: 30px;" v-show="!item.isRead"></el-badge>
          </div>
          <!-- 消息内容 -->
          <div class="systemMessage body">
            <span class="systemMessage comment">{{ item.comment.length > 100 ? item.comment.substr(0, 100)+"..." : item.comment }}</span>
            <!-- <a href="#">活动链接</a> -->
          </div>
        </div>
        <!-- 没有消息提示 -->
        <div v-if="messageList.length==0 && $route.path=='/message'" class="nullmsg">
          这里空空如也呢！
        </div>
        <!-- 聊天室内容导航显示区 -->
        <RouterView name="Message"></RouterView>
      </div>
    </div>
  </div>
</template>

<script>
import { RouterLink, RouterView } from 'vue-router';
import HeaderNav from './HeaderNav.vue';
import IconSvg from './IconSvg.vue';
import { countAllNoReadMessage, getMessageByPage } from '@/api/message';

export default{
  name:'Message',
  data(){
    return{
      // 展示的消息列表
      messageList:'',
      // 当前所展示的消息类型 01视频/评论 2@我 3点赞 4联系短信 5系统消息
      type:0,
      // 当前展示所属页面
      page:0,
      // 节流计时器
      timer:'',
      // 内容最大页数
      pages:0,

      // 总未读消息
      AllNoReadMessageNumber:{
        type01Num:0,
        type2Num:0,
        type3Num:0,
        type4Num:0,
        type5Num:0
      },
    }
  },
  computed:{
    // 是否处于登录状态
    islogin(){
      return this.$store.state.login || false 
    },
  },
  methods:{
    // 前往个人空间
    gotospace(){
      this.$router.push({
        name: 'space',
        params:{
          // 访问来源
          fromUser:this.$store.state.loginUser.uid,
          // 访问目标
          toUser:uid,
        }
      })
    },
    // 前往聊天室
    gotoChatRoom(){
      this.$router.push({
        path: '/message/chatRoom'
      })
    },
    //前往消息界面
    gotomessage(){
      if(this.islogin){
        this.$router.push({
          path:'/message'
        })
      }
    },
    // 前往消息的视频界面
    gotovideo(type, videoid, cid){
      // 消息类型为回复我的，要携带跳转评论位置的评论id
      if (type == '0'||type=='1') {
        // 0为不跳转视频界面消息
        if (videoid != 0) {
          this.$router.push({
            path:'/video', 
            query:{
              vid:videoid,
              cid:cid
            }
          })
        }
      }
      else{
        // 视频id为0的为不跳转视频界面消息
        if (videoid != 0) {
          this.$router.push({
            path:'/video', 
            query:{
              vid:videoid
            }
          })
        }
      }
    },

    // 获取默认选择的回复消息 类型为0/1 提供0即可,1后端判断衔接上
    async init(){
      console.log(this.page);
      console.log(this.type);
      // 获取message信息
      let data = await getMessageByPage(this.type, this.page + 1);
      if (data) {
        this.page +=1
        this.messageList = data.messageList
        this.pages = data.pages
      }
    },

    // 消息列表滚动事件
    messageListScroll(){
      let scrollTop = event.target.scrollTop
      let clientHeight = event.target.clientHeight
      let scrollHeight = event.target.scrollHeight
      if (scrollTop + clientHeight + 30 >= scrollHeight){
        console.log("调用添加消息");
        // 如果计时器为空且还没有到达最大数
        if (!this.timer && this.pages > this.page) {
          this.addMessageToList()
          console.log("a");
        }
      }
    },

    // 将消息添加如显示列表
    async addMessageToList(){
      // 有计时器时
      if(this.timer){
        // 清除计时器
        clearTimeout(this.timer)
        // 重新计时
        this.timer = setTimeout(()=>{
          clearTimeout(this.timer)
          this.timer = ''
        },1000)
      }
      // 首次执行或者无计时器
      if(!this.timer){
        // 设置1s空计时器
        this.timer = setTimeout(()=>{
          clearTimeout(this.timer)
          this.timer = ''
        },1000)
        let data = await getMessageByPage(this.type, this.page + 1);
        if (data) {
          this.page +=1
          let temp = data.messageList
          for (let i = 0; i < temp.length; i++) {
            this.messageList.push(temp[i])
          }
        }
      }
    },

    // 统计当前登录用户有多少个未读消息
    async countAllNoReadMessage(){
      let data = await countAllNoReadMessage();
      if (data) {
        this.AllNoReadMessageNumber = data
      }
    },

    // 点击消息nav切换内容
    changeContent(){
      // console.log("切换选择消息条件");
      // if (document.getElementsByClassName('active')[0]){
      //   document.getElementsByClassName('active')[0].classList.remove('active')
      // }
      // event.target.classList.add('active')
      if(event.target.innerText != '我的消息'){
        this.gotomessage()
        // 设置要获取的消息类型 01视频/评论 2@我 3点赞 4联系短信 5系统消息
        console.log(event.target);
        // 改变当前展示的消息类型
        this.type = event.currentTarget.id
        // 刷新消息列表
        this.page = 0
        // 初始化展示消息
        this.init()
      }
      else if(event.target.innerText == '我的消息'){
        // 设置当前展示的消息类型，用于判断当前活动nav
        // 改变当前展示的消息类型
        this.type = event.currentTarget.id
        // 清空展示列表
        this.messageList=[]
        // 跳转路由到聊天室
        this.gotoChatRoom()
      }
    },
    // 获取图片
    getImgURL(address){
      return "http://localhost:9000" + address
    }
  },
  created(){
    // 如果跳转过来时携带了要展示的内容类型
    if(typeof this.$route.query.type== typeof ''){
      this.type = this.$route.query.type
    }
    // 初始化消息
    this.init()
  },
  mounted(){
    // 统计未读数量
    this.countAllNoReadMessage()
  },
  components: {HeaderNav}
}

</script>

<style scoped>
  /* 导航栏的红点提醒 */
  .red-remind-item{
    scale: 0.8;
    position: absolute;
    translate: 30px -5px;
  }
  /* 页面整体样式 */
  .Message{
    background: url(/public/img/e7194a11546e40ca11757dcc528f7688_1000928329875750192.png);
    width:100%;			
    height:100%;			
    position:fixed;
    background-size:100% 100%;
  }
  /* 占位div */
  .nulldiv{
    height: 100px;
  }
  /* 页面整体 */
  .PageContent{
    width: 70%;
    display: flex;
    justify-content: space-between;
    margin: 0 auto;
    border-radius: 10px;
    position: relative;
  }
  /* 左边导肮区整体 */
  .left_nav{
    width: 10%;
    padding: 10px;
    background-color: rgba(255, 255, 255, 0.7);
    border-radius: 10px;
    text-align: center;
  }
  /* 左边导航单个元素 */
  li{
    font-size: 14px;
    font-weight: bolder;
    padding: 5px 0;
    color: gray;
  }
  /* 首个信息中心 不处参与交互 */
  .nav_list li:first-child{
    font-size: 16px;
    margin-bottom: 20px;
    color: rgb(0, 0, 0);
  }
  /* 消息设置 */
  .nav_list li:last-child{
    margin-top: 20px;
    padding-top: 20px;
    border-top: white 1px solid;
  }
  /* 参与交互的按钮悬浮动画 */
  .nav_list li:not(:first-child):hover{
    color: #00a1d6;
    cursor: pointer;
  }
  /* 活动状态 */
  .active{
    color: #00a1d6;
  }


  /* 右边内容区 */
  .right_content{
    height: 88vh;
    width: 88%;
    background-color: rgba(255, 255, 255, 0.6);
    border-radius: 10px;
    overflow-y: auto;
  }
  /* 单个消息 */
  .content_item{
    min-height: 100px;
    position: relative;
    padding: 30px 0 0 0;
    display: flex;
    background-color: white;
    cursor: pointer;
  }
  /* 单个系统消息 */
  .systemMessageItem{
    padding: 30px 20px;
    border-radius: 10px;
    margin-bottom: 10px;
    background-color: white;
    cursor: pointer;
    font-size: 14px;
  }
  /* 系统消息标题 */
  .systemMessageItem .title{
    margin-right: 20px;
    font-weight: bold;
  }
  /* 系统消息发布日期 */
  .systemMessageItem .date{
    color: rgb(180, 180, 180);
  }
  /* 系统的主体 */
  .systemMessageItem .body{
    margin-top: 10px;
    text-indent: 2em;
    color: gray;
  }

  /* 用户信息栏头像 */
  .user_img_tospace{
    /* float: left; */
    width: 50px;
    height: 50px;
    border: rgb(207,207,207) solid 1px;
    background-color: white;
    object-fit: cover; /*图片完全填充*/
    border-radius: 50%; /*头像框圆形设置*/
    vertical-align: top;
    margin-left: 20px;
    cursor: pointer;
  }
  /* 用户名称 */
  .user_name{
    font-weight: bold;
    margin-right: 20px;
  }
  .user_name:hover{
    color: #00a1d6;
  }
  .message_type{
    color: gray;
  }
  .content_item_right{
    width: 100%;
    margin-left: 10px;
    border-bottom: 1px solid rgb(230,230,230);
  }
  .content_item_right div{
    margin-bottom: 10px;
  }

  /* 评论区 */
  .content_right_middle{
    width: 80%;
  }

  .content_right_foot{
    display: flex;
    font-size: 14px;
    color: gray;
  }
  .content_right_foot div{
    margin-right: 20px;
  }
  /* 点赞图标 */
  .content_right_foot .icon-nav{
    width: 18px;
    height: 18px;
    vertical-align: -0.15em;
  }
  /* 回复点赞按钮悬浮样式 */
  .answer_button:hover,.good_button:hover{
    color: #00a1d6;
  }
  /* 消息来自的视频封面 */
  .msgfromvideo{
    position: absolute;
    right: 20px;
    width: 100px;
    height: 80px;
  }
  /* 没有消息提示 */
  .nullmsg{
    height: 200px;
    line-height: 200px;
    text-align: center;
    background-color: rgba(255, 255, 255, 0.7);
  }
</style>