<!-- 
  项目：Elyden.com
  创建时间：2024.01.29
  上次更新时间：2023.05.11
  组件名称：SpaceCollection
  此文件负责的板块：用户空间收藏界面
    功能：
      1、游客查看收藏夹和收藏夹内容
      2、空间主人编辑收藏夹内容，新建收藏夹
  -->
<template>
  <div>
    <div class="collect_content">
      <!-- 左边内容导航栏 -->
      <div class="aside">
        <div class="aside_content">
          <!-- 左边导航标题 -->
          <div class="aside_title">
            <span style="font-size: 20px;" v-if="showModel=='other'">TA的创建</span>
            <span style="font-size: 20px;" v-if="showModel=='me'">我的创建</span>
            <div class="aside_order_nav">
              <!-- 排序图标 -->
              <span>⏳</span>
              <!-- 创建时间倒叙排序 -->
              <span @click="changeLeftCondition" ref="collectionFirstNav">↓</span>
              <!-- 创建时间正序排序 -->
              <span @click="changeLeftCondition" ref="collectionSecondNav">↑</span>
              <!-- 排序顺序翻转 -->
              <span @click="changeLeftCondition">⇵</span>
            </div>

          </div>
          <!-- 新建收藏夹 -->
          <div class="aside_item" v-if="showModel=='me'" @click="addNowCollection">
            <div style="color: rgb(160, 160, 160);">新建收藏夹<span style="float: right; font-size: 20px;">+</span></div>
          </div>
          <!-- 单个收藏夹 -->
          <div class="aside_item" v-for="(item, index) in collection_list" :id="NavId[index]" @click="changeCollection(item.id)">
            <div class="collection_name">{{item.name}}</div>
            <span class="collection_item_count" :class="{'aside_item:hover .collection_item_count': showModel == 'me'}" >{{item.totalNum}}</span>
            <!-- <button class="deleteButton" v-if="showModel == 'me'" @click="deleteCollection(item.id)">删除</button> -->
            <el-dropdown style="position: absolute; right: 8%;" placement="bottom" @command="controlMethod" v-if="showModel=='me'">
              <span class="el-dropdown-link">
                ┇<i class="el-icon-arrow-down el-icon--right"></i>
              </span>
              <el-dropdown-menu slot="dropdown" @click.native="controlCollectionId(item.id)">
                <el-dropdown-item command="a">编辑</el-dropdown-item>
                <el-dropdown-item command="b" v-if="item.type!='0'">删除</el-dropdown-item>
              </el-dropdown-menu>
            </el-dropdown>
          </div>
        </div>
      </div>
      <!-- 右边内容区 -->
      <div class="content" v-if="this.collectionsInfo.total>0 && state">
        <!-- 内容区上方收藏夹简介，即第一个视频信息 -->
        <div class="collection_first_video">
          <!-- 收藏夹首个视频封面 -->
          <div class="first_video_l">
            <img :src="getImgURL(collection_cover_video.coverAddress)" alt="收藏封面视频">
          </div>
          <!-- 收藏夹信息 -->
          <div class="first_video_r">
            <!-- 收藏夹名称 -->
            <div class="first_video_head"><span class="fist_video_title">{{ collection.name }}</span></div>
            <!-- 收藏夹创建者 -->
            <div class="first_video_middle">
              <span class="fist_video_">创建者：{{ userInfo.uName }}</span>
            </div>
            <!-- <div class="first_video_foot">
              <span class="fist_video_">点赞：</span>
              <span class="fist_video_">收藏：</span>
              <span class="fist_video_">转发：</span>
            </div> -->
            <!-- 播放整个收藏夹视频按钮 -->
            <span class="playAllButton" @click="addVideoPAndGoToVideoPlayer">播放全部</span>
          </div>
        </div>
        <!-- 非编辑模式下的内容导航 -->
        <div class="head" v-if="!editCollectState">
          <!-- 左边导航栏 -->
          <div class="nav_l">
            <!-- 内容排序按钮 -->
            <div class="video_nav_l_l" @mouseleave="return_scroll_bar" @click="click_scroll_bar" @mouseover="move_scroll_bar">
              <!-- 滑动条 -->
              <div class="scroll_bar" ref="scroll_bar"></div>
              <!-- 内容加入时间排序倒叙 -->
              <div class="video_nav_l" @click="changeRightCondition">加入时间倒序</div>
              <!-- 内容加入时间排序正序 -->
              <div class="video_nav_l" @click="changeRightCondition">加入时间正序</div>
              <!-- <div class="video_nav_l new_update nav_active" id="video_nav_l">最新发布</div>
              <div class="video_nav_l play_more" id="video_nav_l">最多播放</div>
              <div class="video_nav_l collect_more" id="video_nav_l">最多收藏</div> -->
            </div>
          </div>
          <!-- 进入编辑模式按钮 -->
          <div class="nav_r">
            <span class="editButton" @click="editCollectState = true">批量操作</span>
          </div>
        </div>
        <!-- 编辑模式下的内容导航 -->
        <div class="head" v-if="editCollectState">
          <!-- 左边导航 -->
          <div class="nav_l">
            <!-- 全选框 -->
            <el-checkbox :indeterminate="isIndeterminate" v-model="checkAll" @change="handleCheckAllChange">全选</el-checkbox>
            <!-- 反选框 -->
            <el-checkbox v-model="reverseCheckAll" @change="handleReverseCheckAllChange">反选</el-checkbox>
            <!-- 取消收藏按钮 -->
            <span class="cancelCollectButton" @click="cancelCollectionByVidList">取消收藏</span>
          </div>
          <div class="nav_r">
            <!-- 已选择数量提示 -->
            已经选择{{ checkedVideos.length }}
            <!-- 取消全部已选框 -->
            <el-checkbox style="margin-right: 20px;" v-if="isIndeterminate || checkAll" v-model="cancelCheckAll" @change="handleCancelCheckAllChange">取消全部已选</el-checkbox>
            <!-- 取消编辑按钮 -->
            <span class="returnButton" @click="cancelEdit">取消编辑</span>
          </div>
        </div>
        <!-- 内容展示区 -->
        <div class="main">
          <!-- 视频列表 -->
          <div class="video_list">
            <!-- 单个视频元素 -->
            <div class="video_list_item1" v-for="(item,index) in collection_videoList" @click="gotovideo(item.vid)">
              <!-- 视频封面 -->
              <div class="video_list_item1_cover">
                <img :src="getImgURL(item.coverAddress)" alt="稿件封面">
              </div>
              <!-- 视频标题 -->
              <div class="video_list_item1_title">
                <span> {{ item.title }} </span>
              </div>
              <!-- 视频信息 -->
              <div class="video_list_item1_msg">
                <!-- 播放量图标和数字 -->
                <div>
                  <svg class="play_video_icon" aria-hidden="true"><use xlink:href="#icon-shipin"></use></svg>
                  {{ item.playedNum / 10000 > 1 ? item.playedNum / 10000+"万": item.playedNum}}
                </div>
                <!-- 发布时间 -->
                <div class="video_data_item recommend_date">
                  {{ item.publishTime? item.publishTime.slice(0,10) :''}}
                </div>
              </div>
              <!-- 编辑模式下的选择框 -->
              <el-checkbox-group v-if="editCollectState" style="scale: 2; position: absolute; right: 20px; top: 10px;" v-model="checkedVideos" @change="handlecheckedVideosChange">
                <el-checkbox :label="item.vid">{{  }}</el-checkbox>
              </el-checkbox-group>
            </div>          
          </div>
        </div>
        <!-- 底部分页导航 -->
        <div class="pageNav">
        <el-pagination
          @size-change="handleSizeChange"
          @current-change="handleCurrentChange"
          :hide-on-single-page="true"
          :current-page="1"
          :page-size="15"
          layout="prev, pager, next, jumper"
          :total="collection.totalNum">
        </el-pagination>
      </div>
      </div>
      <!-- 无数据提示gif动画 -->
      <div style="margin: 0 auto; text-align: center;" v-if="!state">
        <img src="/img/nollData.gif" alt="暂无数据" style="width: 100px;"><br>
        <span>暂无数据</span>
      </div>
    </div>
    <!-- 添加新收藏夹和编辑收藏夹弹窗 -->
    <el-dialog
      :title="dialogTitle"
      :visible.sync="dialogCollectionVisible"
      top="30vh"
      width="30%"
      :before-close="handleClose">
      <div>
        <!-- 新建收藏夹弹窗界面 -->
        <form style=" width: 100%;">
          <!-- 输入框 -->
          <div style="margin-bottom: 20px;"><span>新收藏夹名称：</span><input class="new_collect_titleBox" type="text" v-model="new_collect.name" placeholder="给你的新收藏夹取一个好听的名字吧♪" style="padding: 0 5px; width: 70%; height: 30px;"></div>
        </form>
      </div>
      <span slot="footer" class="dialog-footer">
        <!-- 取消新建收藏夹按钮 -->
        <el-button type="primary" v-if="dialogTitle=='新收藏夹'" style="background-color: rgb(180, 180, 180); border: none;" @click="dialogCollectionVisible = false">取消</el-button>
        <!-- 取消编辑收藏夹按钮 -->
        <el-button type="primary" v-if="dialogTitle=='编辑收藏夹'" style="background-color: rgb(180, 180, 180); border: none;" @click="cancelEditCollection">取消</el-button>
        <!-- 确定新建收藏夹按钮 -->
        <el-button type="primary" v-if="dialogTitle=='新收藏夹'" @click="newCollectButton">确定</el-button>      
        <!-- 确定编辑收藏夹按钮 -->
        <el-button type="primary" v-if="dialogTitle=='编辑收藏夹'" @click="EditCollectButton">确定</el-button>      
      </span>
    </el-dialog>
  </div>
</template>

<script>
import { cancelCollection, deleteCollection, getCollectionById, getCollectionVidListById, getUserAllCollectionByPage, saveNewCollection, updateCollectionName } from '@/api/collection';
import { getUserInfoByUid } from '@/api/user';
import { getVideo, getVideoByVid } from '@/api/video';

  export default{
    name: 'SpaceCollection',
    data(){
      return{
        // 是否开启渲染dom状态
        state:false,

        // --------------------------------------收藏夹内容编辑模式数据---------------------------------
        // 是否在编辑模式
        editCollectState:false,
        // 用以表示 checkbox 的不确定状态 - ，一般用于实现全选的效果
        isIndeterminate: false,
        // 全选框是否打勾状态
        checkAll: false,
        // 取消全选框是否打勾状态
        cancelCheckAll: true,
        // 反选框是否打勾状态
        reverseCheckAll: false,
        // 已选择的视频列表
        checkedVideos: [],
        // --------------------------------------收藏夹内容编辑模式数据---------------------------------

        // --------------------------------------新建收藏夹数据---------------------------------
        // 弹窗标题
        dialogTitle:'新收藏夹',
        // 是否显示新建收藏界面或者添加视频到收藏夹弹窗界面是否显示，两个共用一个弹窗界面
        dialogCollectionVisible:false,
        // 新收藏夹对象
        new_collect:{
          "id":"",
          "name":"",
          "collectionTime":"",
          "updateTime":""
        },
        // --------------------------------------新建收藏夹数据---------------------------------


        // 左边导航样式修改
        NavId:["active"],

        // 左边活动导航
        left_active_nav:'',

        // 右边活动导航
        active_nav:'',

        // 导航条点击位置
        click_scroll_bar_position : '',
        
        // 当前空间用户所有收藏夹信息列表
        collection_list:[],

        // 用户所有收藏夹信息，1、收藏夹列表，2、收藏夹数量
        collectionsInfo:[],

        // 收藏排序
        rightNavCondition:'desc',
        leftNavCondition:'desc',

        // 当前显示的收藏夹id
        id:0,
        // 当前显示收藏夹封面
        collection_cover_video:{},
        // 收藏夹的视频id列表
        collection_vidList:[],
        // 收藏夹的视频信息列表
        collection_videoList:[],
        // 当前显示收藏夹信息
        collection:[],
        // 当前展示页码
        page:1,

        //空间所属用户信息
        userInfo:{},
      }
    },
    computed:{
      showModel() {
        return this.$store.state.spaceViewModel
      },
    },
    methods: {
      // ----------------------------------------收藏夹内容管理--------------------------------------
      // 取消收藏
      async cancelCollectionByVidList(){
        // 已经选择的视频内容为空,退出函数
        if (this.checkedVideos.length < 1) {
          return
        }
        // 视频vid字符串拼接
        let vidlist = ''
        this.checkedVideos.forEach((temp)=>{
          vidlist += temp + ','
        })

        let data = await cancelCollection(this.id, vidlist);
        if (data == 1) {
          this.$message.success("取消收藏成功")
        }else{
          this.$message.error("取消收藏失败")
        }
        

      },

      // 取消编辑,退出编辑模式
      cancelEdit(){
        // 清空选择
        this.checkedVideos = []
        // 退出编辑模式
        this.editCollectState = false;
      },

      // 点击全选按钮
      handleCheckAllChange(val) {
        let cityOptions = []
        this.collection_videoList.forEach((item)=>{
          cityOptions.push(item.vid)
        })
        this.checkedVideos = val ? cityOptions : [];
        this.isIndeterminate = false;
      },

      // 点击取消全选
      handleCancelCheckAllChange(){
        // 清空选择
        this.checkedVideos = []
        // 全选框不打勾
        this.checkAll = false
        this.isIndeterminate = false;
      },

      // 点击反选
      handleReverseCheckAllChange(val){
        // 所有收藏内容
        let all = []
        this.collection_videoList.forEach((item)=>{
          all.push(item.vid)
        })
        // 已选内容
        let checked = this.checkedVideos
        // 情况一: 已选内容为空
        if (checked.length == 0) {
          // 将所有内容赋值给已选择数组
          this.checkedVideos = all
          // 全选框为打勾状态
          this.checkAll = true
        }
        // 情况二: 选完了
        else if (checked.length == all.length) {
          // 清空选择
          this.checkedVideos = []
          // 全选框为不打勾
          this.checkAll = false
          // 取消全选框为打勾状态
          this.cancelCheckAll = true
        }
        // 情况三: 满还是不满,如满~,到底满还是不满,如满~~
        else {
          // 当前所有的拼接已选的  filter过滤正数第一个出现的下标和倒数第一个出现的下标相等的,即拼接的数组中不重复的选项
          // console.log(all.concat(checked));
          this.checkedVideos = all.concat(checked).filter((v, index, array) =>{
            return array.indexOf(v) == array.lastIndexOf(v);
          })
        }
        // 设置反选框状态
        this.reverseCheckAll = val
      },

      // 编辑模式下的视频的选框 点击值变化时调用 用于判断显示顶部导航选择框否全选的状态
      handlecheckedVideosChange(value) {
        let checkedCount = value.length;
        this.checkAll = checkedCount === this.collection_videoList.length;
        this.isIndeterminate = checkedCount > 0 && checkedCount < this.collection_videoList.length;
        this.cancelCheckAll = this.isIndeterminate || this.checkAll ? true : false
        console.log(this.checkedVideos);
      },
      // ----------------------------------------收藏夹内容管理--------------------------------------


      // ----------------------------------------收藏夹管理--------------------------------------
      // 取消编辑收藏夹
      cancelEditCollection(){
        // 弹窗标题回复为默认的新建收藏夹
        this.dialogTitle = '新收藏夹'
        // 清空新收藏夹名字
        this.new_collect.name =''
        // 关闭显示
        this.dialogCollectionVisible = false
      },

      // 确定编辑收藏夹
      EditCollectButton(){
        console.log(this.new_collect.name);
        if (this.new_collect.name.trim() == '') {
          // 提示名字不能为空
          this.$message({
            message: '好啦，不要调皮了，收藏夹名称不能为空喔♪',
            type: 'warning'
          });
          return
        }
        // 确定修改收藏夹
        this.acceptEditCollection()
      },

      // 确定编辑收藏夹
      async acceptEditCollection(){
        let data = await updateCollectionName(this.new_collect);
        if (data == 1) {
          this.dialogCollectionVisible = false
          console.log("修改成功");
        }else{
          console.log("修改失败");
        }
      },

      // 选择的操作方式
      controlMethod(command){
        // console.log("当前选择" +command);
        if (command == 'a') {
          console.log("编辑此收藏夹");
          // 显示新收藏夹编辑界面
          this.dialogTitle = '编辑收藏夹'
          this.dialogCollectionVisible = true
        }
        else if (command == 'b'){
          console.log("删除此收藏夹");
          this.deleteCollection()
        }
      },

      // 点击的下拉条所属收藏夹id，即要操作的id
      controlCollectionId(id){
        console.log("当前操作的id"+id);
        // 设置当前操作的收藏夹id
        this.new_collect.id = id
      },

      // 删除收藏
      deleteCollection(){
        this.$confirm('确定删除这个收藏夹吗？', '提示', {
          confirmButtonText: '确定',
          cancelButtonText: '取消',
          type: 'warning'
        }).then(() => {
          this.acceptDeletedCollection()
        })
      },
      
      // 确认删除该收藏夹
      async acceptDeletedCollection(){
        let data = await deleteCollection(this.new_collect.id)
        console.log("删除成功");
      },

      // 添加新收藏
      addNowCollection(){
        // 显示界面
        this.dialogCollectionVisible = true
      },

      // 确定新建收藏夹
      async newCollectButton(){
        if (this.new_collect.name.trim() == '') {
          // 提示名字不能为空
          this.$message({
            message: '好啦，不要调皮了，新收藏夹名称不能为空喔♪',
            type: 'warning'
          });
          return
        }
        // 确定新收藏夹信息没问题后提交创建新收藏夹请求
        // 设置创建时间
        this.new_collect.collectionTime = Date.now();
        // 设置更新时间
        this.new_collect.updateTime = Date.now();
        // 发送请求
        let data = await saveNewCollection(this.new_collect)
        // 关闭创建新收藏夹表单
        this.dialogCollectionVisible = false
      },

      // 添加新收藏夹和编辑收藏夹名称弹窗关闭提示
      handleClose(done) {
        this.$confirm('确认关闭？')
          .then(_ => {
            // 恢复弹窗标题
            this.cancelEditCollection()
            done();
          })
          .catch(_ => {});
      },
      // ----------------------------------------收藏夹管理--------------------------------------


      // ----------------------------------------导航拉条控制--------------------------------------
      move_scroll_bar(event){
        if(event.target.id == 'video_nav_l'){
          this.$refs.scroll_bar.style.translate = event.target.offsetLeft + 'px'
        }
      },
      click_scroll_bar(event){
        this.click_scroll_bar_position = event.target.offsetLeft + 'px'
        this.$refs.scroll_bar.style.translate = event.target.offsetLeft + 'px'
      },
      return_scroll_bar(){
        this.$refs.scroll_bar.style.translate = this.click_scroll_bar_position
      },
      // ----------------------------------------导航拉条控制--------------------------------------
      
      
      // ----------------------------------------跳转播放器播放视频--------------------------------------
      // 点击单个视频跳跃播放器界面，播放视频
      gotovideo(videoid){
        if (!this.editCollectState) {
          this.$router.push({
            path:'/video', 
            query:{
              vid:videoid
            }
          })
        }
      },

      // 播放当前展示的收藏夹的全部内容 分P播放
      addVideoPAndGoToVideoPlayer(){
        this.$router.push({
          path:'/video', 
          query:{
            havePList:true,
            from:'collection',
            // 当前显示的收藏夹id
            id:this.id
          }
        })
      },
      // ----------------------------------------跳转播放器播放视频--------------------------------------


      // ----------------------------------------左边导航--------------------------------------
      // 根据uid获取全部收藏夹信息  左边导航排序改变时调用
      async getCollectionListById(){
        let data = await getUserAllCollectionByPage(this.$store.state.spaceUserId, this.leftNavCondition, 1000)
        // console.log(res);
        this.collection_list = data.videoList
        // console.log(this.collection_list)
        console.log(this.collection_list);
      },

      // 左侧收藏夹排序改变 
      changeLeftCondition(e){
        // 初始时活动导航为空
        if(this.left_active_nav == ''){
          // 设置活动导航
          this.left_active_nav = this.$refs.collectionFirstNav
        }
        // 点击创建时间正序按钮
        if(e.target.innerText == '↑'){
          // 设置左边导航排序条件
          this.leftNavCondition = 'asc'
          // 样式修改
          e.target.style.backgroundColor = '#00a1d6'
          e.target.style.color = 'white'
        }
        // 点击创建时间倒叙按钮
        else if(e.target.innerText == '↓'){
          // 设置左边导航排序条件
          this.leftNavCondition = 'desc'
          // 样式修改
          e.target.style.backgroundColor = '#00a1d6'
          e.target.style.color = 'white'
        }
        // 点击翻转排序条件
        else if(e.target.innerText == '⇵'){
          this.leftNavCondition == 'desc' ? this.leftNavCondition = 'asc' : this.leftNavCondition = 'desc'
          if(this.left_active_nav == this.$refs.collectionFirstNav){
            console.log(1);
            this.$refs.collectionSecondNav.style.backgroundColor = '#00a1d6'
            this.$refs.collectionSecondNav.style.color = 'white'
          }
          else if(this.left_active_nav == this.$refs.collectionSecondNav){
            console.log(2);
            this.$refs.collectionFirstNav.style.backgroundColor = '#00a1d6'
            this.$refs.collectionFirstNav.style.color = 'white'
          }
        }
        // 先前的活动样式回复普通
        this.left_active_nav.style.backgroundColor = 'rgba(0,0,0,0)'
        this.left_active_nav.style.color = 'black'
        // this.left_active_nav = e.target
        // 设置当前活动的导航
        if(this.left_active_nav == this.$refs.collectionFirstNav){
          console.log(3);
          this.left_active_nav = this.$refs.collectionSecondNav
        }
        else if(this.left_active_nav == this.$refs.collectionSecondNav){
          console.log(4);
          this.left_active_nav = this.$refs.collectionFirstNav
        }
        // 根据用户id获取用户全部收藏夹信息
        this.getCollectionListById()
      },

      // 左侧导航点击改变右边
      changeCollection(id){
        // 改变当前显示收藏夹id
        this.id = id
        // 数据置为空
        // 当前显示收藏夹封面
        this.collection_cover_video = {}
        // 收藏夹的视频id列表
        this.collection_vidList = []
        // 收藏夹的视频信息列表
        this.collection_videoList = []
        // 当前显示收藏夹信息
        this.collection = []
        // 隐藏内容
        this.state = false

        // 根据改变的收藏夹id去获取收藏夹信息
        this.getCollectionById()

        //-------------------------------------------活动导航样式修改-------------------------------
        // 如果存在活动导航，仅执行一次
        if (document.getElementById('active')){
          // 去除活动样式
          document.getElementById('active').id  = ''
          // 设置当前活动导航
          this.active_nav = event.currentTarget
        }
        // 如果当前活动导航和需要的活动导航不一致
        else if(this.active_nav != event.currentTarget){
          // console.log(1);
          // 去除上一个活动导航样式，重新设置活动导航为当前点击导航
          this.active_nav.style.backgroundColor = "#fff"
          this.active_nav.style.color = "black";
          this.active_nav = event.currentTarget
        }
        // 导航元素相同，不改变
        else if(this.active_nav == event.currentTarget){
          // console.log(2);
          // this.active_nav.style.backgroundColor = "#fff"
          // this.active_nav.style.color = "black";
        }
        event.currentTarget.style.backgroundColor = "#00a1d6"
        event.currentTarget.style.color = "white";
      },
      // ----------------------------------------左边导航--------------------------------------


      // ----------------------------------------右边内容--------------------------------------
      // 右侧内容排序改变
      changeRightCondition(e){
        if(e.target.innerText == '加入时间倒序'){
          this.rightNavCondition = 'desc'
        }
        else if(e.target.innerText == '加入时间正序'){
          this.rightNavCondition = 'asc'
        }
        // 根据收藏夹id获取收藏夹视频
        this.getCollectionVidListById(this.page)
      },

      // 分页每页条数改变时触发
      handleSizeChange(val) {
        console.log(`每页 ${val} 条`);
      },

      // 分页当前页面改变时触发
      handleCurrentChange(val) {
        // console.log(`当前页: ${val}`);
        // 记录当前页码
        this.page = val
        // 获取新内容
        this.getCollectionVidListById(val)
      },
      // ----------------------------------------右边内容--------------------------------------


      //-------------------------------------------初始化-----------------------------------------

      // 根据收藏id获取收藏夹视频id
      async getCollectionVidListById(page){
        let data = await getCollectionVidListById(this.id, page, this.rightNavCondition)
        this.collection_vidList = data
        // console.log(this.collection_list)
        console.log(this.collection_vidList);
        this.getVideoListByVid()
      },

      // 根据vid获取视频信息  使用async await防止异步请求结果顺序混乱
      async getVideoListByVid(){
        // 清空原列表存储内容
        this.collection_videoList = []
        for (let i = 0; i<this.collection_vidList.length; i++){
          // 获取视频
          let data = await getVideoByVid(this.collection_vidList[i].vid)
          this.collection_videoList.push(data)
        }
        console.log(this.collection_videoList);
        // 开始渲染
        this.state = true
      },

      // 根据vid获取收藏夹封面视频信息
      async getCollectionFirstVideoByVid(){
        let data = await getVideoByVid(this.collection.videolist[0].vid)
        // 设置当前展示收藏夹的首个视频
        this.collection_cover_video = data
        console.log(this.collection_cover_video);
      },

      // 根据收藏id获取收藏夹信息
      async getCollectionById(){
        let data = await getCollectionById(this.id)
        // 设置当前展示收藏夹信息
        this.collection = data
        // console.log(this.collection_list)
        console.log(this.collection);
        // 收藏夹存在视频
        if (this.collection.videolist.length > 0) {
          // 根据收藏id获取收藏夹视频id
          this.getCollectionVidListById(this.page)
          // 获取封面视频信息
          this.getCollectionFirstVideoByVid()
        }
        else{
          console.log("收藏夹为空");
        }
      },

      //发送请求，根据uid获取目标空间主人的信息
      async getUserInfoByUid(){
        let data = await getUserInfoByUid(this.$store.state.spaceUserId)
        // 设置空间用户信息为获取到的信息
        this.userInfo = data
      },

      // 根据空间用户uid查询用户所有收藏
      async getCollectionList(){
        let data = await getUserAllCollectionByPage(this.$store.state.spaceUserId, 'desc', 1000)
        // console.log(res.data)
        this.collectionsInfo = data
        // 左边导航渲染数据
        this.collection_list = data.videoList
        
        // 用户收藏夹数量大于0
        if(this.collectionsInfo.total>0){
          if(this.id == 0){
            // 跳转过来时没有指定收藏夹
            // 设置当前展示的id为第一个收藏夹id
            this.id = this.collectionsInfo.videoList[0].id
          }
          // 根据收藏夹id获取收藏夹信息
          this.getCollectionById()
          // this.getCollectionListById()
          // 获取空间主人的信息
          this.getUserInfoByUid()
        }
      },
      //-------------------------------------------初始化-----------------------------------------

      // 获取视频封面url
      getImgURL(address){
        return getVideo(address)
      },
    },
    created(){
      // 先根据uid获取所有收藏夹信息
      this.getCollectionList()

      // 如果是首页跳转过来的，携带了需要显示的收藏夹id，默认id为1
      if(typeof this.$route.query.collection_id == typeof ''){
        this.id =  this.$route.query.collection_id
      }
      // console.log(this.id);
    }
  }
</script>

