<!-- 
  项目：Elyden.com
  创建时间：2024.01.29
  上次更新时间：2023.05.11
  组件名称：SpaceHome
  此文件负责的板块：用户空间首页
    功能：
      1、游客查看空间首页
      2、空间主人编辑空间首页
        置顶推荐视频
        投稿视频
        合集视频
        收藏视频
        点赞记录视频（未实现）
        献花记录视频（未实现）
        转发记录视频（未实现）
        公告（未实现）
        个人简介（未实现）
  -->
<template>
  <div class="space_main_content">
    <!-- 个人空间内容左边 -->
    <div class="space_content_l">
      <!-- 用户设置的推荐内容 -->
      <div class="user_recommend_content" v-if="showModel=='me'||issetrecommend">
        <div>
          <!-- 自己视角标题 -->
          <div class="nav_title" v-if="showModel=='me'">访客会看到</div>
          <!-- 外人视角标题 -->
          <div class="nav_title" v-if="showModel=='other' && issetrecommend">推荐视频</div>
          <!-- 本人还没添加置顶 -->
          <div class="add_recommend_content" v-if="showModel=='me'&&!issetrecommend">
            <!-- 添加置顶区域 -->
            <div class="add_recommend" @click="setRecommendVideo">
              <div class="add_txt">设置置顶内容</div>
            </div>
          </div>
          <!-- 本人添加了置顶 -->
          <div class="recommend_content" v-if="issetrecommend" @mouseenter="show_button" @mouseleave="hiden_button">
            <!-- 推荐视频封面 -->
            <div class="recommend"  @click="gotovideo(recommend_video.vid)">
              <img class="recommend_cover" :src=getImgURL(recommend_video.coverAddress) alt="稿件封面">
            </div>
            <!-- 推荐视频信息 -->
            <div class="recommend_msg">
              <!-- 内容 -->
              <div class="recommend_msg_main">
                <!-- 视频标题 -->
                <div class="recommend_name">
                  {{ recommend_video.title }}
                </div>
                <!-- 视频数据 -->
                <div class="recommend_data">
                  <!-- 播放数 -->
                  <div class="recommend_data_item recommend_play_count">
                    <svg class="icon_recommend_icon" aria-hidden="true">
                      <use xlink:href="#icon-shipin"></use>
                    </svg>
                    {{ recommend_video.playedNum / 10000 > 1 ? recommend_video.playedNum / 10000+"万": recommend_video.playedNum}}
                  </div>
                  <!-- 弹幕数 -->
                  <div class="recommend_data_item recommend_comment">
                    <svg class="icon_recommend_icon" aria-hidden="true">
                      <use xlink:href="#icon-danmushu"></use>
                    </svg>
                    {{ recommend_video.incomment / 10000 > 1 ? recommend_video.incomment / 10000+"万": recommend_video.incomment}}
                  </div>
                  <!-- 发布日期 -->
                  <div class="recommend_data_item recommend_date">
                    {{ recommend_video.publishTime? recommend_video.publishTime.slice(0,10) :''}}
                  </div>
                </div>
                <!-- 视频简介 -->
                <div>{{ recommend_video.synopsis }}</div>
              </div>
              <!-- 切换置顶和取消按钮 -->
              <div class="control_button" v-if="showModel=='me' && issetrecommend" ref="recommend_button">
                <div class="chance_video_button" @click="changeRecommentVideo">切换视频</div>
                <div class="cancel_video_button" @click="cancelRecommendVideo">取消置顶</div>
              </div>
            </div>
          </div>
        </div>
      </div>
      <!-- 用户视频     组件-->
      <div class="user_video_content">
        <!-- 用户投稿视频顶部导航 -->
        <div class="user_video_nav">
          <!-- 左边导航 -->
          <div class="user_video_nav_l">
            <!-- 自己视角 标题 -->
            <div class="video_nav_item1" v-if="showModel=='me'"><span class="video_title" @click="gotoSpaceContribution">我的视频</span><span class="compilation_title_num">{{ videoTotal }}</span></div>
            <!-- 外人视角 标题 -->
            <div class="video_nav_item1" v-if="showModel=='other'"><span class="video_title" @click="gotoSpaceContribution">TA的视频</span><span class="compilation_title_num">{{ videoTotal }}</span></div>
            <!-- 排序方式 -->
            <div class="video_nav_l_l">
              <div class="video_nav_l new_update active" @click="changeOrderByVideo">最新发布</div>
              <div class="video_nav_l play_more" @click="changeOrderByVideo">最多播放</div>
              <div class="video_nav_l collect_more" @click="changeOrderByVideo">最多收藏</div>
            </div>
          </div>
          <!-- 右边导航 -->
          <div class="user_video_nav_r">
            <!-- 播放全部按钮 -->
            <div class="video_nav_r play_all_button" @click="addVideoPAndGoToVideoPlayer2($store.state.spaceUserId)">播放全部</div>
            <!-- 查看更多按钮 -->
            <div class="video_nav_r chack_more_button" @click="gotoSpaceContribution">查看更多</div>
          </div>
        </div>
        <!-- 视频列表 -->
        <div class="video_list">
          <!-- 单个视频 -->
          <div class="video_list_item1" v-for="(item,index) in video_list" :key="item.vid" @click="gotovideo(item.vid)">
            <!-- 视频封面 -->
            <div class="video_list_item1_cover">
              <img :src=getImgURL(item.coverAddress) alt="稿件封面">
            </div>
            <!-- 视频标题 -->
            <div class="video_list_item1_title">
              <span class="video_title"> {{ item.title }} </span>
            </div>
            <!-- 视频信息 -->
            <div class="video_list_item1_msg">
              <!-- 播放量 -->
              <div>
                <svg class="play_video_icon" aria-hidden="true">
                  <use xlink:href="#icon-shipin"></use>
                </svg>
                {{ item.playedNum / 10000 > 1 ? (item.playedNum / 10000).toFixed(1)+"万": item.playedNum}}
              </div>
              <!-- 发布日期 -->
              <div class="video_data_item recommend_date">
                {{ item.publishTime? item.publishTime.slice(0,10) :''}}
              </div>
            </div>
          </div>
        </div>
      </div>
      <!-- 用户合集视频     组件 因为和视频结构一致，使用v-for渲染-->
      <div class="video_compilation" v-for="(compilationItem,index) in compilation_list" :key="compilationItem.id">
        <!-- 合集顶部导航 -->
        <div class="user_video_nav">
          <!-- 合集名称和数量 -->
          <div class="user_video_nav_l">
            <div class="video_nav_item1 video_title" @click="gotoCompilation(compilationItem.id, compilationItem.name)">合集 · {{ compilationItem.name }}<span class="compilation_title_num">{{compilationItem.totalNum}}</span></div>
          </div>
          <!-- 播放全部和查看更多按钮 -->
          <div class="user_video_nav_r">
            <div class="video_nav_r play_all_button" @click="addVideoPAndGoToVideoPlayer(compilationItem.id)">播放全部</div>
            <div class="video_nav_l chack_more_button" @click="gotoCompilation(compilationItem.id, compilationItem.name)">查看更多</div>
          </div>
        </div>
        <!-- 视频列表  v-if 是防止三层数据v-for读不到第三层数据而报错 -->
        <div class="video_list" v-if="compilation_Videolist[index]">
          <!-- 单个视频 -->
          <div class="video_list_item1" v-for="(videoItem,index) in compilation_Videolist[index].videoList" :key="videoItem.vid" @click="gotovideo(videoItem.vid)">
            <!-- 视频封面 -->
            <div class="video_list_item1_cover">
              <img :src=getImgURL(videoItem.coverAddress) alt="稿件封面">
            </div>
            <!-- 视频标题 -->
            <div class="video_list_item1_title">
              <span> {{ videoItem.title }} </span>
            </div>
            <!-- 视频信息 -->
            <div class="video_list_item1_msg">
              <!-- 播放量 -->
              <div>
                <svg class="play_video_icon" aria-hidden="true">
                  <use xlink:href="#icon-shipin"></use>
                </svg>
                {{ videoItem.playedNum / 10000 > 1 ? (videoItem.playedNum / 10000).toFixed(1)+"万": videoItem.playedNum}}
              </div>
              <!-- 发表日期 -->
              <div class="video_data_item recommend_date">
                {{ videoItem.publishTime? videoItem.publishTime.slice(0,10) :''}}
              </div>
            </div>
          </div>
        </div>
      </div>
      <!-- 添加合集 -->
      <div class="add_compilation" v-if="showModel=='me'">
        <!-- 顶部导航 -->
        <div class="user_video_nav">
          <div class="user_video_nav_l">
            <div class="video_nav_item1 video_title">添加合集</div>
          </div>
        </div>
        <!-- 添加合集按钮 -->
        <button class="add_compilation_button" @click="dialogCompilationVisible = true">添加合集</button>
      </div>
      <!-- 收藏列表 -->
      <div class="video_collection" v-if="spaceInfo.isOpenCollection || showModel=='me'">
        <!-- 顶部导航 -->
        <div class="user_video_nav">
          <!-- 顶部导航左边 -->
          <div class="user_video_nav_l">
            <div class="video_nav_item1 video_title" @click="gotoCollection">
              <!-- 自己模式 标题 -->
              <span class="video_title" v-if="showModel=='me'">我</span>
              <!-- 外人模式 标题 -->
              <span class="video_title" v-if="showModel=='other'">TA</span>的收藏夹
              <!-- 收藏夹数量 -->
              <span class="collection_title_num">{{collection_list.total}}</span>
            </div>
          </div>
          <!-- 顶部导航右边 查看更多按钮 -->
          <div class="user_video_nav_r">
            <div class="video_nav_l chack_more_button"  @click="gotoCollection" >查看更多</div>
          </div>
        </div>
        <!-- 收藏夹列表 -->
        <div class="collection_list">
          <!-- 单个收藏夹 -->
          <div class="collection_list_item" v-for="(videoItem,index) in collection_list.videoList" @click="gotoCollection(videoItem.id)">
            <!-- 收藏夹内容物数量 -->
            <span class="collection_num">{{ videoItem.totalNum }}</span>
            <!-- 收藏夹封面 -->
            <img class="collection_cover" :src="getImgURL(collection_videoList[index].video.coverAddress)" @error="defimg()"/>
            <!-- 收藏夹名字 -->
            <div class="collection_name">{{ videoItem.name}}</div>
          </div>
        </div>
      </div>

      <!-- 添加合集弹窗 -->
      <el-dialog
        title="新建合集"
        :visible.sync="dialogCompilationVisible"
        top="30vh"
        width="30%"
        :before-close="handleClose2">
        <div>
          <form v-if="!secondPage" style="text-align: center; width: 100%; margin: 20px;">
            <!-- 新合集标题 -->
            <div style="margin-bottom: 20px;"><span>合集标题：</span><input class="new_compilation_titleBox" type="text" v-model="new_compilation.name" placeholder="给你的新合集取一个标题吧♪" style="padding: 0 5px; width: 70%; height: 30px;"></div>
            <!-- 新合集简介 -->
            <div style="height: 100px; line-height: 100px; border-radius: 10px;"><span>合集简介：</span><textarea type="text" v-model="new_compilation.synopsis" class="new_compilation_synopsisBox" placeholder="向大家介绍一下这个新合集吧♪" style="padding: 0 5px; height: 80px; width: 70%; vertical-align: middle;"></textarea></div>
          </form>
          <form v-if="secondPage">
            <!-- 标题 -->
            <div style="font-size: 20px;">
              <div>选择视频</div>
              <div><el-checkbox :indeterminate="isIndeterminate" v-model="checkAll" @change="handleCheckAllChange">全选</el-checkbox></div>
            </div>
            <!-- 可选择视频列表 -->
            <ol style="height: 30vh; overflow-x: auto;" @scroll="selectVideoSmallPageScrollBottom">
              <!-- 单个视频 -->
              <li v-for="(item,index) in select_video_list" :key="item.vid">
                <div style="position: relative; width: 90%;">
                  <!-- 视频 -->
                  <div class="video_list_item1">
                    <!-- 视频封面 -->
                    <div class="video_list_item1_cover">
                      <img :src=getImgURL(item.coverAddress) alt="稿件封面">
                    </div>
                    <!-- 视频标题 -->
                    <div class="video_list_item1_title">
                      <span class="video_title"> {{ item.title }} </span>
                    </div>
                    <!-- 视频信息 -->
                    <div class="video_list_item1_msg">
                      <!-- 播放量 -->
                      <div>
                        <svg class="play_video_icon" aria-hidden="true">
                          <use xlink:href="#icon-shipin"></use>
                        </svg>
                        {{ item.playedNum / 10000 > 1 ? item.playedNum / 10000+"万": item.playedNum}}
                      </div>
                      <!-- 发表日期 -->
                      <div class="video_data_item recommend_date">
                        {{ item.publishTime? item.publishTime.slice(0,10) :''}}
                      </div>
                    </div>
                  </div>
                  <!-- 选择框 -->
                  <el-checkbox-group style="scale: 2; position: absolute; right: 0; top: 30%;" v-model="checkedCities" @change="handleCheckedCitiesChange">
                    <el-checkbox :label="item.vid">{{  }}</el-checkbox>
                  </el-checkbox-group>
                </div>
              </li>
            </ol>
          </form>
        </div>
        <span slot="footer" class="dialog-footer">
          <!-- 取消新建合集 -->
          <el-button v-if="!secondPage" @click="dialogCompilationVisible = false">取 消</el-button>
          <!-- 下一步选择加入合集视频 -->
          <el-button v-if="!secondPage" @click="addNewCompilationNextPage">下一步</el-button>
          <!-- 返回新建合集上一步 -->
          <el-button v-if="secondPage" @click="secondPage = false">上一步</el-button>
          <!-- 确认新建合集 -->
          <el-button v-if="secondPage" type="primary" @click="saveNewCompilation">确定</el-button>
        </span>
      </el-dialog>

      <!-- 设置置顶推荐视频弹窗 -->
      <el-dialog
        title="选择推荐视频"
        :visible.sync="dialogRecommendVisible"
        top="25vh"
        width="30%"
        :before-close="handleClose">
        <div>
          <!-- 搜索我的视频 -->
          <div style="position: relative;">
            <input style="width: 100%; box-sizing: border-box; border-radius: 10px; border: 1px solid gray; padding: 5px 10px;" type="text" v-model="searchContent" @keyup.enter="searchMyContent" placeholder="搜索我的稿件" >
            <span style="position: absolute; line-height: 27.6px; right: 15px; cursor: pointer;" @click="searchMyContent">🔍</span>
          </div>
          <!-- 提示找到的信息 -->
          <span style="font-size: 12px;" v-if="searchContent.trim() != '' && searchMy">共找到关于“</span>
          <span style="font-size: 12px; color: rgb(255, 120, 120);" v-if="searchContent.trim() != '' && searchMy">{{searchContent}}</span>
          <span style="font-size: 12px;" v-if="searchContent.trim() != '' && searchMy">”的{{recommendTotal}}个视频</span>
          <form>
            <div style="display: flex; justify-content: space-between; margin-bottom: 5px;">
              <!-- 标题 -->
              <div style="color: black; font-size: 14px;">选择视频</div>
              <!-- 内容排序方式 -->
              <div class="head_nav" @click="changeRecommendOrder">
                <span class="active" style="margin-right: 10px;" ref="now_active_recommend_nav">时间倒叙</span>
                <span>最多播放</span>
              </div>
            </div>
            <!-- 视频列表 -->
            <ol style="height: 30vh; overflow-x: auto;" @scroll="scrollRecommendVideoList" ref="recommendVideoList">
              <!-- 视频 -->
              <li class="recommend_video_select" style="margin-bottom: 5px; border-radius: 5px;" v-for="(item,index) in selectRecommendVideoList" :key="item.vid" @click="seletedRecommend(item.vid)">
                <div style="position: relative; width: 95%;">
                  <div class="recommendVideo" style="display: flex;">
                    <!-- 视频封面 -->
                    <div class="video_item_l">
                        <img :src=getImgURL(item.coverAddress) alt="稿件封面">
                    </div>
                    <!-- 内容 -->
                    <div class="video_item_r" style="display: flex; flex-direction: column; justify-content: space-between; margin-left: 10px; width: 100%;">
                      <!-- 视频标题 -->
                      <div class="video_item_title">
                        <span > {{ item.title }} </span>
                      </div>
                      <!-- 视频信息 -->
                      <div class="video_item_msg" style="display: flex; justify-content: space-between; width: 200px;">
                        <!-- 播放量 -->
                        <div>
                          <svg class="play_video_icon" aria-hidden="true"><use xlink:href="#icon-shipin"></use></svg>
                          {{ item.playedNum / 10000 > 1 ? item.playedNum / 10000+"万": item.playedNum}}
                        </div>
                        <!-- 发表日期 -->
                        <div class="publish_date">
                          {{ item.publishTime? item.publishTime.slice(0,10) :''}}
                        </div>
                      </div>
                    </div>
                  </div>
                </div>
              </li>
            </ol>
          </form>
        </div>
        <span slot="footer" class="dialog-footer">
          <el-button  @click="cancelRecommend">取 消</el-button>
          <el-button  type="primary" @click="confirmRecommendVideo">确定</el-button>
        </span>
      </el-dialog>
    </div>

    <!-- 个人空间内容右边 -->
    <div class="space_content_r">
      <!-- 身份认证栏 -->
      <div class="identification_content">
        <div class="goto_identification">
          <div class="goto_identification_msg1">点此申请账号认证</div>
          <div class="goto_identification_msg2">获取认证,享受更多福利</div>
        </div>
      </div>
      <!-- 公告栏 自己访问 -->
      <div class="bulletin_board" v-if="showModel=='me'">
        <div class="bulletin_board_content">
          <div class="bulletin_board_nav">公告</div>
          <textarea class="bulletin_board_textarea" name="bulletin_board" cols="30" rows="10"></textarea>
        </div>
      </div>
      <!-- 公告栏 别人访问 -->
      <div class="bulletin_board" v-if="showModel=='other'">
        <div class="bulletin_board_content">
          <div class="bulletin_board_nav">公告</div>
          <div class="bulletin">如果你因错过太阳而流泪，那么你也将错过群星。</div>
        </div>
      </div>
      <!-- 用户信息栏 -->
      <div class="user_info">
        <div class="user_info_content">
          <div class="user_info_nav">个人资料</div>
          <div style="margin-top: 15px; display: flex; justify-content: space-evenly;">
            <div class="uid">UID: {{userInfo.uid}}</div>
            <div class="ubirthday" v-if="spaceInfo.isOpenBirthday == 1 || showModel =='me'">生日: {{userInfo.birthday ?  userInfo.birthday.slice(0,10):''}}</div>
          </div>
        </div>
      </div>
    </div>
  </div>
</template>

<script>
import { getUserAllCollectionByPage } from '@/api/collection';
import { getCompilationVidList, saveNewCompilation } from '@/api/compilation';
import { cancelRecommendVideo, getSpaceSetInfoByUid, setRecommendVideo } from '@/api/space';
import { getUserInfoByUid } from '@/api/user';
import { countUserVideo, getUserAllVideoByPage, getUserVideoByPage, getVideo, getVideoByVid, searchSpaceVideo } from '@/api/video';


  export default{
    name:'SpaceHome',
    computed:{
      // 空间展示模式
      showModel() {
        return this.$store.state.spaceViewModel
      },
      // 用户空间状态信息
      spaceInfo(){
        // console.log(this.$store.state.spaceInfo);
        return this.$store.state.spaceInfo
      },
      // 是否设置了推荐
      issetrecommend(){
        return this.spaceInfo.isSetRecommend == '1'
      },
      // 当前登录的用户信息
      loginUser(){
        return this.$store.state.loginUser || ''
      },
    },
    data(){
      return{
        // ---------------------------------------推荐视频数据----------------------------------------
        // 是否显示置顶推荐视频弹窗
        dialogRecommendVisible: false,
        // 是否进行搜索我的
        searchMy:false,
        // 选择的视频列表
        selectRecommendVideoList: [],
        // 当前活动导航
        now_active_recommend_nav:'',
        // 当前已选择的视频
        selected_video:'',
        // 当前选择的视频id
        selected_vid:'',
        // 排序条件
        recommend_order:'publish_time',
        // 当前页数
        recommend_page:1,
        // 分段获取计时器
        recommend_timer:'',
        // 搜索内容
        searchContent:'',
        // 置顶推荐总内容数量
        recommendTotal:0,
        // 用户是否设置推荐置顶视频
        // isSetRecommend:true,
        // 推荐视频对象
        recommend_video:{},
        // ---------------------------------------推荐视频数据----------------------------------------


        // ------------------------------------------新合集数据------------------------------------
        // 添加合集弹窗显示
        dialogCompilationVisible: false,
        // 添加合集是否处于第二页
        secondPage: false,
        // 用以表示 checkbox 的不确定状态，一般用于实现全选的效果
        isIndeterminate: true,
        checkAll: false,
        checkedCities: [],
        // 添加合集界面的选择视频列表
        select_video_list:[],
        // 计时器
        timer:'',
        // 选择视频列表当前页面
        page:1,
        
        // 新合集信息
        new_compilation:{
          name:'',
          synopsis:'',
          // 合集创建时间
          time:'',
          uid:'',
        },
        // 字符串vid字符串拼接
        vidlist:'',
        // ------------------------------------------新合集数据------------------------------------

        // 导航条点击位置
        click_scroll_bar_position : '',
        // 用户的首页合集展示列表
        // homeShowList:[],
        // 视频列表的视频总数量
        videoTotal:0,
        // 用户视频 排序条件
        condition:'publish_time', 

        // 视频列表
        video_list:{},
        // 合集种类列表
        compilation_list:[],
        // 合集视频列表
        compilation_Videolist:[],
        // 收藏列表
        collection_list:{},
        // 收藏视频列表
        collection_videoList:[],

        // 当前空间所属用户的信息
        userInfo:{},

        // 默认图片路径
        defaultImg:require("/public/img/nollData.gif"),

        // 是否设置置顶推荐
        // recomend: sessionStorage.getItem("spaceInfo").isSetRecommend
      }
    },
    watch:{
      // 路由更新
      $route(to, from) {
        this.getRecommendVideoById()
        this.getSpaceUserCountNum()
        this.getVideoByUidAndPage()
        this.getCompilationVidList()
        this.getCollectionList()
      },
    },
    methods:{
      // 前往投稿界面
      gotoSpaceContribution(){
        this.$router.push({
          path:'/space/contribution',
        })
        this.$store.dispatch('barPosition', '221px')
        document.documentElement.scrollTop = 0;
      },

      // 前往合集界面
      gotoCompilation(id, name){
        this.$router.push({
          path:'/space/compilation/child',
        })
        console.log(id);
        console.log(name);
        // 当前显示合集id
        this.$store.dispatch('changeCompilationId', id)
        // 当前合集名称
        this.$store.dispatch('changeCompilationTitle', `合集 · ${name}`)
        // 导航条跳转
        this.$store.dispatch('barPosition', '322px')
        document.documentElement.scrollTop = 0;
      },

      // 前往收藏界面
      gotoCollection(id = 0){
        this.$router.push({
          path:'/space/collection',
          query:{
            collection_id:id
          }
        })
        this.$store.dispatch('barPosition', '423px')
        document.documentElement.scrollTop = 0;
      },

      //视频跳跃
      gotovideo(videoid){
        this.$router.push({
          path:'/video', 
          query:{
            vid:videoid
          }
        })
      },

      // 前往视频播放，合集模式
      addVideoPAndGoToVideoPlayer(compilation_id){
        console.log(compilation_id);
        this.$router.push({
          path:'/video', 
          query:{
            havePList:true,
            from:'compilation',
            id:compilation_id
          }
        })
      },
      
      // 前往视频播放，所有视频模式
      addVideoPAndGoToVideoPlayer2(uid){
        console.log(uid);
        this.$router.push({
          path:'/video', 
          query:{
            havePList:true,
            from:'video',
            id:uid
          }
        })
      },

      // 用户投稿视频的导航 改变排序顺序
      changeOrderByVideo(e){
        // console.log(e.target.className);
        if(e.target.className == 'video_nav_l new_update'){
          this.condition = 'publish_time'
        }
        else if(e.target.className == 'video_nav_l play_more'){
          this.condition = 'played_num'
        }
        else if(e.target.className == 'video_nav_l collect_more'){
          this.condition = 'collection'
        }
        if(document.getElementsByClassName('active').length>0){
          document.getElementsByClassName('active')[0].classList.remove('active')
        }
        e.target.classList.add('active')  
        this.getVideoByUidAndPage()
      },

      // --------------------------------------设置推荐置顶视频逻辑---------------------------------
      // 搜索我的内容
      async searchMyContent(){
        console.log("搜索");
        if (this.searchContent.trim() == '') {
          return
        }
        console.log("搜索内容" + this.searchContent);
        this.recommend_page = 1
        let data = await searchSpaceVideo(this.loginUser.uid, this.searchContent, this.recommend_order, this.recommend_page)
        this.searchMy = true
        this.selectRecommendVideoList = data.videoList
        this.recommend_page += 1
        this.recommendTotal = data.total
      },

      // 切换推荐视频
      changeRecommentVideo(){
        console.log("切换");
        this.setRecommendVideo()
      },

      //取消置顶操作
      cancelRecommend(){
        // 取消显示
        this.dialogRecommendVisible = false
        // 清除计时器
        clearTimeout(this.recommend_timer)
        // 数据置为空
        this.selectRecommendVideoList = []
        // 当前页为1
        this.recommend_page = 1
        // 排序为默认
        this.recommend_order = 'publish_time'
        // 搜索内容空
        this.searchContent = ''
        // 选项恢复活动样式为默认
        if (this.selected_video) {
          this.selected_video.style.backgroundColor = 'white'
          this.selected_video.style.color = '#606266'
        }
        // 导航恢复
        if (this.now_active_recommend_nav) {
          this.now_active_recommend_nav.classList.remove('active')
        }
        this.now_active_recommend_nav = this.$refs.now_active_recommend_nav
        this.now_active_recommend_nav.classList.add('active')
      },

      // 取消置顶内容
      cancelRecommendVideo() {
        this.$confirm('确定取消置顶吗？', '提示', {
          confirmButtonText: '确定',
          cancelButtonText: '取消',
          type: 'warning'
        }).then(async () => {
          await cancelRecommendVideo(this.spaceInfo.uid)
          this.dialogRecommendVisible = false
          // 重新获取空间设置信息
          this.getSetInfoByspaceUid()
          this.$message({
            type: 'success',
            message: '取消成功!'
          });
        })
      },

      // 选择置顶内容完毕
      seletedRecommend(vid){
        // 如果当前存在活动选择项，恢复普通样式
        if (this.selected_video) {
          this.selected_video.style.backgroundColor = 'white'
          this.selected_video.style.color = '#606266'
        }
        // 设置点击元素为活动样式
        event.currentTarget.style.color = 'white'
        event.currentTarget.style.backgroundColor = '#00a1d6'
        // 设置点击对象为当前活动选项
        this.selected_video = event.currentTarget
        // 设置选择的视频id
        this.selected_vid = vid;
      },

      // 确认提交置顶推荐视频
      async confirmRecommendVideo(){
        if (!this.selected_vid) {
          return
        }
        let data = await setRecommendVideo(this.spaceInfo.uid, this.selected_vid)
        if (data == 0) {
          // 失败
          // 恢复原样
          this.cancelRecommend()
          return
        }
        // 重新获取空间信息
        this.getSetInfoByspaceUid()
        // 恢复原样
        this.cancelRecommend()
      },

      // 根据目标uid获取目标空间的设置信息
      async getSetInfoByspaceUid(){
        let data = await getSpaceSetInfoByUid(this.$store.state.spaceUserId)
        // 提交空间信息
        this.$store.dispatch('spaceInfo', data)
        // 获取推荐视频信息
        this.getRecommendVideoById()
      },

      // 设置置顶推荐内容
      setRecommendVideo(){
        console.log("设置推荐");
        // 显示选择弹窗
        this.dialogRecommendVisible = true
        // 获取视频数据
        this.getRecommendVideoList()
      },

      // 改变排序条件
      changeRecommendOrder(){
        if (event.target.innerText == '时间倒叙'){
          this.recommend_order = 'publish_time'
        }
        else if(event.target.innerText == '最多播放'){
          this.recommend_order = 'played_num'
        }
        if(!this.now_active_recommend_nav){
          this.now_active_recommend_nav = this.$refs.now_active_recommend_nav
        }
        this.now_active_recommend_nav.classList.remove('active')
        event.target.classList.add('active')
        this.now_active_recommend_nav = event.target
        // 重新获取第一页视频数据
        this.recommend_page = 1
        this.$refs.recommendVideoList.scrollTop = 0;
        if (this.searchContent.trim() == '') {
          this.getRecommendVideoList()
        }
        else{
          this.searchMyContent()
        }
      },

      // 获取视频
      async getRecommendVideoList(){
        this.recommend_page = 1
        let data = await getUserVideoByPage(this.spaceInfo.uid, this.recommend_order, this.recommend_page)
        this.selectRecommendVideoList = data
        // 页面加1
        this.recommend_page +=1
      },

      // 滚动事件
      scrollRecommendVideoList(){
        console.log("没满");
        let scrollTop = event.target.scrollTop
        let clientHeight = event.target.clientHeight
        let scrollHeight = event.target.scrollHeight
        this.recommend_timer = ''
        if (scrollTop + clientHeight + 30 >= scrollHeight){
          console.log("调用添加视频");
          // 当前获取到的视频总数小于用户所有视频总数，调用后端分页获取视频信息
          if( this.selectRecommendVideoList.length < this.videoTotal && this.searchContent.trim() == ''){
            
            this.addVideoToRecommendVideoList()
          }
          else if (this.searchContent.trim()!='' && this.selectRecommendVideoList.length < this.recommendTotal){
            this.addVideoToRecommendVideoList2()
          }
        }
        
      },

      // 动态添加视频
      async addVideoToRecommendVideoList(){
        // 有计时器时
        if(this.recommend_timer){
          // 清除计时器
          clearTimeout(this.recommend_timer)
          // 重新计时
          this.recommend_timer = setTimeout(async()=>{
              let data = await getUserVideoByPage(this.spaceInfo.uid, this.recommend_order, this.recommend_page)
              this.recommend_page = this.recommend_page + 1
              let temp = data
              temp.forEach((item)=>{
                this.selectRecommendVideoList.push(item)
              })
            },1000)
          }
          // 首次执行
          if(!this.recommend_timer){
            let data = await getUserVideoByPage(this.spaceInfo.uid, this.recommend_order, this.recommend_page)
            this.recommend_page = this.recommend_page + 1
            let temp = data
            temp.forEach((item)=>{
              this.selectRecommendVideoList.push(item)
            })
          }
      },

      // 动态添加视频2 (我的视频模糊搜索内容)
      async addVideoToRecommendVideoList2(){
        // 有计时器时
        if(this.recommend_timer){
          // 清除计时器
          clearTimeout(this.recommend_timer)
          // 重新计时
          this.recommend_timer = setTimeout(async()=>{
              let data = await searchSpaceVideo(this.loginUser.uid, this.searchContent, this.recommend_order, this.recommend_page);
              this.recommend_page += 1
              let temp = data.videoList
              temp.forEach((item)=>{
                this.selectRecommendVideoList.push(item)
              })
            },1000)
          }
          // 首次执行
          if(!this.recommend_timer){
            let data = await searchSpaceVideo(this.loginUser.uid, this.searchContent, this.recommend_order, this.recommend_page);
            this.recommend_page += 1
            let temp = data.videoList
            temp.forEach((item)=>{
              this.selectRecommendVideoList.push(item)
            })
          }
      },

      // 鼠标进入置顶推荐内容区域显示操作按钮
      show_button(){
        // 判断是否拿到元素，在other模式访问时是拿不到的
        if(this.$refs.recommend_button){
          this.$refs.recommend_button.style.display = 'flex'
        }
      },
      
      // 置顶推荐操作按钮隐藏
      hiden_button(){
        // 判断是否拿到元素，在other模式访问时是拿不到的
        if(this.$refs.recommend_button){
          this.$refs.recommend_button.style.display = 'none'
        }
      },
      // --------------------------------------设置推荐置顶视频逻辑---------------------------------

      // ------------------------------------------新建合集逻辑------------------------------------
      // 保存新建合集
      async saveNewCompilation(){
        // 关闭新建合集界面
        this.dialogCompilationVisible = false
        // 关闭新建合集第二页
        this.secondPage = false
        // 设置新合集创建时间
        this.new_compilation.time = Date.now()
        // 设置合集的创建者id
        this.new_compilation.uid = this.loginUser.uid

        // 拼接vid字符串
        this.checkedCities.forEach((item)=>{
          this.vidlist = this.vidlist + item +','
          // console.log(this.vidlist);
        })

        // 发送新建合集请求
        let data = await saveNewCompilation(this.vidlist, this.new_compilation);
        if (data == 0) {
          this.newCompilationError()  // 创建失败
        }
        // 创建成功清空信息，创建失败不清空，减少操作
        this.new_compilation.name=''
        this.new_compilation.synopsis=''
        this.new_compilation.time=''
        this.new_compilation.uid=''
        // 成功提示
        this.newCompilationSuccess()
        // 重新调用数据，刷新列表
        this.getCollectionList()
      },

      // 提示创建新合集失败
      newCompilationSuccess(){
        this.$message({
          message: '创建成功',
          type: 'success'
        });
      },

      // 提示创建新合集失败
      newCompilationError(){
        this.$message.error('创建失败，请稍后重试');
      },

      // 点击新建合集界面的第二页按钮
      addNewCompilationNextPage(){
        // 将视频栏的数据复制到第二页选择视频数据列表
        this.select_video_list = this.video_list
        // 显示第二页
        if (this.new_compilation.name.trim() == '') {
          // 提示必须要标题
          this.newCompilationTitleNullError()
        }
        else{
          this.secondPage = true
        }
      },

      // 提示标题不能为空
      newCompilationTitleNullError(){
        this.$message({
          message: '标题不能为空喔♪',
          type: 'warning'
        });
      },

      // 新建合集选择视频滚动事件
      selectVideoSmallPageScrollBottom(){
        // console.log("asdasd");
        // 当前获取到的视频总数小于用户所有视频总数，调用后端分页获取视频信息
        if( this.select_video_list.length < this.videoTotal){
          console.log("没满");
          let scrollTop = event.target.scrollTop
          let clientHeight = event.target.clientHeight
          let scrollHeight = event.target.scrollHeight
          if (scrollTop + clientHeight + 30 >= scrollHeight){
            console.log("调用添加视频");
            this.addVideoToSelectList()
          }
        }
      },

      // 滚到底部时调用添加视频
      async addVideoToSelectList(){
        // 有计时器时
        if(this.timer){
          // 清除计时器
          clearTimeout(this.timer)
          // 重新计时
          this.timer = setTimeout(async ()=>{
            let data = await getUserVideoByPage(this.spaceInfo.uid, this.condition, `${parseInt(this.page)+1}`)
            this.page = this.page + 1
            let temp = data
            temp.forEach((item)=>{
              this.select_video_list.push(item)
            })
          },500)
        }
        // 首次执行
        if(!this.timer){
          let data = await getUserVideoByPage(this.spaceInfo.uid, this.condition, `${parseInt(this.page)+1}`)
          this.page = this.page + 1
          let temp = data
          temp.forEach((item)=>{
            this.select_video_list.push(item)
          })
          console.log(this.select_video_list);
          // // 设置1s空计时器
          // this.timer = this.timer = setTimeout(()=>{
          // },500)
        }
      
      },

      // 新建合集点击全选按钮
      handleCheckAllChange(val) {
        let cityOptions = []
        this.video_list.forEach((item)=>{
          cityOptions.push(item.vid)
        })
        this.checkedCities = val ? cityOptions : [];
        this.isIndeterminate = false;
      },

      // 选择框点击值变化时调用
      handleCheckedCitiesChange(value) {
        let checkedCount = value.length;
        this.checkAll = checkedCount === this.video_list.length;
        this.isIndeterminate = checkedCount > 0 && checkedCount < this.video_list.length;
        console.log(this.checkedCities);
      },
      
      // 新建合集弹窗/设置置顶推荐弹窗点击关闭时提示
      handleClose(done) {
        this.$confirm('确认关闭？')
          .then(_ => {
            // 恢复原样
            this.cancelRecommend()
            done();
          })
          .catch(_ => {});
      },

      handleClose2(done) {
        this.$confirm('确认关闭？')
          .then(_ => {
            this.dialogCompilationVisible = false
            done();
          })
          .catch(_ => {});
      },
      // ------------------------------------------新建合集逻辑------------------------------------

      // ------------------------------------------初始化逻辑------------------------------------
      // 根据空间用户uid获取用户视频稿件的数量
      async getSpaceUserCountNum(){
        let data = await countUserVideo(this.$store.state.spaceUserId)
        this.videoTotal = data
        console.log(this.videoTotal);
        
      },

      // for循环获取单个合集视频  一页最大10个 使用单线程
      async getCompilationVideoByVid(){
        for (let i = 0; i < this.compilation_list.length; i++) {
          // console.log(this.compilation_list[i].vidList.length);
          // 创建对象
          let obj = { compilation_id : i, videoList : [] }
          if(this.compilation_list[i].vidList.length>0){
            for (let j = 0; j < this.compilation_list[i].vidList.length; j++){
              obj.videoList.push(await getVideoByVid(this.compilation_list[i].vidList[j].vid))
            }
            // this.compilation_list[i].vidList.forEach(item => {
            //   axios.get("/video/" + item.vid)
            //     .then((res)=>{
            //       obj.videoList.push(res.data.data)
            //     })
            // });
          }
          this.compilation_Videolist.push(obj)
        } 
        // console.log(this.compilation_Videolist);
      },

      // 根据vid 获取置顶推荐视频
      async getRecommendVideoById(){
        if(this.$store.state.spaceInfo.isSetRecommend == '0'){
          return
        }
        let data = await getVideoByVid(this.$store.state.spaceInfo.recommendVid)
        this.recommend_video = data
        console.log(this.recommend_video);
      },

      // 根据uid 获取视频 10个一页，其余点击全部跳转其它页面重新获取
      async getVideoByUidAndPage(){
        let data = await getUserVideoByPage(this.$store.state.spaceUserId, this.condition, 1)
        this.video_list = data
        console.log(this.video_list);
      },

      // 根据uid获取合集列表vid
      async getCompilationVidList(){
        let data = await getCompilationVidList(this.$store.state.spaceUserId)
        this.compilation_list = data
        // console.log(this.compilation_list);
        // 封装使用的合集视频数据
        this.getCompilationVideoByVid()
      },

      // 将收藏夹视频信息封装,  这里每个收藏夹数组只有一个元素（收藏夹首个视频）
      getCollectionVideoByVid(){
        for (let i = 0; i < this.collection_list.videoList.length; i++) {
          // 创建对象
          // console.log(this.collection_list.videoList[i]);
          let obj = { collection_id : i, video : {} }
          if(this.collection_list.videoList[i].videolist.length>0){
            this.collection_list.videoList[i].videolist.forEach(async (item) => {
              let data = await getVideoByVid(item.vid)
              obj.video = data
            });
          }
          this.collection_videoList.push(obj)
        } 
        // console.log( this.collection_videoList);
      },

      // 根据空间用户uid查询所有收藏
      async getCollectionList(){
        let data = await getUserAllCollectionByPage(this.$store.state.spaceUserId, 'desc', 8)
        this.collection_list = data
        // console.log(this.collection_list)
        // 将收藏夹视频信息封装,  这里每个收藏夹数组只有一个元素（收藏夹首个视频）
        this.getCollectionVideoByVid()
      },

      // 获取空间用户信息
      async getUserInfoByUid(){
        let data = await getUserInfoByUid(this.$store.state.spaceUserId)
        // 设置空间用户信息为获取到的信息
        this.userInfo = data
      },
      // ------------------------------------------初始化逻辑------------------------------------

      // 图片出错时调用的默认图片
      defimg(){
        let img = event.srcElement;   //当前元素
        img.src = this.defaultImg;
        img.onerror = null; //防止闪图
      },

      // 获取视频封面url
      getImgURL(address){
        return getVideo(address);
      },
    },
    created(){
      // 根据vid 获取置顶推荐视频      前置条件space设置信息
      // 这里延迟获取，因为需要等space组件网络请求拿到空间设置信息
      setTimeout(() => {
        this.getRecommendVideoById()
      }, 100);
      
      
      // 根据空间用户uid获取用户视频稿件的数量
      this.getSpaceUserCountNum()                                  
      // 根据uid 获取视频 10个一页，其余点击全部跳转其它页面重新获取
      this.getVideoByUidAndPage()                                 
      // 根据uid获取合集列表vid
      this.getCompilationVidList()                                
      // 根据空间用户uid查询所有收藏
      this.getCollectionList()                                   
      // 获取空间用户信息
      this.getUserInfoByUid()                                      
    },
    mounted(){
      console.log(this.showModel);
    }
  }
</script>

