<!-- 
  项目：Elyden.com
  创建时间：2024.05.25
  上次更新时间：2023.05.25
  组件名称：VideoComment
  此文件负责的板块：视频评论区
  需要提供参数：要查看的视频id
  需要父组件具有举报功能（直接调用父组件方法）和登录功能（事件总线方式）
    功能：
      1、展示指定视频的评论区
  -->


<template>
  <div class="video_comment" v-if="state">
    <!-- 评论区顶部导航 -->
    <div class="content_nav">
      <!-- 左边 -->
      <div class="comment_nav_left">
        评论
        <!-- 当前视频评论总数 -->
        <span class="comment_total">{{video.comments}}</span>
      </div>
      <!-- 右边 -->
      <div class="comment_nav_right">
        <!-- 热门按钮 -->
        <div class="comment_nav_hot">
          <span class="hot_button activeCommentNav" @click="changeCommentOrder('热门')" ref="nowActiveCommentOrderNav">热门</span>
        </div>
        <!-- 最新按钮 -->
        <div class="comment_nav_new">
          <span class="new_button" @click="changeCommentOrder('最新')">最新</span>
        </div>
      </div>
    </div>
    <!-- 发布评论栏 -->
    <div class="comment_input">
      <!-- <input class="comment_input_box" type="text" > -->
      <!-- 输入框 -->
      <el-input
        type="textarea"
        :autosize="{ minRows: 2, maxRows: 5}"
        placeholder="请输入内容"
        @keydown.enter.native="sendComment2"
        v-model="comment.comment">
      </el-input>
      <!-- <textarea class="comment_input_box" name="comment" cols="30" rows="10" @keydown.enter="sendComment2" v-model="comment.comment"></textarea> -->
      <!-- 发布按钮 -->
      <div class="comment_button" @click="sendComment2">发布</div>
    </div>
    <!-- 评论展示区 -->
    <div class="comment_list" ref="commentListDom">
      <!-- 单个父评论 -->
      <div class="comment_list_item" v-for="(item,index) in commentList" :key="commentList.cid" :id="item.cid">
        <!-- 用户简介卡片 -->
        <div class="comment_item_l">
          <!-- 用户简介界面弹窗 -->
          <SmallUserCard :user="item.user"></SmallUserCard>
        </div>
        <!-- 评论右边 -->
        <div class="comment_item_r">
          <!-- 评论顶部 -->
          <div class="comment_top_nav">
            <!-- 评论所属发布者名称 -->
            <div class="user_name user_name_comment" v-if="item.user">{{item.user.uName}}</div>
            <!-- 评论举报 🚨 -->
            <!-- <div class="comment_more_control">┇</div> -->
            <!-- 更多选择 -->
            <el-dropdown @command="handleCommand">
              <!-- 更多选择图标 -->
              <i class="el-icon-more comment_more_control" ></i>
              <!-- 下拉菜单 -->
              <el-dropdown-menu slot="dropdown">
                <el-dropdown-item :command="item.cid">🚨</el-dropdown-item>
              </el-dropdown-menu>
            </el-dropdown>
          </div>
          <!-- 评论内容区 -->
          <div class="comment">
            <!-- 评论内容 -->
            <span class="comment_content">{{ item.comment }}</span>
            <!-- 评论内容信息 -->
            <div class="comment_info">
              <!-- 发布日期 -->
              <div class="comment_info_item comment_time">{{item.time}}</div>
              <!-- 点赞 -->
              <div class="comment_info_item" @click="giveGoodToComment(item.cid)" :class="{'videoInfoActive': commentGoodIdList.indexOf(Number(item.cid))!=-1}">
                <!-- 点赞 -->
                <svg-icon iconname="icon-good"></svg-icon>
                <span class="comment_good_num">{{item.good}}</span>
              </div>
              <!-- 点踩 -->
              <svg-icon iconname="icon-good" class="comment_info_item dislike_icon" @click.native="giveBadToComment(item.cid)" :class="{'videoInfoActive': commentBadIdList.indexOf(Number(item.cid))!=-1}"></svg-icon>
              <!-- 最佳评论按钮 -->
              <div class="comment_info_item comment_answer_button" @click="addanswer(index)">回复</div>
            </div>
            <!-- 追加评论展示区 (父评论有追加评论才展示)-->
            <div class="comment_answer" v-if="item.answer=='1'">
              <div class="comment_answer_list">
                <!-- 单个追加评论 -->
                <div class="comment_answer_list_item" v-for="(additem, addindex) in item.addcomment" v-if="additem.user" :key="additem.id">
                  <!-- 追加评论所属用户头像和缩小简介界面 -->
                  <div class="comment_item_l">
                    <!-- 用户头像缩小简介界面弹窗 -->
                    <SmallUserCard :user="additem.user"></SmallUserCard>
                  </div>
                  <!-- 追加评论内容 -->
                  <div class="comment_item_r">
                    <!-- 追加评论顶部 -->
                    <div class="comment_top_nav">
                      <!-- 用户名称 -->
                      <div class="user_name user_name_comment">{{additem.user.uName}}</div>
                      <!-- <div>┇</div> -->
                      <!-- 更多选项 -->
                      <el-dropdown @command="handleAddCommand">
                        <i class="el-icon-more comment_more_control" ></i>
                        <!-- 下拉菜单 -->
                        <el-dropdown-menu slot="dropdown">
                          <!-- 举报评论 -->
                          <el-dropdown-item :command="additem.id">🚨</el-dropdown-item>
                        </el-dropdown-menu>
                      </el-dropdown>
                    </div>
                    <!-- 追加评论内容区 -->
                    <div class="comment_answer">
                      <!-- 追加评论 -->
                      <span class="comment_content">{{ additem.comment }}</span>
                      <!-- 追加评论信息 -->
                      <div class="comment_info">
                        <!-- 追加评论发布时间 -->
                        <div class="comment_info_item comment_time">{{additem.time.slice(0,10)}}</div>
                        <!-- 追加评论点赞按钮 -->
                        <div class="comment_info_item" @click="giveGoodToAddComment(additem.id)" :class="{'videoInfoActive': addcommentGoodIdList.indexOf(Number(additem.id))!=-1}">
                          <!-- 追加评论点赞按钮 -->
                          <svg-icon iconname="icon-good"></svg-icon>
                          <span class="comment_good_num">{{additem.good}}</span>
                        </div>
                        <!-- 追加评论点踩按钮 -->
                        <svg-icon iconname="icon-good" class="comment_info_item dislike_icon" @click.native="giveBadToAddComment(additem.id)" :class="{'videoInfoActive': addcommentBadIdList.indexOf(Number(additem.id))!=-1}"></svg-icon>
                        <!-- 追加评论回复按钮 -->
                        <div class="comment_info_item comment_answer" @click="addanswer(index)" >回复</div>
                      </div>
                    </div>
                  </div>
                </div>
                <!-- 查看更多评论 -->
                <div class="chack_more_answer" v-if="item.addcomment.length > 2 && item.isCheck == '0'">
                  <!-- 总追加评论数 -->
                  <span>共有{{item.addCommentNum}}条评论，</span>
                  <!-- 查看更多评论按钮 -->
                  <span class="chack_more_answer_button" @click="seeMoreComment(item)">查看更多</span>
                </div>
                <!-- 评论分页导航 -->
                <div class="chack_more_answer_page" v-if="item.isCheck=='1'">
                  <!-- 总页数 -->
                  <span>共{{nowTotalPages}}页</span>
                  <!-- <span class="page_item" v-for="(pagenum,index) in nowTotalPages" @click="nextPage(pagenum)" v-if="index<5">{{ pagenum }}</span>
                  <span class="page_item" v-if="nowTotalPages>5">...</span>
                  <span class="page_item" @click="nextPage(nowTotalPages)">{{ nowTotalPages}}</span> -->
                  <!-- 首页页数 -->
                  <span class="page_item" v-if="pageNav.leftshow" @click="nextPage(item,1)">1</span>
                  <!-- 页数超6个时显示的缩略 -->
                  <span class="page_item" v-if="pageNav.leftshow">...</span>
                  <!-- 导航页 -->
                  <span class="page_item" v-for="(pagenum,index) in item.nav" @click="nextPage(item,pagenum)">{{ pagenum }}</span>
                  <!-- 页数超6个时显示的缩略 -->
                  <span class="page_item" v-if="pageNav.rightshow">...</span>
                  <!-- 最后一页页数 -->
                  <span class="page_item" v-if="pageNav.rightshow" @click="nextPage(item,nowTotalPages)">{{ nowTotalPages }}</span>
                  <!-- 下一页按钮 -->
                  <span class="chack_next_answer_page_button page_item" @click="nextPage(item,parseInt(nowpage)+1)">下一页</span>
                </div>
              </div>
            </div>
            <!-- 追加评论输入栏 -->
            <div class="addcomment_input">
              <!-- <input class="comment_input_box" type="text" > -->
              <!-- 输入框 -->
              <el-input
                type="textarea"
                :autosize="{ minRows: 2, maxRows: 5}"
                placeholder="请输入内容"
                @keydown.enter.native="sendAddComment2(item)"
                v-model="addComment.comment">
              </el-input>
              <!-- <textarea class="comment_input_box" name="comment" cols="30" rows="10" @keydown.enter="sendAddComment2(item)" v-model="addComment.comment"></textarea> -->
              <!-- 发布按钮 -->
              <div class="comment_button" @click="sendAddComment2(item)">发布</div>
            </div>
          </div>
        </div>
      </div>
    </div>
  </div>
</template>

<script>
import SmallUserCard from './SmallUserCard.vue'
import { getVideo, getVideoByVid } from '@/api/video';
import { getVipInfoById } from '@/api/vip';
import { computeUserLevel } from '@/api/user';
import { getCommentBadInfo, getCommentGoodInfo, getMoreComment, getVidoeAllComment, getVidoeComment, saveBadToAddComment, saveBadToComment, saveGoodToAddComment, saveGoodToComment, saveNewAddComment, saveNewComment, updateCommentAnswer } from '@/api/comment';
import { cancelFollow, followUser2, userIsFollowTarget } from '@/api/follow';

  export default{
    name: 'VideoComment',
    components:{
      SmallUserCard
    },
    props:{
      // 要展示的视频id Long类型即String类型
      initVid: {
        type: String,
        default: ""
      }
    },
    watch:{
      $route(to, from) {
        this.initVid != this.vid ? this.vid = this.initVid :''
        console.log("vid"+this.vid);
        if (this.vid != '') {
          // 获取视频信息
          this.getVideoByid()
        }
      }
    },
    data(){
      return{
        // 是否开始渲染的标志，使用v-if判断数据对象也行
        state: false,

        // 当前页面的视频信息
        video:{},
        // 当前页面的视频vid
        vid:'',

        // 登录用户和用户简介卡片用户是否关注关系
        isFollowSmallCard: false,

        /**
       * 评论区逻辑需要的数据
       * ----------------------------------------------------------------------
       */
        // 当前视频评论列表
        commentList:[],
        // 追加评论列表
        moreComment: [],
        // 点击查看评论的父评论id
        cid:-1,
        // 当前显示更多评论页数
        nowpage: 1,
        // 当前详情评论的总共页数
        nowTotalPages: 0,
        // 发送评论数据
        comment:{
          // "uid": "1000000001",
          "vid": "",
          "time": "",
          "comment": ""
        },
        // 追加评论数据
        addComment:{
          "cid": "",
          // "uid": "1000000001",
          "time": "",
          "comment": ""
        },
        // 评论排序
        commentOrder:'good',
        // 分页导航数组
        pageNav:{
          nav:[],
          rightshow:true,
          leftshow:false,
        },
        // 当前激活的追加评论框
        activeAddinput:null,
        // 当前评论显示排序导航
        activeCommentOrderNav:'',
        // 点赞评论id数组
        commentGoodIdList:[],
        addcommentGoodIdList:[],
        // 点踩评论id数组
        commentBadIdList:[],
        addcommentBadIdList:[],
        /**
         * 评论区逻辑需要的数据
         * ----------------------------------------------------------------------
         */
      }
    },
    methods:{
      // 这里获取要展示的信息，也可以不写，让父组件直接将子组件要用的数据传递给此组件，减少请求后端次数，看你选择什么
      // 根据父组件提供的视频id获取视频信息
      async getVideoByid(){
        let data = await getVideoByVid(this.vid)
        this.video = data
        this.state = true
        // 获取视频id获取评论信息
        this.getVideoComment()
      },

      // 根据视频id获取评论信息
      async getVideoComment(){
        let data = await getVidoeAllComment(this.vid, this.commentOrder)
        this.commentList = data
        // 获取是否有点赞评论记录
        this.getCommentGoodInfo()
        // 获取是否有点踩评论记录
        this.getCommentBadInfo()
        // 评论区末尾加提示词
        this.commentAfterAddElement()
      },

      // 检举父评论
      handleCommand(command){
        if (this.$store.state.loginUser == ''){
          // 提示没登录
          // this.$emit('showLoginForm', true)
          // this.$bus.$emit('showLogin', true)
          this.$bus.$emit('showLoginFormss', true)
          return
        }
        else if (command != '') {
          // 调用父组件的举报方法
          this.$parent.handleCommand(command)
        }
      },

      // 检举子评论
      handleAddCommand(command){
        if (this.$store.state.loginUser == ''){
          // 提示没登录
          // this.$emit('showLoginForm', true)
          // this.$bus.$emit('showLogin', true)
          this.$bus.$emit('showLoginFormss', true)
          return
        }
        else if (command != '') {
          // 调用父组件的举报方法
          this.$parent.handleAddCommand(command)
        }
      },

      // 悬浮右边用户头像时需要会员数据 获取vip数据
      async getVipInfo(uid){
        let data = await getVipInfoById(uid)
        this.vipInfo = data
        // 判断是否关注关系
        this.userIsFollow2(uid)
      },

      // 用户等级计算
      nowLevel(experience){
        return computeUserLevel(experience);
      },

      // 前往聊天室
      gotoChatRoom(uid){
        // 没登录提示登录
        if (this.$store.state.loginUser == ''){
          // this.dialogLoginVisible = true
          // this.$bus.$emit('showLogin', true)
          // this.$emit('showLoginForm', true)
          this.$bus.$emit('showLoginFormss', true)
          return
        }

        if (uid == this.$store.state.loginUser.uid) {
          // 提示不能给自己发送消息
          this.$message({
            message: '警告哦♪，不能给自己发送消息',
            type: 'warning'
          });
          return 
        }
        this.$router.push({
          path: '/message/chatRoom',
          query:{
            recipientId:uid
          }
        })
      },

      

      /**
       * ----------------------------------------------------------------------------------------------
       * 评论区板块
       * 是否需要登录：是
       */
    
      // 点击回复追加评论显示输入框
      addanswer(index){
        if (this.$store.state.loginUser == ''){
          // 提示没登录
          // this.$bus.$emit('showLogin', true)
          // this.$emit('showLoginForm', true)
          this.$bus.$emit('showLoginFormss', true)
          return
        }
        if(this.activeAddinput != null){
          this.activeAddinput.style.display = 'none'
          this.activeAddinput = null
        }
        this.activeAddinput = document.getElementsByClassName('addcomment_input')[index];
        // console.log(this.activeAddinput);
        // console.log(event.target)
        // console.log(index);
        this.activeAddinput.style.display = 'flex'
      },

      // 发送评论保存给后端 (token校验)
      async sendComment2(){
        if (this.$store.state.loginUser == ''){
          // 提示没登录
          // this.$bus.$emit('showLogin', true)
          // this.$emit('showLoginForm', true)
          this.$bus.$emit('showLoginFormss', true)
          return
        }

        // 内容为空退出
        if(this.comment.comment.trim() == ""){
          this.commentNullError()
          return
        }
        this.comment.vid = this.vid
        this.comment.time = Date.now();
        console.log(this.comment);
        let data = await saveNewComment(this.comment);
        if (data == "noLogin") {
          // 提示登录后操作
          // this.dialogLoginVisible = true
          // this.$bus.$emit('showLogin', true)
          // this.$emit('showLoginForm', true)
          this.$bus.$emit('showLoginFormss', true)
          return
        }
        this.getVideoComment();
        this.comment.comment = ""
      },

      // 更新评论的回复状态
      async updateCommentAnswer(cid, answer){
        let data = await updateCommentAnswer(cid, answer)
        // 刷新评论列表
        this.getVideoComment()
      },

      // 发送追加评论保存给后端 (token校验)
      async sendAddComment2(item){
        if(this.addComment.comment.trim() == ""){
          this.commentNullError()
          return
        }
        // console.log(item);
        this.addComment.cid = item.cid
        this.addComment.time = Date.now();
        // console.log(this.addComment);
        let data = await saveNewAddComment(this.addComment)
        if (data == "noLogin") {
          // 提示登录后操作
          // this.dialogLoginVisible = true
          // this.$bus.$emit('showLogin', true)
          // this.$emit('showLoginForm', true)
          this.$bus.$emit('showLoginFormss', true)
          return
        }
        // 父评论设为有追加评论状态
        // 更新评论的回复状态为1
        this.updateCommentAnswer(item.cid,'1')
        this.addComment.comment = ""
      },

      // 点击查看更多评论
      async seeMoreComment(item){
        // 查看更多评论的父评论id
        this.cid = item.cid
        // 父评论的查看点击过
        item.isCheck = '1'
        // 当前查看的是第一页
        this.nowpage = 1
        // 根据父评论id向后端请求追加评论信息
        let data = await getMoreComment(this.cid, 1);
        this.commentList.forEach((item1)=>{
          if(item1.cid == this.cid){
            item1.addcomment = data.list
            this.nowTotalPages = data.pages
            // 调用分页导航初始化函数
            this.initPageNav(item)
          }
        })
        setTimeout(() => {
          let documentList =  document.getElementsByClassName('page_item')
          if(documentList[0].innerHTML == "1"){
            documentList[0].classList.add('nowpage')
          }
        }, 100);
        // console.log(item);
      },

      // 点击查看更多追加评论的底部分页导航显示逻辑
      initPageNav(item){
        if(this.nowTotalPages == 1){
          for (let i = 1; i <= this.nowTotalPages; i++) {
            item.nav.push(i);
            this.pageNav.rightshow = false
            this.pageNav.leftshow = false
          }
        }
        // 总页数小于等于5 不显示左右...和中右数组
        else if(this.nowTotalPages<=6){
          for (let i = 1; i <= this.nowTotalPages; i++) {
            item.nav.push(i);
            this.pageNav.rightshow = false
          }
        }
        // 总页数大于6才显示...
        else if(this.nowTotalPages>6){
          for (let i = 1; i <= 5; i++) {
            item.nav.push(i);
          }
          this.pageNav.rightshow = true
        }
      },

      // 点击下一页 或者点击页码数字 分页查询
      async nextPage(item,nextPage){
        this.nowpage = nextPage
        //非最后一页，并且未超出范围跳转
        if (nextPage <= this.nowTotalPages){
          // 根据父评论id向后端请求追加评论信息
          let data = await getMoreComment(this.cid, nextPage);
          this.commentList.forEach((item)=>{
            if(item.cid == this.cid){
              item.addcomment=res.data.data.list
            }
          })
          item.nav = data.nav
          // 页面导航调整
          if(this.nowpage>=this.nowTotalPages-2){
            this.pageNav.rightshow = false
          }
          else{
            this.pageNav.rightshow = true
          }
          if(this.nowpage-2>1){
            this.pageNav.leftshow = true
          }
          else{
            this.pageNav.leftshow = false
          }
          // console.log(document.getElementsByClassName('page_item'));
          // 导航活动样式
          setTimeout(() => {
            let documentList =  document.getElementsByClassName('page_item')
            // console.log(documentList);
              for(let i = 0; i < documentList.length; i++){
                if(documentList[i].innerHTML==this.nowpage){
                  document.getElementsByClassName('nowpage')[0].classList.remove('nowpage')
                  documentList[i].classList.add('nowpage');
                  // 改完跳出，防止bug
                  break
                }
              }
          }, 100)
        }
      },

      // 评论区评论排序
      changeCommentOrder(order){
        if(this.activeCommentOrderNav == ''){
          this.activeCommentOrderNav = this.$refs.nowActiveCommentOrderNav
        }
        this.activeCommentOrderNav.classList.remove('activeCommentNav')
        event.target.classList.add('activeCommentNav')
        this.activeCommentOrderNav = event.target
        if (order == '热门'){
          this.commentOrder = 'good'
        }
        else if(order == '最新'){
          this.commentOrder = 'time'
        }
        // 重新获取该视频评论
        this.getVideoComment()
      },

      // 点赞评论
      async giveGoodToComment(cid){
        let data = await saveGoodToComment(this.vid, cid);
        if (data == "noLogin"){
          // this.$emit('showLoginForm', true)
          // this.$bus.$emit('showLogin', true)
          this.$bus.$emit('showLoginFormss', true)
        }
        // 刷新评论信息
        this.getVideoComment()
        // 获取已点赞信息
        this.getCommentGoodInfo()
        console.log("bbbbb");
        console.log(this.commentGoodIdList);
        
         
      },

      // 获取点赞评论记录
      async getCommentGoodInfo(){
        this.commentGoodIdList = []
        this.addcommentGoodIdList = []
        let data = await getCommentGoodInfo(this.vid);
        if (data == "noLogin") {
          //不存在记录，清空id选择
          this.commentGoodIdList = []
          this.addcommentGoodIdList = []
          return
        }
        else{
          let temp = data
          console.log(temp);
          
          if (temp) {
            temp.forEach((item)=>{
              if (item.type =='0') {
                this.commentGoodIdList.push(item.id);
              }
              else if (item.type == '1'){
                this.addcommentGoodIdList.push(item.id)
              }
            })
          }
        }
      },

      // 点踩评论
      async giveBadToComment(cid){
        let data = await saveBadToComment(this.vid, cid);
        if (data == "noLogin") {
          // this.$emit('showLoginForm', true)
          // this.$bus.$emit('showLogin', true)
          this.$bus.$emit('showLoginFormss', true)
          return
        }
        // 刷新评论信息
        this.getVideoComment()
        // 获取已点踩信息
        this.getCommentBadInfo()
      },

      // 获取点踩评论记录
      async getCommentBadInfo(){
        this.commentBadIdList = []
        this.addcommentBadIdList = []
        let data = await getCommentBadInfo(this.vid);
        if (data == "noLogin") {
          //不存在记录，清空id选择
          this.commentBadIdList = []
          this.addcommentBadIdList = []
          return
        }else{
          let temp = data
          console.log(temp);
          
          if (data) {
            temp.forEach((item)=>{
              if (item.type =='0') {
                this.commentBadIdList.push(item.id);
              }
              else if (item.type == '1'){
                this.addcommentBadIdList.push(item.id)
              }
            })
          }
        }
      },

      // 点赞追加评论
      async giveGoodToAddComment(id){
        let data = await saveGoodToAddComment(this.vid, id);
        if (data == "noLogin") {
          // this.$emit('showLoginForm', true)
          // this.$bus.$emit('showLogin', true)
          this.$bus.$emit('showLoginFormss', true)
          return
        }
        // 刷新评论信息
        this.getVideoComment()
        // 获取已点赞信息
        this.getCommentGoodInfo()
      },

      // 点踩追加评论
      async giveBadToAddComment(id){
        let data = await saveBadToAddComment(this.vid, id);
        if (data == "noLogin"){
          // this.$emit('showLoginForm', true)
          // this.$bus.$emit('showLogin', true)
          this.$bus.$emit('showLoginFormss', true)
          return;
        }
        // 刷新评论信息
        this.getVideoComment()
        // 获取已点踩信息
        this.getCommentBadInfo()
      },

      // 在评论区末尾添加评论显示完提示
      commentAfterAddElement(){
        // console.log(document.getElementsByClassName('noMoreComment').length);
        setTimeout(() => {
          if (document.getElementsByClassName('noMoreComment').length < 1){
            let item =  document.createElement('div')
            item.className = 'noMoreComment'
            item.style.textAlign = 'center'
            item.style.paddingBottom = "50px"
            item.innerText = '没有评论了ฅ(๑˙o˙๑)ฅ，等一等，好吗♪'
            // this.$refs.commentListDom.after(item)
            if (this.$refs.commentListDom) {
              this.$refs.commentListDom.after(item)
            }
          }
        }, 100);
      },

      // 评论提示 评论不能为空
      commentNullError(){
        this.$message.error('评论不能为空');
      },

      /**
       * 评论板块结束
       * ----------------------------------------------------------------------------------------------
       */


      /**
       * ----------------------------------------------------------------------------------------------
       * 关注板块             这里调用父组件方法，需要返回值判断是否已经关注，暂时没解决，组件自己实现
       * 是否需要登录：是
       */

      // 根据用户id判断是否关注状态 (token)
      async userIsFollow2(uid){
        let data = await userIsFollowTarget(uid);
        if (data == 1) {
          this.isFollowSmallCard = true
        }
        else{
          // 不是关注关系
          this.isFollowSmallCard = false
        }
      },

      // 保存follow关系 (token)
      async followUser2(followedUid){
        let data = await followUser2(followedUid)
        if (data == "noLogin") {
          // 提示登录后操作 事件总线方式让调用组件的父组件显示未登录提示让用户登录, 登录逻辑在父组件已经实现，这里此组件不实现此逻辑，你也可以写相关逻辑，增加组件适用性
          // this.dialogLoginVisible = true
          // this.$emit('showLoginForm', true)
          // this.$bus.$emit('showLogin', true)
          this.$bus.$emit('showLoginFormss', true)
        }
        this.isFollowSmallCard = true
        // 关注成功提示
        this.followTrue()
        // 假数据更新
        this.video.user.fans += 1;
      },

      // 点击取消关注 (token)
      async cancelFollow2(followedUid){
        let data = await cancelFollow(followedUid);
        // console.log("删除成功");
        this.isFollowSmallCard = false
        this.cancelFollowTrue()
        // 假数据更新
        this.video.user.fans -= 1
      },

      // 取消关注成功
      cancelFollowTrue() {
        this.$message({
          message: '取消关注成功♪',
          type: 'success'
        });
      },

      // 关注成功提示
      followTrue() {
        this.$message({
          message: '关注成功♪',
          type: 'success'
        });
      },

      // 展示已关注按钮
      show_unfollow_creator(){
        this.$refs.unfallow_creator_button.style.display = "block";
      },
      
      // 隐藏已关注按钮
      hide_unfallow_creator(){
        this.$refs.unfallow_creator_button.style.display = "none";
      },
      /**
       * 关注板块结束
       * ----------------------------------------------------------------------------------------------
       */

      // 获取图片url
      getImgURL(address){
        return getVideo(address);
      },

    },
    created(){
      this.vid = this.initVid
      console.log("vid"+this.vid);
      if (this.vid != '') {
        // 获取视频信息
        this.getVideoByid()
      }
    },
    mounted(){
    },
    beforeDestroy(){
    }
  }
</script>

