import HeaderNav from './HeaderNav.vue';
import MyFooter from './MyFooter.vue';
import { checkLogin, computeUserLevel, getUserCover, getUserInfo, getUserInfoByUid, login, updateUserFanOrFollow } from '@/api/user';
import { getSpaceSetInfoByUid } from '@/api/space';
import { getVipInfoById } from '@/api/vip';
import { cancelFollow, followUser, userIsFollowTarget } from '@/api/follow';
import { getLocal, saveLocal } from '@/utils/StorageUtils';
import { deleteFan, saveFan } from '@/api/fan';

  export default{
    name: 'UserSpace',
    data(){
      return{
        imgUrl: "img/点击生成.png",

        // 个人空间的内容导航栏元素名字数组
        space_content_name: ['首页','动态','投稿','合集','收藏','设置'],
        // 个人空间的内容导航栏元素图标名字数组
        space_contnet_icon_name: ['icon-shouye','icon-dongtai2','icon-shipin1','icon-heji','icon-shoucang1','icon-shezhi'],
        // 导航路由
        space_content_nav_router_name:['/space/home','/space/update','/space/contribution','/space/compilation/home','/space/collection','/space/setting'],


        // 空间所属用户的vip信息, 会员等级
        vipInfo:{},
        // 空间所属用户信息
        userInfo:{},

        //访问空间请求从谁发起     这里可以读取loginUser，没有登录或者登录过期会自动消除存储记录
        fromUser: this.$store.state.loginUser.uid || 'from',
        //访问的目标空间所属用户id  刷新页面后所有数据丢失，只能从sessionstroage读取目标用户
        // toUser: this.$store.state.loginUser.uid  || 'to',
        toUser: JSON.parse(sessionStorage.getItem('toUser')) || 'to',

        // 用户是否设置了置顶推荐视频, 默认为未设置
        isSetRecommend:false,

        // 访问者和空间所属者是否是关注状态
        isFollow:false,

        // 登录界面是否展示
        // dialogVisible: false,
        // 用户登录提交信息
        // user:{
        //   "account":"",
        //   "password":"",
        //   "LineCode":"",
        // },

        // 是否显示切换壁纸弹窗
        drawer: false,
      }
    },
    computed:{
      // 空间展示模式
      showModel() {
        return this.$store.state.spaceViewModel
      },
      // 空间是否处于预览状态(在视角切换预览状态)
      isPreview() {
        return this.$store.state.isPreview
      },
      // 用户个性标签内容
      synopsis(){
        return this.userInfo.synopsis || ''
      },
      // 当前登录的用户信息
      loginUser(){
        return this.$store.state.loginUser || ''
      },
      // 当前是否处于登录状态
      islogin(){
        return this.$store.state.login
      },
      // 观看的空间所属用户id
      spaceUid(){
        return this.$store.state.spaceUserId
      },
      // 用户空间设置的状态信息
      spaceInfo(){
        // console.log(this.$store.state.spaceInfo);
        return this.$store.state.spaceInfo
      },
      // 空间导航滑动条所处位置
      click_scroll_bar_position:{
        get(){
          return this.$store.state.position || ''
        },
        set(){}
      },
      // 空间用户等级计算
      nowLevel(){
        return computeUserLevel(this.userInfo.experience)
      }
    },
    components: {
      HeaderNav,
      MyFooter,
      RouterView
    },
    watch:{
      // 监视barposition变化时调用滑动条位置设置
      click_scroll_bar_position(){
        this.initBar()
      },
      // 路由更新
      $route(to, from) {
        console.log(to);
        console.log(from);
        console.log(typeof this.$route.params.toUser == typeof '');
        // 如果route有params就赋值，默认是读取loginUser的uid或者为空
        if(typeof this.$route.params.fromUser == typeof ''){
          this.fromUser=this.$route.params.fromUser
        }
        // 访问的对象   如果有传递才赋值，若用户刷新会丢失，使用默认值spaceUserId或者空
        if(typeof this.$route.params.toUser == typeof ''){
          this.toUser = this.$route.params.toUser
          console.log("sadasd");
        }

        // 判断访问的模式 处于非预览模式才重新判断是否是自己访问，因为在预览模式下不需要判断后设置访问模式
        if(!this.$store.state.isPreview){
          this.selectModel()
        }
        else{
          // 判断展示模式, 防止此方法执行两次
          this.show()
        }
        // 根据目标uid获取目标空间的设置信息
        this.getSetInfoByspaceUid(this.toUser)
        // 初始化滑动条
        this.initBar()
        // 判断空间主人和用户是否为关注状态
        this.userIsFollow2()
      }
    },
    methods: {
      /**
       * --------------------------------------------------------------------
       * 本组件初始化时调用方法
       */
      // 决定访问的模式并上传
      selectModel(){
        // 提交空间所属用户id
        this.$store.dispatch('spaceUserId', this.toUser)

        if(this.fromUser==this.toUser && this.fromUser==this.loginUser.uid){
          console.log("自己");
          this.$store.dispatch('spaceViewModel','me')
        }
        else if(this.fromUser!=this.toUser){
          console.log("游客");
          this.$store.dispatch('spaceViewModel','other')
        }
        // 判断获取空间主人的信息
        this.show()
        // 根据目标uid获取目标空间的设置信息
        this.getSetInfoByspaceUid(this.toUser)
      },
      // 展示逻辑
      show(){

        console.log("当前展示id为" + this.toUser);

        // 如果是登录用户自己的空间
        if(this.showModel == 'me'){
          // 空间用户信息是登录用户的信息
          // this.userInfo = this.$store.state.loginUser
          // console.log(this.userInfo);
          // this.getUserInfoByUid(this.$store.state.loginUser.uid)
          this.getUserInfoByUid(this.toUser)
        }
        // 如果为访问模式，根据空间所属用户的id获取用户信息
        if(this.showModel == 'other'){
          //发送请求，根据uid获取目标空间主人的信息
          // this.getUserInfoByUid(this.$store.state.spaceUserId)
          this.getUserInfoByUid(this.toUser)
        }
      },
      //发送请求，根据uid获取目标空间主人的用户信息
      async getUserInfoByUid(uid){
        let data = await getUserInfoByUid(uid);
        if (data) {
          // 设置空间用户信息为获取到的信息
          this.userInfo = data
          //获取vip信息
          this.getVipInfo()
        }
      },
      // 根据目标uid获取目标空间的设置信息并上交保存
      async getSetInfoByspaceUid(uid){
        let data = await getSpaceSetInfoByUid(uid);
        if (data) {
          // 提交空间设置信息
          this.$store.dispatch('spaceInfo', data)
          console.log(this.spaceInfo);
          
        }
      },
      // 获取vip数据
      async getVipInfo(){
        let data = await getVipInfoById(this.userInfo.vipId)
        if (data) {
          this.vipInfo = data
        }
      },
      //（废弃） 根据登录的用户id和空间id判断是否关注状态 （废弃）
      // userIsFollow(){
      //   if(this.loginUser.uid){
      //     axios.get('/follow/isFollow/'+this.loginUser.uid+'/'+this.spaceUid)
      //       .then((res)=>{
      //         if (res.data.data == 1) {
      //           // 设置当前访问者和所属者的关系为关注关系
      //           this.isFollow = true
      //         }
      //       })
      //   }
      // },

      // 根据空间所属者uid和登录用户id判断是否关注状态 (token)
      async userIsFollow2(){
        let data = await userIsFollowTarget(this.spaceUid);
        console.log(data);
        
        if (data == 1) {
          this.isFollow = true
          console.log(this.isFollow);
          
        }
      },
      /**
       * 本组件初始化时调用方法
       * --------------------------------------------------------------------
       */



      /*
       * -------------------------------------------------------------------
       * 登录功能相关逻辑
      */
      // showLoginForm(val){
      //   this.dialogVisible = val;
      // },

      // refashCode(type){
      //   if (type == "login") {
      //     // this.$refs.refashLoginCode.style.display = 'inline'
      //     this.$refs.loginCode.src = "http://localhost:9000/user/createCode?time=" + new Date().getTime();
      //     document.getElementsByClassName('code1')[0].style.marginTop = '0px'
      //   }
      //   else{
      //     // this.$refs.refashSignUpCode.style.display = 'inline'
      //     this.$refs.signUpCode.src = "http://localhost:9000/user/createCode?time=" + new Date().getTime();
      //   }
      // },

      // 发送登录信息给后端
      // async login(user){
      //   // 发送登录请求，成功获取到data的token，失败为null
      //   let data = await login(user, this.user.LineCode);
      //   // console.log(data);
      //   if (data){
      //     // 将token存储到本地
      //     // localStorage.setItem("token",response.data.data.token)
      //     saveLocal("token", data.token);
      //     // 获取登录用户信息
      //     this.getUserInfo()
      //     // 获取助手设置信息
      //     this.getHelperSet()
      //   }
      // },

      // 获取登录用户信息(token校验)
      // async getUserInfo(){
      //   let data = await getUserInfo();
      //   if (data) {
      //     // 上传登录用户信息
      //     this.$store.dispatch('loginUser', data.loginUser)
      //       // 刷新页面
      //     location.reload();
      //   }
      // },

      // 前往登录界面进行注册账号
      gotoSignUp(){
        this.$router.push({
          path:'/login',
          query:{
            'signUp':true
          }
        })
      },
      
      // 登录界面提示关闭提示
      handleClose(done) {
        this.$confirm('确认关闭？')
          .then(_ => {
            done();
          })
          .catch(_ => {});
      },
      /*
       * 登录功能相关逻辑
       * -------------------------------------------------------------------
      */



      /**
       * --------------------------------------------------------------------
       * 关注空间所属者的逻辑
       */
      // 点击取消关注
      async cancelFollow(followedUid){
        let data = await cancelFollow(followedUid);
        if (data) {
          // 设置当前访问者和所属者的关系为未关注
          this.isFollow = false
          // 更新update和fan值
          this.updateFanAndFollow('subtract')
          // 逻辑删除fan表数据
          this.updateFan('subtract')
          // 取消成功提示
          this.cancelFollowTrue()
        }
      },
      // 取消关注成功提示弹窗
      cancelFollowTrue() {
        this.$message({
          message: '取消关注成功♪',
          type: 'success'
        });
      },
      // 取消关注失败提示弹窗
      cancelFollowError() {
        this.$message({
          message: '失败！请重试',
          type: 'warning'
        });
      },
      // 保存follow关系 关注空间所属用户
      async followUser(){
        // 登录状态的用户id和空间用户id相同时
        if (this.loginUser.uid == this.spaceUid) {
          // 提示不能对自己就行关注操作
          this.FollowMyselfError()
        }
        // 处于登录状态才能关注
        else if(this.loginUser.uid){
          let temp = {
            uid: this.loginUser.uid,
            followedUid:this.spaceUid
          }
          let data = await followUser(temp);
          if (data) {
            // 关注成功，修改关注状态为真
            this.isFollow = true
            // user表关注者fan加1 自己follow加1
            this.updateFanAndFollow('add')
            // fan表数据加一
            this.updateFan('add')
            // 关注成功提示
            this.followTrue()
          }
        }
        else{
          // 提示登录后再操作
          // 显示登录操作栏
          this.dialogVisible = true
        }
      },
      // 不能关注自己提示弹窗
      FollowMyselfError(){
        this.$message({
          message: '不能关注自己喔♪',
          type: 'warning'
        });
      },
      // 关注成功提示弹窗
      followTrue() {
        this.$message({
          message: '关注成功♪',
          type: 'success'
        });
      },
      // 关注失败提示
