          this.$message({
            message: '警告哦♪，不能给自己发送消息',
            type: 'warning'
          });
          return 
        }
        if (!getLocal('token')){
          this.dialogVisible = true;
          this.$message({
            message: '请先登录哦♪',
            type: 'warning'
          });
          return
        }
        // 发送请求，查看是否登录状态
        let data = await checkLogin();
        if (data == 0){
          this.dialogVisible = true;
          this.$message({
            message: '请先登录哦♪',
            type: 'warning'
          });
          return
        }
        else if (data == 1){
