<!-- 
  项目：Elyden.com
  创建时间：2023.10.10
  上次更新时间：2024.10.10
  组件名称：MinHelper
  此文件负责的板块：缩小版助手
    功能：
      1、移动位置
  -->
<template>
  <!-- 缩小版助手 -->
  <div class="mainHelper">
    <div class="smallHelper" ref="helperElemt" @click="remove">
      <img src="../assets/images/minHelper.png" alt="缩小版助手">
      <ol>
        <!-- 缩小图标 -->
        <li>
          <svg class="icon big" aria-hidden="true" @click="chanceShowHelper">
            <use xlink:href="#icon-fangda"></use>
          </svg>
        </li>
        <!-- 返回顶部按钮 -->
        <li>
          <div class="top helper_nav_item" id="returnTopButton" @click="returnTop">
            <span style="font-size: 12px; line-height: 30px;">顶部</span>
          </div>
        </li>
        <!-- 小窗口播放按钮 -->
        <li>
          <div class="nav helper_nav_item window" id="windowButton" @click="changeWindow" :class="{'windowclose': !windowPlay}">
            <span style="font-size: 12px; line-height: 30px;">窗口</span>
          </div>
        </li>
      </ol>    
    </div>
  </div>
</template>

<script>
import { RouterView } from 'vue-router';

// 默认暴露组件
export default {
  // vue开发插件显示的名字
  name: 'MinHelper',
  components: { 
    RouterView 
  },
  data(){
    return{
      // x轴坐标
      x:0,
      // y轴坐标
      y:0,

      windowPlay: true
    }
  },
  methods:{
    // 是否显示展示小窗口按钮（事件总线）
    showWindowButton(data){
      data ? document.getElementById('windowButton').style.display = 'block' : document.getElementById('windowButton').style.display = 'none'
    },

    // 是否显示返回顶部按钮（事件总线）
    showReturnTopButton(data){
      data ? document.getElementById('returnTopButton').style.display = 'block' : document.getElementById('returnTopButton').style.display = 'none'
      // console.log(data);
    },

    // 返回顶部
    returnTop(){
      // 直接设置位置为0
      document.documentElement.scrollTop = 0;
    },

    // 切换窗口播放模式（事件总线）
    changeWindow(){
      // 关闭或者开启小窗口播放
      this.windowPlay = !this.windowPlay
      this.$bus.$emit('changeWindow', this.windowPlay)
    },

    // vuex组件修改大小状态
    chanceShowHelper(){
      // 登录后才能切换
      if (localStorage.getItem('token')) {
        this.$store.dispatch('chanceshow',true)
      }
    },
    // mousemove事件移动坐标
    moveTo(el){
      let x1 = el.pageX - this.x + 'px'
      let y1 = el.pageY - this.y + 'px'
      this.$refs.helperElemt.style.left = x1
      this.$refs.helperElemt.style.top = y1
    },
    // 拖动事件
    remove(){
      let downtime
      let uptime
      //拖动事件
      this.$refs.helperElemt.addEventListener('mousedown',(e)=>{
        //元素原点
        this.x = e.pageX - this.$refs.helperElemt.offsetLeft
        this.y = e.pageY - this.$refs.helperElemt.offsetTop
          
        if(e.button==0){
          //鼠标左键点击了
          downtime = Date.now()
          document.body.addEventListener('mousemove',this.moveTo)
        }
        this.$refs.helperElemt.addEventListener('mouseup',()=>{
          uptime = Date.now()
          if(uptime-downtime<500){
            //点击
            document.body.removeEventListener('mousemove',this.moveTo)
          }
          else{
            //停止
            document.body.removeEventListener('mousemove',this.moveTo)
          }
        })
      })
    }
  },
  mounted(){
    this.$bus.$on('showTopButton', this.showReturnTopButton)
    this.$bus.$on('showWindowButton', this.showWindowButton)
  },
  destroyed(){
    this.$bus.$off('showTopButton', this.showReturnTopButton)
    this.$bus.$off('showWindowButton', this.showWindowButton)
  },
}
</script>

<style scoped>
.min{
  position: relative;
}
/* 助手区域 */
.smallHelper{
  width: 80px;
  height: 80px;
  position: fixed;
  top: calc(100% - 250px);
  left: calc(100% - 110px);
	z-index : 3;
  /* overflow: hidden; */
}
/* 缩小的助手图片 */
img{
  width: 80%;
}
/* 导航图标 */
.icon {
  width: 1.2em;
  height: 1.2em;
  vertical-align: -0.15em;
  fill: currentColor;
  overflow: hidden;
}
/* 放大图标 */
.big{
  /* border: 1px solid rgb(200, 200, 200); */
  box-shadow: 0 0 1px rgb(3, 3, 3);
  border-radius: 5px;
  padding: 5.5px;
  cursor: pointer;
  position: absolute;
  top: 0;
  right: -20px;
}
/* 顶部按钮 */
.top{
  top: 35px;
  box-sizing: content-box;
  cursor: pointer;
  display: none;
}

/* 导航共同样式 */
.helper_nav_item{
  right: -20px;
  width: 30px;
  height: 30px;
  border-radius: 5px;
  position: absolute;
  box-shadow: 0 0 1px rgb(3, 3, 3);
  /* border: 1px solid rgb(60, 60, 60); */
  line-height: 12px;
  text-align: center;
  color: #18191c;
}
/* 小窗口播放按钮 */
.window{
  top: 71px;
  height: 30px;
  line-height: 30px;
  box-shadow: 0 0 1px #00aeec;
  /* border: 1px solid #00aeec; */
  cursor: pointer;
  color: #00aeec;
  transition: top .3s ease-in;
  display: none;
}
/* 窗口播放关闭样式 */
.windowclose{
  color: #18191c;
  /* border: 1px solid rgb(60, 60, 60); */
  box-shadow: 0 0 1px rgb(60, 60, 60);
}
</style>