<!-- 
  项目：Elyden.com
  创建时间：2024.05.06
  上次更新时间：2024.05.09
  组件名称：Admin
  此文件负责的板块：后台整体
    功能：
      1、顶部导航 前往首页/退出登录
      2、侧边导航栏，展示内容切换
      3、未审核数量统计
  -->
<template>
  <div>
    <el-container style="height: 100vh">
      <!-- 顶部导航 -->
      <el-header>
        Elyden后台
        <!-- 下拉菜单 -->
        <el-dropdown split-button @command="handleCommand" type="primary" style="float: right;">
          <span>你好，管理员：{{$store.state.loginUser.uName}}</span>
          <el-dropdown-menu slot="dropdown">
            <el-dropdown-item command="a">前往前台</el-dropdown-item>
            <el-dropdown-item command="b">退出登录</el-dropdown-item>
          </el-dropdown-menu>
        </el-dropdown>
      </el-header>
      
      <!-- 主体内容 -->
      <el-container>
        <!-- 侧边导航 -->
        <el-aside width="200px">
          <!-- 使用router标签，vue的router路由 -->
          <el-menu
            default-active="/admin/home"
            class="el-menu-vertical-demo"
            background-color="#545c64"
            text-color="#fff"
            router
            active-text-color="#ffd04b">
            <!-- 首页导航 -->
            <el-menu-item index="/admin/home">
              <i class="el-icon-location"></i>
              <span slot="title">首页</span>
            </el-menu-item>
            <!-- 用户管理 -->
            <el-menu-item index="/admin/user">
              <i class="el-icon-menu"></i>
              <span slot="title">用户管理</span>
            </el-menu-item>
            <!-- 审核 -->
            <el-menu-item index="/admin/examine">
              <i class="el-icon-document"></i>
              <span slot="title">
                审核
                <!-- 红点提醒 -->
                <el-badge :value="total" v-show="!total<1" :max="99" style="position: absolute; right: 30px;"></el-badge>
              </span>
            </el-menu-item>
            <!-- 设置 -->
            <el-menu-item index="/admin/set">
              <i class="el-icon-setting"></i>
              <span slot="title">设置</span>
            </el-menu-item>
          </el-menu>
        </el-aside>

        <!-- 主题内容 -->
        <el-main>
          <RouterView  name="Admin"></RouterView>
        </el-main>
      </el-container>
    </el-container>
  </div>
</template>

<script>
import { getNoExamineNum,  } from '@/api/admin';

  export default{
    name:'Admin',
    data(){
      return{
        // 未审核的总数
        total:0,
      }
    },
    computed:{
      
    },
    methods:{
      // 获取未审核的数量
      async getNoExamineNum(){
        let data = await getNoExamineNum();
        if (data){
          this.total = data.total
        } else {
          this.gotoError('400','获取审核数量出错')
        }
      },

      // 顶部导航下拉菜单点击事件
      handleCommand(command) {
        if (command == 'a') {
          // 前往首页
          this.gotoMain()
        }
        else if (command == 'b') {
          // 退出登录
          this.quitLogin()
        }
      },

      gotoError(errorCode, errorMessage){
        this.$router.push({
          path: '/Error4XX',
          query:{
            code: errorCode,
            message: errorMessage
          }
        })
      },

      //  退出登录 
      quitLogin(){
        // 登录提示关闭提示
        this.$confirm('确认退出登录？')
        .then(_ => {
          // 清除token
          localStorage.setItem("token","")
          // 清除登录用户信息
          sessionStorage.removeItem('loginUser')
          // 登录状态关闭
          this.$store.dispatch('loginState',false)
          sessionStorage.removeItem('login')
          // 前往首页
          this.gotoMain()
          done();
        })
        .catch(_ => {});
      },

      //前往首页 
      gotoMain(){
        this.$router.push({
          path: '/',
        })
      },
    },
    created(){
      // 获取未审核的数量
      this.getNoExamineNum()
    }
  }
</script>

<style scoped>
  .el-header{
    background-color: #78b2ff;
    color: #ffffff;
    text-align: left;
    line-height: 60px;
    font-size: 30px;
  }
  
  .el-aside {
    background-color: #D3DCE6;
    color: #333;
    text-align: center;
    line-height: 200px;
  }
  
  .el-main {
    background-color: #E9EEF3;
    color: #333;
    text-align: center;
  }
  
  body > .el-container {
    margin-bottom: 40px;
  }
  
  .el-container:nth-child(5) .el-aside,
  .el-container:nth-child(6) .el-aside {
    line-height: 260px;
  }
  
  .el-container:nth-child(7) .el-aside {
    line-height: 320px;
  }

  .el-menu{
    height: 100%;
  }
</style>