<!-- 
  项目：Elyden.com
  创建时间：2024.05.27
  上次更新时间：2024.05.27
  组件名称：SpaceFanAndFollow
  此文件负责的板块：用户空间设置板块
    功能：
      1、展示粉丝和关注表
  -->


<template>
  <div class="space_fan_follow" style="display: flex;">
    <!-- 左边导航区 -->
    <div class="left" style="width: 20%;">
      <!-- 关注列表导航 -->
      <ol class="nav_list_1">
        <!-- 导航标题 -->
        <li>
          <span v-if="showModel == 'me'">我</span>
          <span v-if="showModel == 'other'">Ta</span>
          <span>的关注</span>
          <span class="new_class_button" v-if="showModel == 'me'">+</span>
        </li>
        <!-- 全部关注 -->
        <li :class="{'active_nav': nowModel=='follow'&&type == '1'}" @click="changeContnet('follow', '1')">
          <span class="all_follow_icon nav_icon" style="background-image: url(/img/icons.png);" :style="{backgroundPosition: (nowModel=='follow'&&type == '1' ? '-86px -856px' : '-150px -856px')}"></span>
          全部关注
          <span style="float: right;line-height: 22px; font-size: 14px">{{ followtotal[1] }}</span>
        </li>
        <!-- 特别关注 -->
        <li v-if="showModel == 'me'" :class="{'active_nav': type == '2'}" @click="changeContnet('follow', '2')">
          <span class="special_icon nav_icon" style="background-image: url(/img/icons.png);" :style="{backgroundPosition: (type == '2' ? '-86px -791px' : '-150px -791px')}"></span>
          特别关注
          <span style="float: right;line-height: 22px; font-size: 14px">{{ followtotal[2] }}</span>
        </li>
      </ol>
      <!-- 粉丝列表导航 -->
      <ol class="nav_list_2">
        <li><span>我的</span><span>Ta</span><span>粉丝</span></li>
        <li :class="{'active_nav': nowModel=='fan'&&type == '1'}" @click="changeContnet('fan', '1')">
          <span class="fan_icon nav_icon" style="background-image: url(/img/icons.png);" :style="{backgroundPosition: ( nowModel=='fan'&&type == '1' ? '-86px -984px' : '-21px -984px')}"></span>
          我的粉丝
          <span style="float: right;line-height: 22px; font-size: 14px">{{ fantotal[1] }}</span>
        </li>
      </ol>
    </div>
    <!-- 右边内容区 -->
    <div class="right" style="width: 80%; border-left: 2px rgb(230, 230, 230) solid;">
      <div class="head" style="display: flex; justify-content: space-between;">
        <div class="nav_title"><h3>全部关注</h3></div>
        <div class="nav_right">
          <span class="active" style="margin-right: 10px;">最常访问</span>
          <span>最近关注</span>
        </div>
      </div>
      <div class="main">
        <ol class="user_list" v-for="(item, index) in contentList" :key="item.id">
          <li style="padding: 20px 0; border-top: 1px solid rgb(229, 229, 229);">
            <div class="user_list_item" style="display: flex; justify-content: space-between;">
              <!-- 内容 -->
              <div class="user_list_item_left" style="display: flex;">
                <!-- 用户头像和简介卡片 -->
                <SmallUserCard :user="item.userInfo"></SmallUserCard>
                <div class="user_name" style="margin-left: 40px; color: rgb(251, 114, 153);">
                  <div>{{ item.userInfo.uName }}</div>
                  <div style="color: #6d757a; margin-top: 10px; font-size: 12px;">2024年度优秀创作者</div>
                </div>
              </div>
              <!-- 按钮 -->
              <div class="user_list_item_right" style="line-height: 53px;">
                <button class="follow_button control_button" v-if="!isFollow">关注</button>
                <button class="followed_button control_button" v-if="isFollow">已关注</button>
                <button class="message_button control_button">发消息</button>
              </div>
            </div>
          </li>
        </ol>
        <!-- 分页导航 -->
        <div class="pageNav" style="text-align: center;">
          <el-pagination
            @size-change="handleSizeChange"
            @current-change="handleCurrentChange"
            :hide-on-single-page="true"
            :current-page="page"
            :page-size="20"
            layout="prev, pager, next, jumper"
            :total="nowModel=='follow' ? followtotal[type] : fantotal[type]">
          </el-pagination>
        </div>
        <!-- 无数据提示gif动画 -->
        <div style="margin: 0 auto; text-align: center;" v-if="!contentList">
          <img src="/img/nollData.gif" alt="暂无数据" style="width: 100px;"><br>
          <span>Up关闭了显示权限</span>
        </div>
      </div>
      
    </div>
  </div>
</template>

<script>
import { countFollows, getFollowInfoInSpace } from '@/api/follow';
import SmallUserCard from './SmallUserCard.vue';
import { countFans, getFanInfoInSpace } from '@/api/fan';

  export default{
    name: 'SpaceFanAndFollow',
    components: {
      // 用户简介卡片
      SmallUserCard

    },
    data(){
      return{
        // 当前展示类型
        nowModel: 'follow',
        // 展示类型
        type: '1',
        // 用户列表
        contentList: '',
        // 当前活动导航
        activeNav: '',
        // 当前展示的页面
        page: 0,
        // 总数
        followtotal:{
          '1': 0,
          '2': 0,
        },
        fantotal:{
          '1': 0,
        },
        // 当前内容最大页数
        maxPages: 0,

        isFollow: true,
      }
    },
    computed:{
      // 空间展示模式
      showModel() {
        return this.$store.state.spaceViewModel
      },
      // 空间隐藏和显示权限信息
      spaceInfo() {
        return this.$store.state.spaceInfo
      },
      // 空间用户id
      spaceUserId() {
        return this.$store.state.spaceUserId
      }
    },
    watch:{

    },
    methods:{
      // 初始化数据
      async init(){
        // console.log(this.nowModel);
        if (this.nowModel == 'follow' && (this.spaceInfo.isOpenFollow || this.showModel == 'me')) {
          // 获取关注表信息
          this.getFollowInfo()
        }
        else if (this.nowModel == 'fan' && (this.spaceInfo.isOpenFan || this.showModel == 'me')) {
          // 获取粉丝表信息
          this.getFanInfo()
        }
        else{
          // 提示Up关闭显示权限
          this.$message.warning('Up关闭了显示权限')
        }
        // 获取统计数量
        // 关注数量
        let data = await countFollows(this.spaceUserId);
        this.followtotal[1] = data.allFollow
        this.followtotal[2] = data.special
        // 粉丝数量
        let data2 = await countFans(this.spaceUserId);
        this.fantotal[1] = data2
      },
      // 获取关注表信息
      async getFollowInfo(){
        let data = await getFollowInfoInSpace(this.spaceUserId, this.type, Number(this.page) + 1)
        this.contentList = data.list
        this.page = Number(this.page) + 1
      },
      // 获取粉丝表信息
      async getFanInfo(){
        let data = await getFanInfoInSpace(this.spaceUserId, this.type, Number(this.page) + 1)
        this.contentList = data.list
        this.page = Number(this.page) + 1
      },

      // 点击导航获取对应内容
      changeContnet(nowModel, type){
        this.nowModel = nowModel
        this.type = type
        this.contentList = ''
        this.page = 0
        if (this.nowModel == 'follow' && (this.spaceInfo.isOpenFollow || this.showModel == 'me')) {
          // 获取关注表信息
          this.getFollowInfo()
        }
        if (this.nowModel == 'fan' && (this.spaceInfo.isOpenFan || this.showModel == 'me')) {
          // 获取粉丝表信息
          this.getFanInfo()
        }
      },

      // 分页每页条数改变时触发
      handleSizeChange(val) {
        console.log(`每页 ${val} 条`);
      },
      // 分页当前页面改变时触发
      handleCurrentChange(val) {
        // console.log(`当前页: ${val}`);
        // 获取用户数据
        // this.get(val)
      },
    },
    created(){
      if(typeof this.$route.query.model == typeof ''){
        this.nowModel=this.$route.query.model
      }

      // 获取展示用户数据
      this.init()
    },
    mounted(){

    },
    destroyed(){
      
    },
    
  }
</script>

<style scoped>
  /* 右边活动导航样式 */
  .active{
    color: #00a1d6;
  }
  /* 左边活动导航样式 */
  .active_nav{
    color: white;
    background-color: #00a1d6;
    cursor: pointer;
  }
  /* 页面整体 */
  .space_fan_follow{
    background-color: white;
    margin-top: 10px;
    border-radius: 5px;
    box-shadow: 0px 0px 20px rgb(229, 229, 229);
  }

  /*
   左边导航
  */
  .nav_list_1, .nav_list_2{
    border-bottom: 1px solid rgb(229, 229, 229);
  }
  .nav_list_1 li, .nav_list_2 li{
    padding: 15px;
    
  }
  .nav_list_1 li:not(:first-child,.active_nav):hover, .nav_list_2 li:not(:first-child,.active_nav):hover{
    cursor: pointer;
    background-color: rgb(240, 240, 240);
    color: #00a1d6;
  }

  .nav_list_1 li:first-child,.nav_list_2 li:first-child{
    color: rgb(160, 160, 160); 
  }

  /* 新分类按钮 */
  .new_class_button{
    float: right; 
    width: 22px; 
    height: 22px; 
    font-size: 22px; 
    line-height: 22px; 
    text-align: center; 
    color: white; 
    border-radius: 50%; 
    background-color: rgb(220, 220, 220);
  }
  .new_class_button:hover{
    cursor: pointer;
    background-color: rgb(180, 180, 180);
  }

  /* 导航图标共有 */
  .nav_icon{
    margin-right: 6px;
    vertical-align: middle;
    background-repeat: no-repeat;
    display: inline-block;
    
  }
  /* 所有关注栏图标 */
  .all_follow_icon{
    width: 20px;
    height: 18px;
  }
  /* 特别关注图标 */
  .special_icon{
    width: 20px;
    height: 17px;
  }
  /* 粉丝图标 */
  .fan_icon{
    background-position: -21px -984px;
    width: 20px;
    height: 17px;
  }



  /* 
    右边内容区
   */
  .right{
    padding: 0 30px;
  }

  .head{
    padding: 20px 0;
  }

  .nav_right{
    font-size: 13px;
  }
  .nav_right span{
    padding: 4px 8px;
  }
  .nav_right span:hover{
    color: #00a1d6;
    cursor: pointer;
  }

  /* 控制按钮共同 */
  .control_button{
    width: 70px;
    height: 25px;
    margin-left: 10px;
    border-radius: 5px;
    font-size: 12px;
    color: #6d757a;
    background-color: #e5e9ef;
  }

  .control_button:hover{
    color: #00a1d6;
    border-color: #00a1d6;
    cursor: pointer;
  }
  .follow_button{
    border: 1px solid #c8d0d6;
    background-color: transparent;
  }
  .message_button{
    background-color: transparent;
    border: 1px solid  rgb(180, 180, 180);
  }
</style>