      // 复制本页面链接存储剪切板
      copyUrl(){
        // console.log(window.location.href);
        const clipboardObj = navigator.clipboard.writeText(`${window.location.href}`)
        if(clipboardObj){
          this.$message({
            message: '视频链接已复制到剪切板了，快和大家分享吧♪',
            type: 'success'
          });
        }
        else{
          this.$message.error('链接复制出错了');
        }
      },

      // 查询用户在这vid列表所属视频是否有点赞等记录，
      async getVideoInfoByvid(){
        let temp = ""
        for (let i = 0; i < this.updateContentList.length; i++) {
          temp += this.updateContentList[i].vid + ','
        }
        console.log(temp);
        let data = await getUserVideoListInfoByVid(temp);
        if (data != "noLogin") {
          this.videoListInfo = data
        }
      },

      //获取当前可视范围的高度  当前显示页面高度
      getClientHeight() {
        var clientHeight = 0;
        if (document.body.clientHeight && document.documentElement.clientHeight) {
          clientHeight = Math.min(document.body.clientHeight, document.documentElement.clientHeight)
        } else {
          clientHeight = Math.max(document.body.clientHeight, document.documentElement.clientHeight)
        }
        return clientHeight
      },
      
      //获取文档完整的高度  全部高度
      getScrollHeight() {
        return Math.max(document.body.scrollHeight, document.documentElement.scrollHeight)
      },

      //获取当前滚动条的位置  距离顶部距离
      getScrollTop() {
        var scrollTop = 0;
        //window.pageYOffset = document.documentElement.scrollTop
        if (document.documentElement && document.documentElement.scrollTop) {
          scrollTop = document.documentElement.scrollTop
        } else if (document.body) {
          scrollTop = document.body.scrollTop
        }
        return scrollTop
      },
      
      //回调函数
      windowScroll() {
        // console.log(1);
        //获取三个值
        var scrollTop = this.getScrollTop()
        // console.log(scrollTop);
        var clientHeight = this.getClientHeight()
        // console.log(clientHeight);
        var scrollHeight = this.getScrollHeight()
        // console.log(scrollHeight);
        //如果满足公式则，确实到底了
        if(scrollTop+clientHeight + 500 >= scrollHeight){
          if (!this.timer) {
            console.log("刷新");
            this.addVideoByUidAndPage()
          }
        }
      },
      
      addVideoByUidAndPage(){
        // 有计时器存在时
        if(this.timer){
          // 清除当前计时器
          clearTimeout(this.timer)
          // 重新计时
          this.timer = setTimeout(()=>{
            // 时间到清除计时器，开放调用接口
            this.timer = ''
          },1000)
        }
        // 首次执行
        if(!this.timer){
          this.addContentToList()
          // 设置1s空计时器
          this.timer = this.timer = setTimeout(()=>{
            // 时间到清除计时器，开放调用接口
            this.timer = ''
          },1000)
        }
      },

      // 内容列表追加内容
      async addContentToList(){
        // 当前数量还未到全部
        if(this.updateContentList.length < this.maxNum){
          this.page = this.page + 1
          console.log(this.initUid);
          let data = await getVideoByUidList(this.initUid, this.page)
          console.log(res);
          let temp = data.list.data
          temp.forEach((item)=>{
            this.updateContentList.push(item)
          })
          // 请求新视频的点赞等记录
          this.getVideoInfoByvid()
          console.log(this.updateContentList);
        }
      },

      // 点击标签前往搜索界面搜索标签内容 和视频推荐列表共用一个接口，uid不传递
      gotosearch(label){
        // console.log(e.target.innerText.slice(2,-1));
        this.$router.push({
          path: '/search',
          query:{searchContent:label}
        })
      },

      // label字符串裁剪打印
      videoLabelList(string){
        if(string){
          return string.split(',')
        }
      },
      // ----------------------------------------------------更新内容列表逻辑结束---------------------------------

      // 获取用户头像url
      getImgURL(address){
        return getUserCover(address);
      },
      // 获取vip图
      getVIPImgURL(address){
        return getVipIcon(address);
      },

      // 获取uid对象所有显示内容（分页）
      async getContentByUidList(){
        this.page = 1
        console.log(this.initUid);
        let data = await getVideoByUidList(this.initUid, this.page)
        this.updateContentList = data.list.data
        this.maxNum = data.totalNum
        // 请求新视频的点赞等记录
        this.getVideoInfoByvid()
      },
    },
    mounted(){
      // 根据父组件提供的initUid字符串列表
      this.getContentByUidList()
      window.addEventListener('scroll', this.windowScroll) //监听页面滚动
    },
    beforeDestroy(){
    },
    destroyed() {
      window.removeEventListener("scroll", this.windowScroll);//销毁滚动事件
    },
    //删除滚动监听器，建议使用beforeRouteLeave，因为destroyed()钩子在路由跳转时不会触发
    beforeRouteLeave(to,from,next) {
      window.removeEventListener("scroll", this.windowScroll);//销毁滚动事件
      next()
    }
  }
</script>

