import request from '@/Request'

export {
  getAllFollowInfoByUid,
  userIsFollowTarget,
  cancelFollow,
  followUser,
  followUser2,
  countFollows,
  getFollowInfoInSpace,

  
}

// 根据用户id获取其关注者信息
function getAllFollowInfoByUid (uid) {
  return request({
    method:'get',
    url:'/follow/all/' + uid,
  })
}

// 判断两个uid是否是关注状态(token)
function userIsFollowTarget(uid){
  return request({
    method:'get',
    url:'/follow/isFollow2/'+ uid,
  })
}

// 取消关注
function cancelFollow(followedUid){
  return request({
    method:'delete',
    url:'/follow/delete/' + followedUid,
  })
}

// 保存关注
function followUser(data){
  return request({
    method:'post',
    url:'/follow/save',
    data: data,
  })
}

// 保存关注2
function followUser2(followedUid){
  return request({
    method:'post',
    url:'/follow/save2/'+ followedUid,
  })
}

// 统计关注数量
function countFollows(uid){
  return request({
    method: 'get',
    url: '/follow/count/' + uid,
  })
}

// 获取关注表信息
function getFollowInfoInSpace(uid, type, page){
  return request({
    method: 'get',
    url: '/follow/table/' + uid + "/" + type + '/' + page
  })
}
