  此文件负责的板块：后端错误界面
    功能：
      1、后端错误跳转到此界面，穿梭动画卡顿效果未解决
  -->

<template>
  <div id="view" style="overflow: hidden; width: 100vw; height: 100vh; background-color: white;">
  </div>
</template>

<script>
// 导入pixi
import * as PIXI from "pixi.js";
global.PIXI = PIXI;
// 导入spine
require("pixi-spine");

let app
let skeleton
let controlBone
let role
let anim = {
  left: '',
  up: '',
  right: '',
  down: '',
}
let animAlpha = {
  left: 0,
  up: 0,
  right: 0,
  down: 0,
}

  export default{
    name: 'Error5XX',
    methods:{
      // 初始化
      init(){
        // console.log("sd");
        app = new PIXI.Application({
          transparent: true,
          resizeTo: document.getElementById("view")
        })
        document.getElementById("view").appendChild(app.view)

        app.loader.add('spineCharacter', '/spine/Spine_vortex_v03.json')
        .load((loader, resources)=>{
          role = new PIXI.spine.Spine(resources.spineCharacter.spineData)
          skeleton = role.skeleton
          controlBone = skeleton.findBone('control_direction_bone_f')

          // role.state.setAnimation(0, 'vortex-idle', true)
          role.state.setAnimation(0, 'vortex-idle', true)
          role.state.setAnimation(1, 'spineboy-idle', true)

          anim.up = role.state.setAnimation(2, 'up', true)
          anim.down = role.state.setAnimation(3, 'down', true)
          anim.left = role.state.setAnimation(4, 'left', true)
          anim.right = role.state.setAnimation(5, 'right', true)

          anim.up.alpha = animAlpha.up
          anim.down.alpha = animAlpha.down
          anim.left.alpha = animAlpha.left
          anim.right.alpha = animAlpha.right
          

          role.x = app.screen.width / 2
          role.y = app.screen.height / 2
          role.scale.set(0.3)
          app.stage.addChild(role)

          // 窗体鼠标移动事件
          window.addEventListener('mousemove',this.eventHandler)
        })
      },
      eventHandler(e){
        // 坐标偏移到中心，y轴翻转
        controlBone.x = e.x - app.screen.width / 2
        controlBone.y = - (e.y - app.screen.height / 2)

        // 值约束到（0，1）
        let x = e.x / document.getElementById('view').clientWidth
        let y = e.y / document.getElementById('view').clientHeight

        // console.log(x);
        // console.log(y);

        // 中心上半边，中心为0，边界为0.7
        anim.up.alpha = (0.7 - Math.min(y, 0.5))
        // 中心下半边，中心为0，边界为0.7
        anim.down.alpha = (Math.max(y, 0.5) - 0.3)
        // 中心左半边，中心为0 边界为0.7
        anim.left.alpha  = (0.7 - Math.min(x, 0.5)) 
        // 中心右半边，中心为0，边界为0.7
        anim.right.alpha = (Math.max(x, 0.5) - 0.3)
        

        // console.log("x轴" + (e.x - app.screen.width / 2));
        // console.log("y轴" + (e.y - app.screen.height / 2));

        // 判断是在偏移后中心的方位
        // if (e.x - app.screen.width / 2 > 0)
        // role.state.setAnimation(2, 'right', true) 
        // if (e.x - app.screen.width / 2 < 0) 
        // role.state.setAnimation(2, 'left', true)
        // if ((e.y - app.screen.height / 2) < 0) 
        // role.state.setAnimation(1, 'up', true)
        // if ((e.y - app.screen.height / 2) > 0) 
        // role.state.setAnimation(1, 'down', true)
      }
      // 窗口大小变化事件，恢复中心点
    },
    mounted(){
      // 初始化
      this.init()
    },
    destroyed(){
      // 销毁窗体鼠标移动事件
      window.removeEventListener('mousemove', this.eventHandler)
    },
  }
</script>