<!-- 
  项目：Elyden.com
  创建时间：2024.01.29
  上次更新时间：2023.05.11
  组件名称：SpaceCompilation
  此文件负责的板块：用户空间合集界面顶部导航
    功能：
      1、游客查看合集和合集内容
      2、空间主人编辑合集内容，新建合集
  -->
<template>
  <div class="content">
    <!-- 前往合集home界面链接 -->
    <router-link to="/space/compilation/home">
      <span v-if="showModel=='other'">TA</span>
      <span v-if="showModel=='me'">我</span>的合集
    </router-link>
    <!-- <router-link class="jump" to="/space/compilation/child" v-if="showTitle">
      <span class="title_cut_icon">></span>
      {{ compilation_title }}
    </router-link> -->
    <!-- 当前展示的详细合集名称 -->
    <div style="display: inline-block;" v-if="showTitle">
      <span class="title_cut_icon">></span>
      {{ compilation_title }}
    </div>
    <!-- 添加合集按钮 -->
    <div v-if="!compilation_title && showModel=='me'" class="addCompilationButton" @click="dialogCompilationVisible = true">
      <span class="addicon">+</span>
      <span>添加合集</span>
    </div>
    <!-- 删除合集按钮 -->
    <div v-if="compilation_title && showModel=='me'" class="deleteCompilationButton" @click="deletedCompilation">
      <span>删除合集</span>
    </div>
    <!-- 编辑合集按钮 -->
    <div v-if="compilation_title && showModel=='me'" class="editCompilationButton" @click="editCompilation">
      <span>编辑合集</span>
    </div>
    
    <!-- <el-breadcrumb separator-class="el-icon-arrow-right">
      <el-breadcrumb-item :to="{ path: '/space/compilation/home' }" @click.native="hh"><h2 style="cursor: pointer;">合集</h2></el-breadcrumb-item>
      <el-breadcrumb-item class="h2">对印反击战</el-breadcrumb-item>
      <el-breadcrumb-item></el-breadcrumb-item>
    </el-breadcrumb> -->
    <!-- 合集展示列表 -->
    <RouterView name="Compilation"></RouterView>

    <!-- 添加合集和新建合集弹窗 -->
    <el-dialog
      :title="dialogTitle"
      :visible.sync="dialogCompilationVisible"
      top="30vh"
      width="30%"
      :before-close="handleClose">
      <div>
        <!-- 合集名称和合集简介表单 -->
        <form v-if="!secondPage" style="text-align: center; width: 100%; margin: 20px;">
          <div style="margin-bottom: 20px;"><span>合集标题：</span><input class="new_compilation_titleBox" type="text" v-model="new_compilation.name" placeholder="给你的新合集取一个标题吧♪" style="padding: 0 5px; width: 70%; height: 30px;"></div>
          <div style="height: 100px; line-height: 100px; border-radius: 10px;"><span>合集简介：</span><textarea type="text" v-model="new_compilation.synopsis" class="new_compilation_synopsisBox" placeholder="向大家介绍一下这个新合集吧♪" style="padding: 5px; height: 80px; width: 70%; vertical-align: middle;"></textarea></div>
        </form>
        <!-- 选择视频加入到合集 -->
        <form v-if="secondPage">
          <!-- 选择视频 -->
          <div style="font-size: 20px;">
            <div>选择视频</div>
            <!-- 全选按钮 -->
            <div><el-checkbox :indeterminate="isIndeterminate" v-model="checkAll" @change="handleCheckAllChange">全选</el-checkbox></div>
          </div>
          <!-- 视频列表 -->
          <ol style="height: 30vh; overflow-x: auto;" @scroll="selectVideoSmallPageScrollBottom">
            <!-- 单个视频 -->
            <li v-for="(item,index) in select_video_list" :key="item.vid">
              <div style="position: relative; width: 90%;">
                <div class="video_list_item1">
                  <!-- 视频封面 -->
                  <div class="video_list_item1_cover">
                    <img :src=getImgURL(item.coverAddress) alt="稿件封面">
                  </div>
                  <!-- 视频标题 -->
                  <div class="video_list_item1_title">
                    <span class="video_title"> {{ item.title }} </span>
                  </div>
                  <!-- 视频信息 -->
                  <div class="video_list_item1_msg">
                    <!-- 视频播放量 -->
                    <div class="videoPlayedInfo">
                      <svg class="play_video_icon" aria-hidden="true">
                        <use xlink:href="#icon-shipin"></use>
                      </svg>
                      {{ item.playedNum / 10000 > 1 ? item.playedNum / 10000+"万": item.playedNum}}
                    </div>
                    <!-- 发布日期 -->
                    <div class="video_data_item recommend_date">
                      {{ item.publishTime? item.publishTime.slice(0,10) :''}}
                    </div>
                  </div>
                </div>
                <!-- 视频选择框 -->
                <el-checkbox-group style="scale: 2; position: absolute; right: 0; top: 30%;" v-model="checkedCities" @change="handleCheckedCitiesChange">
                  <el-checkbox :label="item.vid">{{  }}</el-checkbox>
                </el-checkbox-group>
              </div>
            </li>
          </ol>
        </form>
      </div>
      <!-- 底部控制按钮 -->
      <span slot="footer" class="dialog-footer">
        <!-- 取消新建合集或者取消编辑合集按钮 -->
        <el-button v-if="!secondPage" @click="cancel">取 消</el-button>
        <!-- 新建合集下一步按钮，前往合集添加视频 -->
        <el-button v-if="!secondPage && dialogTitle == '新建合集'" @click="addNewCompilationNextPage">下一步</el-button>
        <!-- 返回新建合集上一步按钮 -->
        <el-button v-if="secondPage" @click="secondPage = false">上一步</el-button>
        <!-- 确认新建合集 -->
        <el-button v-if="secondPage && dialogTitle == '新建合集'" type="primary" @click="saveNewCompilation">确定</el-button>
        <!-- 确认编辑合集 -->
        <el-button v-if="dialogTitle == '编辑合集'" type="primary" @click="acceptEditCompilation">确定</el-button>
      </span>
    </el-dialog>
  </div>
</template>

<script>
import { RouterView } from 'vue-router';
import { deleteCompilation, editCompilation, saveNewCompilation } from '@/api/compilation';
import { countUserVideo, getUserVideoByPage, getVideo } from '@/api/video';
  export default{
    name: 'SpaceCompilation',
    data(){
      return{
        // 弹窗标题
        dialogTitle:'新建合集',
        // 添加合集弹窗显示
        dialogCompilationVisible: false,
        // 添加合集是否处于第二页
        secondPage: false,
        // 用以表示 checkbox 的不确定状态，一般用于实现全选的效果
        isIndeterminate: true,
        checkAll: false,
        checkedCities: [],
        // 添加合集界面的选择视频列表
        select_video_list:[],
        // 计时器
        timer:'',
        // 选择视频列表当前页面
        page:1,
        // 排序条件
        condition:'publish_time',
        // 此用户的视频总数
        videoTotal:0,

        // 新合集
        new_compilation:{
          id:'',
          name:'',
          synopsis:'',
          // 合集创建时间
          time:'',
          uid:'',
        },
        // 选择的vid集合
        vidlist:'',
      }
    },
    watch: {
      // 页面跳转，清空合集标题
      $route(to, from){
        // this.$store.dispatch('changeCompilationTitle','')
      }
    },
    components: {
      RouterView
    },
    computed:{
      // 获取合集标题展示
      compilation_title(){
        return this.$store.state.compilation_title || ''
      },
      // 是否展示合集标题
      showTitle(){
        return this.compilation_title!=''
      },
      // 当前空间的访问模式
      showModel() {
        return this.$store.state.spaceViewModel
      },
      // 用户空间状态信息
      spaceInfo(){
        // console.log(this.$store.state.spaceInfo);
        return this.$store.state.spaceInfo
      },
    },
    methods:{
      // 编辑合集
      editCompilation(){
        // 展示界面
        this.dialogCompilationVisible = true
        // 修改title
        this.dialogTitle = '编辑合集'
      },

      // 确认修改合集信息
      async acceptEditCompilation(){
        // console.log(this.new_compilation);
        this.new_compilation.id = this.$store.state.compilation_id
        // 发送请求
        let data = await editCompilation(this.new_compilation)
        console.log("修改成功");
        // 关闭页面
        this.dialogCompilationVisible = false
        // 清除数据
        this.new_compilation.id = ''
        this.new_compilation.name = ''
        this.new_compilation.synopsis = ''
      },

      // 删除合集提示
      deletedCompilation() {
        this.$confirm('确定删除这个合集吗？', '提示', {
          confirmButtonText: '确定',
          cancelButtonText: '取消',
          type: 'warning'
        }).then(() => {
          this.acceptDeletedCompilation()
        })
      },

      // 确认删除合集
      async acceptDeletedCompilation(){
        console.log("删除");
        let data = await deleteCompilation(this.$store.state.compilation_id)
        if (data == 1) {
          console.log("删除成功");
          this.$message({
            type: 'success',
            message: '删除成功!'
          });
          // 跳转合集home界面
          this.$router.push({
            path:'/space/compilation/home'
          })
        }else{
          this.$message({
            type: 'error',
            message: '删除失败!'
          });
        }
      },

      // 取消新建合集或者编辑合集
      cancel(){
        this.dialogCompilationVisible = false
        this.dialogTitle = '新建合集'
        this.page = 1
      },

      // 保存新建合集
      async saveNewCompilation(){
        // 关闭新建合集界面
        this.dialogCompilationVisible = false
        // 关闭新建合集第二页
        this.secondPage = false
        // 设置新合集创建时间
        this.new_compilation.time = Date.now()
        // 设置合集的创建者id
        this.new_compilation.uid = this.spaceInfo.uid

        // 拼接vid字符串
        this.checkedCities.forEach((item)=>{
          this.vidlist = this.vidlist + item +','
          // console.log(this.vidlist);
        })

        // 发送新建合集请求
        let data = await saveNewCompilation(this.vidlist, this.new_compilation)
        if (data == 1) {
          console.log("创建成功");
          // 创建成功清空信息，创建失败不清空，减少操作
          this.new_compilation.name=''
          this.new_compilation.synopsis=''
          this.new_compilation.time=''
          this.new_compilation.uid=''
          this.page = 1
          // 成功提示
          this.newCompilationSuccess()
        }else{
          console.log("创建失败");
          this.newCompilationError()
        }
      },

      // 提示创建新合集失败
      newCompilationSuccess(){
        this.$message({
          message: '创建成功',
          type: 'success'
        });
      },
      
      // 提示创建新合集失败
      newCompilationError(){
        this.$message.error('创建失败，请稍后重试');
      },


      // 点击新建合集界面的第二页按钮
      async addNewCompilationNextPage(){
        // 显示第二页
        if (this.new_compilation.name.trim() == '') {
          // 提示必须要标题
          this.newCompilationTitleNullError()
          return
        }
        else{
          this.secondPage = true
          this.getSpaceUserCountNum()
          // 获取用户视频
          let data = await getUserVideoByPage(this.spaceInfo.uid, this.condition, `${this.page}`)
          this.page += 1
          this.select_video_list = data
        }
      },

      // 根据空间用户uid获取用户视频稿件的数量
      async getSpaceUserCountNum(){
        let data = await countUserVideo(this.$store.state.spaceUserId)
        this.videoTotal = data
      },

      // 提示标题不能为空
      newCompilationTitleNullError(){
        this.$message({
          message: '标题不能为空喔♪',
          type: 'warning'
        });
      },

      // 新建合集选择视频滚动事件
      selectVideoSmallPageScrollBottom(){
        // console.log("asdasd");
        // 当前获取到的视频总数小于用户所有视频总数，调用后端分页获取视频信息
        if( this.select_video_list.length < this.videoTotal){
          console.log("没满");
          let scrollTop = event.target.scrollTop
          let clientHeight = event.target.clientHeight
          let scrollHeight = event.target.scrollHeight
          if (scrollTop + clientHeight + 30 >= scrollHeight){
            console.log("调用添加视频");
            this.addVideoToSelectList()
          }
        }
      },

      // 滚到底部时调用添加视频
      async addVideoToSelectList(){
        // 有计时器时
        if(this.timer){
          // 清除计时器
          clearTimeout(this.timer)
          // 重新计时
          this.timer = setTimeout(async ()=>{
            console.log(14);
            let data = await getUserVideoByPage(this.spaceInfo.uid, this.condition, `${parseInt(this.page)+1}`)
            this.page = this.page + 1
            let temp = data
            temp.forEach((item)=>{
              this.select_video_list.push(item)
            })
            },500)
          }
          // 首次执行
          if(!this.timer){
            let data = await getUserVideoByPage(this.spaceInfo.uid, this.condition, `${parseInt(this.page)+1}`)
            this.page = this.page + 1
            let temp = data
            temp.forEach((item)=>{
              this.select_video_list.push(item)
            })
            // // 设置1s空计时器
            // this.timer = this.timer = setTimeout(()=>{
            // },500)
          }
      },

      // 新建合集点击全选按钮
      handleCheckAllChange(val) {
        let cityOptions = []
        this.select_video_list.forEach((item)=>{
          cityOptions.push(item.vid)
        })
        this.checkedCities = val ? cityOptions : [];
        this.isIndeterminate = false;
      },
      // 点击值变化时调用
      handleCheckedCitiesChange(value) {
        let checkedCount = value.length;
        this.checkAll = checkedCount === this.select_video_list.length;
        this.isIndeterminate = checkedCount > 0 && checkedCount < this.select_video_list.length;
        console.log(this.checkedCities);
      },
      

      // 新建合集弹窗/设置置顶推荐弹窗点击关闭时提示
      handleClose(done) {
        this.$confirm('确认关闭？')
          .then(_ => {
            this.dialogCompilationVisible = false
            this.page = 1
            done();
          })
          .catch(_ => {});
      },
      // 获取视频封面url
      getImgURL(address){
        return getVideo(address);
      },
    },
    mounted(){
      // console.log(this.compilation_title);
    }
  }
</script>

<style scoped>
a{
  text-decoration: none;
  color: black;
}

/* 页面整体 */
.content{
  margin-top: 20px;
  padding: 20px;
  font-size: 20px;
  background-color: white;
  border-radius: 5px;
  box-shadow: 0px 0px 20px rgb(229, 229, 229);
}

/* 当前展示详细合集的标题 */
.title_cut_icon{
  color: gray;
  margin: 0 10px;
}

/* 添加新合集按钮 */
.addCompilationButton{
  overflow: hidden;
  vertical-align: middle;
  display: inline-block;
  padding: 4px 8px;
  margin-left: 10px; 
  border-radius: 5px; 
  font-size: 12px; 
  color: rgb(180, 180, 180); 
  border: 1px solid rgb(210, 210, 210);
}

/* 小添加合集动画 */
@keyframes hover-anim{
            0%{translate: 0 0;}
            50%{translate: 0 -22px;}
            51%{translate: 0 25px;}
            100%{translate: 0, 0;}
          }

/* 添加新合集按钮悬浮样式 */
.addCompilationButton:hover{
  color: #00a1d6;
  border: 1px solid #00a1d6;
  cursor: pointer;
}

/* 应用动画 */
.addCompilationButton:hover .addicon{
  animation: hover-anim 1s;
}
.addicon{
  width: 15px;
  scale: 2;
  display: inline-block; 
  translate: 2px -1.5px;
}

/* 编辑合集按钮和删除合集按钮 */
.editCompilationButton,.deleteCompilationButton{
  float: right;
  display: inline;
  padding: 4px 8px;
  margin-left: 10px; 
  border-radius: 5px; 
  font-size: 12px; 
  color: #00a1d6;
  border: 1px solid #00a1d6;
  cursor: pointer;
}

/* 删除合集按钮颜色修改 */
.deleteCompilationButton{
  color: rgb(255, 110, 110);
  border: 1px solid rgb(255, 110, 110);
}


/* 
  视频列表
 */
/* 播放图标 */
 .play_video_icon{
  width: 1em;
  height: 1em;
  vertical-align: -0.1em;
  fill: currentColor;
  overflow: hidden;
}
/* 视频列表 */
.video_list{
  display: flex;
  flex-wrap: wrap;
  margin-bottom: 30px;
}
/* 单个视频列表元素 */
.video_list_item1{
  width: 203px;
  margin-right: 20px;
  margin-top: 20px;
  cursor: pointer;
}
/* 视频信息 */
.video_list_item1_msg{
  font-size: 12px;
  color: gray;
  display: flex;
  justify-content: space-between;
  margin-top: 10px;
}
/* 视频封面 */
.video_list_item1 img{
  width: 100%;
  height: 140px;
  border-radius: 5px;
}
/* 视频标题 */
.video_list_item1_title{
  font-size: 14px;
  height: 40px;
  overflow: hidden;
}

/* 创建新合集的标题框 */
.new_compilation_titleBox::placeholder{
  color: #cecece;
}
/* 创建新合集简介框 */
.new_compilation_synopsisBox::placeholder{
  color: #cecece;
}
</style>