          <div class="parkBackGround01" style="opacity: 0;"></div>
          <div class="parkBackGround02" style="opacity: 0;"></div>
          <img class="parkText" style="opacity: 0; margin-top: 60px;" src="/img/带你去游乐园.png" alt="">
        </div>
        <!-- 分镜六：成长和衰老 -->
        <div id="view" style="text-align: center; flex-shrink:0;">
          <div class="growUp" ref="growUp"></div>
