</template>

<script>
// 导入pixi和spine
import * as PIXI from "pixi.js";
global.PIXI = PIXI;
require("pixi-spine");
import {TweenMax, TimelineMax, gsap} from "gsap";


// 总时间轴
let allTimeLine

  export default{
    name:'Activity',
    data(){
      return{
        state: false,

        h:'1',

        // pixi对象
        app: '',

        aili:'',

        baseTexture:'',

        loader:'',
      }
    },
    methods:{
      //前往首页界面
      gotoMain(){
        this.$router.push({
          path:'/'
        })
      },
      // 初始化
      init(){
        this.app = new PIXI.Application({
          transparent: true,
          resizeTo: document.getElementById("view")
        })
        document.getElementById("view").appendChild(this.app.view)

        // 加载素材
        this.loader = this.app.loader;
        this.loader.add('i1','/img/桌面宠物.jpg')
              .add('t2','/img/电脑椅.jpg')
              .add('openTextPng','/img/你是否还记得.png');

        // 加载并添加
        this.loader.load((loader, resources) => {
          this.h = new PIXI.Sprite(resources.i1.texture);
          this.h.position.set(0, 700)
          this.h.alpha = 0
          this.app.stage.addChild(this.h)
        });


        // 加载进度
        this.loader.onProgress.add((loader, res)=>{
          console.log(loader.progress)

        })
        
        // 加载完成
        this.loader.onComplete.add(()=>{

          // 测试分镜一
          this.sceneOne()




          console.log("加载完成");

          // 创建timeline,默认不播放动画 整体时间轴看作1
          let allTimeLine = gsap.timeline({paused:true})

          // 监听窗体滚动事件
          window.addEventListener('scroll', ()=>{
            let scrollY = window.scrollY
            let clientHeight = document.documentElement.clientHeight
            // 滚动条总高度
            let scrollHeight = document.body.scrollHeight;
            console.log("已经滚动"+scrollY);
            console.log("可视"+ clientHeight);
            console.log("总"+scrollHeight);

            let nowtime = scrollY / (scrollHeight - clientHeight)
            console.log(nowtime);
            // 计算当前滚动占总百分比，用于判断是否显示动画
            allTimeLine.seek(nowtime)

            this.AnimationPlay(nowtime)
          });
          console.log(this.h);

          

          // // // 在时间轴在0.3，整体30%时改变动画
          // let timeline = gsap.timeline({delay: 0.3})
          // // 指定控制哪个精灵，动画占时间轴多少百分比，执行的内容
          // let tweenMax = new TweenMax(this.h, 0.2, {alpha : 1})
          // // 动画添加到子时间轴，开始为0
          // timeline.add(tweenMax, 0)
          // // 将时间轴加入到总时间轴
          // allTimeLine.add(timeline, 0)

          // 序列帧动画加载
          // 加载角色图片
          this.baseTexture = PIXI.BaseTexture.from('/img/flyAnim.png')

          // 创建帧动画图片数组
          let flyAnimTextureArray = []

          // 图片加入
          for(let i = 0;  i < 12; i++){
            flyAnimTextureArray.push(
              new PIXI.Texture(
                this.baseTexture,
                new PIXI.Rectangle(149*i, 0, 149, 226)
              )
            )
          }

          // 创建动画精灵
          // this.aili = new PIXI.AnimatedSprite(flyAnimTextureArray)
          // this.aili.animationSpeed = 0.1
          // this.aili.play()
          // this.aili.alpha = 0
          // this.aili.scale.set(-1, 1)
          // this.aili.x = this.app.screen.width / 2 ;
          // this.aili.y = 1300;
          // this.aili.transform.pivot.set(70, 120)
          // this.app.stage.addChild(this.aili)


          // 创建角色纹理，区域裁剪
          const roleTexture = new PIXI.Texture(
            this.baseTexture,
            new PIXI.Rectangle(0, 0, 149, 226)
          )

          // 创建角色精灵
          this.aili = new PIXI.Sprite(roleTexture)
          this.aili.position.set(this.app.screen.width / 2, 1300)
          this.aili.alpha = 0
          this.app.stage.addChild(this.aili);
          console.log(this.aili);

          // 滚动窗口控制动画播放，正向滚动正向播放，反向滚动，反向播放，停止滚动停止播放
          // 设置子时间轴，在总时间轴50%开始播放
          let timeline2 = gsap.timeline({delay: 0.5})
          // 指定控制对象和动画操作, 整体10%的时间内显示
          let tweenMax2 = new TweenMax(this.aili, 0.1, {alpha: 1})
          timeline2.add(tweenMax2, 0)
          allTimeLine.add(timeline2, 0)

        });

        
        
        
        
      },
      setup(){
        console.log("加载完成");
      },
      AnimationPlay(nowtime){
        if (nowtime>0.6) {
          // 序列帧总图片
          let allAnimPageNum = 12

          // 计算当前动画图片下标 当前时间-开始播放时间 播放时长 总动画图片数
          // 当前时间 - 开始播放时间 = 已经播放时间
          // 播放时长 / 总动画图片数 = 单张图片播放时间
          // 已经播放时间 / 单张播放时间 = 当前播放图片下标 
          let index = Math.floor((nowtime - 0.6) / 0.3 * allAnimPageNum)
          if (index < allAnimPageNum ) {
            this.aili.texture = new PIXI.Texture( this.baseTexture, new PIXI.Rectangle(149*index, 0, 149, 226))
            console.log(this.aili);
          }
        }
      },

      // 滚动事件
      scrollEvent(e){
        let scrollTop = e.target.scrollTop
        let clientHeight = e.target.clientHeight
        let scrollHeight = e.target.scrollHeight
        console.log("已经滚动"+scrollTop);
        console.log("可视"+ clientHeight);
        console.log("总"+scrollHeight);

        let nowtime = scrollTop / (scrollHeight - clientHeight)
        console.log(nowtime);
        // 计算当前滚动占总百分比，直接切换到指定时间点 用于判断是否显示动画
        allTimeLine.seek(nowtime)

        // 切换动画图片
        this.changeImg(nowtime)
      },

      changeImg(nowtime){
        // 播放分镜二第一个动画，时长8%，和显示动画重叠4%，总 显示3%-7% 播放3%-11%
        if (nowtime > 0.03) {
          // // 序列帧总图片
          // let allAnimPageNum = 28

          // // 计算当前动画图片下标 当前时间-开始播放时间 播放时长 总动画图片数
          // // 当前时间 - 开始播放时间 = 已经播放时间
          // // 播放时长 / 总动画图片数 = 单张图片播放时间
          // // 已经播放时间 / 单张播放时间 = 当前播放图片下标 
          // let index = Math.floor((nowtime - 0.03) / 0.08 * allAnimPageNum)
          // if (index < allAnimPageNum) {
          //   this.$refs.babyCry.style.backgroundPosition = `-${227 * index}px 0`
          // }
          this.changePlayImg(28, nowtime, 0.03, 0.08, "babyCry", 227)
        }

        // 播放分镜二第二个动画，时长10%，和显示动画重叠4%，总 显示10%-14% 播放10%-20%
        if (nowtime > 0.1) {
          // // 序列帧总图片
          // let allAnimPageNum = 32

          // // 计算当前动画图片下标 当前时间-开始播放时间 播放时长 总动画图片数
          // // 当前时间 - 开始播放时间 = 已经播放时间
          // // 播放时长 / 总动画图片数 = 单张图片播放时间
          // // 已经播放时间 / 单张播放时间 = 当前播放图片下标 
          // let index = Math.floor((nowtime - 0.09) / 0.1 * allAnimPageNum)
          // if (index < allAnimPageNum) {
          //   this.$refs.comeFrom.style.backgroundPosition = `-${363 * index}px 0`
          // }
          this.changePlayImg(32, nowtime, 0.1, 0.1, "comeFrom", 363)
        }
        
        // 播放分镜三动画，时长17%，和显示动画重叠4%，总 显示17%-21% 播放17%-30%
        if (nowtime > 0.17) {
          this.changePlayImg(30, nowtime, 0.17, 0.13, "studyBike", 1537)
        }

        // 播放分镜五动画，时长13%，和显示动画重叠3%，总 显示14%-18% 播放14%-27%
        // if (nowtime > 0.39) {
        //   this.changePlayImg(15, nowtime, 0.39, 0.64, "park", 339)
        // }

        // 播放分镜六动画，时长9%，和显示动画重叠3%，总 显示55%-59% 播放56%-65%
        if (nowtime > 0.56) {
          this.changePlayImg(14, nowtime, 0.56, 0.09, "growUp", 548)
        }

        // 播放分镜七动画，时长8%，和显示动画重叠3%，总 显示64%-68% 播放65%-73%
        if (nowtime > 0.65) {
          this.changePlayImg(14, nowtime, 0.65, 0.08, "old01", 206)
          
        }
        // 播放分镜七动画，时长8%，和显示动画重叠3%，总 显示72%-76% 播放73%-81%
        if (nowtime > 0.73) {
          this.changePlayImg(14, nowtime, 0.73, 0.08, "old02", 203)
        }
        
        // 播放分镜八动画，时长9%，和显示动画重叠3%，总 显示83%-87% 播放84%-92%
        if (nowtime > 0.84) {
          this.changePlayImg(55, nowtime, 0.84, 0.08, "camera", 870)
        }
      },

      // 切换播放动画图片
      // 总图片数 开始时间 持续时间 操作动画对象 宽度
      changePlayImg(allAnimPageNum, nowtime, startTime, long, target, width){
        // 计算当前动画图片下标 当前时间-开始播放时间 播放时长 总动画图片数
        // 当前时间 - 开始播放时间 = 已经播放时间
        // 播放时长 / 总动画图片数 = 单张图片播放时间
        // 已经播放时间 / 单张播放时间 = 当前播放图片下标 
        let index = Math.floor((nowtime - startTime) / long * allAnimPageNum)
        if (index < allAnimPageNum) {
          let string = `this.$refs.${target}.style.backgroundPosition = "-${width * index}px 0"`
          eval(string)
        }
      },

      // 初始化2
      init2(){
        // 创建timeline总时间轴,默认不播放动画，滚动轴百分比数值给seek函数直接跳转动画播放位置，整体时间轴看作1
        allTimeLine = gsap.timeline({paused:true, duration: 1})

        // 分镜一：文字动画
        gsap.to(".scene01", {
          opacity: 1,
          delay: .5,
          duration: 2,
          y: -100
        },)

        // 分镜二 动画一：宝宝哭泣
        // 滚动窗口控制动画播放，正向滚动正向播放，反向滚动，反向播放，停止滚动停止播放
        // 设置子时间轴，在总时间轴3%开始播放，即总时间轴起点延迟0.03
        let timelineview0201 = gsap.timeline({delay: 0.03})
        // 指定控制对象和动画操作, 整体4%的时间内显示
        let tweenMax01 = new TweenMax(".babyCry", {duration: 0.04, opacity: 1})
        let tweenMax0102 = new TweenMax(".babyCryText", {duration: 0.05, y:-100, opacity: 1})
        // 以子时间轴的起点开始
        timelineview0201.add(tweenMax01, 0)
        timelineview0201.add(tweenMax0102, 0)
        // 子时间轴加入到总时间轴
        allTimeLine.add(timelineview0201, 0)

        // 分镜二 动画二：我从哪来
        // 设置子时间轴，在总时间轴10%开始播放
        let timelineview0202 = gsap.timeline({delay: 0.1})
        // 指定控制对象和动画操作, 整体4%的时间内显示
        let tweenMax02 = new TweenMax(".comeFrom", {duration: 0.04, opacity: 1})
        let tweenMax0202 = new TweenMax(".comeFromText", {duration: 0.05, y:-100, opacity: 1})
        timelineview0202.add(tweenMax02, 0)
        timelineview0202.add(tweenMax0202, 0)
        allTimeLine.add(timelineview0202, 0)

        // 分镜三：学自行车
        // 设置子时间轴，在总时间轴17%开始播放
        let timelineview03 = gsap.timeline({delay: 0.17})
        // 指定控制对象和动画操作, 整体4%的时间内显示
        let tweenMax03 = new TweenMax(".studyBike", {duration: 0.04, opacity: 1})
        let tweenMax0302 = new TweenMax(".studyBikeText", {duration: 0.1, opacity: 1})
        timelineview03.add(tweenMax03, 0)
        timelineview03.add(tweenMax0302, 0)
        allTimeLine.add(timelineview03, 0)

        // 分镜四：陪伴
        // 设置子时间轴，在总时间轴33%开始播放
        let timelineview04 = gsap.timeline({delay: 0.33})
        // 指定控制对象和动画操作, 整体10%的时间内显示
        let tweenMax04 = new TweenMax(".gotoschoolText", {duration: 0.1, opacity: 1})
        timelineview04.add(tweenMax04, 0)
        allTimeLine.add(timelineview04, 0)

        // 分镜五：游乐园
        // 设置子时间轴，在总时间轴45%开始播放
        let timelineview05 = gsap.timeline({delay: 0.45})
        // 指定控制对象和动画操作, 整体4%的时间内显示
        let tweenMax05 = new TweenMax(".park", {duration: 0.04, opacity: 1})
        let tweenMax0501 = new TweenMax(".park", {duration: 0.15, x: 1500})
        let tweenMax0502 = new TweenMax(".parkText", {duration: 0.1, opacity: 1})
        timelineview05.add(tweenMax05, 0)
        .to('.parkBackGround01', {duration: 0.04, opacity: 1}, 0)
        .to('.parkBackGround02', {duration: 0.04, opacity: 1}, 0)
        timelineview05.add(tweenMax0501, 0)
        timelineview05.add(tweenMax0502, 0)
        allTimeLine.add(timelineview05, 0)

        // 分镜六：成长和衰老
        // 设置子时间轴，在总时间轴55%开始播放
        let timelineview06 = gsap.timeline({delay: 0.55})
        // 指定控制对象和动画操作, 整体10%的时间内显示
        let tweenMax06 = new TweenMax(".growUpText", {duration: 0.1, opacity: 1})
        timelineview06.add(tweenMax06, 0)
        allTimeLine.add(timelineview06, 0)


        // 分镜七：陪伴
        // 设置子时间轴，在总时间轴70%开始播放
        let timelineview07 = gsap.timeline({delay: 0.70})
        // 指定控制对象和动画操作, 整体10%的时间内显示
        let tweenMax07 = new TweenMax(".oldText", {duration: 0.1, opacity: 1})
        timelineview07.add(tweenMax07, 0)
        allTimeLine.add(timelineview07, 0)

        // 分镜八：时光相机
        // 设置子时间轴，在总时间轴84%开始播放
        let timelineview08 = gsap.timeline({delay: 0.84})
        // 指定控制对象和动画操作, 整体10%的时间内显示
        let tweenMax08 = new TweenMax(".cameraText", {duration: 0.1, opacity: 1})
        timelineview08.add(tweenMax08, 0)
        allTimeLine.add(timelineview08, 0)

        // 内容显示
