<!-- 
  项目：Elyden.com
  创建时间：2024.05.06
  上次更新时间：2023.05.10
  组件名称：AdminHome
  此文件负责的板块：后台首页
    功能：
      1、展示当前网站的信息，注册人数，日活人数，最多观看的视频，营收
  -->
<template>
  <div>
    <!-- 当前网站数据分析 -->
    <el-row :gutter="20">
      <!-- DAU日活用户 -->
      <el-col :span="6">
        <div>
          <el-statistic
            group-separator=","
            :value="loginNum"
            title="DAU日活人数"
          ></el-statistic>
        </div>
        <div id="t1" style="margin-top: 20px; padding: 10px 5px; border: 1px solid rgb(180, 180, 180);border-radius: 5px; width: 400px; height: 300px;"></div>
        <div id="t2" style="margin-top: 20px; padding: 10px 5px; border: 1px solid rgb(180, 180, 180);border-radius: 5px; width: 400px; height: 300px;"></div>
      </el-col>
      <!-- 注册用户数 -->
      <el-col :span="6">
        <div>
          <el-statistic
            group-separator=","
            :value="signUpNum"
            title="注册用户数"
          ></el-statistic>
        </div>
        <div id="t3" style="margin-top: 20px; padding: 10px 5px; border: 1px solid rgb(180, 180, 180);border-radius: 5px; width: 400px; height: 300px;"></div>
        <div id="t4" style="margin-top: 20px; padding: 10px 5px; border: 1px solid rgb(180, 180, 180);border-radius: 5px; width: 400px; height: 300px;"></div>
      </el-col>
      <!-- 最火热视频人数 -->
      <el-col :span="6">
        <div>
          <el-statistic
            group-separator=","
            :value="hotVideoNum"
            title="最火热视频观看人数"
          ></el-statistic>
        </div>
        <div id="t5" style="margin-top: 20px; padding: 10px 5px; border: 1px solid rgb(180, 180, 180);border-radius: 5px; width: 400px; height: 300px;"></div>
        <div id="t6" style="margin-top: 20px; padding: 10px 5px; border: 1px solid rgb(180, 180, 180);border-radius: 5px; width: 400px; height: 300px;"></div>
      </el-col>
      <!-- 营收 -->
      <el-col :span="6">
        <div>
          <el-statistic title="营收"
            group-separator=","
            :precision="2"
            decimal-separator="."
            :value="money"
          >
          </el-statistic>
        </div>
        <div id="t7" style="margin-top: 20px; padding: 10px 5px; border: 1px solid rgb(180, 180, 180);border-radius: 5px; width: 400px; height: 300px;"></div>
        <div id="t8" style="margin-top: 20px; padding: 10px 5px; border: 1px solid rgb(180, 180, 180);border-radius: 5px; width: 400px; height: 300px;"></div>
      </el-col>
    </el-row>
  </div>
</template>

<script>
import { getHotVideoNum, getSignUpNum } from '@/api/admin';
import * as echarts from 'echarts';

  export default{
    name:'AdminHome',
    data(){
      return{
        state: false,

        // 活跃数
        loginNum:0,
        // 数据库用户表注册数
        signUpNum:0,
        age:{
          le10: 0,
          le18: 0,
          le35: 0,
          le49: 0,
          ge50: 0,
        },
        // 最多人观看视频的id和人数
        hotVideoNum:0,
        hotVideoId:0,
        // 营收
        money:0,
      }
    },
    methods:{
      // 获取注册人数
      async getSignUpNum(){
        let data = await getSignUpNum();
        if (data){
          this.signUpNum = data.total
          let ageList = data.ageList
          ageList.forEach(item => {
            if (item <= 10) {
              this.age.le10 += 1
            }
            else if (item <= 18) {
              this.age.le18 += 1
            }
            else if (item <= 35) {
              this.age.le35 += 1
            }
            else if (item <= 49) {
              this.age.le49 += 1
            }
            else{
              this.age.ge50 += 1
            }
          });
          this.initTable()
        }
      },

      // 获取热门视频信息
      async getHotVideoNum(){
        let data = await getHotVideoNum();
        if (data){
          this.hotVideoNum = data.maxNum
          this.hotVideoId = data.vid
        }
      },

      // 初始化图表 
      initTable(){
        // 基于准备好的dom，初始化echarts实例
        let myChart01 = echarts.init(document.getElementById('t1'));
        // 绘制DAU年龄图表
        myChart01.setOption(
        //   {
        //   // 数据颜色
        //   color: ['green'],
        //   // 图表标题
        //   title: {
        //     text: 'ECharts 入门示例'
        //   },
        //   // 图表提示框
        //   tooltip: {
        //     // 触发方式：axis坐标轴（折线图）item元素（柱状图）
        //     trigger: 'item',
        //   },
        //   // 图例的提示组件，提示数据代表什么，可以筛选显示，必须和series的name对应，如果有name，这里可以不写
        //   legend: {
        //     // data: ['销量']
        //   },
        //   // 工具箱组件 这里展示的是下载为图片
        //   toolbox: {
        //     feature: {
        //       saveAsImage: {}
        //     }
        //   },
        //   // x轴
        //   xAxis: {
        //     data: ['衬衫', '羊毛衫', '雪纺衫', '裤子', '高跟鞋', '袜子']
        //   },
        //   // y轴
        //   yAxis: {},
        //   // 网格配置 grid可以控制线形图等图大小，不包含刻度，刻度会挤压显示区域
        //   grid: {
        //     left: '5%',
        //     right: '4%',
        //     bottom: '3%',
        //     // 刻度标签是否向内挤压内容 true 挤压 false 不挤压  默认false
        //     containLabel: true
        //   },
        //   // 系列图表，决定显示的图表类型
        //   series: [
        //     {
        //       name: '销量',
        //       // 柱状图
        //       type: 'bar',
        //       data: [5, 20, 36, 10, 10, 20]
        //     }
        //   ]
        // }

        {
          // 标题
          title:{
            text: '年龄分布'
          },
          // 图表提示框 柱状图形式
          tooltip: {
            trigger: 'item'
          },
          // 图例的提示组件，提示数据代表什么，可以筛选显示和隐藏内容
          legend: {
            top: '10%',
            left: 'center'
          },
          // 图样式内容
          series: [{
            top:'10%',
            name: '年龄分布',
            // 类型为片
            type: 'pie',
            // 内外半径
            radius: ['40%', '70%'],
            avoidLabelOverlap: false,
            // 样式
            itemStyle: {
              borderRadius: 10,
              borderColor: '#fff',
              borderWidth: 2
            },
            // 中心显示item的提示
            label: {
              show: false,
              position: 'center'
            },
            // 中心提示样式
            emphasis: {
              label: {
                show: true,
                fontSize: 20,
                fontWeight: 'bold'
              }
            },
            labelLine: {
              show: false
            },
            // 数据
            data: [
              { value: 100, name: '10岁以下' },
              { value: 100, name: '11~18岁' },
              { value: 100, name: '19~35岁' },
              { value: 100, name: '36~50岁' },
              { value: 100, name: '50岁以上' }
            ]
          }]
        });

        // 绘制DAU省份分布
        let myChart02 = echarts.init(document.getElementById('t2'));
        myChart02.setOption({
          title: {
            text: '省份分布'
          },
          grid: {
            left: '5%',
            right: '4%',
            bottom: '3%',
            // 刻度标签是否向内挤压内容 true 挤压 false 不挤压  默认false
            containLabel: true
          },
          xAxis: {
            type: 'category',
            data: ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun']
          },
          yAxis: {
            type: 'value'
          },
          series: [
            {
              data: [100, 100, 100, 100, 100, 100, 100],
              type: 'bar'
            }
          ]
        });

        // 绘制注册用户数年龄分布
        let myChart03 = echarts.init(document.getElementById('t3'));
        myChart03.setOption({
          // 标题
          title:{
            text: '年龄分布'
          },
          // 图表提示框 柱状图形式
          tooltip: {
            trigger: 'item'
          },
          // 图例的提示组件，提示数据代表什么，可以筛选显示和隐藏内容
          legend: {
            top: '10%',
            left: 'center'
          },
          // 图样式内容
          series: [{
            top:'10%',
            name: '年龄分布',
            // 类型为片
            type: 'pie',
            // 内外半径
            radius: ['40%', '70%'],
            avoidLabelOverlap: false,
            // 样式
            itemStyle: {
              borderRadius: 10,
              borderColor: '#fff',
              borderWidth: 2
            },
            // 中心显示item的提示
            label: {
              show: false,
              position: 'center'
            },
            // 中心提示样式
            emphasis: {
              label: {
                show: true,
                fontSize: 20,
                fontWeight: 'bold'
              }
            },
            labelLine: {
              show: false
            },
            // 数据
            data: [
              { value: this.age.le10, name: '10岁及以下' },
              { value: this.age.le18, name: '11~18岁' },
              { value: this.age.le35, name: '19~35岁' },
              { value: this.age.le49, name: '36~49岁' },
              { value: this.age.ge50, name: '50岁及以上' }
            ]
          }]
        });

        // 绘制注册用户数地域分布
        let myChart04 = echarts.init(document.getElementById('t4'));
        myChart04.setOption({
          title: {
            text: '省份分布'
          },
          grid: {
            left: '5%',
            right: '4%',
            bottom: '3%',
            // 刻度标签是否向内挤压内容 true 挤压 false 不挤压  默认false
            containLabel: true
          },
          xAxis: {
            type: 'category',
            data: ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun']
          },
          yAxis: {
            type: 'value'
          },
          series: [
            {
              data: [100, 100, 100, 100, 100, 100, 100],
              type: 'bar'
            }
          ]
        });

        // 绘制最热视频观看人数的年龄分布
        let myChart05 = echarts.init(document.getElementById('t5'));
        myChart05.setOption({
          tooltip: {
            trigger: 'item'
          },
          legend: {
            top: '5%',
            left: 'center'
          },
          series: [
            {
              name: 'Access From',
              type: 'pie',
              radius: ['40%', '70%'],
              avoidLabelOverlap: false,
              itemStyle: {
                borderRadius: 10,
                borderColor: '#fff',
                borderWidth: 2
              },
              label: {
                show: false,
                position: 'center'
              },
              emphasis: {
                label: {
                  show: true,
                  fontSize: 40,
                  fontWeight: 'bold'
                }
              },
              labelLine: {
                show: false
              },
              data: [
                { value: 1048, name: 'Search Engine' },
                { value: 735, name: 'Direct' },
                { value: 580, name: 'Email' },
                { value: 484, name: 'Union Ads' },
                { value: 300, name: 'Video Ads' }
              ]
            }
          ]
        });
        
        // 绘制最热视频观看人的地域分布
        let myChart06 = echarts.init(document.getElementById('t6'));
        myChart06.setOption({
          title: {
            text: '省份分布'
          },
          grid: {
            left: '5%',
            right: '4%',
            bottom: '3%',
            // 刻度标签是否向内挤压内容 true 挤压 false 不挤压  默认false
            containLabel: true
          },
          xAxis: {
            type: 'category',
            data: ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun']
          },
          yAxis: {
            type: 'value'
          },
          series: [
            {
              data: [100, 100, 100, 100, 100, 100, 100],
              type: 'bar'
            }
          ]
        });

        let myChart07 = echarts.init(document.getElementById('t7'));
        myChart07.setOption({
          tooltip: {
            trigger: 'item'
          },
          legend: {
            top: '5%',
            left: 'center'
          },
          series: [
            {
              name: 'Access From',
              type: 'pie',
              radius: ['40%', '70%'],
              avoidLabelOverlap: false,
              itemStyle: {
                borderRadius: 10,
                borderColor: '#fff',
                borderWidth: 2
              },
              label: {
                show: false,
                position: 'center'
              },
              emphasis: {
                label: {
                  show: true,
                  fontSize: 40,
                  fontWeight: 'bold'
                }
              },
              labelLine: {
                show: false
              },
              data: [
                { value: 1048, name: 'Search Engine' },
                { value: 735, name: 'Direct' },
                { value: 580, name: 'Email' },
                { value: 484, name: 'Union Ads' },
                { value: 300, name: 'Video Ads' }
              ]
            }
          ]
        });

        let myChart08 = echarts.init(document.getElementById('t8'));
        myChart08.setOption({
          title: {
            text: '省份分布'
          },
          grid: {
            left: '5%',
            right: '4%',
            bottom: '3%',
            // 刻度标签是否向内挤压内容 true 挤压 false 不挤压  默认false
            containLabel: true
          },
          xAxis: {
            type: 'category',
            data: ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun']
          },
          yAxis: {
            type: 'value'
          },
          series: [
            {
              data: [100, 100, 100, 100, 100, 100, 100],
              type: 'bar'
            }
          ]
        });
      }
    },
    created(){
      // 获取注册用户数和年龄分布
      // this.getSignUpNum()
      // 获取正在观看视频的最大数量
      this.getHotVideoNum()
    },
    mounted(){
      // 获取注册用户数和年龄分布
      this.getSignUpNum()
    },
  }
</script>

<style scoped>
  .like {
    cursor: pointer;
    font-size: 25px;
    display: inline-block;
  }
</style>