    <!-- 页面整体内容 -->
    <div class="PageContent">
      <!-- 左边用户信息区 -->
      <div class="user_info">
        <!-- 用户头像、名称、等级 -->
        <div class="user_info_top">
          <!-- 登录用户头像 -->
          <div class="user_info_top_left">
            <img class="user_img_tospace" :src="getImgURL(loginUser.picture)" alt="头像" ref="user_icon_nav" @click="gotoSpace(loginUser.uid)">
          </div>
          <!-- 用户名称和等级 -->
          <div class="user_info_top_right">
            <span class="user_name">{{loginUser.uName}}</span><br>
            <span class="user_level">{{ nowLevel(loginUser.experience) }}</span>
          </div>
        </div>
        <!-- 用户关注、粉丝、动态 -->
        <div class="user_info_list">
          <div class="user_follow">
            <div>{{loginUser.follows /10000 >=1 ? parseInt(loginUser.follows / 10000)+"万" : loginUser.follows}}</div>
            <span>关注</span>
          </div>
          <div class="user_fans">
            <div>{{loginUser.fans /10000 >=1 ? parseInt(loginUser.fans / 10000)+"万" : loginUser.fans}}</div>
            <span>粉丝</span>
          </div>
          <div class="user_update">
            <div>100</div>
            <span>动态</span>
          </div>
        </div>
      </div>
      <!-- 中间动态区 -->
      <div class="update_content">
        <!-- 发布感想 -->
        <div class="publish_think">
          <textarea class="think_input_box" name="comment" cols="105" rows="5" placeholder="向大家分享一下当前的想法吧"></textarea>
          <span class="publish_think_nav">#选择话题</span>
        </div>
        <!-- 关注者列表 -->
        <div class="select_creater">
          <div class="select_creater_list">
            <!-- <div class="creater_select_line"></div> -->
            <!-- 全部关注者的动态 -->
            <div class="select_creater_list_item all_update" @click="changeActiveNav" @mouseenter="openHeightLine" @mouseleave="closeHeightLine">
              <svg-icon iconname="icon-dongtai" class="icon-nav"></svg-icon>
              <div class="all_update_item">全部动态</div>
            </div>
            <!-- 单个关注者 -->
            <div class="select_creater_list_item" v-for="(item,index) in followList" :key = followList.id @click="changeActiveNav(item.followedUid)" @mouseenter="openHeightLine" @mouseleave="closeHeightLine">
              <!-- 用户头像 -->
              <img class="user_img_tospace" :src="getImgURL(item.userInfo.picture)" alt="头像" ref="user_icon_nav">
              <!-- 用户名称 -->
              <div class="user_name">{{item.userInfo.uName}}</div>
            </div>
            <!-- <div class="select_creater_list_item">
              <img class="user_img_tospace" src="/logo.png" alt="头像" ref="user_icon_nav" @click="gotospace">
              <div class="user_name">不讲武德</div>
            </div> -->
          </div>
        </div>
        <!-- 关注者内容列表导航 -->
        <div class="update_list_nav">
          <div class="update_select_line"></div>
          <div class="update_list_nav_item active">全部</div>
          <div class="update_list_nav_item">视频</div>
          <div class="update_list_nav_item">订阅</div>
          <div class="update_list_nav_item">文章</div>
        </div>
