        <!-- 直播板块 -->
        <div class="living">
          <!-- 直播顶部导航 -->
          <div class="living_nav">
            <div class="living_nav_l">
              <span class="living_nav_title">正在直播</span>
              <span class="living_count_num">xxx</span>
            </div>
            <div class="living_nav_r">更多关注</div>
          </div>
          <!-- 当前正在直播用户列表 -->
          <div class="living_list">
