              <!-- 用户名称和直播简介 -->
              <div class="living_list_item_r">
                <span class="user_name">不讲武德</span><br>
                <span class="living_introduction">直播教大家使用UE实现卡通渲染</span>
              </div>
            </div>
            <!-- 单个直播用户 -->
            <div class="living_list_item">
              <div class="living_list_item_l">
                <img class="user_img_toliving" src="/logo.png" alt="头像" ref="user_icon_nav" >
                <div class="living_icon">
                  <img src="/img/playing.gif" alt="播放gif" v-if="true">
                  <span>直播中</span>
                </div>
              </div>
              <div class="living_list_item_r">
                <span class="user_name">不讲武德</span><br>
                <span class="living_introduction">直播教大家使用UE实现卡通渲染</span>
