<script>
import { getAllFollowInfoByUid } from '@/api/follow';
import HeaderNav from './HeaderNav.vue';
import UpdateContent from '@/page/UpdateContent.vue';

import * as PIXI from "pixi.js";
import { computeUserLevel, getUserCover } from '@/api/user';
import { getVipIcon } from '@/api/vip';


 export default{
  name:'UpdatePage',
  components: {
    // 顶部导航组件
    HeaderNav,
    // 更新内容板块
    UpdateContent

  },
  computed:{
    // 当前登录的用户信息
    loginUser(){
      return this.$store.state.loginUser
    },
  }, 
  data(){
    return{
      // 用户关注表
      followList:[],
      // 当前查询内容的uidList
      uidlist:'',
      
    }
  },
  methods:{
    // 用户等级计算
    nowLevel(experience){
      return computeUserLevel(experience);
    },

    //前往空间
    gotoSpace(uid){
      this.$router.push({
        name: 'space',
        params:{
          // 访问来源
          fromUser:this.$store.state.loginUser.uid,
          // 访问目标
          toUser:uid,
        }
      })
      // 提交目标uid
      this.$store.dispatch('spaceUserId',uid)
    },

    //视频跳跃
    gotovideo(videoid){
      this.$router.push({
        path:'/video', 
        query:{
          vid:videoid
        }
      })
    },

    // 开启选择用户的高光显示
    openHeightLine(){
      event.currentTarget.childNodes[1].style.color = '#00a1d6'
      event.currentTarget.childNodes[0].style.border = "#00a1d6 1px solid"
      // console.log(event.currentTarget.childNodes[1]);
    },

    // 关闭选择用户的高光显示 
    closeHeightLine(){
      if (event.currentTarget != this.updateNowNav){
        event.currentTarget.childNodes[1].style.color = 'gray'
        event.currentTarget.childNodes[0].style.border = 'rgb(207,207,207) 1px solid'
      }
    },

    // 获取用户的关注列表 （token拦截校验）
    async getUserFollowInfo(){
      console.log(this.loginUser.uid);
      let data = await getAllFollowInfoByUid(this.loginUser.uid)
      if (data) {
        this.followList = data
        // console.log(this.followList);
        if (this.followList) {
          this.uidlist=''
          let temp = ''
          this.followList.forEach((item)=>{
            temp = temp + item.followedUid + ','
          })
          // 设置当前要查询的用户uid字符串
          this.uidlist = temp
        }
      }
    },

    // 切换当前选择活动样式并改变要查询的内容
    changeActiveNav(uid){
      if (!this.updateNowNav) {
        this.updateNowNav = document.getElementsByClassName('all_update')[0]
      }
      // 取消当前样式
      this.updateNowNav.childNodes[1].style.color = 'gray'
      this.updateNowNav.childNodes[0].style.border = 'rgb(207,207,207) 1px solid'
      // 修改当前活动样式
      event.currentTarget.childNodes[1].style.color = '#00a1d6'
      event.currentTarget.childNodes[0].style.border = "#00a1d6 1px solid"
      // 设置当前活动导航
      this.updateNowNav = event.currentTarget

      // 当前点击的是全部
      if (event.currentTarget.className == 'select_creater_list_item all_update') {
        // 获取全部
        // 重新赋值要查询的字符串
        this.uidlist=''
        let temp = ''
        // 遍历用户关注列表，拼接要查询的所有用户uid
        this.followList.forEach((item)=>{
          temp = temp + item.followedUid + ','
        })
        // 设置当前要查询的用户uid字符串
        this.uidlist = temp
      }
      // 点击的是指定用户
      else{
        // 获取单个uid的稿件
        // this.selectContentByUid(uid)
        this.uidlist = uid + ","
      }
    },

    // 获取用户头像url
    getImgURL(address){
      return getUserCover(address);
    },

    // 获取vip图
    getVIPImgURL(address){
      console.log(1);
      return getVipIcon(address);
    },

    //初始化背景动画
    initBacganim(){
      var bacgAnimStage = new PIXI.Application({
        antialias: true,
        transparent: true,
        // resizeTo: window
      });
      // 创建video标签
      const video = document.createElement('video');
      video.src ='/img/动态背景动画.mp4';
      // 配置muted，不然报错play()方法
      video.muted = "meted";
      // 给元素添加画布
      this.$refs.bacgAnim.appendChild(bacgAnimStage.view);
      // 加载视频资源纹理
      let videoTexture = PIXI.Texture.from(video);
      // 创建精灵并添加纹理
      let videoSprite = new PIXI.Sprite(videoTexture);
      // 视频位置偏移
      videoSprite.x=-600;

      // 加载遮罩图片
      const mask = PIXI.Sprite.from('/img/backAnimMask.png');

      mask.anchor.set(0.5);
      // 遮罩位置偏移
      mask.x = 100;
      mask.y = 100;

      // 使用遮罩
      videoSprite.mask = mask;

      // videoSprite.interactive = true;

      //循环播放
      videoTexture.baseTexture.resource.source.loop = true;

      // videoSprite.preload = 'auto';
      // this.autoPlay = videoSprite.autoplay;
      // 偏移   x  y
      // videoSprite.anchor.set(0.3, -0.08);

      // videoSprite.anchor.x = 0.5;
      // videoSprite.anchor.y = 0.5;

      // 精灵添加到舞台渲染（包括mask精灵）
      bacgAnimStage.stage.addChild(videoSprite,mask);

      
      // 设置舞台大小
      bacgAnimStage.renderer.view.style.position = "absolute";
      bacgAnimStage.renderer.view.style.display = "block";
      bacgAnimStage.renderer.autoResize = true;
      bacgAnimStage.renderer.resize(window.innerWidth/2, window.innerHeight);

      // 配置PIXI的alpha过滤器，或者使用CSS的filter设置operity效果一致
      const alphaFilter = new PIXI.filters.AlphaFilter();
			videoSprite.filters = [alphaFilter]
			alphaFilter.alpha = 0.3;

    }
  },
  created(){
    this.getUserFollowInfo()
  },
  mounted(){
    //初始化背景视频动画
    this.initBacganim();
    window.addEventListener('scroll', this.windowScroll) //监听页面滚动
  },
  destroyed() {
    window.removeEventListener("scroll", this.windowScroll);//销毁滚动事件
  },
  //删除滚动监听器，建议使用beforeRouteLeave，因为destroyed()钩子在路由跳转时不会触发
  beforeRouteLeave(to,from,next) {
    window.removeEventListener("scroll", this.windowScroll);//销毁滚动事件
    next()
  }
 }
</script>

