import request from '@/Request'

export {
  saveFan,
  deleteFan,
  countFans,
  getFanInfoInSpace,
  
}

function saveFan(data) {
  return request({
    method: 'post',
    url: '/fan/save',
    data: data
  })
}

function deleteFan(uid, followerUid){
  return request({
    method: 'delete',
    url: '/fan/'+ temp.uid + '/' + temp.followerUid
  })
}

// 统计粉丝数量
function countFans(uid){
  return request({
    method: 'get',
    url: '/fan/count/' + uid,
  })
}

// 获取粉丝表信息
function getFanInfoInSpace(uid, type, page){
  return request({
    method: 'get',
    url: '/fan/table/' + uid + "/" + type + '/' + page
  })
}