import request from '@/Request'

export {
  countAllNoReadMessage,
  getMessageByPage,
  getAllMessageByPage,
  getNowChatRoomMessage,
  saveNewMessage,
  getLoginUserNearlySendMessage,
  getLoginUserNoReadMessage,
}


function countAllNoReadMessage() {
  return request({
    method:'get',
    url:'/message/count/all',
  })
}

function getMessageByPage(messageType, page){
  return request({
    method:'get',
    url:`/message?type=${messageType}&page=${page}`,
  })
}

// 分页获取所有聊天室记录信息
function getAllMessageByPage(page){
  return request({
    method:'post',
    url:`/message/single?page=${page}`,
  })
}

// 分页获取当前选择聊天室的全部信息
function getNowChatRoomMessage(senderId, recipientId, page, isFirstGetMessage){
  return request({
    method:'post',
    url:`/message/single/${senderId}/${recipientId}/${page}/${isFirstGetMessage}`,
  })
}

// 保存新消息(聊天室)
function saveNewMessage(newMessage){
  return request({
    method:'post',
    url:'/message/single/save',
    data:newMessage,
  })
}

// 获取登录用户的最近发送消息
function getLoginUserNearlySendMessage(mid){
  return request({
    method:'post',
    url:`/message/single/nearly?mid=${mid}`,
  })
}

// 获取登录用户未读消息
function getLoginUserNoReadMessage(senderId){
  return request({
    method:'post',
    url:`/message/single/nearly/${senderId}`,
  })
}

