<!-- 
  项目：Elyden.com
  创建时间：2023.11.10
  上次更新时间：2024.5.09
  组件名称：MainContent
  此文件负责的板块：首页活动轮播图和推荐内容板块
    功能：
      1、活动轮播
      2、推荐视频内容
  -->
<template>
  <div class="MainContent">
    <!-- 刷新按钮 -->
    <div class="flashMainContent" @click="refashContent"> 
      <svg class="icon" aria-hidden="true" ref="refashIcon">
        <use xlink:href="#icon-shuaxin1"></use>
      </svg>
      <span>刷新</span>
    </div>
    <div class="Main">
      <!-- 活动页面 -->
      <div class="Main-left">
        <!-- <img class="activities" src="/img/640.jpg" alt="活动"> -->
        <!-- Swiper -->
        <div class="swiper mySwiper">
          <!-- 展示内容列表 -->
          <div class="swiper-wrapper">
            <div class="swiper-slide"><img class="activities" src="/img/d63df7153d252d48583f080f00d982118a1ceee4.jpg" alt="活动"></div>
            <div class="swiper-slide"><img class="activities" src="/img/e401a60fed3cb95a9f8a534e1e5e7594740c9adb.jpg" alt="活动" @click="gotoError5XX"></div>
            <div class="swiper-slide"><img class="activities" src="/img/东瀛大保健.jpg" alt="活动" @click="gotoError4XX"></div>
            <div class="swiper-slide" @click="gotoActivity"><img class="activities" src="/img/cover_0.png" alt="活动"></div>
          </div>
          <!-- 按钮和点 -->
          <div class="swiper-button-next"></div>
          <div class="swiper-button-prev"></div>
          <div class="swiper-pagination"></div>
        </div>
      </div>
      <!-- 推荐页面 -->
      <div class="Main-right">
        <!-- 单个视频元素  使用v-for循环 -->
        <!-- 这里使用video组件跳跃 -->
        <div class="video-item" v-for="(item,index) in videoList.slice(0,6)" :key="item.vid" @click="gotovideo(item.vid)">
          <!-- 视频封面 -->
          <img :src=getImgURL(item.coverAddress) alt="推荐">
          <!-- 视频标题 -->
          <div class="video-title">{{item.title}}</div>
          <!-- 视频作者和发布日期 -->
          <div class="video-foot" @click.stop="gotoSpace(item.uid)">
            <svg-icon iconname="icon-zuozhe" class="icon-nav"></svg-icon>
            <span class="video-creater">{{item.user.uName}}</span>  
            <span class="video-date">{{item.publishTime.slice(0,10)}}</span>
          </div>
        </div>
      </div>
    </div>
  </div>
</template>

<script>
import { set } from 'vue';
import Swiper from 'swiper'; // 注意引入的是Swiper
import 'swiper/css/swiper.min.css' // 注意这里的引入
import { getRecommend, getVideo } from '@/api/video';

  export default{
    name:'MainContent',
    data(){
      return{
        img:['/img/美越战争.jpg',
             '/img/组成原理.jpg',
             '/img/东瀛大保健.jpg',
             '/img/20e93f25ddc781618aa1f4cdd7765c958e30a851.jpg',
             '/img/868c92af4571a142a286ab59f4a3f59e65e5e07c.jpg',
             '/img/943f0c39d5734618751b34fbf00bdd9892956c33.jpg',
             '/img/b183e9f55220efb77dd1820bb7bae727cdaae5dd.jpg',
             '/img/640.jpg',
            ],
        content:[1,2,3,4,5,6],
        // 视频；列表
        videoList:[],
        // 活动轮播
        activity_img:[],
        // 当前展示界面页码
        page: 1,
      }
    },
    methods:{
      //前往作者个人空间
      gotoSpace(uid){
        let routeData = this.$router.resolve({
          name: 'space',
          query:{
            // 访问来源
            fromUser:this.$store.state.loginUser.uid,
            // 访问目标
            toUser:`${uid}`,
          },
          replace:true
        })
        // 新窗口打开
        window.open(routeData.href, '_blank');
      },

      // 视频跳跃
      gotovideo(videoid){
        this.$router.push({
          path:'/video', 
          query:{
            vid:videoid
          }
        })
      },

      // 前往活动界面
      gotoActivity(){
        this.$router.push({
          path: '/activity'
        })
      },

      // 验证5XX界面
      gotoError5XX(){
        this.$router.push({
          path: '/Error5XX'
        })
      },

      // 验证4XX界面
      gotoError4XX(){
        this.$router.push({
          path: '/Error4XX'
        })
      },

      // 刷新箭头动画  计算器实现
      refashContent(){
        let i = 40
        let timer = setInterval(()=>{
          this.$refs.refashIcon.style.transform = `rotate(${i}deg)`
          i+=40
          if(i>360){
            i=20
            clearInterval(timer);
          }
        },60)
        // 获取视频数据，这里只是翻页，没考虑推荐算法
        this.page += 1
        this.getVideo()
      },

      // 开启Swiper  动态展示图
      getSwiper(){
        let swiper = new Swiper(".mySwiper", {
          spaceBetween: 30,
          centeredSlides: true,
          autoplay: {
            delay: 2500,
            disableOnInteraction: false,
          },
          pagination: {
            el: ".swiper-pagination",
            clickable: true,
          },
          navigation: {
            nextEl: ".swiper-button-next",
            prevEl: ".swiper-button-prev",
          },
        });
      },

      // 获取video数据
      async getVideo(){
        let data = await getRecommend(this.page);
        if (data) {
          this.videoList = data
        }
      },

      // 获取活动轮播图
      // getActivity_img(){}

      // 获取视频封面url
      getImgURL(address){
        return getVideo(address)
      }
    },
    mounted(){
      // 挂载完成时必须调用函数
      // 开启Swiper
      this.getSwiper()
    },
    created(){
      // 获取推荐视频
      this.getVideo()
      
      // this.getActivity_img()
    }
  }
</script>

<style scoped>
  img{
    width:100%;
  }
  .icon-nav{
    font-size: 12px;
    vertical-align: -0.3em;
  }
  /* 推荐区整体 */
  .MainContent{
    position: relative;
    width: 80%;
    height: 30%;
    margin: 0 auto;
  }
  /* 推荐区的内容整体 */
  .Main{
    width: 100%;
    height: 100%;
    margin: 0 auto;
    margin-top: 20px;
    display: grid;
    grid-template-rows: 1fr;
    grid-template-columns: 700px 1fr;
    gap: 0px 30px;
  }
  /* 右边推荐视频区 */
  .Main-right{
    display: grid;
    grid-template-rows: 1fr 1fr;
    grid-template-columns: repeat(3,1fr);
    gap: 15px 15px;
  }
  /* 左边动态展示区 */
  .Main-left{
    position: relative;
  }
  /* 悬浮动画 */
  .Main-left:hover, .Main-right:hover{
    cursor: pointer;
  }
  /* 单个视频 */
  .video-item{
    
  }
  /* 推荐的视频的标题 */
  .video-title{
    max-height: 41px;
    overflow: hidden;
  }
  .video-title:hover{
    color: #00a1d6;
  }


  .video-foot{
    font-size: 12px;
    color: gray;
  }

  /* 视频的创作者 */
  .video-creater{
    margin-right: 10px;
  }
  /* 推荐视频的日期 */
  .video-date{
    
  }

  .video-foot:hover{
    color: #00a1d6;
  }

  /* 刷新按钮 */
  .flashMainContent{
    width: 40px;
    height: 80px;
    color: rgb(255, 255, 255);
    border: 3px solid rgb(225, 225, 225);
    background-color: #00bfff;
    border-radius: 20px;
    position: absolute;
    display: flex;
    flex-direction: column;
    justify-content: space-evenly;
    align-items: center;
    left: 100%;
    translate: 10px 0;
    box-shadow: 0px 0px 20px rgb(229, 229, 229);
    user-select:none;
  }
  .flashMainContent:hover{
    cursor: pointer;
  }



  /* 
    动态轮播展示图 
  */
  .swiper {
    overflow: hidden;
    width: 100%;
    height: 100%;
  }

  .swiper-slide {
    text-align: center;
    font-size: 18px;
    background: #ffffff00;
    /* display: flex; */
    /* justify-content: center; */
    /* align-items: center; */
  }

  .swiper-slide img {
    display: block;
    width: 100%;
    object-fit: cover;
  }
  .swiper-button-next,.swiper-button-prev{
    color: white;
    border-radius: 5px;
    padding: 5px;
    background-color: #00a1d6;
    z-index: 1;
    scale: 0.7;
  }
</style>