import request from '@/Request'

// 图片基地址和视频基地址一致
const videoBaseUrl = "http://localhost:9000";


export {
  getVideo,
  getRecommend,
  getVideoByVid,
  getVideoByUidList,
  getUserAllVideoByPage,
  getUserVideoByPage,
  getUserCompilationVideos,
  uploadVideo,
  searchOrder,
  updateVideoPlayed,
  getLikeList,
  accusationVideo,
  countUserVideo,
  getVideoFourInfo,
  updateVideoGood,
  updateVideoShare,
  updateVideoFlower,
  getUserVideoListInfoByVid,
  searchSpaceVideo,
  getVideoOnContributionByPage,
  countSpaceUserContribution,

}

// 获取视频连接地址
function getVideo(address){
  return videoBaseUrl + address;
}

// 获取首页推荐视频分页
function getRecommend(page){
  return request({
    method: 'get',
    url: `/video/getRecommend?page=${page}`
  })
}

// 根据id获取视频信息
function getVideoByVid(vid){
  return request({
    method:'get',
    url:`/video/${vid}`,
  })
}



// 上传视频
function uploadVideo(data){
  return request({
    method:'post',
    url:'/video/upload/',
    data: data,
  })
}

// 获取所有关注对象所有显示内容（分页）
function getVideoByUidList(uidlist, page){
  return request({
    method:'get',
    url:'/video/update',
    params:{
      uidlist:uidlist,
      page: page
    }
  })
}

// 设置筛选条件获取视频列表
function searchOrder(classify){
  return request({
    method: 'post',
    url: "/video/searchOrderBy",
    data: classify
  })
}

// 更新视频播放量
function updateVideoPlayed(vid){
  return request({
    method: 'put',
    url: '/video/' + vid
  })
}

// 请求推荐视频列表(播放器)
function getLikeList(uid, label, likePage){
  return request({
    method: 'get',
    url: `/video/like?uid=${uid}&label=${label}&page=${likePage}`
  })
}

// 举报视频
function accusationVideo(data){
  return request({
    method:'post',
    url:'/video/accusation',
    data: data,
  })
}

// 获取用户的所有视频分页 一页20个
function getUserAllVideoByPage(uid, order, page){
  return request({
    method: 'get',
    url: "/video/all/"+ uid+ "/" + order + "/" + page
  })
}

// 获取用户的所有视频分页 一页10个
function getUserVideoByPage(uid, order, page){
  return request({
    method: 'get',
    url: '/video/' + uid + '/' + order + '/' + page
  })
}

//  获取用户合集视频分页
function getUserCompilationVideos(vidlist, page, orderBy){
  return request({
    method: 'get',
    url: '/video/compilation?vidlist=' + vidlist + '&page='+ page + `&order=${orderBy}`
  })
}

// 获取用户投递的视频总数
function countUserVideo(uid){
  return request({
    method: 'get',
    url: "/video/countVideo/" + uid
  })
}

// 获取用户是否在视频存在四连记录
function getVideoFourInfo(vid){
  return request({
    method:'get',
    url:'/video/info/' + vid,
  })
}

// 点赞视频
function updateVideoGood(data){
  return request({
    method:'put',
    url:'/video/info/good',
    data: data
  })
}

// 分享视频
function updateVideoShare(data){
  return request({
    method:'put',
    url:'/video/info/share',
    data:data,
  })
}

// 献花视频
function updateVideoFlower(data){
  return request({
    method:'put',
    url:'/video/info/flower',
    data:data,
  })
}


// 查询用户在这vid列表所属视频是否有点赞等记录，
function getUserVideoListInfoByVid(temp){
  return request({
    method:'get',
    url:'/video/info?vidList=' + temp,
  })
}

// 模糊查询空间所属者uid的视频内容
function searchSpaceVideo(uid, search, order, page){
  return request({
    method: 'get',
    url:'/video/'+ uid + '/' + search + '/' + order +'/' + page
  })
}

// 分页获取视频投稿内容
function getVideoOnContributionByPage(uid, condition, page){
  return request({
    method: 'get',
    url: '/video/contribute/'+ uid + '/' + condition + '/' + page
  })
}

// 统计用户投稿总数
function countSpaceUserContribution(uid){
  return request({
    method: 'get',
    url: "/video/countVideo/" + uid
  })
}