<!-- 
  项目：Elyden.com
  创建时间：2024.05.26
  上次更新时间：2024.05.26
  组件名称：SmallUserCard
  此文件负责的板块：用户简介卡片
    功能：
      1、展示用户信息
      2、关注和发消息
-->
<template>
  <div>
    <el-popover
      placement="top-start"
      width="400"
      trigger="hover">
      <div>
        <!-- 头部空间背景板 -->
        <div class="smallCardHead" style="height: 100px; background-image: url(./img/Snipaste02.png); background-size: cover; background-position: 0px -20px;"></div>
        <!-- 简介界面主体 -->
        <div class="smallCardMain">
          <!-- 左边头像区 -->
          <div class="smallCardMainLeft">
            <img class="user_img_tospace smallCard" :src="getImgURL(user.picture)" alt="头像" ref="user_icon_nav" @click="gotoSpace(user.uid)">
          </div>
          <!-- 右边信息区 -->
          <div class="smallCardMainRight">
            <!-- 用户信息 -->
            <div class="smallCardUserInfo">
              <!-- 用户名称 -->
              <span class="smallCardUserName">{{user.uName}}</span>
              <!-- 用户等级 -->
              <span class="smallCardLevel">{{ nowLevel(user.experience) }}</span>
              <!-- 用户会员图标 -->
              <img :src="getImgURL(vipInfo.img)" class="user_merbership" style="vertical-align:middle;" alt="会员">
            </div>
            <!-- 用户粉丝等数据 -->
            <div class="smallCardUserData">
              <div class="smallCardUserFollows" style="cursor: pointer;" @click="gotoFanAndFollow('follow', user.uid)">
                <span class="smallCardUserDataNum">{{user.follows}}</span>
                <span>关注</span>
              </div>
              <div class="smallCardUserFans" style="cursor: pointer;" @click="gotoFanAndFollow('fan', user.uid)">
                <span class="smallCardUserDataNum">{{user.fans}}</span>
                <span>粉丝</span>
              </div>
              <div class="smallCardUserGood">
                <span class="smallCardUserDataNum">{{user.flower}}</span>
                <span>小红花</span>
              </div>
            </div>
            <!-- 用户认证信息 -->
            <div class="smallCardUserAuthentication" style="display: flex;">
              <span>✨Elyden个人认证：2024年度优秀创作者</span>
            </div>
            <!-- 用户简介 -->
            <div class="smallCardUserSynopisis">{{ user.synopsis }}</div>
            <!-- 关注和发消息按钮 -->
            <div class="smallCardbutton" style="margin: 0 auto;">
              <button class="smallCardFollowButton" v-if="!isFollowSmallCard" @click="followUser(user.uid)"><span style="margin-right: 5px; scale: 2; display: inline-block;">+</span>关注</button>
              <button class="smallCardFollowedButton" v-if="isFollowSmallCard" @click="cancelFollow(user.uid)">已关注</button>
              <button class="smallCardSendMessage" @click="gotoChatRoom(user.uid)">发消息</button>
            </div>
          </div>
        </div>
      </div>
      <!-- 用户头像  solt是用于标识简介界面显示的触发机关 -->
      <img slot="reference" class="user_img_tospace" :src="getImgURL(user.picture)" alt="头像" ref="user_icon_nav" @mouseenter="getVipInfo(user.uid)" @click="gotoSpace(user.uid)">
    </el-popover>
  </div>
</template>

<script>
import { cancelFollow, followUser2, userIsFollowTarget } from "@/api/follow";
import { computeUserLevel, getUserCover } from "@/api/user";
import { getVipInfoById } from "@/api/vip";

export default{
  name:'SmallUserCard',
  props:{
    // 要展示的用户信息 Integer类型即String类型
    user: {
      type: Object,
      default: ""
    }
  },
  data(){
    return{
      // 是否是关注状态
      isFollowSmallCard: false,
      // vip信息
      vipInfo:{}
    }
  },
  methods:{
    // 前往聊天室
    gotoChatRoom(uid){
      // 没登录提示登录
      if (this.$store.state.loginUser == ''){
        // this.dialogLoginVisible = true
        this.$bus.$emit('showLoginFormss', true)
        return
      }
      if (uid == this.$store.state.loginUser.uid) {
        // 提示不能给自己发送消息
        this.$message({
          message: '警告哦♪，不能给自己发送消息',
          type: 'warning'
        });
        return 
      }
      this.$router.push({
        path: '/message/chatRoom',
        query:{
          recipientId:uid
        }
      })
    },

    /**
     * ----------------------------------------------------------------------------------------------
     * 关注板块开始
    */
    // 关注按钮点击
    // 保存follow关系 (token校验)
    async followUser(followedUid){
      // console.log("想要关注的uid--"+followedUid);
      if (!this.$store.state.loginUser) {
        // 提示登录后操作
        this.$bus.$emit('showLoginFormss', true)
        return
      }
      let data = await followUser2(followedUid);
      if (data == "noLogin") {
        // 提示登录后操作
        this.$bus.$emit('showLoginFormss', true)
      }
      this.isFollowSmallCard = true
      // 关注成功提示
      this.followTrue();
    },
    // 点击取消关注按钮 (token)
    async cancelFollow(followedUid){
      // console.log("取消关注的uid----" + followedUid);
      let data = await cancelFollow(followedUid)
      if (data == 1) {
        this.isFollowSmallCard = false
        this.cancelFollowTrue()
      }
    },
    // 取消关注成功
    cancelFollowTrue() {
      this.$message({
        message: '取消关注成功♪',
        type: 'success'
      });
    },
    // 取消关注失败
    cancelFollowError() {
      this.$message({
        message: '失败！请重试',
        type: 'warning'
      });
    },
    // 不能关注自己提示
    FollowMyselfError(){
      this.$message({
        message: '不能关注自己喔♪',
        type: 'warning'
      });
    },
    // 关注成功提示
    followTrue() {
      this.$message({
        message: '关注成功♪',
        type: 'success'
      });
    },
    // 关注失败提示
    followError() {
      this.$message.error('失败了！请重试');
    },
    /**
     * 关注板块结束
     * ----------------------------------------------------------------------------------------------
    */

    // 获取vip数据
    async getVipInfo(uid){
      let data = await getVipInfoById(uid);
      this.vipInfo = data
      // 判断是否关注关系
      this.userIsFollow2(uid)
    },

    // 根据用户id判断是否关注状态 (token)
    async userIsFollow2(uid){
      let data = await userIsFollowTarget(uid)
      if (data == 1) {
        this.isFollowSmallCard = true
      }else{
        // 不是关注关系
        this.isFollowSmallCard = false
      }
    },

    // 用户等级计算
    nowLevel(experience){
      return computeUserLevel(experience)
    },

    // 前往空间   新窗口打开无法携带params，改query
    gotoSpace(uid){
      let routeData = this.$router.resolve({
        name: 'space',
        query:{
          // 访问来源
          fromUser:this.$store.state.loginUser.uid,
          // 访问目标
          toUser:`${uid}`,
        },
        replace:true
      })
      // console.log("前往空间uid"+uid);
      // 提交目标uid
      // this.$store.dispatch('spaceUserId',uid)
      // 新窗口打开
      window.open(routeData.href, '_blank');
    },

    // 前往粉丝和关注界面
    gotoFanAndFollow(model, uid){
      let routeData = this.$router.resolve({
        path:'/space/fansAndFollow',
        query:{
          model: model,
          // 访问来源
          fromUser:this.$store.state.loginUser.uid,
          // 访问目标
          toUser:`${uid}`,
        },
        replace:true
      })
      window.open(routeData.href, '_blank');
    },

    //前往空间 非新窗口模式
    // gotoSpace(uid){
    //   this.$router.push({
    //     name: 'space',
    //     params:{
    //       // 访问来源
    //       fromUser:this.$store.state.loginUser.uid,
    //       // 访问目标
    //       toUser:`${uid}`,
    //     }
    //   })
    //   // 提交目标uid
    //   this.$store.dispatch('spaceUserId',uid)
    // },

    // 获取用户头像url
    getImgURL(address){
      return getUserCover(address);
    },
  },
  created(){

  },
  mounted(){

  }
}
</script>

<style scoped>
  /* 用户信息栏头像 */
  .user_img_tospace{
    /* float: left; */
    width: 50px;
    height: 50px;
    border: rgb(207,207,207) solid 1px;
    background-color: white;
    object-fit: cover; /*图片完全填充*/
    border-radius: 50%; /*头像框圆形设置*/
    vertical-align: top;
    box-sizing: inherit;
    padding: 1px;
    cursor: pointer;
  }

/* 用户简介界面 */
  .smallCard{
    width: 40px; 
    height: 40px; 
    margin-top: 20px;
  }
  .smallCardMain{
    display: flex;
  }
  /* 简介右边信息区 */
  .smallCardMainRight{
    font-size: 14px; 
    margin: 20px 0 0 15px; 
    display: flex; 
    flex-direction: column; 
    justify-content: space-evenly;
  }
  .smallCardMainRight>div{
    margin: 5px 0;
  }

  /* 用户信息展示 */
  .smallCardUserInfo span{
    margin-right: 10px;
  }
  /* 等级 */
  .smallCardLevel{
    color: red;
  }
  /* 用户名称 */
  .smallCardUserName{
    color: #f69;
  }
  /* 用户关注粉丝等数据 */
  .smallCardUserData{
    display: flex;
    color: rgb(170,170,170);
  }
  .smallCardUserData div{
    margin-right: 15px;
  }
  .smallCardUserData span{
    margin-right: 5px;
  }
  .smallCardUserDataNum{
    color: black;
  }

  .smallCardUserSynopisis,.smallCardUserAuthentication{
    color: rgb(170,170,170);
  }
  /* 底部按钮 */
  .smallCardbutton{
    display: flex;
    justify-content: space-evenly;
    width: 100%;
  }
  /* 关注按钮 */
  .smallCardFollowButton{
    padding: 5px 10px; 
    border-radius: 5px; 
    background-color: #00a1d6; 
    color: white;
  }
  .smallCardFollowButton:hover{
    cursor: pointer;
    background-color: #45b4d9;
  }

  /* 已关注按钮 */
  .smallCardFollowedButton{
    padding: 5px 10px; 
    border-radius: 5px; 
    color: gray;
    background-color: rgb(230, 230, 230);
  }
  .smallCardFollowedButton:hover{
    cursor: pointer;
    background-color: rgb(240, 240, 240);
  }

  /* 发消息按钮 */
  .smallCardSendMessage{
    padding: 5px 10px; 
    border-radius: 5px; 
    color: rgb(150, 150, 150);
    border: 1px solid rgb(150, 150, 150);
  }
  .smallCardSendMessage:hover{
    cursor: pointer;
    color: #00a1d6;
    border: 1px solid #00a1d6;
  }
</style>