<!-- 
  项目：Elyden.com
  创建时间：2024.04.12
  上次更新时间：2023.05.10
  组件名称：chatRoom
  此文件负责的板块：聊天室
    功能：
      1、查看发给我的消息
      2、和指定在线用户实时发短信
      3、查看历史发送记录
  -->
<template>
  <div class="chatRoom">
    <!-- 左边导航 有消息记录的用户 -->
    <div class="aside">
      <span style="font-size: 14px; text-align: center; display: inline-block; padding: 10px 0; width: 100%; color: gray;border-bottom: 1px solid rgb(220, 220, 220);">最近我的消息</span>
      <!-- 历史消息用户列表 -->
      <ol class="send_message_user_list">
        <!-- <li class="send_message_user_item active">
          <img class="user_img" src="/img/食贫道.png" alt="头像">
          <span class="user_name">用户名</span><br>
        </li> -->
        <!-- 要建立联系的新用户 -->
        <li class="send_message_user_item" v-if="$route.query.recipientId && historyMessageUid.indexOf(Number($route.query.recipientId))==-1" :class="{'active':nowChatRoom.senderId == needLinkChatUid}" @click="changeChatRoom(item)">
          <!-- 单个导航栏左边，用户头像 -->
          <div class="new_message_nav_r">
            <img class="user_img" :src="getImgURL(needLinkChatUser.picture)" alt="头像">
          </div>
          <!-- 单个导航栏右边，用户名称和最近一次的聊天消息内容 -->
          <div class="new_message_nav_l">
            <!-- 用户名称 -->
            <span class="user_name">{{needLinkChatUser.uName}}</span><br>
            <!-- 最近的聊天消息 -->
            <span class="smallComment" v-if="messageList[messageList.length-1]">{{ messageList[messageList.length-1].comment.length > 10 ? messageList[messageList.length-1].comment.substr(0, 10)+"..." : messageList[messageList.length-1].comment }}</span>
          </div>
        </li>
        <!-- 已存在历史聊天记录的用户 -->
        <li class="send_message_user_item" v-if="$store.state.loginUser.uid == item.recipientId || isFirstMessage(item)" :class="{'active':nowChatRoom.mid == item.mid}" v-for="(item,index) in messageNavList" @click="changeChatRoom(item)">
          <!-- 单个导航栏左边，用户头像 -->
          <div class="new_message_nav_r">
            <!-- 情况1、消息接收者是登录用户自己，发送者是非自己的其他人，显示消息发送者的头像 -->
            <img class="user_img" v-if="!isFirstMessage(item)" :src="getImgURL(item.senderInfo.picture)" alt="头像">
            <!-- 情况2、登录用户是发送者，登录用户自己与之前未聊天过的用户发了消息，但是对方未回复，消息发送者是自己，接收者是目标用户，头像显示是消息接收者的头像 -->
            <img class="user_img" v-if="isFirstMessage(item)" :src="getImgURL(item.recipientInfo.picture)" alt="头像">
          </div>
          <!-- 单个导航栏右边，用户名称和最近一次的聊天消息内容 -->
          <div class="new_message_nav_l">
            <!-- 用户名称 -->
            <div class="user_name" v-if="!isFirstMessage(item)">{{item.senderInfo.uName}}</div>
            <div class="user_name" v-if="isFirstMessage(item)">{{item.recipientInfo.uName}}</div>
            <!-- 最近的聊天消息 -->
            <span class="smallComment">{{ getNearlyNewMessage(item) }}</span>
            <!-- <span class="smallComment" v-if="nearlyNewMessage">{{ nearlyNewMessage }}</span> -->
            <!-- 未读消息提示 -->
            <el-badge v-if="item.recipientId == $store.state.loginUser.uid" is-dot class="item" style="margin-left: 10px;" v-show="!item.isRead"></el-badge>
            <!-- <span class="smallComment" v-if="nowChatRoom.mid != item.mid">{{ item.comment.length > 10 ? item.comment.substr(0, 10)+"..." : item.comment }}</span> -->
            <!-- <span class="smallComment" v-if="messageList[messageList.length-1]&&nowChatRoom.mid == item.mid">{{ messageList[messageList.length-1].comment.length > 10 ? messageList[messageList.length-1].comment.substr(0, 10)+"..." : messageList[messageList.length-1].comment }}</span> -->
          </div>
        </li>
      </ol>
    </div>
    <!-- 右边内容 -->
    <div class="Main" v-if="state">
      <!-- 消息显示区 -->
      <div class="content" v-if="nowChatRoom.senderInfo" ref="messageList" @scroll="messageListScroll">
        <!-- 顶部当前聊天对象名称 -->
        <div class="senderUserName">
          <span style="text-align: center; background-color: white; font-size: 14px; display: inline-block; padding: 10px 0; width: 100%; color: gray;border-bottom: 1px solid rgb(220, 220, 220);">{{nowChatRoom.senderInfo.uName}}</span>
        </div>
        <!-- <ol class="messageList">
          <li class="messageItem" :class="{'loginUser':item.senderId == $store.state.loginUser.uid}" v-for="(item, index) in messageList">
            <div class="messageHead">
              <div class="messageDate"><span>{{ compilationDate(item.date) }}</span></div>
            </div>
            <div class="messageBody">
              <div class="messageBodyLeft">
                <img class="user_img_messageContent" :src="getImgURL(item.senderInfo.picture)" alt="头像" ref="user_icon_nav">
              </div>
              <div class="messageBodyRight">
                <div class="messageContent"><span>{{ item.comment }}</span></div>
              </div>
            </div>
          </li>
        </ol> -->
        <!-- 消息列表 使用transition-grop动画插入效果 -->
        <transition-group tag="ul" name="list" class="messageList" >
          <li class="messageItem" :class="{'loginUser':item.senderId == $store.state.loginUser.uid}" v-for="(item, index) in messageList" :key="item.mid">
            <!-- 消息发布日期 -->
            <div class="messageHead">
              <div class="messageDate"><span>{{ compilationDate(item.date) }}</span></div>
            </div>
            <!-- 单个消息 -->
            <div class="messageBody">
              <!-- 用户头像 -->
              <div class="messageBodyLeft">
                <img class="user_img_messageContent" :src="getImgURL(item.senderInfo.picture)" alt="头像" ref="user_icon_nav">
              </div>
              <!-- 消息内容 -->
              <div class="messageBodyRight">
                <div class="messageContent"><span>{{ item.comment }}</span></div>
              </div>
            </div>
          </li>
        </transition-group>
      </div>
      <!-- 有新消息提示 点击跳转 -->
      <div v-if="!needListBottom && noticeNewMessage" style="text-align: center; font-size: 14px; color: #00a1d6; cursor: pointer;" @click="$refs.messageList.scrollTop = $refs.messageList.scrollHeight">有新消息，点我跳转</div>
      <!-- 发布言论区域 -->
      <div class="bottom">
        <!-- 文字输入区域 -->
        <textarea name="messageinput" id="" cols="30" rows="10" v-model="newMessage.comment" @keydown.enter="saveMessage"></textarea>
        <!-- 发布按钮 -->
        <button class="sendMessageButton" @click="saveMessage">发送</button>
      </div>
    </div>
    <!-- 没有消息历史记录提示 -->
    <div style="margin: 0 auto; color: gray;" v-if="!state"><span>这里什么都没有呢!</span></div>
  </div>
</template>

<script>
import { getAllMessageByPage, getLoginUserNearlySendMessage, getLoginUserNoReadMessage, getNowChatRoomMessage, saveNewMessage } from '@/api/message';
import { getUserCover, getUserInfoByUid } from '@/api/user';

  export default{
    name:'chatRoom',
    data(){
      return{
        // 是否开始渲染
        state:false,

        // ------------------------------------聊天websocket数据-----------------------------
        // 重连计时器
        socketRestartTimer:'',
        // socket对象
        ws:'',
        // 是否手动关闭socket链接
        isNeedRestart: true,
        // ------------------------------------聊天websocket数据-----------------------------

        // ------------------------------------左边导航栏数据-----------------------------
        // 当前导航栏页面
        navPage:0,
        // 最大页数
        maxNavPage:0,
        // 消息导航列表
        messageNavList:[],
        // 当前需要建立联系的uid 由其它地方跳转携带
        needLinkChatUid:'',
        // 当前需要建立联系的用户信息
        needLinkChatUser :{},
        // 导航展示最新消息
        nearlyNewMessage:{},
        // 有历史聊天记录的用户uid列表 
        historyMessageUid:[],
        // 消息接收者的用户信息
        recipientInfo:{},
        // ------------------------------------左边导航栏数据-----------------------------

        // ------------------------------------右边内容栏数据-----------------------------
        // 当前选择的聊天室信息
        nowChatRoom:{},
        // 当前展示消息列表的页码
        messagePage:0,
        // 是否为第一次获取信息，因为是倒数页码获取，向上滚动到第一页是拿第一页数据，而不是初始化的时候拿最后一页数据，这里是一次请求获取，可以拆为两次请求后可以不使用这个数据，第一次获取总页数，第二次请求获取最后一页数据
        isFirstGetMessage:true,
        // 当前聊天室最大页码
        messageMaxPage:0,
        // 消息列表
        messageList:[],
        // 自己刚刚发送的消息id
        MyNearlySendMessageId:0,

        // 有新短信时是否下拉到最底
        needListBottom:true,
        // 有新消息提示是否显示
        noticeNewMessage:false,

        // 输入的要发送的消息内容
        newMessage:{
          "comment":"",
          "senderId":"",
          "recipientId":"",
          "date":"",
          "type":"4",
        },

        // 请求间隔计算器
        timer: '',
        // ------------------------------------右边内容栏数据-----------------------------
      }
    },
    updated(){
      // 聊天框下拉到最底
      // this.$refs.messageList.scrollTop = this.$refs.messageList.scrollHeight
    },
    methods:{
      // 初始化webSocket
      initWebSocket(senderId){
        // 创建webSocket
        this.ws = new WebSocket(`ws://localhost:9000/message/${this.$store.state.loginUser.uid}/${senderId}`)
        console.log(this.nowChatRoom.senderId);
        // 添加链接成功点击事件
        this.ws.addEventListener("open", ()=>{
          console.log("链接成功");
          // 如果连接状态成功，发送消息给后端
          // if (this.ws.readyState===1) {
          //   this.sendMessage()
          // }
        })
        // 添加关闭事件
        this.ws.addEventListener("close", ()=>{
          console.log("链接关闭");
          if (this.isNeedRestart) {
            // 不明原因关闭后请求重连
            this.restartSocket()
          }
          // this.isNeedRestart = true
        })
        // 接受后端消息事件
        this.ws.addEventListener("message", (e)=>{
          // console.log(e);
          console.log("收到要更新");
          // 提示当前有新信息
          this.noticeNewMessage = true
          // 获取自己未读的消息push加入消息列表
          this.getLoginUserNoReadMessage()
        })
        // 添加出错事件
        this.ws.addEventListener("error", ()=>{
          console.log("出错了");
        })
      },
      // 发送空消息给后台，通知后台让在线的对方刷新数据获取新发送的消息
      sendMessage(){
        this.ws.send("")
      },
      // 手动关闭链接
      closeSocketByHand(){
        // 不需要重连
        this.isNeedRestart = false
        // websorcket存在
        if (this.ws) {
          this.ws.close()
        }
      },
      // 断开链接后请求重连
      restartSocket(){
        console.log("链接失败");
        this.socketRestartTimer = setInterval(() => {
          console.log("重新连接中");
          this.ws = new WebSocket(`ws://localhost:9000/ws/${this.uid}`)
          if (this.ws.readyState === 0){
            // 重连成功。关闭计时器
            clearInterval(this.socketRestartTimer)
            this.socketRestartTimer = null
            console.log("重连成功");
            // 添加链接成功点击事件
            this.ws.addEventListener("open", ()=>{
              console.log("链接成功");
              // 如果连接状态成功，发送消息给后端
              if (this.ws.readyState===1) {
                this.sendMessage()
              }
            })
            // 添加关闭事件
            this.ws.addEventListener("close", ()=>{
              console.log("链接关闭");
              if (this.isNeedRestart) {
                // 不明原因关闭后请求重连
                this.restartSocket()
              }
              // this.isNeedRestart = true
            })
            // 添加消息事件
            this.ws.addEventListener("message", (e)=>{
              console.log("接受消息" + e.data);
            })
            // 添加出错事件
            this.ws.addEventListener("error", ()=>{
              console.log("出错了");
            })
          }
        }, 3000);
      },


      // 其它页面跳转过来的携带要连接的对象id，获取接收者用户信息
      // 左边默认是根据发送者信息显示，但是建立未连接过的通信时首次通信是登录用户，所以获取消息接收者的信息，渲染到左边显示
      async getRecipientInfo(){
        let data = await getUserInfoByUid(`${this.needLinkChatUid}`)
        // 设置连接聊天室信息
        // 注意：这里设置的发送者实际身份是接收者
        this.nowChatRoom.senderInfo = data
        this.nowChatRoom.senderId = this.needLinkChatUid
        this.needLinkChatUser = data
        // 链接聊天室，接收方是需要连接的对象
        this.initWebSocket(this.needLinkChatUid)
        // 获取当前选择的对话链接窗口的用户全部短信信息
        this.getMeAndUserMessage(this.$store.state.loginUser.uid, this.needLinkChatUid)
        // 获取左边导航的最新1条消息
        // this.getNearlyNewMessage(this.needLinkChatUid)
      },

      // 初始化函数
      // 根据登录用户uid获取消息  实现左边导航栏
      async getAllMessageByLoginUid(){
        let data = await getAllMessageByPage(this.navPage+1)
        this.navPage += 1
        this.messageNavList = data.messageNavList
        if (this.messageNavList.length>0) {
          this.maxNavPage = data.navPages
          // 设置当前选择链接的用户, 默认第一个
          // console.log("情况一：没有设置要连接的对象");
          // 获取第一条接收者是登录用户自己信息作为聊天室
          this.nowChatRoom = this.messageNavList.find((item)=>{
            return item.recipientId == this.$store.state.loginUser.uid
          })
          // 记录有信息记录的用户id，且发送者不是登录用户自己，自己是接收者
          this.messageNavList.forEach((item)=>{
            if (this.$store.state.loginUser.uid == item.recipientId) {
              this.historyMessageUid.push(item.senderId)
            }
          })
          console.log(this.historyMessageUid);

          // 从其它地方跳转过来，如果有需要建立连接的用户，并且无链接记录的，新建窗口建立链接
          if(this.needLinkChatUid && this.historyMessageUid.indexOf(Number(this.needLinkChatUid))==-1){
            // console.log(222222222);
            // console.log(this.needLinkChatUid);
            // console.log(this.historyMessageUid.indexOf(this.needLinkChatUid));
            // 获取接收者个人信息用于导航栏展示并建立链接
            this.getRecipientInfo()
            // 退出此函数，初始化和链接逻辑由上面的函数执行
            return
          }

          // 如果有需要建立连接的并且存在链接记录的，打开旧窗口查找历史记录，不新建窗口
          else if(this.needLinkChatUid && this.historyMessageUid.indexOf(Number(this.needLinkChatUid))!=-1){
            // console.log(3333333333);
            // 设置当前聊天室信息
            this.nowChatRoom = this.messageNavList.find((item)=>{
              // 获取发送者（因为左边导航栏以发送者id分组排序的）是需要链接对象的id
              return item.senderId == this.needLinkChatUid
            })
          }
          
          // console.log(this.nowChatRoom);
          // 链接聊天室
          this.initWebSocket(this.nowChatRoom.senderId)
          // 获取当前选择的对话链接窗口的用户全部短信信息
          this.getMeAndUserMessage(this.nowChatRoom.senderId, this.$store.state.loginUser.uid)
          // 获取左边导航的最新1条消息
          // this.getNearlyNewMessage(this.nowChatRoom.senderId)
        }
      },

      // 判断是否是与对方第一次建立联系，自已发送消息，对方未回复过消息的状态
      isFirstMessage(item){
        if (this.$store.state.loginUser.uid == item.senderId && this.historyMessageUid.indexOf(item.recipientId)==-1) {
          return true
        }
        return false
      },

      // 判断获取最新一条消息，用于左边导航栏展示
      getNearlyNewMessage(SenderMessage){
        let loginUserNarlySend = this.messageNavList.filter((item)=>{
          // 消息发送者是登录用户并且接收者是
          if (item.senderId == this.$store.state.loginUser.uid && item.recipientId == SenderMessage.senderId) {
            return item
          }         
          else if(this.isFirstMessage(SenderMessage)){
            return SenderMessage
          }
        })
        console.log(SenderMessage);
        console.log(loginUserNarlySend);
        // console.log(loginUserNarlySend[0].date > SenderMessage.date);
        if (SenderMessage.mid != loginUserNarlySend.mid && SenderMessage.date && loginUserNarlySend[0]) {
          return loginUserNarlySend[0].date > SenderMessage.date ? loginUserNarlySend[0].comment.length > 10 ? loginUserNarlySend[0].comment.substr(0, 10)+"..." : loginUserNarlySend[0].comment 
          :SenderMessage.comment.length > 10 ? SenderMessage.comment.substr(0, 10)+"..." : SenderMessage.comment 
        }
        else if(SenderMessage.mid == loginUserNarlySend.mid){
          return SenderMessage
        }
        
        // axios({
        //   method:'post',
        //   url:`/message/single/nearly/${senderId}/${this.$store.state.loginUser.uid}`,
        //   headers:{token:localStorage.getItem('token')}
        // })
        // .then((res)=>{
        //   console.log(res);
        //   if (res.data.code == 200) {
        //     this.nearlyNewMessage = res.data.data
        //   }
        // })
      },

      // 获取当前聊天室所有信息（分页）短信默认获取的是最后一页内容，向上滑动获取前一页内容，
      // 初始不知道有多少页，先提交1页上去，后端判断返回最大页数和最后一页数据，并将未读的改为已读，前端获取数据后将下拉条道最低
      async getMeAndUserMessage(senderId,recipientId){
        console.log(senderId);
        console.log(recipientId);
        let data = await getNowChatRoomMessage(senderId, recipientId, this.messagePage+1, this.isFirstGetMessage)
        // 修改第一次获取为false；
        this.isFirstGetMessage = false
        this.messageList = data.messageList
        this.messageMaxPage = data.pages
        this.state = true
        this.$nextTick(function(){
          // 聊天框下拉到最底
          if (this.needListBottom && this.messageList>0){
            this.$refs.messageList.scrollTop = this.$refs.messageList.scrollHeight
          }
        })
        // 设置当前页为最后一页
        this.messagePage = this.messageMaxPage
        // 展示条数过少
        if (this.messageList.length < 8) {
          // 多获取一页内容
          await this.addMessageToMessageList()
        }
      },

      // 消息列表滚动事件
      messageListScroll(){
        let scrollTop = event.target.scrollTop
        let clientHeight = event.target.clientHeight
        let scrollHeight = event.target.scrollHeight
        // console.log("上边界距离顶部：" + scrollTop);
        // console.log("窗口高度：" + clientHeight);
        // console.log("可滚动范围最大值：" + scrollHeight);
        
        // 当滚动距离超过窗口大小时不需要移动到底部
        this.needListBottom = (parseInt(scrollHeight) - parseInt(clientHeight))-scrollTop < clientHeight - 100 ? true : false 
        this.noticeNewMessage = this.needListBottom
        console.log(this.needListBottom);

        if (scrollTop < 15){
          console.log("调用添加消息");
          // 如果计时器为空且还没有到达最大数
          if (this.timer == '' && this.messagePage > 1) {
            this.addMessageToMessageList()
          }
          this.$refs.messageList.scrollTop += 1;
        }
      },

      // 滚动到顶部添加新消息内容
      async addMessageToMessageList(){
        if (this.messagePage <= 1) {
          // 获取完，退出
          return
        }
        this.timer = setTimeout(() => {
          this.timer = ''
        }, 500);
        let data = await getNowChatRoomMessage(this.nowChatRoom.senderId, this.nowChatRoom.recipientId, this.messagePage - 1, this.isFirstGetMessage)
        if (data.messageList.length > 0){
          // 修改第一次获取为false；
          this.isFirstGetMessage = false 
          this.messagePage -= 1
          let temp = data.messageList
          temp.reverse()
          await temp.forEach((item)=>{
            this.messageList.unshift(item);
          })
          this.$nextTick(function(){
            // 聊天框下拉到最底
            if (this.needListBottom){
              this.$refs.messageList.scrollTop = this.$refs.messageList.scrollHeight
            }
          })
        }
      },

      // 点击左边导航切换聊天室
      changeChatRoom(chatRoom){
        console.log(chatRoom);
        // 设置当前聊天室
        this.nowChatRoom = chatRoom
        // 重新获取信息
        this.messagePage = 0
        this.isFirstGetMessage = true
        this.messageList = []
        this.isFirstMessage(chatRoom) ? this.getMeAndUserMessage(this.$store.state.loginUser.uid, chatRoom.recipientId) : this.getMeAndUserMessage(this.nowChatRoom.senderId, this.$store.state.loginUser.uid)
        // 重新连接聊天室
        chatRoom.recipientId == this.$store.state.loginUser.uid ? this.initWebSocket(chatRoom.senderId) : this.initWebSocket(chatRoom.recipientId)
      },

      // 发送消息给聊天室对象
      async saveMessage(){
        // 发送内容为空退出
        if (this.newMessage.comment.trim()=='') {
          return 
        }
        this.newMessage.date = Date.now()
        this.newMessage.senderId = this.$store.state.loginUser.uid
        this.newMessage.recipientId = this.needLinkChatUid ? this.needLinkChatUid : this.nowChatRoom.senderId
        console.log(this.newMessage);
        let data = await saveNewMessage(this.newMessage)
        if (data) {
          this.MyNearlySendMessageId = data
          this.newMessage.comment = ''
          // 发送成功,发送webSorket消息提示对方更新
          this.sendMessage()
          // 获取自己刚刚发送的消息信息
          this.getMyNearlySendMessage()
        }
      },

      // 刷新数据，左边导航展示最新的数据
      async refreshMessage(){
        // 重置当前导航页码
        this.navPage = 0
        let data = await getAllMessageByPage(this.navPage + 1)
        this.navPage += 1
        this.messageNavList = data.messageNavList
        if (this.messageNavList.length>0) {
          this.maxNavPage = data.navPages
        }
      },

      // 获取自己刚刚发送的消息信息
      async getMyNearlySendMessage(){
        let data = await getLoginUserNearlySendMessage(this.MyNearlySendMessageId)
        if (data) {
          this.messageList.push(data)
          // 刷新数据，导航展示最新的数据
          this.refreshMessage()
          this.$nextTick(function(){
            // 聊天框下拉到最底
            if (this.needListBottom){
              this.$refs.messageList.scrollTop = this.$refs.messageList.scrollHeight
            }
          })
        }
      },

      // 接收到在线对方发送成功后获取自己未读的消息push进消息列表
      async getLoginUserNoReadMessage(){
        let data = await getLoginUserNoReadMessage(this.nowChatRoom.senderId)
        if (data) {
          let temp = data
          if (temp.length > 0){
            temp.forEach(item => {
              this.messageList.push(item);
            });
            // 刷新数据，导航展示最新的数据
            this.refreshMessage()
            this.$nextTick(function(){
              // 聊天框下拉到最底
              if (this.needListBottom){
                this.$refs.messageList.scrollTop = this.$refs.messageList.scrollHeight
              }
            })
          }
        }
      },

      // 计算消息日期显示样式，这里只判断了今天，需要继续分化，上午，下午，昨天等
      compilationDate(date){
        let now = new Date()
        let messageDate = new Date(date)
        if (now.toLocaleDateString() == messageDate.toLocaleDateString()) {
          return "今天 "+messageDate.toLocaleTimeString()
        }
        return date
      },

      // 获取用户头像
      getImgURL(address){
        return getUserCover(address);
      }
    },
    created(){
      // 需要和传递的uid联系 recipientId
      if(typeof this.$route.query.recipientId== typeof ''){
        this.needLinkChatUid = this.$route.query.recipientId
      }
      // 获取消息数据
      this.getAllMessageByLoginUid()
    },
    mounted(){
      // this.initWebSocket()
    },
    destroyed(){
      this.closeSocketByHand()
    },
    beforeRouteLeave(to,from,next){
      this.closeSocketByHand()
      next()
    }
  }
</script>

