<!-- 
  项目：Elyden.com
  创建时间：2024.05.06
  上次更新时间：2023.05.10
  组件名称：AdminUser
  此文件负责的板块：管理员用户管理
    功能：
      1、删除用户
      2、给用户发消息
  -->
<template>
  <div>
    <!-- filter用于搜索结果筛选 -->
    <el-table
      :data="userList.filter(item => !search || item.uName.toLowerCase().includes(search.toLowerCase()) || item.uid.toLowerCase().includes(search.toLowerCase()))"
      style="width: 100%;">

      <!-- 列过多折叠显示的属性 -->
      <el-table-column type="expand">
        <template slot-scope="props">
          <el-form label-position="left" inline class="demo-table-expand">
            <el-form-item label="UID" ><span>{{ props.row.uid }}</span></el-form-item>
            <el-form-item label="名称" ><span>{{ props.row.uName }}</span></el-form-item>
            <el-form-item label="vip类型" ><span>{{ props.row.vipId }}</span></el-form-item>
            <el-form-item label="粉丝数" ><span>{{ props.row.fans }}</span></el-form-item>
            <el-form-item label="关注者数" ><span>{{ props.row.follows }}</span></el-form-item>
            <el-form-item label="稿件数" ><span>{{ props.row.updates }}</span></el-form-item>
            <el-form-item label="头像地址" ><span>{{ props.row.picture }}</span></el-form-item>
            <el-form-item label="经验" ><span>{{ props.row.experience }}</span></el-form-item>
            <el-form-item label="小红花数" ><span>{{ props.row.flower }}</span></el-form-item>
            <el-form-item label="简介" ><span>{{ props.row.synopsis }}</span></el-form-item>
          </el-form>
        </template>
      </el-table-column>

      <!-- 列属性 -->
      <el-table-column
        label="UID"
        prop="uid">
      </el-table-column>
      <el-table-column
        label="名称"
        prop="uName">
      </el-table-column>
      <el-table-column
        label="粉丝数"
        prop="fans">
      </el-table-column>
      <el-table-column
        label="关注者数"
        prop="follows">
      </el-table-column>
      <!-- <el-table-column
        label="是否注销账号"
        >
        <template slot-scope="scope">
          <i v-if="scope.row.deleted == '1'" class="el-icon-delete"></i>
        </template>
      </el-table-column> -->

      <!-- 分类标签 -->
      <el-table-column
        prop="deleted"
        label="是否已注销"
        width="110"
        :filters="[{ text: '未注销', value: '0' }, { text: '已注销', value: '1' }]"
        :filter-method="filterTag"
        filter-placement="bottom-end">
        <template slot-scope="scope">
          <el-tag
            v-if="scope.row.deleted == '1'"
            :type="scope.row.deleted === '0' ? 'primary' : 'success'"
            disable-transitions><i class="el-icon-delete"></i></el-tag>
        </template>
      </el-table-column>

      <!-- 操作 -->
      <el-table-column
        align="right">

        <!-- 搜索用户以uid或者用户名称 -->
        <template slot="header" slot-scope="scope">
          <el-input
            v-model="search"
            size="mini"
            placeholder="输入关键字搜索"/>
        </template>

        <!-- 按钮 -->
        <template slot-scope="scope">
          <el-button
            size="mini"
            @click="handleEdit(scope.$index, scope.row)">编辑</el-button>

          <!-- 删除用户按钮 -->
          <el-button
            size="mini"
            type="danger"
            :disabled="scope.row.deleted =='1'?true:false"
            @click="handleDelete(scope.$index, scope.row)">删除</el-button>

          <!-- 给用户发消息以管理员身份 -->
          <el-button
            size="mini"
            type="info"
            icon="el-icon-message"
            :disabled="scope.row.deleted =='1'?true:false"
            @click="handleMessage(scope.$index, scope.row)">发消息</el-button>
        </template>
      </el-table-column>
    </el-table>

    <!-- 发送消息弹窗 -->
    <el-dialog
      title="给此用户发送消息"
      top="30vh"
      :visible.sync="dialogMessageVisible"
      width="40%"
      :before-close="handleClose"
      >
      <div>
        <el-input
          type="textarea"
          :autosize="{ minRows: 2, maxRows: 4}"
          placeholder="请输入内容"
          v-model="message.comment">
        </el-input>
      </div>
      <span slot="footer" class="dialog-footer">
        <el-button @click="handleClose">取 消</el-button>
        <el-button type="primary" @click="sendMessage">确 定</el-button>
      </span>
    </el-dialog>
  </div>
</template>

<script>
import { deleteUser, getAllUserByPage, sendMessage } from '@/api/admin';


  export default{
    name:'AdminUser',
    data(){
      return{
        // 是否显示发消息弹窗
        dialogMessageVisible:false,
        // 搜索内容
        search: '',
        // 展示的用户列表
        userList:[],
        // 用户列表当前展示页码
        userPage:0,
        // 用户列表展示的总页码数
        userPages:0,
        
        // 消息对象
        message:{
          "comment":"",
          "recipientId":"",
          "date":"",
          "type":"5"
        },
      }
    },
    methods: {
      // 过滤标签分类
      filterTag(value, row) {
        return row.deleted == value;
      },

      // 发消息界面提示关闭提示
      handleClose(done) {
        this.$confirm('确认关闭？')
          .then(_ => {
            this.message.comment = ''
            this.dialogMessageVisible = false
            done();
          })
          .catch(_ => {});
      },

      // 点击编辑按钮
      handleEdit(index, row) {
        console.log(index, row);
      },

      // 点击删除按钮
      handleDelete(index, row) {
        // console.log(index, row);
        // 删除用户提示
        this.$confirm('确认删除此用户？')
        .then(async _ => {
          let data = await deleteUser(row.uid);
          if (data) {
            this.$message.success("删除成功")
            // 用户列表移除此用户
            this.userList = this.userList.filter((item)=>{return item.uid != row.uid})
          }
          done();
        })
        .catch(_ => {});
      },

      // 点击发消息按钮 类型为5
      handleMessage(index, row){
        // 显示弹窗
        this.dialogMessageVisible = true
        this.message.recipientId = row.uid
      },

      // 将消息提交给后端
      async sendMessage(){
        if (this.message.comment.trim() != '') {
          this.message.date = Date.now()
          let data = await sendMessage(this.message);
          if (data) {
            this.$message.success("发送成功")
            this.dialogMessageVisible = false
          }
        }
      },

      // 获取用户所有列表
      async getAllUser(){
        let data = await getAllUserByPage(this.userPage + 1);
        if (data) {
          this.userPage += 1
          this.userList = data.userList
          this.userPages = data.pages
        }
      },
    },
    created(){
      // 获取用户数据所有列表
      this.getAllUser()
    }
  }
</script>

<style>
  .el-form{
    line-height: 20px;
    margin-left: 5vw;
  }
  .demo-table-expand {
    font-size: 0;
  }
  .demo-table-expand label {
    width: 90px;
    color: #99a9bf;
  }
  .demo-table-expand .el-form-item {
    margin-right: 0;
    margin-bottom: 0;
    width: 50%;
    line-height: 20px;
  }
</style>