<!-- 
  项目：Elyden.com
  创建时间：2024.05.06
  上次更新时间：2023.05.10
  组件名称：AdminExamine
  此文件负责的板块：管理员内容审核
    功能：
      1、审核视频和评论的举报请求
      2、审核新投稿的视频
  -->
<template>
  <div>
    <!-- 顶部审核分类导航 -->
    <el-menu :default-active="activeIndex" class="el-menu-demo" mode="horizontal" @select="handleSelect">
      <el-menu-item index="1">
        视频举报
        <!-- 红点提醒 -->
        <el-badge :value="noExamineNum.videoNum" v-if="noExamineNum.videoNum > 0" :max="99" style="float: right; translate: 0px -10px; scale: 0.8;"></el-badge>
      </el-menu-item>
      <el-menu-item index="2">
        评论举报
        <!-- 红点提醒 -->
        <el-badge :value="noExamineNum.commentNum" v-if="noExamineNum.commentNum > 0" :max="99" style="float: right; translate: 0px -10px; scale: 0.8;"></el-badge>
      </el-menu-item>
      <el-menu-item index="4">
        新视频投稿申请
        <!-- 红点提醒 -->
        <el-badge :value="noExamineNum.newVideoNum" v-if="noExamineNum.newVideoNum > 0" :max="99" style="float: right; translate: 0px -10px; scale: 0.8;"></el-badge>
      </el-menu-item>
    </el-menu>

    <!-- 审核内容表格 搜索过滤逻辑在data filter已经完成 -->
    <el-table
      :data="contentList.filter(item => !search || item.id.toLowerCase().includes(search.toLowerCase()))"
      style="width: 100%">
      <!-- 审核发起者 -->
      <el-table-column
        label="发起者"
        prop="fromUid">
      </el-table-column>
      <!-- 目标内容id -->
      <el-table-column 
        label="对象id"
        prop="targetId">
      </el-table-column>
      <!-- 请求审核原因 -->
      <el-table-column v-if="type != '4'"
        label="原因"
        prop="content">
      </el-table-column>
      <!-- <el-table-column
        label="是否已审阅"
        prop="examined">
      </el-table-column> -->
      <!-- 是否已经审阅 -->
      <el-table-column
        prop="examined"
        label="是否已审阅"
        width="110"
        :filters="[{ text: '未审阅', value: '0' }, { text: '已审阅', value: '1' }]"
        :filter-method="filterTag"
        filter-placement="bottom-end">
        <template slot-scope="scope">
          <el-tag
            v-if="scope.row.examined == '0'"
            :type="scope.row.examined === '0' ? 'primary' : 'success'"
            disable-transitions><i class="el-icon-circle-close"></i>
          </el-tag>
          <el-tag
            v-if="scope.row.examined == '1'"
            :type="scope.row.examined === '1' ? 'primary' : 'success'"
            disable-transitions><i class="el-icon-circle-check"></i>
          </el-tag>
        </template>
      </el-table-column>

      <!-- 操作板块 -->
      <el-table-column
        align="right">
        <!-- 搜索审核请求 -->
        <template slot="header" slot-scope="scope">
          <el-input
            v-model="search"
            size="mini"
            placeholder="输入关键字搜索"/>
        </template>
        
        <!-- 操作按钮 -->
        <template slot-scope="scope">
          <el-button
            size="mini"
            :disabled="scope.row.examined =='1'?true:false"
            @click="handleCheck(scope.$index, scope.row)">前往查看</el-button>
          <el-button
            v-if="type != '4'"
            size="mini"
            type="danger"
            :disabled="scope.row.examined =='1'?true:false"
            @click="handleDeleteContent(scope.$index, scope.row)">确认下架</el-button>
          <el-button
            v-if="type == '4'"
            size="mini"
            type="danger"
            :disabled="scope.row.examined =='1'?true:false"
            @click="handleAdmitContent(scope.$index, scope.row)">确认上架</el-button>
          <el-button
            v-if="type == '4'"
            size="mini"
            type="danger"
            :disabled="scope.row.examined =='1'?true:false"
            @click="handleNoAdmitContent(scope.$index, scope.row)">不通过</el-button>
          <el-button
          size="mini"
          @click="handleDeleteExamine(scope.$index, scope.row)">删除</el-button>
        </template>
      </el-table-column>
    </el-table>
    <!-- 分页导航 -->
    <div class="pageNav">
      <el-pagination
        @size-change="handleSizeChange"
        @current-change="handleCurrentChange"

        :hide-on-single-page="true"
        :current-page="1"
        :page-size="Examin_Page_date.pageSize"
        layout="prev, pager, next, jumper"
        :total="Examin_Page_date.totalSize">
      </el-pagination>
    </div>

    <!-- 评论内容弹窗 -->
    <el-dialog
      title="评论内容"
      top="30vh"
      :visible.sync="dialogCommentVisible"
      width="40%"
      :before-close="handleClose"
      >
      <div style="text-indent: 2em; text-align: left;">
        {{ comment }}
      </div>
      <span slot="footer" class="dialog-footer">
        <el-button type="primary" @click="handleClose">关闭</el-button>
      </span>
    </el-dialog>

    <!-- 视频审核弹窗 -->
    <el-dialog
      title="视频内容"
      top="10vh"
      :visible.sync="dialogVideoVisible"
      width="50%"
      :before-close="handleClose"
      >
      <div>
        <!-- 审核不通过原因填写栏 -->
        <div v-if="showNoAdmitVideoButton" style="margin: 10px 0; font-size: 20px; font-weight: bold;">请输入审核不通过原因：<input style=" width: 70%; padding: 3px 6px; border-radius: 5px;" v-model="noAdmitVideoReason.comment" type="text"></div>
        <!-- 视频栏 -->
        <video id="videoplayer" muted="muted" controls autoplay="autoplay" :src=getVideoURL(video.address) style="width: 100%;"></video>
      </div>
      <span slot="footer" class="dialog-footer">
        <!-- 关闭查看视频按钮 -->
        <el-button v-if="!showNoAdmitVideoButton" type="primary" @click="handleClose">关闭</el-button>
        <!-- 取消不通过按钮 -->
        <el-button v-if="showNoAdmitVideoButton" type="primary" @click="handleClose">取消不通过</el-button>
        <!-- 确认不通过按钮 -->
        <el-button v-if="showNoAdmitVideoButton" type="primary" @click="sendNoAdmitReasonToFromId">确认不通过</el-button>
      </span>
    </el-dialog>

  </div>
</template>

<script>
import { admitVideoContent, deleteAddContent, deleteContent, deleteExamineById, deleteVideo, getExamineByPage, getNoExamineNum, sendNoAdmitReasonToFromId } from '@/api/admin';
import { getAddCommentById, getCommentByCId } from '@/api/comment';
import { getVideo, getVideoByVid } from '@/api/video';

  export default{
    name:'AdminExamine',
    data(){
      return{
        // 默认展示的活动导航   视频举报审核
        activeIndex: '1',

        // 是否显示评论内容展示弹窗
        dialogCommentVisible:false,
        // 展示的评论信息
        comment:'',

        // 是否显示视频展示弹窗
        dialogVideoVisible:false,
        // 展示的视频信息
        video:'',

        // 是否显示审核不通过原因按钮和原因输入框
        showNoAdmitVideoButton:false,
        // 当前审核内容id
        examineId:0,
        // 审核不通过原因
        noAdmitVideoReason:{
          "recipientId":"",
          "date":"",
          "type":"5",
          "comment":"",
        },

        // 搜索内容
        search: '',

        // 当前查询的类型，默认 视频 1 类型   2父评论 3子评论 4新投稿
        type : 1,
        // 表格展示列表
        contentList:[],
        // 展示当前页数
        page:0,
        // 总可以展示页数
        pages:0,

        // 各个类型的没有审核的数量
        noExamineNum:{
          videoNum:0,
          commentNum:0,
          newVideoNum:0
        },

        // 当前分页数据
        Examin_Page_date:[]
      }
    },
    methods: {
      // 请求审核的新视频url
      getVideoURL(address){
        return getVideo(address)
      },

      // 分类标签判断，分类显示逻辑
      filterTag(value, row) {
        return row.examined == value;
      },

      // 弹窗界面提示关闭提示
      handleClose(done) {
        this.$confirm('确认关闭？')
          .then(_ => {
            // 清除审核的评论内容
            this.comment = ''
            // 隐藏评论审核界面
            this.dialogCommentVisible = false
            // 隐藏视频审核界面 
            this.dialogVideoVisible = false
            // 暂停播放视频
            const video = document.getElementById('videoplayer')
            if(!video.paused){
              video.pause()
            }
            this.showNoAdmitVideoButton = false
            this.noAdmitVideoReason.comment = ''
            done();
          })
          .catch(_ => {});
      },

      // 点击顶部导航切换当前选择内容
      handleSelect(key, keyPath) {
        console.log(key, keyPath);
        // 切换审核类型
        this.type = key
        // 重新获取数据
        this.page = 0
        this.getExamine()
      },

      // 查看审核内容
      async handleCheck(index, row) {
        // console.log(index, row);
        if (this.type == '1') {
          // 视频跳跃
          this.$router.push({
            path:'/video', 
            query:{
              vid:row.targetId
            }
          })
        }
        else if (this.type == '2' && row.type=='2') {
          // 根据id查看父评论内容
          let data = await getCommentByCId(row.targetId);
          if (data){
            this.dialogCommentVisible = true
            this.comment = data.comment
          }
        }
        else if (this.type == '2' && row.type=='3') {
          // 根据id查看子评论内容
          let data = await getAddCommentById(row.targetId)
          if (data) {
            this.dialogCommentVisible = true
            this.comment = data.comment
          }
        }
        else if (this.type == '4') {
          // 根据id查看视频内容
          let data = await getVideoByVid(row.targetId);
          if (data) {
            this.dialogVideoVisible = true
            this.video = data
          }
        }
      },

      // 提示确认上架新视频
      handleAdmitContent(index, row){
        if(this.type=='4'){
          this.$confirm('确认上架此视频？')
          .then(async  _ => {
            let data = await admitVideoContent(row.id, row.targetId);
            if (data) {
              this.$message.success("上架成功")
              row.examined = '1'
            }
            done();
          })
          .catch(_ => {});
        }
      },

      // 不通过按钮视频
      handleNoAdmitContent(index, row){
        if(this.type=='4'){
          this.$confirm('确认此视频审核不通过？')
          .then(_ => {
            // 显示弹窗，提示审核员输入审核不通过原因
            // 如果是没有查看视频就直接不通过提示请查看后在不通过
            console.log(this.video);
            if (!this.video||this.video.vid != row.targetId) {
              this.$message.warning("您还未查看过视频，请先查看视频后再不通过")
              return
            }
            this.showNoAdmitVideoButton = true
            this.dialogVideoVisible = true
            this.noAdmitVideoReason.recipientId = row.fromUid
            this.examineId = row.id
            done();
          })
          .catch(_ => {});
        }
      },

      // 发送不通过审核原因给发起请求者 
      async sendNoAdmitReasonToFromId(){
        this.noAdmitVideoReason.date = Date.now()
        console.log(this.noAdmitVideoReason);
        console.log(this.examineId);
        let data = await sendNoAdmitReasonToFromId(this.examineId, this.video.title, this.noAdmitVideoReason)
        if (data) {
          this.$message.success("处理成功")
          // 关闭显示界面
          this.showNoAdmitVideoButton = false
          this.noAdmitVideoReason.comment = ''
        }
      },

      // 点击下架举报内容按钮
      handleDeleteContent(index, row) {
        // console.log(index, row);
        if(this.type=='1'){
          this.$confirm('确认下架此视频？')
          .then(async _ => {
            let data = await deleteVideo(row.id, row.targetId);
            if (data) {
              this.$message.success("下架成功")
              row.examined = '1'
            }
            done();
          })
          .catch(_ => {});
        }
        else if(this.type=='2'&&row.type=='2'){
          // 下架父评论
          this.$confirm('确认下架此评论？')
          .then(async _ => {
            let data = await deleteContent(row.id, row.targetId);
            if (data) {
              this.$message.success("下架成功")
              row.examined = '1'
            }
            done();
          })
          .catch(_ => {});
        }
        else if(this.type=='2'&&row.type=='3'){
          // 下架子评论
          this.$confirm('确认下架此评论？')
          .then(async _ => {
            let data = await deleteAddContent(row.id, row.targetId);
            if (data){
              this.$message.success("下架成功")
              row.examined = '1'
            }
            done();
          })
          .catch(_ => {});
        }
      },

      // 点击删除审核按钮
      handleDeleteExamine(index, row) {
        // console.log(index, row);
        this.$confirm('确认删除此审核不再查看？')
        .then(async _ => {
          let data = await deleteExamineById(row.id);
          if (data){
            this.$message.success("删除成功")
            // 移除此对象
            this.contentList = this.contentList.filter((item)=>{return item.id != row.id})
          }
          done();
        })
        .catch(_ => {});
      },

      // 分页每页条数改变时触发
      handleSizeChange(val) {
        console.log(`每页 ${val} 条`);
      },
      // 分页当前页面改变时触发
      handleCurrentChange(page) {
        // console.log(`当前页: ${val}`);
        this.page = page - 1;
        this.getExamine();
      },

      // ---------------------------------------初始化逻辑-----------------------------------
      // 获取未审核数量
      async getNoExamineNum(){
        let data = await getNoExamineNum();
        if (data){
          this.noExamineNum = data
        }
      },
      // 获取举报内容默认是视频类型的举报
      async getExamine(){
        let data = await getExamineByPage(this.type, this.page + 1);
        if (data){
          this.page += 1
          this.contentList = data.contentList
          this.pages = data.pages
          this.Examin_Page_date = data
        }
      },
      // ---------------------------------------初始化逻辑-----------------------------------
    },
    created(){
      // 获取未审核数量
      this.getNoExamineNum()

      // 进入审核界面默认获取举报内容，视频投稿审核点击获取
      this.getExamine()
    }
  }
</script>

<style>
.el-icon-circle-close,.el-icon-circle-check{
  scale: 2;
}
/* 
    分页导航栏
*/
.pageNav{
  margin: 0 auto;
  text-align: center;
}
</style>