//引入Vue核心库
// import router from '@/router'
import Vue from 'vue'
//引入Vuex
import Vuex from 'vuex'
//应用Vuex插件
Vue.use(Vuex)

import { getLocal } from '@/utils/StorageUtils.js'

//准备actions对象  响应组件中用户的动作
const actions = {
  //响应点击助手切换的动作
  chanceshow(context,value){
    context.commit('CHANCESHOW',value)
  },
  // 助手设置信息
  setHelper(context,helperSet){
    context.commit('SETHELPER',helperSet)
  },

  // // 提交数据
  // commitvideoList(context,videoList){
  //   context.commit('COMMITVIDEOLIST',videoList)
  // },
  
  // 登录的用户信息
  loginUser(context,user){
    context.commit('LOGINUSER',user)
  },
  // 登录状态
  loginState(content,loginState){
    content.commit('LOGINSTATE',loginState)
  },
  // 个人空间的展示模式
  spaceViewModel(context,model){
    context.commit('SPACEVIEWMODEL',model)
  },
  // 是否处于预览模式
  isPreview(content, viewstate){
    content.commit('ISPREVIEW', viewstate)
  },
  // 登记空间用户uid
  spaceUserId(context, uid){
    context.commit('SPACEUSERID',uid)
  },
  // 登记空间用户信息
  spaceInfo(context,Info){
    context.commit('SPACEINFO',Info)
  },
  // 搜索内容
  searchContent(content, searchContent){
    content.commit('SEARCHCONTENT', searchContent)
  },
  // 空间顶部导航条位置
  barPosition(context,position){
    context.commit('BARPOSITION',position)
  },
  // 点击的合集标题
  changeCompilationTitle(context,title){
    context.commit('CHANGECOMPILATIONTITLE',title)
  },
  // 当前展示的合集的id
  changeCompilationId(context, id){
    context.commit('CHANGECOMPILATIONID', id)
  },
}
//准备mutations对象  修改state中的数据
const mutations = {
  //执行切换
  CHANCESHOW(state,value){
    state.showHelper = value
  },
  // 助手设置
  SETHELPER(state,helperSet){
    state.helperSet = helperSet
  },
  // COMMITVIDEOLIST(state,videoList){
  //   state.videoList = videoList
  // },
  // 处于登录状态的用户信息
  LOGINUSER(state,user){
    state.loginUser = user
    sessionStorage.setItem("loginUser",JSON.stringify(user))
  },
  // 用户登录状态
  LOGINSTATE(state, loginState){
    state.login = loginState
    sessionStorage.setItem("login",loginState)
  },
  // 个人空间的展示模式
  SPACEVIEWMODEL(state,model){
    state.spaceViewModel = model
    sessionStorage.setItem("spaceViewModel",JSON.stringify(model))
  },
  // 是否处于预览模式
  ISPREVIEW(state, viewstate){
    state.isPreview = viewstate
    sessionStorage.setItem("isPreview", JSON.stringify(viewstate))
  },
  // 空间所属用户的uid
  SPACEUSERID(state,uid){
    state.spaceUserId = uid
    sessionStorage.setItem("spaceUserId",JSON.stringify(uid))
  },
  // 登记空间用户设置信息
  SPACEINFO(state, Info){
    state.spaceInfo = Info
    sessionStorage.setItem("spaceInfo",JSON.stringify(Info))
  },
  // 搜索内容
  SEARCHCONTENT(state, searchContent){
    state.searchContent = searchContent
  },
  // 空间顶部导航条位置
  BARPOSITION(state, position){
    state.position = position
    sessionStorage.setItem("barPosition",position)
  },
  // 点击合集的标题
  CHANGECOMPILATIONTITLE(state, title){
    state.compilation_title = title
    sessionStorage.setItem("compilationTitle",title)
  },
  // 当前合集的id
  CHANGECOMPILATIONID(state, id){
    state.compilation_id = id
    sessionStorage.setItem("compilation_id",id)
  },
}
//准备state对象  保存具体的数据
const state = {
  // 助手展示方式
  showHelper: false,
  // 助手设置信息
  helperSet:{
    helperSkin:'工作服',
    animSpeed:1,
  },

  token: getLocal('token') || "",

  // 登录状态用户信息
  loginUser:JSON.parse(sessionStorage.getItem("loginUser"))||'',
  // 是否处于登录状态
  login:sessionStorage.getItem("login")||false,
  // 空间展示状态
  spaceViewModel:JSON.parse(sessionStorage.getItem("spaceViewModel"))||'',
  // 是否处于预览状态
  isPreview: JSON.parse(sessionStorage.getItem("isPreview")) || false,
  // 空间展示的uid
  spaceUserId: JSON.parse(sessionStorage.getItem("spaceUserId")) || '',
  // 空间信息 显示和隐藏内容
  spaceInfo: JSON.parse(sessionStorage.getItem("spaceInfo")) || {},
  // 搜索内容
  searchContent: '',
  // 导航条位置
  position: sessionStorage.getItem("barPosition") ||'',
  // 合集标题
  compilation_title: sessionStorage.getItem("compilationTitle") || '',
  // 当前详情页合集id
  compilation_id: sessionStorage.getItem("compilation_id") || 0,
}

