import request from '@/Request'

export {
  saveInComment,
  getVideoIncomment,


  
}

// 保存弹幕
function saveInComment(data) {
  return request({
    method:'post',
    url:"/incomment/save",
    data: data,
  })
}

// 获取视频的弹幕信息
function getVideoIncomment(vid){
  return request({
    method: 'get',
    url: "/incomment/"+ vid
  })
}
