import request from '@/Request'

const baseUrl = "http://localhost:9000";

export {
  getUserCover,
  refashCode,
  login, 
  signUpUser,
  getUserInfo, 
  getUserInfoByUid,
  getHelperSet,
  updateUserFanOrFollow,
  checkLogin,
  computeUserLevel,
}

// 获取用户头像uil
function getUserCover(address) {
  return baseUrl + address;
}

function refashCode(){
  return request.get('/user/createCode?time=' + new Date().getTime(),{
    responseType: 'arraybuffer',
  })
  // return request({
  //   url: '/user/createCode?time=' + new Date().getTime(),
  //   method: 'get',
  // })
}

function login(data, LineCode){
  return request({
    url: '/user/login',
    method: 'post',
    headers: { 'code': LineCode , 'KEYCODE': localStorage.getItem("KEYCODE")},
    data: data
  })
}

function signUpUser(userForm){
  return request({
    url: '/user/signUpUser',
    method: 'post',
    data: userForm
  })
}

function getUserInfo(){
  return request({
    url: '/user/getUserInfo',
    method: 'get'
  })
}

function getUserInfoByUid(uid){
  return request({
    url: "/user/"+ uid,
    method: 'get'
  })
}

function getHelperSet(){
  return request({
    url: '/helper',
    method: 'get'
  })
}

// 修改用户的关注数或粉丝数
function updateUserFanOrFollow(uid, type, method){
  return request({
    method: 'put',
    url: '/user/'+ uid + '/' + type + '/'+ method 
  })
}

// 是否处于登录状态(登录过期)
function checkLogin(){
  return request({
    method:'get',
    url:'/user/checkLogin',
  })
}

// 计算用户等级
function computeUserLevel(experience){
  let i = 10
  if(experience/i >= 0 && experience/i<10){
    return 'Lv1'
  }
  else if(experience/(i*10) > 0 && experience/(i*10)<10){
    return 'Lv2'
  }
  else if(experience/(i*100) > 0 && experience/(i*100)<10){
    return 'Lv3'
  }
  else if(experience/(i*1000) > 0 && experience/(i*1000)<10){
    return 'Lv4'
  }
  else if(experience/(i*10000) > 0 && experience/(i*10000)<10){ 
    return 'Lv5'
  }
  else if(experience/(i*100000) > 0 && experience/(i*100000)<10){
    return 'Lv6'
  }
  else if(parseInt(experience/(i*1000000) > 0)){
    return 'Lv7'
  }
}