<template>
  <div class="space_update_content" style="display: flex;">
    <!-- 左边更新内容列表组件 -->
    <UpdateContent :initUid="$store.state.spaceUserId+','" v-on="$listeners"></UpdateContent>

    <!-- 右边用户信息栏 -->
    <div class="user_info">
      <div class="user_info_content">
        <div class="user_info_nav">个人资料</div>
        <div style="margin-top: 15px; display: flex; justify-content: space-evenly;">
          <div class="uid">UID: {{userInfo.uid}}</div>
          <div class="ubirthday" v-if="spaceInfo.isOpenBirthday == 1 || showModel =='me'">生日: {{userInfo.birthday ?  userInfo.birthday.slice(0,10):''}}</div>
        </div>
      </div>
    </div>
  </div>
</template>

<script>
import { getUserInfoByUid } from '@/api/user';
import UpdateContent from './UpdateContent.vue'

  export default{
    name:'SpaceUpdate',
    components: {
      // 评论组件
      // VideoComment,
      // 更新内容组件
      UpdateContent
    },    
    data(){
      return{
        
        // 空间所属用户信息
        userInfo:{},

        // 空间信息
        spaceInfo:this.$store.state.spaceInfo,
      }
    },
    computed:{
      spaceUserId(){
        return this.$store.state.spaceUserId
      },
      // 空间展示模式
      showModel() {
        return this.$store.state.spaceViewModel
      },
    },
    methods:{
      //发送请求，根据uid获取目标空间主人的信息
      async getUserInfoByUid(){
        let data = await getUserInfoByUid(this.$store.state.spaceUserId)
        // 设置空间用户信息为获取到的信息
        this.userInfo = data
      },
    },
    created(){
      this.getUserInfoByUid()

    },
    mounted(){
    },
    destroyed() {
    },
    beforeRouteLeave(to,from,next) {
      next()
    }
  }
</script>

<style scoped>
  /* 活动样式 */
  .active{
    color: #00a1d6;
  }

  /* 原生icon图标大小 */
  svg{
    width: 1em;
    height: 1em;
    vertical-align: -0.15em;
    fill: currentColor;
    overflow: hidden;
  }
  /* 用户头像 */
  .user_img_tospace{
    /* float: left; */
    width: 60px;
    height: 60px;
    border: rgb(207,207,207) solid 1px;
    background-color: white;
    object-fit: cover; /*图片完全填充*/
    border-radius: 50%; /*头像框圆形设置*/
    vertical-align: top;
    margin-left: 20px;
    cursor: pointer;
  }
  
  /* 更新内容展示区 */
  .update_content_list{
    width: 70%;
    margin-top: 10px;
  }

  /* 用户信息栏 */
  .user_info{
    margin-left: 15px;
    width: 30%;
    height: 100px;
    margin-top: 10px;
    background-color: white;
    border-radius: 5px;
    overflow: hidden;
    box-shadow: 0px 0px 20px rgb(229, 229, 229);
  }
  .user_info_content{
    margin: 15px;
  }
  .user_info_nav{
    height: 40px;
    border-bottom: 1px solid rgb(216, 216, 216);
  }
  /* 生日和uid */
  .ubirthday,.uid{
    font-size: 12px;
    color: gray;
  }


  /* 
  
  登录界面
  
  */
  .form1{
    padding: 20px;
    border: 1px solid black;
    border-radius: 20px;
    background-color: #d3f4ff;
    text-align: center;
  }
  .signUp{
    color: gray;
    font-size: 12px;
  }
  .signUp:hover{
    color: #00a1d6;
    cursor: pointer;
  }
  .accountInput{
    margin-bottom: 20px;
  }
  .accountInput,.passwordInput{
    height: 30px;
    border-radius: 10px;
  }
</style>