import request from '@/Request'

export {
  getCompilationInfo,
  saveNewCompilation,
  getCompilationVidList,
  getAllCompilationVidList,
  getExistVidByCompilationId,
  addVideoToCompilation,
  deleteCompilation,
  deleteCompilationOneVideo,
  editCompilation,
  

}

function getCompilationInfo(cid) {
  return request({
    method: 'get',
    url: "/compilation/info/" + cid
  })
}

// 保存新合集
function saveNewCompilation(vidList, newCompilation){
  return request({
    method: 'post',
    url: '/compilation/save/' + vidList, newCompilation
  })
}

// 根据uid获取合集列表vid内容
function getCompilationVidList(uid){
  return request({
    method: 'get',
    url: "/compilation/" + uid
  })
}

// 根据合集id获取合集内部视频id集合
function getExistVidByCompilationId(cid){
  return request({
    method: 'get',
    url: '/compilation/exist/' + cid
  })
}

// 将视频添加入视频合集
function addVideoToCompilation(vidList, data){
  return request({
    method: 'put',
    url: '/compilation/'+ vidList,
    data: data
  })
}

// 删除合集
function deleteCompilation(cid){
  return request({
    method: 'delete',
    url: '/compilation/' + cid
  })
}

// 删除合集内的单个视频
function deleteCompilationOneVideo(cid, vid){
  return request({
    method: 'delete',
    url: `/compilation/${cid}/${vid}`
  })
}

// 获取用户所有的合集的分页内容
function getAllCompilationVidList(uid){
  return request({
    method: 'get',
    url: "/compilation/home/" + uid
  })
}


// 修改合集信息
function editCompilation(data){
  return request({
    method: 'put',
    url:'/compilation',
    data:data,
  })
}





