import request from '@/Request'

export {
  getCollectionById,
  getLoginUserAllCollection,
  getCollectionVidListById,
  getUserAllCollectionByPage,
  saveNewVideoToCollection,
  cancelCollection,
  updateCollectionName,
  deleteCollection,
  saveNewCollection,
  

}

//  根据收藏id获取收藏夹信息
function getCollectionById(cid) {
  return request({
    method:'get',
    url:"/collection/all/" + cid
  })
}

// 获取登录用户的所有收藏夹
function getLoginUserAllCollection(vid, page){
  return request({
    method:'post',
    url:`/collection/all/${vid}/${page}`,
  })
}

// 根据用户id分页获取全部收藏
function getUserAllCollectionByPage(uid, condition, size){
  return request({
    method: 'get',
    url: "/collection/all/" + uid + '/' + condition + '/' + size
  })
}

// 添加视频进入收藏夹
function saveNewVideoToCollection(data){
  return request({
    method:'put',
    url:'/collectionList',
    data:data,
  })
}

// 根据收藏id获取收藏夹视频id
function getCollectionVidListById(cid, page, collectCondition){
  return request({
    method: 'get',
    url: "/collectionList/all/" + cid + '/' + page + '/' + collectCondition
  })
}

// 取消收藏夹的内容
function cancelCollection(id, vidlist){
  return request({
    method:'put',
    url:`/collection/${id}/${vidlist}`,
  })
}

// 编辑收藏夹名字
function updateCollectionName(collection){
  return request({
    method:'put',
    url:'/collection',
    data:collection,
  })
}

// 删除收藏夹
function deleteCollection(cid){
  return request({
    method:'delete',
    url:'/collection?id='+ cid,
  })
}

// 新建收藏夹
function saveNewCollection(collect){
  return request({
    method:'post',
    url:'/collection/save',
    data:collect,
  })
}