  组件名称：MainPage
  此文件负责的板块：首各个页组件的拼接
    功能：
      1、顶部导航背景动画
  -->
<template>
  <!-- 首页 -->
  <div>
    <!-- 顶部导航栏 -->
    <HeaderNav></HeaderNav>
    <!-- 顶部背景动画 -->
    <div id = "header" ref="headerAnim"></div>
    <!-- 分类列表 -->
    <MenuList></MenuList>
    <!-- 活动和推荐 -->
    <MainContent></MainContent>
    <!-- 分类列表推荐内容 -->
    <SortList></SortList>
    <!-- 页面脚部 -->
    <MyFooter></MyFooter>
  </div>
</template>

<script>
import * as PIXI from "pixi.js";
import MenuList from "./MenuList.vue";
import MainContent from "./MainContent.vue";
import SortList from "./SortList.vue";
import MyFooter from './MyFooter.vue';
import HeaderNav from "./HeaderNav.vue";
global.PIXI = PIXI;
require("pixi-spine");

export default{
  name: 'MainPage',
  components: { MenuList, MainContent, SortList, MyFooter, HeaderNav},
  mounted() {
    // 初始化顶部导航栏Spine动画，包含鼠标跟踪事件和窗体变换事件
    this.initHanderBacganim();
  },
  methods: {
    // 初始化顶部导航栏Spine动画，包含鼠标跟踪事件和窗体变换事件
    initHanderBacganim() {
      var banner = new PIXI.Application({
        antialias: true,
        transparent: true,
        height: 180
      });
      //添加画布
      this.$refs.headerAnim.appendChild(banner.view);
      banner.loader
            // .add('Serika', '/spine/Serika_home.json')
            .add('Serika', '/spine/Hoshino_home_background.json')
            .load((loader, res) => {
              let Serika = new PIXI.spine.Spine(res.Serika.spineData);
              let skeleton = Serika.skeleton;
              //获取Spine骨骼
              // let controlEye = skeleton.findBone('Touch_Eye');
              //眼位置
              // let relative = { x: 0, y: 0 };
              //记录眼骨骼初始位置
              // relative.x = controlEye.x;
              // relative.y = controlEye.y;
              //移动                  id元素在HeaderNav
              document.getElementById('bacgAnim').addEventListener('mousemove', function (e) {
                // 眼睛跟踪
                // controlEye.x = -(e.clientY - 100) / 3;
                // controlEye.y = -(e.clientX - 1000) / 3;
                // 视角跟踪
                Serika.x = 900 + (e.clientX)/15;
                Serika.y = 800 + (e.clientY)/10;
              });
              //鼠标离开过渡           id元素在HeaderNav
              // document.getElementById('bacgAnim').addEventListener('mouseleave', function (e) {
              //   let i = 1;
              //   let timer = setInterval(function () {
              //     controlEye.y = controlEye.y - (controlEye.y - relative.y) * (i / 10);
              //     controlEye.x = controlEye.x - (controlEye.x - relative.x) * (i / 10);
              //     // Serika.x = Serika.x - (Serika.x - 900)*(i/10); //1000
              //     // Serika.y = Serika.y - (Serika.y - 800)*(i/10); //1000
              //     i++;
              //     if (i === 10) {
              //       i = 1;
              //       clearInterval(timer);
              //     }
              //   }, 40);
              // });
              //设置播放动画
              Serika.state.setAnimation(0, 'Dev_Test', true);
              //原点偏移
              Serika.x = 900; //1000
              Serika.y = 800; //1000
              //缩放
              Serika.scale.x = 0.7;
              Serika.scale.y = 0.7;
              //添加到舞台显示
              banner.stage.addChild(Serika);
            });
      //画布修改大小需要的配置
      banner.renderer.view.style.position = "absolute";
      banner.renderer.view.style.display = "block";
      banner.renderer.autoResize = true;
      banner.renderer.resize(document.documentElement.scrollWidth, 180);
      //窗体变换事件
      window.addEventListener('resize', ()=> {
        // 延迟调用，防止读取不到值
        // this.$nextTick(() => {
        //   this.$refs.headerAnim.offsetWidth > 1200 ? banner.renderer.resize(this.$refs.headerAnim.offsetWidth, 180) : console.log(1);
        // })
        banner.renderer.resize(document.documentElement.scrollWidth, 180);
      });
    },
  },
}
</script>

<style scoped>
  #header{
    position: relative;
    width:100%;
    height:180px;
    box-shadow: -10px 1px 5px rgb(135, 135, 135);
  }
</style>